/* TailRef app · state, IndexedDB, snapshots */
'use strict';

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('tailref', 1);
    req.onupgradeneeded = () => {
      const d = req.result;
      if (!d.objectStoreNames.contains('images')) d.createObjectStore('images');
      if (!d.objectStoreNames.contains('meta'))   d.createObjectStore('meta');
    };
    req.onsuccess = async () => {
      db = req.result;
      try { await migrateLegacyDb(); } catch { /* göç engellenmeye çalışılınca sessiz devam */ }
      resolve();
    };
    req.onerror   = () => reject(req.error);
  });
}

/* Tek seferlik veri göçü: önceki sürümlerin veritabanları → mevcut ad.
   Eski adlar koda çıplak yazılmaz; base64 tutulur (sırayla göç edilir). */
const LEGACY_DBS = [
  atob('cmVmYm9hcmQ='), /* eski marka-b dönemi DB adı */
  atob('cmVmZXZlcnI='), /* önceki marka dönemi DB adı */
];

function legacyStoreCount(oldDb, store) {
  return new Promise(res => {
    const c = oldDb.transaction(store).objectStore(store).count();
    c.onsuccess = () => res(c.result);
    c.onerror = () => res(0);
  });
}

function legacyKeyList(oldDb, store) {
  return new Promise(res => {
    try {
      const tx = oldDb.transaction(store, 'readonly');
      const r = tx.objectStore(store).getAllKeys();
      r.onsuccess = () => res(r.result || []);
      r.onerror = () => res([]);
    } catch { res([]); }
  });
}

/* Her kayıt kendi transaction'ında okunur: cursor'lı tek transaction'ta
   araya `await` girince IndexedDB transaction'ı auto-commit olur ve
   `continue()` TransactionInactiveError'a düşer (sessiz yarım göç). */
function legacyGetValue(oldDb, store, key) {
  return new Promise(res => {
    try {
      const tx = oldDb.transaction(store, 'readonly');
      const r = tx.objectStore(store).get(key);
      r.onsuccess = () => res(r.result);
      r.onerror = () => res(undefined);
    } catch { res(undefined); }
  });
}

async function migrateLegacyDb() {
  /* Her eski DB adı sırayla denenir: kayıt varsa mevcut DB'ye aktarılır,
     sonra eski DB silinir. Kayıtsız/olmayan ad sessizce atlanır. */
  for (const LEGACY_DB of LEGACY_DBS) {
    await migrateOneLegacyDb(LEGACY_DB);
  }
}

function migrateOneLegacyDb(LEGACY_DB) {
  return new Promise((resolve) => {
    let upgraded = false;
    let req;
    try { req = indexedDB.open(LEGACY_DB, 1); } catch { resolve(); return; }
    req.onupgradeneeded = () => { upgraded = true; };
    req.onsuccess = async () => {
      const oldDb = req.result;
      try {
        /* eski adla boş bir DB açıldıysa (yoktu) kur düzgünce ve sil */
        if (upgraded) { oldDb.close(); indexedDB.deleteDatabase(LEGACY_DB); resolve(); return; }
        const stores = ['images', 'meta'].filter(s => oldDb.objectStoreNames.contains(s));
        if (!stores.length) { oldDb.close(); resolve(); return; }
        /* legacy hâlâ duruyor ve en az bir kayıttı varsa göç sürücülü:
           hedef kayıtlara ekleme yapılır (put, aynı anahtı aşar), tamamlanınca eski DB silinir. */
        let total = 0;
        for (const s of stores) total += await legacyStoreCount(oldDb, s);
        if (!total) { oldDb.close(); resolve(); return; }
        for (const s of stores) {
          const keys = await legacyKeyList(oldDb, s);
          for (const key of keys) {
            const val = await legacyGetValue(oldDb, s, key);
            if (val !== undefined) await idbPut(s, key, val);
          }
        }
        oldDb.close();
        indexedDB.deleteDatabase(LEGACY_DB);
        resolve();
      } catch { try { oldDb.close(); } catch { /* zaten kapalı */ } resolve(); }
    };
    req.onerror = () => { /* legacy yok — normal koşum */ resolve(); };
  });
}

/* idb* kapıları db açılmadan çağrılırsa (erken watcher consume'u ya da
   boot sırasında tetiklenen flushSave yarışı) açılışı bekler; db null
   iken transaction patlamaz. openDB ikinci kez çağrılırsa ikinci bağlantı
   zararsızdır (aynı sürüm, db global güncellenir). */
let idbOpenPromise = null;
function idbReady() {
  if (db) return Promise.resolve();
  if (!idbOpenPromise) idbOpenPromise = openDB();
  return idbOpenPromise;
}

async function idbPut(store, key, val) {
  await idbReady();
  return new Promise((res, rej) => {
    const tx = db.transaction(store, 'readwrite');
    tx.objectStore(store).put(val, key);
    tx.oncomplete = () => res();
    tx.onerror    = () => rej(tx.error);
  });
}

async function idbGet(store, key) {
  await idbReady();
  return new Promise((res, rej) => {
    const tx = db.transaction(store, 'readonly');
    const r  = tx.objectStore(store).get(key);
    r.onsuccess = () => res(r.result);
    r.onerror   = () => rej(r.error);
  });
}

async function idbDel(store, key) {
  await idbReady();
  return new Promise((res, rej) => {
    const tx = db.transaction(store, 'readwrite');
    tx.objectStore(store).delete(key);
    tx.oncomplete = () => res();
    tx.onerror    = () => rej(tx.error);
  });
}

async function idbEntries(store) {
  await idbReady();
  return new Promise((res, rej) => {
    const tx = db.transaction(store, 'readonly');
    const os = tx.objectStore(store);
    const out = [];
    const r = os.openCursor();
    r.onsuccess = () => {
      const c = r.result;
      if (c) { out.push([c.key, c.value]); c.continue(); }
      else res(out);
    };
    r.onerror = () => rej(r.error);
  });
}

/* =========================================================
   yardımcılar
   ========================================================= */
const newId = (() => {
  let seq = 0;
  const ts = Date.now().toString(36);
  return () => {
    seq = (seq + 1) & 0xffffff;
    return ts + '-' + seq.toString(36).padStart(4, '0') + '-' + Math.random().toString(36).slice(2, 6);
  };
})();
const clamp = (v, a, b) => v < a ? a : (v > b ? b : v);
const getItem = id => state.items.find(i => i.id === id) || null;
const nextZ = () => state.items.reduce((m, i) => Math.max(m, i.z || 0), 0) + 1;
const byZ = (a, b) => (a.z || 0) - (b.z || 0);

function hasFiniteView(view) {
  return !!(view &&
    Number.isFinite(view.x) &&
    Number.isFinite(view.y) &&
    Number.isFinite(view.scale));
}

function createStateSnapshot() {
  // Çizim modundaki mini tahta, referans görünümünü geçici olarak değiştirir.
  // Kayda her zaman referans modundaki görünüm yazılır; böylece uygulama
  // çizim sırasında kapanıp açılsa bile tahta eski yerine döner.
  let view = state.view;
  try {
    if (document.body.classList.contains('ps-ref-live') &&
        typeof dpProto !== 'undefined' && dpProto && dpProto.refView) {
      view = dpProto.refView;
    }
  } catch { /* sessiz */ }
  /* A3 (maske idle-encode): ertelenmiş maske Kodlaması varsa snapshot'a
     girmeden önce senkron tamamla. Maske vuruşu mask.src'te yaşadığından
     kayıt/undo doğruluğu bu flush'e bağlıdır; pending yoksa maliyetsiz. */
  if (typeof inkMaskFlushPending === 'function') inkMaskFlushPending();
  return {
    items: state.items,
    view,
    bg: state.bg,
    groupTitles: state.groupTitles,
    groupImportant: state.groupImportant,
    groupParents: state.groupParents,
    links: state.links,
    trash: state.trash,
    // Çizim katmanları/vuruşları da panonun parçasıdır. Tuvaller türetilmiş
    // önbellek olduğu için yalnızca vektör veri saklanır.
    ink: state.ink,
  };
}

function restoreSnapshot(snapshot) {
  /* A3 devamı (undo mask-src dedupe): yığından gelen snapshot'ta maske
     src'si token'a (srcRef) sıkıştırılır; uygulanmadan önce yan-tablodan
     gerçek string'e döner ve yığın referansı bırakılır. Diskten gelen
     snapshot'ta srcRef yoktur → no-op. */
  if (snapshot && snapshot.ink && Array.isArray(snapshot.ink.layers)) {
    maskSnapRehydrateParsed(snapshot); /* iade: yığın silme referansı */
  }
  state.items = Array.isArray(snapshot && snapshot.items) ? snapshot.items : [];
  state.view = hasFiniteView(snapshot && snapshot.view)
    ? snapshot.view
    : { x: 0, y: 0, scale: 1 };
  state.bg = snapshot && typeof snapshot.bg === 'number' ? snapshot.bg : 1;
  state.groupTitles = snapshot && snapshot.groupTitles && typeof snapshot.groupTitles === 'object' ? snapshot.groupTitles : {};
  state.groupImportant = snapshot && snapshot.groupImportant && typeof snapshot.groupImportant === 'object' ? snapshot.groupImportant : {};
  state.groupParents = snapshot && snapshot.groupParents && typeof snapshot.groupParents === 'object' ? snapshot.groupParents : {};
  state.links = Array.isArray(snapshot && snapshot.links) ? snapshot.links : [];
  state.trash = normalizeTrash(snapshot && snapshot.trash);
  state.ink = typeof inkNormalizeState === 'function'
    ? inkNormalizeState(snapshot && snapshot.ink)
    : (snapshot && snapshot.ink) || null;
}

async function mapInBatches(items, limit, worker) {
  const out = new Array(items.length);
  let nextIndex = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (true) {
      const index = nextIndex++;
      if (index >= items.length) return;
      out[index] = await worker(items[index], index);
    }
  });
  await Promise.all(runners);
  return out;
}

/* =========================================================
   A3 devamı — undo/redo Snapshot maske src dedupe
   ---------------------------------------------------------
   pushUndo tam doküman JSON'ı üretir; maske src (PNG dataURL, 4K'da
   ~1.4 MB) HER snapshot'a birebir gömülür → 60 derinlik undoStack'te
   ~80 MB kopya + 33-45 ms stringify. Burada src'yi yalnız YANI
   TABLODA bir kez tutup snapshot'a kısa token (srcRef) yazarız.
   - referans sayacı yığın üyeliği başına +1 (JSON.replacer anında),
   - snapshot uygulaması (restoreSnapshot) token'ı gerçek string'e
     geri çözer ve sayaçyı ısıtır (yığın üyeliği bitti),
   - diskten gelen kayıtlar tokenize edilmez (save hattı bypass);
     JSON'da srcRef gören hiçbir fizyoloji (normalize) mask kaybetmez:
     rehydrate uygulanmadan önce çalışır.
   ========================================================= */
const maskSnap = { of: new Map(), to: new Map(), refs: new Map(), seq: 0 };
/* Bu eşiğin altındaki src'leri tokenleştirmemeye değer (kışa uğraş). */
const MASK_SNAP_MIN_LEN = 8192;

function maskSnapReplacer(key, value) {
  if (key !== 'mask' || !value || typeof value !== 'object' ||
      typeof value.src !== 'string' || value.src.length < MASK_SNAP_MIN_LEN) {
    return value;
  }
  let tok = maskSnap.of.get(value.src);
  if (!tok) {
    tok = 'M' + (++maskSnap.seq);
    maskSnap.of.set(value.src, tok);
    maskSnap.to.set(tok, value.src);
  }
  maskSnap.refs.set(tok, (maskSnap.refs.get(tok) || 0) + 1);
  return { srcRef: tok, w: value.w, h: value.h };
}

function maskSnapStringify(snap) {
  return JSON.stringify(snap, maskSnapReplacer);
}

function maskSnapReleaseRef(tok) {
  const n = (maskSnap.refs.get(tok) || 0) - 1;
  if (n <= 0) {
    const src = maskSnap.to.get(tok);
    maskSnap.to.delete(tok);
    if (src) maskSnap.of.delete(src);
    maskSnap.refs.delete(tok);
  } else {
    maskSnap.refs.set(tok, n);
  }
}

/** Snapshot uygulamasından ÖNCE srcRef'leri gerçek string'e döndürür ve
 *  yığın referansını bırakır (mutasyon yalnızca parse edilmiş kopyada). */
function maskSnapRehydrateParsed(parsed) {
  const layers = parsed && parsed.ink && parsed.ink.layers;
  if (!Array.isArray(layers)) return;
  for (const l of layers) {
    const m = l && l.mask;
    if (!m || !m.srcRef) continue;
    const src = maskSnap.to.get(m.srcRef);
    if (src) {
      l.mask = { src, w: m.w, h: m.h };
      maskSnapReleaseRef(m.srcRef);
    } else {
      /* yan-tablo için çoktan kırıldı (sayfalama endişesi) — maskenin
         katkısı yok olmasın diye sessiz mask kaldır. */
      l.mask = null;
    }
  }
}

/** Yığından DÜŞEN ham snapshot string'indeki token referanslarını release eder. */
function maskSnapReleaseRaw(raw) {
  if (typeof raw !== 'string' || raw.indexOf('"srcRef"') < 0) return;
  let parsed = null;
  try { parsed = JSON.parse(raw); } catch { return; }
  if (!parsed || !parsed.ink || !Array.isArray(parsed.ink.layers)) return;
  for (const l of parsed.ink.layers) {
    const m = l && l.mask;
    if (m && m.srcRef) maskSnapReleaseRef(m.srcRef);
  }
}

/** Yığın komple boşalırken (redo temizleme) tüm referansları bırak. */
function maskSnapReleaseStack(stack) {
  if (!Array.isArray(stack)) return;
  for (const raw of stack) maskSnapReleaseRaw(raw);
}

'use strict';
/* ======================================================================
   TailRef · Tur T Faz 2 — Özel tema kayıt defteri (15 Kasım 2026)
   ======================================================================
   Gömülü 10 tema (19-themes-effects.js) DOKUNULMAZ; bu modül onların
   ÜSTÜNE özel temalar ekler. Özel tema, mevcut mekanizmaya biner:
   her özel tema için üretim zamanında bir CSS kuralı üretilir
   (:root[data-theme="<id>"] — 7 çekirdek değişken + #backdrop) ve id
   themeNames'e runtime'da eklenir. Böylece applyTheme/mod-temaları/
   boot geri yükleme/select senkronu HİÇ değişmeden çalışır (parite).

   Depo: localStorage 'tailref-custom-themes' (JSON dizisi). Anahtar
   'tailref-' önekli olduğundan tercih yedeği whitelist'ine otomatik
   girer (60-settings-hub settingsPrefsKeys önek filtresi).

   Veri: { id, name, colors{bg,panel,border,text,dim,accent,accentInk},
          panelAlpha (40-100), backdrop{image|null,position,size,
          opacity,blur}, createdAt }
   Renkler hex; panel = rgba(panelHex, panelAlpha/100).
   ====================================================================== */

const THEME_REG_KEY = 'tailref-custom-themes';
const THEME_REG_MAX = 30;
const THEME_COLOR_SLOTS = ['bg', 'panel', 'border', 'text', 'dim', 'accent', 'accentInk'];
/* native title yasak kanalına uygun: dinamik düğmeler data-tooltip kullanır */
const THEME_SLOT_LABELS = {
  bg: 'Background', panel: 'Panel surface', border: 'Borders', text: 'Text',
  dim: 'Secondary text', accent: 'Accent', accentInk: 'Text over accent',
};

function themeRegRead() {
  try {
    const raw = localStorage.getItem(THEME_REG_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return [];
    return arr.filter(t => t && typeof t.id === 'string' && t.id.startsWith('ct_')
      && t.colors && typeof t.name === 'string');
  } catch { return []; }
}
function themeRegWrite(list) {
  try { localStorage.setItem(THEME_REG_KEY, JSON.stringify(list)); } catch { /* sessiz */ }
  document.dispatchEvent(new CustomEvent('tailref-custom-themes-changed'));
}

/* ---- hex yardımcıları ---- */
function themeRegClampByte(v) { return Math.max(0, Math.min(255, Math.round(v))); }
function themeRegHexToRgb(hex) {
  let h = String(hex || '').trim();
  if (h.startsWith('rgb')) {
    const m = h.match(/[\d.]+/g) || [];
    return { r: +m[0] || 0, g: +m[1] || 0, b: +m[2] || 0 };
  }
  h = h.replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  if (h.length < 6) return { r: 0, g: 0, b: 0 };
  return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
}
function themeRegRgbToHex(r, g, b) {
  const p = v => themeRegClampByte(v).toString(16).padStart(2, '0');
  return '#' + p(r) + p(g) + p(b);
}
function themeRegMix(a, b, t) {
  const A = themeRegHexToRgb(a), B = themeRegHexToRgb(b);
  return themeRegRgbToHex(A.r + (B.r - A.r) * t, A.g + (B.g - A.g) * t, A.b + (B.b - A.b) * t);
}
function themeRegLuma(hex) {
  const { r, g, b } = themeRegHexToRgb(hex);
  return (r * 0.299 + g * 0.587 + b * 0.114) / 255;
}
function themeRegSat(hex) {
  const { r, g, b } = themeRegHexToRgb(hex);
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
  return mx === 0 ? 0 : (mx - mn) / mx;
}
function themeRegAccentInkFor(hex) {
  return themeRegLuma(hex) > 0.62 ? '#0d1013' : '#ffffff';
}
/* Accent modülüyle aynı kural — tek kaynak (62-settings-extended
   settingAccentInkFor yoksa kendi hesabımız kullanılır). */

/* ---- CSS üretimi ---- */
let themeRegStyleEl = null;
function themeRegStyleSheet() {
  if (themeRegStyleEl && document.getElementById('tailrefCustomThemeStyles')) return themeRegStyleEl;
  themeRegStyleEl = document.getElementById('tailrefCustomThemeStyles');
  if (!themeRegStyleEl) {
    themeRegStyleEl = document.createElement('style');
    themeRegStyleEl.id = 'tailrefCustomThemeStyles';
    (document.head || document.documentElement).appendChild(themeRegStyleEl);
  }
  return themeRegStyleEl;
}
function themeRegRuleFor(theme) {
  const c = theme.colors || {};
  const hex = k => themeRegSanitizeHex(c[k]);
  const alpha = Math.max(40, Math.min(100, +theme.panelAlpha || 94)) / 100;
  const pv = themeRegHexToRgb(hex('panel'));
  const panel = `rgba(${pv.r},${pv.g},${pv.b},${alpha})`;
  let css = `:root[data-theme="${theme.id}"]{` +
    `--bg:${hex('bg')};--panel:${panel};--border:${hex('border')};` +
    `--text:${hex('text')};--dim:${hex('dim')};--accent:${hex('accent')};` +
    `--accent-ink:${themeRegAccentInkFor(hex('accent'))};}`;
  const bd = theme.backdrop || null;
  if (bd && bd.image) {
    const blur = Math.max(0, Math.min(40, +bd.blur || 0));
    const op = Math.max(0.05, Math.min(1, +bd.opacity || 1));
    css += `:root[data-theme="${theme.id}"] #backdrop{` +
      `background-color:${hex('bg')};` +
      `background-image:url("${bd.image}");` +
      `background-position:${bd.position || 'center'};` +
      `background-size:${bd.size || 'cover'};background-repeat:no-repeat;` +
      `opacity:${op};filter:blur(${blur}px);}`;
  } else {
    css += `:root[data-theme="${theme.id}"] #backdrop{` +
      `background:radial-gradient(120% 90% at 70% -10%,` +
      `color-mix(in srgb, var(--accent) 9%, var(--bg)), var(--bg));` +
      `opacity:1;filter:none;}`;
  }
  return css;
}
function themeRegSanitizeHex(v) {
  const m = String(v || '').match(/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/);
  return m ? m[0] : '#4da3ff';
}
function themeRegRebuildRules() {
  const sheet = themeRegStyleSheet();
  const list = themeRegRead();
  sheet.textContent = list.map(themeRegRuleFor).join('\n');
}

/* ---- themeNames uzantısı: 19-themes-effects dizisine runtime'da ---- */
function themeRegExtendNames(list) {
  const names = (typeof themeNames === 'object' && themeNames) ? themeNames : null;
  if (!names) return;
  for (const t of list) if (!names.includes(t.id)) names.push(t.id);
  /* Silinen özel temaları diziden düşür (applyTheme guard'ı doğru kalsın) */
  for (let i = names.length - 1; i >= 0; i--) {
    const n = names[i];
    if (n.startsWith('ct_') && !list.some(t => t.id === n)) names.splice(i, 1);
  }
}

/* ---- genel API ---- */
function themeRegList() { return themeRegRead(); }
function themeRegIsCustom(id) { return themeRegRead().some(t => t.id === id); }
function themeRegActive() {
  try { return localStorage.getItem('tailref-theme') || 'classic'; } catch { return 'classic'; }
}
function themeRegEnsureRule(theme) {
  const sheet = themeRegStyleSheet();
  if (!sheet.textContent.includes(`data-theme="${theme.id}"`)) {
    sheet.textContent += '\n' + themeRegRuleFor(theme);
  }
}
function themeRegApply(id) {
  const list = themeRegRead();
  const theme = list.find(t => t.id === id);
  if (theme) { themeRegEnsureRule(theme); themeRegExtendNames(list); }
  if (typeof applyTheme === 'function') applyTheme(id);
  return !!theme || (typeof themeNames === 'object' && themeNames.includes(id));
}
function themeRegNewId() { return 'ct_' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6); }
function themeRegValidate(theme) {
  if (!theme || typeof theme.name !== 'string' || !theme.name.trim()) return 'isim boş';
  if (theme.name.trim().length > 40) return 'isim uzun';
  const c = theme.colors || {};
  for (const k of THEME_COLOR_SLOTS) if (!/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(String(c[k] || ''))) return 'renk bozuk: ' + k;
  if (theme.backdrop && theme.backdrop.image) {
    if (typeof theme.backdrop.image !== 'string' || !theme.backdrop.image.startsWith('data:image/')) return 'görsel bozuk';
    if (theme.backdrop.image.length > 1_600_000) return 'görsel çok büyük';
  }
  return null;
}
/** Kaydet/güncelle. asNew=true → daima yeni id. overwriting mevcut id
    ise üzerine yazar (çağıran taraf onayı sorar — spec kuralı). */
function themeRegSave(draft, asNew) {
  const err = themeRegValidate(draft);
  if (err) return { ok: false, error: err };
  const list = themeRegRead();
  if (list.length >= THEME_REG_MAX && (!draft.id || !list.some(t => t.id === draft.id))) {
    return { ok: false, error: 'limit' };
  }
  let id = draft.id;
  if (!id || asNew || !list.some(t => t.id === id)) {
    id = themeRegNewId();
    const entry = {
      id, name: draft.name.trim(), colors: { ...draft.colors },
      panelAlpha: Math.max(40, Math.min(100, +draft.panelAlpha || 94)),
      backdrop: draft.backdrop ? { ...draft.backdrop } : null,
      createdAt: Date.now(),
    };
    list.push(entry);
  } else {
    const t = list.find(x => x.id === id);
    t.name = draft.name.trim();
    t.colors = { ...draft.colors };
    t.panelAlpha = Math.max(40, Math.min(100, +draft.panelAlpha || 94));
    t.backdrop = draft.backdrop ? { ...draft.backdrop } : null;
  }
  themeRegWrite(list);
  themeRegRebuildRules();
  themeRegExtendNames(list);
  if (typeof applyTheme === 'function') applyTheme(id);
  return { ok: true, id };
}
function themeRegRename(id, name) {
  const list = themeRegRead();
  const t = list.find(x => x.id === id);
  if (!t || !String(name || '').trim()) return { ok: false, error: 'yok' };
  t.name = String(name).trim().slice(0, 40);
  themeRegWrite(list);
  themeRegRebuildRules();
  return { ok: true };
}
function themeRegDuplicate(id) {
  const list = themeRegRead();
  const src = list.find(x => x.id === id);
  if (!src) return { ok: false, error: 'yok' };
  if (list.length >= THEME_REG_MAX) return { ok: false, error: 'limit' };
  const copy = {
    id: themeRegNewId(), name: (src.name + ' — copy').slice(0, 40),
    colors: { ...src.colors }, panelAlpha: src.panelAlpha,
    backdrop: src.backdrop ? { ...src.backdrop } : null, createdAt: Date.now(),
  };
  list.push(copy);
  themeRegWrite(list);
  themeRegRebuildRules();
  themeRegExtendNames(list);
  return { ok: true, id: copy.id };
}
function themeRegDelete(id) {
  const list = themeRegRead();
  const i = list.findIndex(x => x.id === id);
  if (i < 0) return { ok: false, error: 'yok' };
  list.splice(i, 1);
  themeRegWrite(list);
  themeRegRebuildRules();
  themeRegExtendNames(list);
  const active = themeRegActive();
  if (active === id && typeof applyTheme === 'function') applyTheme('classic');
  return { ok: true };
}
function themeRegSetImage(id, dataUrl, opts) {
  const list = themeRegRead();
  const t = list.find(x => x.id === id);
  if (!t) return { ok: false, error: 'yok' };
  if (dataUrl && (!String(dataUrl).startsWith('data:image/') || dataUrl.length > 1_600_000)) {
    return { ok: false, error: 'görsel bozuk' };
  }
  t.backdrop = dataUrl ? {
    image: dataUrl, position: opts && opts.position || 'center',
    size: opts && opts.size || 'cover',
    opacity: Math.max(0.05, Math.min(1, +(opts && opts.opacity) || 1)),
    blur: Math.max(0, Math.min(40, +(opts && opts.blur) || 0)),
  } : null;
  themeRegWrite(list);
  themeRegRebuildRules();
  if (themeRegActive() === id) themeRegApply(id);
  return { ok: true };
}

/* ---- palet çıkarma (yerel, median-cut; harici servis yok) ---- */
function themeRegLoadImage(dataUrl) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('image'));
    img.src = dataUrl;
  });
}
/** dataUrl → { palette:string[6], slots:{bg,panel,...} } — slot
    atamaları sezgisel (kullanıcı editörde değiştirebilir). */
async function themeRegExtractPalette(dataUrl) {
  const img = await themeRegLoadImage(dataUrl);
  const scale = Math.min(1, 128 / Math.max(img.width || 1, img.height || 1));
  const w = Math.max(1, Math.round((img.width || 1) * scale));
  const h = Math.max(1, Math.round((img.height || 1) * scale));
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  const g = cv.getContext('2d', { willReadFrequently: true });
  g.drawImage(img, 0, 0, w, h);
  const data = g.getImageData(0, 0, w, h).data;
  const px = [];
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < 128) continue;
    px.push([data[i], data[i + 1], data[i + 2]]);
  }
  if (!px.length) throw new Error('boş görsel');
  /* median-cut: en geniş kanaldan ortanca ile böl, 6 kova */
  let buckets = [px];
  while (buckets.length < 6) {
    let bi = -1, bc = null, br = 0;
    for (let i = 0; i < buckets.length; i++) {
      const b = buckets[i];
      if (b.length < 2) continue;
      for (let ch = 0; ch < 3; ch++) {
        let mn = 255, mx = 0;
        for (const p of b) { if (p[ch] < mn) mn = p[ch]; if (p[ch] > mx) mx = p[ch]; }
        const range = mx - mn;
        if (range > br) { br = range; bi = i; bc = ch; }
      }
    }
    if (bi < 0) break;
    const b = buckets[bi].slice().sort((x, y) => x[bc] - y[bc]);
    const mid = b.length >> 1;
    buckets.splice(bi, 1, b.slice(0, mid), b.slice(mid));
  }
  const palette = buckets.map(b => {
    let r = 0, gg = 0, bl = 0;
    for (const p of b) { r += p[0]; gg += p[1]; bl += p[2]; }
    const n = Math.max(1, b.length);
    return themeRegRgbToHex(r / n, gg / n, bl / n);
  }).filter((h, i, a) => a.indexOf(h) === i);
  /* slot atamaları */
  const byLuma = palette.slice().sort((a, b2) => themeRegLuma(a) - themeRegLuma(b2));
  const bg = byLuma[0] || '#15151a';
  const text = byLuma[byLuma.length - 1] || '#e7e7ee';
  const accent = palette.slice().sort((a, b2) =>
    themeRegSat(b2) * (1 - Math.abs(themeRegLuma(b2) - 0.5)) -
    themeRegSat(a) * (1 - Math.abs(themeRegLuma(a) - 0.5)))[0] || '#4da3ff';
  const panelBase = byLuma[1] || bg;
  const slots = {
    bg, text, accent,
    panel: panelBase,
    border: themeRegMix(text, bg, 0.8),   /* text %20 + bg %80 */
    dim: themeRegMix(text, bg, 0.55),
    accentInk: themeRegAccentInkFor(accent),
  };
  return { palette, slots };
}
/** dataUrl'i toleranslı küçültür: uzun kenar ≤1600px, JPEG q.82. */
async function themeRegDownscale(dataUrl) {
  const img = await themeRegLoadImage(dataUrl);
  const scale = Math.min(1, 1600 / Math.max(img.width || 1, img.height || 1));
  const w = Math.max(1, Math.round((img.width || 1) * scale));
  const h = Math.max(1, Math.round((img.height || 1) * scale));
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  cv.getContext('2d').drawImage(img, 0, 0, w, h);
  return cv.toDataURL('image/jpeg', 0.82);
}

window.tailrefThemeRegistry = {
  slots: THEME_COLOR_SLOTS,
  slotLabels: THEME_SLOT_LABELS,
  list: themeRegList,
  isCustom: themeRegIsCustom,
  active: themeRegActive,
  apply: themeRegApply,
  save: themeRegSave,
  rename: themeRegRename,
  duplicate: themeRegDuplicate,
  delete: themeRegDelete,
  setImage: themeRegSetImage,
  extractPalette: themeRegExtractPalette,
  downscale: themeRegDownscale,
  accentInkFor: themeRegAccentInkFor,
  mix: themeRegMix,
};

/* Boot: 19-themes-effects modülünün kendi boot'u (applyTheme) modül
   değerlendirme sırasında çalışır; biz daha ÖNCE yüklendiğimiz için
   ertelenmiş boot ile kuralları hazırlar, themeNames'i genişletir ve
   kayıtlı özel tema gerçekte uygulamadaysa onu gerçekten uygular
   (19-themes'in applyTheme guard'ı bilinmeyen id'yi classic'e
   düşürürdü — parite bozulmasın diye burada düzeltilir). */
setTimeout(() => {
  try {
    const list = themeRegRead();
    themeRegExtendNames(list);
    themeRegRebuildRules();
    const active = themeRegActive();
    if (list.some(t => t.id === active)) themeRegApply(active);
  } catch { /* sessiz — parite: özel tema yoksa davranış yok */ }
}, 0);

'use strict';
/* ======================================================================
   TailRef · Tur T Faz 2 — Arayüz kayıt defteri (15 Kasım 2026)
   ======================================================================
   Tema (renk paleti) ve Arayüz (bileşen tasarım dili) BAĞIMSIZ iki
   katmandır (spec PART 5). Bu modül arayüz seçimini yönetir:
   - documentElement.dataset.interface = id (classic → attribute yok,
     görsel değişiklik YOK — parite).
   - Arayüze özel sunum CSS'i <link data-ui-skin="..."> üzerinden
     enable/disable edilir (link yoksa o arayüz seçilemez — sahte
     kontol yasak; Faz 4 ui-win95.css eklendiğinde kayıta girer).
   - Paket mimarisi (Faz 6) register() ile genişler: doğrulanmış
     dekleratif paket tanımı buraya bağlanır; JS yürütülmez.
   Depo: localStorage 'tailref-interface' ('classic' varsayılan).
   ====================================================================== */

const UI_INTERFACE_KEY = 'tailref-interface';
/* Gömülü arayüzler. classic DAIMA mevcut TailRef sunumu — varsayılan,
   yeniden tasarlanmaz. Yeni preset yalnızca skin CSS dosyası projeye
   eklendiğinde bu listeye girer (skin dosyasız arayüz sahte olur). */
const uiInterfaceDefs = [
  { id: 'classic', name: 'TailRef Classic', version: 1, builtin: true,
    desc: 'The current TailRef interface — default, always available.' },
  /* Tur T Faz 4: SGI IRIX 4Dwm — ui-irix.css skin'i ile. Skin link
     belgelerde var; registry yalnızca enable/disable eder. Kullanıcı
     kararı: preset = IRIX (kendi arayüzümüz classic + IRIX; ileride
     yeni arayüzler register() ile gelir). */
  { id: 'irix', name: 'SGI IRIX 4Dwm', version: 1, builtin: true, wip: true,
    desc: 'SGI IRIX / Indigo Magic Desktop: thick Motif 4Dwm bevels, plum and indigo title bars, Helvetica, petrol teal workspace, square corners. Colors still follow the theme.' },
];

/* Skin kaynağı: builtin'lerde <link data-ui-skin>, Faz 6 paketlerinde
   <style data-ui-skin> (derlenmiş dekleratif CSS). İkisi de aynı
   kontratla açılır/kapanır. */
function uiInterfaceSkinEl(id) {
  return document.querySelector(
    'link[data-ui-skin="' + CSS.escape(id) + '"],style[data-ui-skin="' + CSS.escape(id) + '"]');
}
/* Skin'i aç/kapat. on=true → AÇIK. <style> elementinde disabled
   etkisizdir — media geçişi kullanılır. DİKKAT: LINK dalında atama
   TERSİNE (!on) — disabled özelliği "kapalı" anlamına gelir. */
function uiInterfaceSkinToggle(skin, on) {
  if (!skin) return;
  if (skin.tagName === 'LINK') skin.disabled = !on;
  else skin.media = on ? '' : 'not all';
}
function uiInterfaceList() { return uiInterfaceDefs.slice(); }
function uiInterfaceActive() {
  try { return localStorage.getItem(UI_INTERFACE_KEY) || 'classic'; } catch { return 'classic'; }
}
/** Arayüz uygula. classic → data-interface yok + tüm skin'ler kapalı.
    Diğerleri → dataset + kendi skin'i açık, diğer kapalı. Skin kaynağı
    belgelerde yoksa seçim REDDEDİLİR (false) — mevcut görünüm korunur. */
function uiInterfaceApply(id) {
  const def = uiInterfaceDefs.find(d => d.id === id);
  if (!def) return false;
  const skin = uiInterfaceSkinEl(id);
  if (id !== 'classic' && !skin) return false;
  for (const el of document.querySelectorAll('link[data-ui-skin],style[data-ui-skin]')) {
    if (el !== skin) uiInterfaceSkinToggle(el, false);
  }
  uiInterfaceSkinToggle(skin, true);
  if (id === 'classic') delete document.documentElement.dataset.interface;
  else document.documentElement.dataset.interface = id;
  try { localStorage.setItem(UI_INTERFACE_KEY, id); } catch { /* sessiz */ }
  document.dispatchEvent(new CustomEvent('tailref-interface-changed',
    { detail: { id, def } }));
  return true;
}
/** Faz 6: paket kaydı. Doğrulama 02d-ui-package-format.js'te; burada
    yalnız skin kaynağı olan tanımlar kabul edilir (register anında
    skin yoksa bile kabul — 02e enjeksiyonu register'dan ÖNCE yapar;
    belge kapanınca eski haline döner, kalıcı zarar yok). */
function uiInterfaceRegister(def) {
  if (!def || typeof def.id !== 'string' || !def.id || def.builtin) return false;
  if (uiInterfaceDefs.some(d => d.id === def.id)) return false;
  uiInterfaceDefs.push({
    id: def.id, name: String(def.name || def.id).slice(0, 40),
    version: +def.version || 1, builtin: false,
    desc: String(def.desc || '').slice(0, 200), packaged: true,
  });
  document.dispatchEvent(new CustomEvent('tailref-interface-changed',
    { detail: { registered: def.id } }));
  return true;
}
/** Faz 6: paket kaldırma (yalnız packaged kayıtlar). */
function uiInterfaceUnregister(id) {
  const idx = uiInterfaceDefs.findIndex(d => d.id === id && !d.builtin);
  if (idx < 0) return false;
  uiInterfaceDefs.splice(idx, 1);
  document.dispatchEvent(new CustomEvent('tailref-interface-changed',
    { detail: { unregistered: id } }));
  return true;
}
window.tailrefInterfaces = {
  list: uiInterfaceList,
  apply: uiInterfaceApply,
  active: uiInterfaceActive,
  register: uiInterfaceRegister,
  unregister: uiInterfaceUnregister,
};
/* Boot: kayıtlı arayüz. Skin link yüklenmemişse (Faz 4 öncesi)
   classic'te kalır — sessiz güvenli düşüş, parite korunur. */
setTimeout(() => {
  try {
    const saved = uiInterfaceActive();
    if (saved && saved !== 'classic') uiInterfaceApply(saved);
  } catch { /* sessiz */ }
}, 0);

'use strict';
/* ======================================================================
   TailRef · Tur T Faz 6 — Arayüz paket formatı doğrulayıcı (SAF)
   ======================================================================
   Format: { format:"tailref-ui@1", meta{name,author,version,desc},
             tokens{--ui-*:değer}, rules[{selector, props{...}}] }
   GÜVENLİK KURALLARI (spec):
   - JS yürütme YOK: bu modül saf Object/JSON denetimi yapar; paketten
     kod ÇALIŞTIRILMAZ. CSS metni bu modülde BİZ üretiriz — paketin
     ham CSS'i asla belgeye girmaz.
   - Boyut limiti: paket ≤ 64 KB (MAX_BYTES).
   - Alan doğrulama: property whitelist, seçici/özellik karakter seti
     ({};@ ve url()/expression()/javascript: yasak).
   - Asset yalnız data:image/* URI (background-image); path yok.
   Bu dosya SAF'tır (DOM/localStorage YOK): hem app bundle'ında hem
   scripts/ui-package-validate.js CLI'ında aynı kod koşar.
   ====================================================================== */

(function () {
  const MAX_BYTES = 65536;          /* tek paket limiti */
  const MAX_RULES = 120;
  const MAX_TOKENS = 64;

  /* Property whitelist — sunum kimliği taşıyan güvenli küme.
     Arayüz paketi yerleşimi değiştiremez (position/display yasak),
     veri okuyamaz, davranışa giremez. */
  const PROP_ALLOW = new Set([
    'background', 'background-color', 'background-image',
    'color', 'opacity',
    'border', 'border-color', 'border-radius', 'border-width',
    'box-shadow', 'outline',
    'font-family', 'font-size', 'font-weight',
    'letter-spacing', 'text-transform',
    'min-height', 'height',
    'padding', 'gap',
  ]);

  const FORBIDDEN_IN_VALUE = ['url(', 'expression(', 'javascript:', 'import', '@import'];

  function err(errors, msg) { errors.push(msg); }

  function checkText(value, label, errors, max) {
    if (typeof value !== 'string') { err(errors, label + ' metin değil'); return; }
    if (value.length > max) { err(errors, label + ' çok uzun (>' + max + ')'); }
    /* CSS dil enjeksiyonu yüzeyi: {} ; @ ve ters bölü (CSS kaçış dizisi)
       belgeye bizim derleyicimizden girmedikçe zararsız olsa da doğrulama
       REDDEDER (hatasız paket ilkesi). Ters bölü olmadan `\7b` gibi bir
       kaçış dizisi `{` olarak çözülüp kural enjekte edebilirdi. */
    if (/[{};@\\]/.test(value)) { err(errors, label + ' yasaklı karakter'); return; }
    const low = value.toLowerCase();
    for (const bad of FORBIDDEN_IN_VALUE) {
      if (low.includes(bad)) { err(errors, label + ' yasaklı içerik: ' + bad); return; }
    }
  }

  /** background-image özel kuralı: yalnız 'none' veya data:image/* URI. */
  function checkBackgroundImage(value, errors) {
    if (value === 'none') return;
    const low = String(value).toLowerCase();
    if (!/^data:image\/(png|jpeg|gif|webp|svg\+xml);base64,[a-z0-9+/=]+$/.test(low)) {
      err(errors, 'background-image yalnız data:image/* URI veya none olabilir');
    }
  }

  /** Seçici: {} ; @ < ve ters bölü yasak — enjeksiyon yüzeyini kapatır. */
  function checkSelector(sel, errors) {
    if (typeof sel !== 'string' || !sel.trim()) { err(errors, 'boş seçici'); return; }
    if (sel.length > 120) { err(errors, 'seçici çok uzun'); return; }
    if (/[{};@<\\]/.test(sel)) { err(errors, 'seçicide yasaklı karakter'); return; }
  }

  /**
   * Paketi doğrular; geçerliyse derlenmiş CSS'i döner.
   * @param {*} pkg    çözümlenmiş JSON (Object olmalı)
   * @param {string} id belgeye yazılacak arayüz id'si (önek ui_)
   * @returns {{ok:true, css:string} | {ok:false, errors:string[]}}
   */
  function validate(pkg, id) {
    const errors = [];
    if (!pkg || typeof pkg !== 'object' || Array.isArray(pkg)) {
      return { ok: false, errors: ['paket nesne değil'] };
    }
    if (pkg.format !== 'tailref-ui@1') {
      return { ok: false, errors: ['format "tailref-ui@1" değil: ' + JSON.stringify(pkg.format).slice(0, 40)] };
    }
    const meta = pkg.meta;
    if (!meta || typeof meta !== 'object' || typeof meta.name !== 'string' || !meta.name.trim()) {
      return { ok: false, errors: ['meta.name zorunlu'] };
    }
    checkText(meta.name, 'meta.name', errors, 40);
    checkText(meta.author || '', 'meta.author', errors, 60);
    checkText(meta.desc || '', 'meta.desc', errors, 200);
    if (meta.version != null && !(typeof meta.version === 'number' && meta.version > 0)) {
      err(errors, 'meta.version pozitif sayı olmalı');
    }

    /* --- tokens: yalnız --ui-* özel özellikleri --- */
    const tokens = pkg.tokens || {};
    const tokenKeys = Object.keys(tokens);
    if (tokenKeys.length > MAX_TOKENS) err(errors, 'token sayısı > ' + MAX_TOKENS);
    let tokenCss = '';
    for (const key of tokenKeys) {
      if (!/^--ui-[a-z0-9-]{2,40}$/.test(key)) { err(errors, 'token adı whitelist dışı: ' + key); continue; }
      const value = tokens[key];
      checkText(value, 'token ' + key, errors, 200);
      if (typeof value === 'string' && !/[{};@\\]/.test(value)) {
        tokenCss += key + ':' + value + ';';
      }
    }

    /* --- rules: whitelisted property + güvenli değer (denetim turu) --- */
    const rules = Array.isArray(pkg.rules) ? pkg.rules : [];
    if (rules.length > MAX_RULES) err(errors, 'kural sayısı > ' + MAX_RULES);
    for (let i = 0; i < rules.length; i++) {
      const rule = rules[i];
      if (!rule || typeof rule !== 'object') { err(errors, 'kural #' + i + ' nesne değil'); continue; }
      checkSelector(rule.selector, errors);
      for (const prop of Object.keys(rule.props || {})) {
        const pl = String(prop).toLowerCase();
        if (!PROP_ALLOW.has(pl)) { err(errors, 'property whitelist dışı: ' + prop); continue; }
        const value = rule.props[prop];
        if (typeof value !== 'string') { err(errors, prop + ' değeri metin değil'); continue; }
        if (value.length > 300) { err(errors, prop + ' değeri çok uzun'); continue; }
        if (pl === 'background-image') { checkBackgroundImage(value, errors); }
        else checkText(value, prop + ' değeri', errors, 300);
      }
    }

    if (errors.length) return { ok: false, errors };

    /* --- derleme: bu modül CSS metnini kendisi üretir.
       Kurallar !important ile derlenir — sunum otoritesi emsali
       (skin otoritesi): ID'li temel kurallar paketi eziyordu.
       Tokenlar özel özellik olduğundan !important'suz. --- */
    let css = ':root[data-interface="' + id + '"]{' + tokenCss + '}';
    for (let i = 0; i < rules.length; i++) {
      const rule = rules[i];
      if (!rule || typeof rule !== 'object') continue;
      let props = '';
      for (const prop of Object.keys(rule.props || {})) {
        const pl = String(prop).toLowerCase();
        const value = rule.props[prop];
        if (typeof value !== 'string' || !PROP_ALLOW.has(pl)) continue;
        if (pl === 'background-image') {
          if (value !== 'none' && !/^data:image\//i.test(value)) continue;
        } else if (/[{};@\\]/.test(value)) continue;
        props += pl + ':' + value + '!important;';
      }
      /* ÖNEMLİ: önek ile seçici arasında torun kombinatoru (boşluk) ŞART —
         aksi hâlde compound selector olur ve hiçbir şeyi eşlemez. */
      if (props && !/[{};@<\\]/.test(rule.selector)) {
        css += ':root[data-interface="' + id + '"] ' + rule.selector + '{' + props + '}';
      }
    }
    return { ok: true, css };
  }

  window.tailrefUiPackageFormat = { validate, MAX_BYTES, PROP_ALLOW };
})();

'use strict';
/* ======================================================================
   TailRef · Tur T Faz 6 — Arayüz paket deposu + içe aktarım (DOM'lu)
   ======================================================================
   02d saf doğrulayıcıyı kullanır:
   - Depo: localStorage 'tailref-ui-packages' (JSON dizisi; her öğe
     ham paket). Boot'ta HER paket yeniden doğrulanır → bozulmuşsa
     sessizce düşer (self-heal).
   - Enjeksiyon: doğrulanmış paketin derlenmiş CSS'i
     <style data-ui-skin="<id>"> elementine yazılır (link gibi skin
     kaynağıdır; 02c apply() style skin'lerini de açıp kapatır).
   - Kayıt: window.tailrefInterfaces.register() + unregister().
   - İçe aktarım: Ayarlar → Interface → "Import .json" düğmesi;
     FileReader kullanılır — dosya yolu belgeye girmez (güvenlik).
   Depolama limitleri: paket ≤ 64 KB, depo toplam ≤ 256 KB.
   ====================================================================== */

(function () {
  const UI_PKG_KEY = 'tailref-ui-packages';
  const TOTAL_LIMIT = 256 * 1024;

  function readStore() {
    try {
      const raw = localStorage.getItem(UI_PKG_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    } catch { return []; }
  }
  function writeStore(arr) {
    try {
      localStorage.setItem(UI_PKG_KEY, JSON.stringify(arr));
      return true;
    } catch { return false; }
  }
  /** meta.name → güvenli id: ui_slate-test biçimi. */
  function slugId(name) {
    const slug = String(name).toLowerCase()
      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24) || 'ui';
    return 'ui_' + slug;
  }
  function injectStyle(id, css) {
    let style = document.querySelector('style[data-ui-skin="' + CSS.escape(id) + '"]');
    if (!style) {
      style = document.createElement('style');
      style.dataset.uiSkin = id;
      document.head.appendChild(style);
    }
    style.textContent = css;
    style.media = ''; /* görünür durumda */
    return style;
  }
  function bootstrap() {
    const store = readStore();
    let changed = false;
    for (let i = store.length - 1; i >= 0; i--) {
      const entry = store[i];
      if (!entry || typeof entry !== 'object' || typeof entry.text !== 'string') {
        store.splice(i, 1); changed = true; continue;
      }
      let pkg = null;
      try { pkg = JSON.parse(entry.text); } catch { /* bozuk */ }
      const res = window.tailrefUiPackageFormat.validate(pkg, entry.id);
      if (!res.ok) { store.splice(i, 1); changed = true; continue; }
      injectStyle(entry.id, res.css);
      window.tailrefInterfaces.register({
        id: entry.id,
        name: pkg.meta.name,
        desc: pkg.meta.desc || '',
        version: pkg.meta.version || 1,
      });
    }
    if (changed) writeStore(store);
  }
  /** Ham paket metnini doğrula → depola → enjekte et → kaydet. */
  function importText(text) {
    if (typeof text !== 'string' || !text.length) return { ok: false, errors: ['boş dosya'] };
    if (text.length > window.tailrefUiPackageFormat.MAX_BYTES) {
      return { ok: false, errors: ['paket 64 KB sınırını aşıyor'] };
    }
    let pkg = null;
    try { pkg = JSON.parse(text); } catch (e) {
      return { ok: false, errors: ['JSON çözülemedi: ' + String(e.message).slice(0, 80)] };
    }
    const metaName = pkg && pkg.meta && pkg.meta.name;
    let id = slugId(metaName);
    const existing = readStore();
    if (window.tailrefInterfaces.list().some(d => d.id === id) ||
        existing.some(e => e.id === id)) {
      return { ok: false, errors: ['aynı id zaten kurulu: ' + id] };
    }
    const res = window.tailrefUiPackageFormat.validate(pkg, id);
    if (!res.ok) return { ok: false, errors: res.errors.slice(0, 5) };
    let total = existing.reduce((n, e) => n + e.text.length + 32, 0) + text.length;
    if (total > TOTAL_LIMIT) return { ok: false, errors: ['paket deposu dolu (256 KB)'] };
    existing.push({ id, text });
    if (!writeStore(existing)) return { ok: false, errors: ['depo yazılamadı'] };
    injectStyle(id, res.css);
    window.tailrefInterfaces.register({
      id, name: pkg.meta.name, desc: pkg.meta.desc || '', version: pkg.meta.version || 1,
    });
    return { ok: true, id, name: pkg.meta.name };
  }
  /** Kurulu paket kaldır: etkinse classic'e dön, style'ı sök, kayıttan düş. */
  function removePackage(id) {
    const store = readStore();
    const idx = store.findIndex(e => e.id === id);
    if (idx < 0) return false;
    if (window.tailrefInterfaces.active() === id) {
      window.tailrefInterfaces.apply('classic');
    }
    const style = document.querySelector('style[data-ui-skin="' + CSS.escape(id) + '"]');
    if (style) style.remove();
    window.tailrefInterfaces.unregister(id);
    store.splice(idx, 1);
    writeStore(store);
    return true;
  }
  /** #settingsInterfacePackages içini kurulu paket satırlarıyla doldur. */
  function renderInstalled(box) {
    if (!box) return;
    const packages = readStore().map(e => e.id);
    const defs = (window.tailrefInterfaces.list() || [])
      .filter(d => d.packaged || packages.includes(d.id));
    box.replaceChildren();
    if (!defs.length) {
      const empty = document.createElement('span');
      empty.className = 'settingsThemeDraftHint';
      empty.textContent = 'No packages installed.';
      box.appendChild(empty);
      return;
    }
    for (const def of defs) {
      const row = document.createElement('div');
      row.className = 'uiPkgRow';
      const name = document.createElement('span');
      name.className = 'settingsThemeCardName';
      name.textContent = def.name;
      const tag = document.createElement('span');
      tag.className = 'settingsThemeCardTag';
      tag.textContent = 'v' + (def.version || 1) + ' · ' + def.id;
      name.appendChild(tag);
      row.appendChild(name);
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'settingsAction';
      btn.textContent = 'Remove';
      btn.dataset.uiPkg = def.id;
      btn.addEventListener('click', () => {
        if (removePackage(def.id)) {
          try { window.toast('Package removed: ' + def.name); } catch { /* sessiz */ }
          document.dispatchEvent(new CustomEvent('tailref-interface-changed',
            { detail: { removed: def.id } }));
        }
      });
      row.appendChild(btn);
      box.appendChild(row);
    }
  }

  /* Dış API */
  window.tailrefUiPackages = {
    importText, removePackage, renderInstalled, bootstrap, slugId,
  };

  /* Boot: depodaki paketleri yeniden doğrula + enjekte et + kaydet.
     02c'in setTimeout(0) apply'ından ÖNCE senkron koşmalı (bu script
     sıralı yüklendiği için öyle olur). */
  try { bootstrap(); } catch { /* sessiz — classic parite */ }

  /* Ayarlar içe aktarım düğmesi (varsa) bağla. */
  function bindImportButton() {
    const btn = document.getElementById('btnUiPackageImport');
    const file = document.getElementById('uiPackageFile');
    if (!btn || !file || btn.dataset.uiPkgBound) return;
    btn.dataset.uiPkgBound = '1';
    btn.addEventListener('click', () => file.click());
    file.addEventListener('change', () => {
      const f = file.files && file.files[0];
      if (!f) return;
      const reader = new FileReader();
      reader.onload = () => {
        const res = importText(String(reader.result || ''));
        if (res.ok) {
          try { window.toast('Package imported: ' + res.name); } catch { /* sessiz */ }
          document.dispatchEvent(new CustomEvent('tailref-interface-changed',
            { detail: { registered: res.id } }));
        } else {
          try { window.toast('Package rejected: ' + (res.errors[0] || 'invalid')); } catch { /* sessiz */ }
        }
        file.value = '';
      };
      reader.readAsText(f);
    });
  }
  setTimeout(bindImportButton, 0);
})();

/* TailRef app · coordinates, bounds, snapping */
'use strict';

function screenToWorld(p) {
  return {
    x: (p.x - state.view.x) / state.view.scale,
    y: (p.y - state.view.y) / state.view.scale,
  };
}

function itemCenter(it) {
  return { x: it.x + it.w / 2, y: it.y + (it.h || 0) / 2 };
}

/** Döndürülmüş kutunun dünya koordinatlarındaki köşeleri */
function itemCorners(it) {
  const c = itemCenter(it);
  const hw = it.w / 2, hh = (it.h || 0) / 2;
  const r = (it.rot || 0) * Math.PI / 180;
  const cos = Math.cos(r), sin = Math.sin(r);
  return [[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]].map(([px, py]) => ({
    x: c.x + px * cos - py * sin,
    y: c.y + px * sin + py * cos,
  }));
}

function boundsOf(items, pad = 0) {
  if (!items.length) return { x: 0, y: 0, w: 0, h: 0 };
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const it of items) {
    for (const p of itemCorners(it)) {
      minX = Math.min(minX, p.x); minY = Math.min(minY, p.y);
      maxX = Math.max(maxX, p.x); maxY = Math.max(maxY, p.y);
    }
  }
  return { x: minX - pad, y: minY - pad, w: (maxX - minX) + pad * 2, h: (maxY - minY) + pad * 2 };
}

/* ---------------- yapışma (snap) ----------------
   Sürüklenen fotoğraf(lar) yakındaki fotoğraflara yapışır:
   kenar kenara tam oturur, köşeler birbirine değer, ortalar hizalanır. */
const SNAP_SCREEN_PX = 16;   // ekran pikseli cinsinden yapışma mesafesi

/* Tahta yapışması (aday 9): hizalama kılavuzlarını "Snap on board"
   anahtarı açıp kapatır. Anahtar yoksa → açık (mevcut davranış). */
function boardSnapOn() {
  try { return localStorage.getItem('tailref-board-snap') !== '0'; } catch { return true; }
}
window.tailrefBoardSnapOn = boardSnapOn;

function itemBounds(it) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const p of itemCorners(it)) {
    minX = Math.min(minX, p.x); minY = Math.min(minY, p.y);
    maxX = Math.max(maxX, p.x); maxY = Math.max(maxY, p.y);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

/** b: hareket eden seçimin sınır kutusu; dönüş: {d: uygulanacak kaydırma, at: hizalama çizgisi, o: hedef} */
function snapDelta(b, others, axis) {
  const tol = SNAP_SCREEN_PX / state.view.scale;
  const mS = axis === 'x' ? b.x : b.y;
  const mE = mS + (axis === 'x' ? b.w : b.h);
  const mM = (mS + mE) / 2;

  let best = null, bestAt = 0, bestO = null, bestType = 'align';
  const take = (d, at, o, type) => {
    if (Math.abs(d) <= tol && (best === null || Math.abs(d) < Math.abs(best))) {
      best = d; bestAt = at; bestO = o; bestType = type;
    }
  };

  for (const o of others) {
    const ob = itemBounds(o);
    const oS = axis === 'x' ? ob.x : ob.y;
    const oE = oS + (axis === 'x' ? ob.w : ob.h);
    const oM = (oS + oE) / 2;
    take(oE - mS, oE, o, 'contact');   // sol/üst kenar, diğerinin sağ/alt kenarına değer
    take(oS - mE, oS, o, 'contact');   // sağ/alt kenar, diğerinin sol/üst kenarına değer
    take(oS - mS, oS, o, 'align');     // aynı hizada (sol/sol)
    take(oE - mE, oE, o, 'align');     // aynı hizada (sağ/sağ)
    take(oM - mM, oM, o, 'align');     // ortalar aynı hizada
  }
  return { d: best || 0, at: bestAt, o: bestO, type: best === null ? null : bestType };
}

/* --- yapışma geri bildirimi: ince kılavuz çizgi + birleşme yerinde ışın --- */
const snapGuidesEl = $('#snapGuides');
const sgV = snapGuidesEl.querySelector('.sg.v');
const sgH = snapGuidesEl.querySelector('.sg.h');
let snapBeamKey = '';

function hideSnapFeedback() {
  sgV.hidden = true;
  sgH.hidden = true;
  snapBeamKey = '';
}

/** Sadece gerçekten birbirine değen kenarlar için dikiş (ışın) üretir */
function contactBeams(box, other, eps = 0.75) {
  const ob = itemBounds(other);
  const out = [];
  const oy1 = Math.max(box.y, ob.y), oy2 = Math.min(box.y + box.h, ob.y + ob.h);
  const ox1 = Math.max(box.x, ob.x), ox2 = Math.min(box.x + box.w, ob.x + ob.w);

  // dikey dikiş (yan yana duran fotoğraflar)
  let vx = null;
  if (Math.abs(box.x + box.w - ob.x) <= eps) vx = ob.x;
  else if (Math.abs(ob.x + ob.w - box.x) <= eps) vx = box.x;
  if (vx !== null && oy2 >= oy1 - eps) out.push({ dir: 'v', at: vx, a: oy1, b: oy2, o: other });

  // yatay dikiş (üst üste duran fotoğraflar)
  let hy = null;
  if (Math.abs(box.y + box.h - ob.y) <= eps) hy = ob.y;
  else if (Math.abs(ob.y + ob.h - box.y) <= eps) hy = box.y;
  if (hy !== null && ox2 >= ox1 - eps) out.push({ dir: 'h', at: hy, a: ox1, b: ox2, o: other });

  return out;
}

function addSnapBeam(beam) {
  const sc = state.view.scale, vx = state.view.x, vy = state.view.y;
  const el = document.createElement('i');
  el.className = 'snapBeam ' + beam.dir;
  const len = Math.max(0, (beam.b - beam.a) * sc);
  if (beam.dir === 'v') {
    const x = beam.at * sc + vx;
    const y = beam.a * sc + vy;
    el.style.left = (x - 1) + 'px';
    el.style.top = y + 'px';
    el.style.height = Math.max(3, len) + 'px';
  } else {
    const x = beam.a * sc + vx;
    const y = beam.at * sc + vy;
    el.style.left = x + 'px';
    el.style.top = (y - 1) + 'px';
    el.style.width = Math.max(3, len) + 'px';
  }
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 560);
}

function showSnapFeedback(b, sx, sy, others) {
  const hasX = !!(sx && sx.d), hasY = !!(sy && sy.d);
  const sc = state.view.scale, vx = state.view.x, vy = state.view.y;
  const pad = 16;   // çizginin uçlarda sönmesi için pay (ekran pikseli)

  if (hasX) {
    sgV.hidden = false;
    sgV.style.left = (sx.at * sc + vx) + 'px';
    // çizgi sonsuza kadar gitmesin: sadece hizalanan fotoğrafların boyu kadar
    let y1 = b.y + (sy ? sy.d : 0);
    let y2 = y1 + b.h;
    if (sx.o) {
      const ob = itemBounds(sx.o);
      y1 = Math.min(y1, ob.y);
      y2 = Math.max(y2, ob.y + ob.h);
    }
    sgV.style.top = (y1 * sc + vy - pad) + 'px';
    sgV.style.height = Math.max(10, (y2 - y1) * sc + pad * 2) + 'px';
  } else sgV.hidden = true;

  if (hasY) {
    sgH.hidden = false;
    sgH.style.top = (sy.at * sc + vy) + 'px';
    let x1 = b.x + (sx ? sx.d : 0);
    let x2 = x1 + b.w;
    if (sy.o) {
      const ob = itemBounds(sy.o);
      x1 = Math.min(x1, ob.x);
      x2 = Math.max(x2, ob.x + ob.w);
    }
    sgH.style.left = (x1 * sc + vx - pad) + 'px';
    sgH.style.width = Math.max(10, (x2 - x1) * sc + pad * 2) + 'px';
  } else sgH.hidden = true;

  // yapıştıktan sonraki gerçek kutu; sadece gerçekten temas eden kenarlar ışık verir
  const box = {
    x: b.x + (sx ? sx.d : 0),
    y: b.y + (sy ? sy.d : 0),
    w: b.w, h: b.h,
  };
  const seen = new Set();
  const beams = [];
  for (const o of (others || [])) {
    for (const bm of contactBeams(box, o)) {
      const k = bm.dir + ':' + Math.round(bm.at) + ':' + Math.round(bm.a) + ':' + Math.round(bm.b);
      if (seen.has(k)) continue;
      seen.add(k);
      beams.push(bm);
    }
  }
  if (!beams.length) { snapBeamKey = ''; return; }

  const key = beams.map(bm => bm.o.id + ':' + bm.dir + ':' + Math.round(bm.at)).join('|');
  if (key === snapBeamKey) return;   // aynı dikiş sürüyor: tekrar çakmasın
  snapBeamKey = key;
  for (const bm of beams) addSnapBeam(bm);
}

/* TailRef app · save, backup, undo/redo, view transform */
'use strict';

/* =========================================================
   kayıt / geri al
   ========================================================= */
/* =========================================================
   kalıcılık modu (.tail)
   ---------------------------------------------------------
   auto:    her değişiklikte IndexedDB'ye kaydet, açılışta geri yükle.
   manual:  yalnızca Ctrl+S ile .tail dosyasına kaydet; otomatik kayıt/yedek kapalı.
   localStorage boşsa (ilk açılış) auto varsayılır; karşılama diyaloğu seçim yaptırır.
   scheduleSave ve autoBackup buradan geçer — tek noktadan geçit.
   ========================================================= */
const PERSISTENCE_KEY = 'tailref-persistence';
function getPersistenceMode() {
  const m = localStorage.getItem(PERSISTENCE_KEY);
  return m === 'manual' ? 'manual' : 'auto';
}
function isPersistenceAuto() { return getPersistenceMode() !== 'manual'; }
function hasChosenPersistence() { return !!localStorage.getItem(PERSISTENCE_KEY); }
function setPersistenceMode(mode) {
  localStorage.setItem(PERSISTENCE_KEY, mode === 'manual' ? 'manual' : 'auto');
  syncPersistenceUI();
  /* Manuel modda otomatik yedek zamanlayıcısını da durur; otomatik modda eski
     aralığa döner. Aralık ayarı diske yazılmaz: mod değişimi kullanıcının
     seçtiği yedekleme sıklığını sıfırlamamalı. */
  configureBackupInterval(isPersistenceAuto()
    ? Number(localStorage.getItem('tailref-backup-interval') || 5)
    : 0, false);
  /* Mod değişiminde veri kaybı penceresini kapat: manuelden otomatiğe
     geçince canlı tahtayı hemen diske yaz (uygulama çökse bile geri gelir)
     ve canlı çalışma alanında olmayan eski pano kayıtlarını temizle;
     otomatikten manuele geçerken bekleyen yazımı iptal et. */
  if (isPersistenceAuto()) {
    if (typeof appReady !== 'undefined' && appReady && typeof saveNow === 'function') {
      Promise.resolve().then(async () => {
        try {
          await saveNow();
          if (typeof pruneStaleStoredBoards === 'function') await pruneStaleStoredBoards();
        } catch { /* kullanıcıya saveNow zaten bildirir */ }
      });
    }
  } else {
    clearTimeout(saveTimer);
    saveTimer = null;
  }
}

function scheduleSave() {
  if (!isPersistenceAuto()) return;
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveNow, SAVE_DEBOUNCE);
}

/* İçe aktarma + location.reload() yarışı: importBackupPayload diske yazar,
   hemen ardından pagehide/visibilitychange flushSave() çalışır ve CANLI
   (eski) tahtayı import edilen verinin üstüne yazardı. Bayrak set edilince
   hem saveNow hem flushSave susar; sayfa yenilenince modül sıfırlanır.
   Import başarısız olursa bayrak geri alınır ki otomatik kayıt devam etsin. */
let persistenceSuspendedForReload = false;
function suspendPersistenceForReload() {
  persistenceSuspendedForReload = true;
  clearTimeout(saveTimer);
  saveTimer = null;
  pendingStateJSON = null;
  pendingProjectRecord = null;
}
function resumePersistenceAfterFailedImport() {
  persistenceSuspendedForReload = false;
  if (appReady) scheduleSave();
}

/* Kayıt hatası sessiz kalmasın: depo dolu/izinsiz olduğunda kullanıcı
   "otomatik modda her şey kaydediliyor" sanmasın. Aynı mesajı oturumda
   bir kez göster (art arda hata yağmuru olmasın). */
let persistenceErrorNotified = false;
function notifyPersistenceError() {
  if (persistenceErrorNotified) return;
  persistenceErrorNotified = true;
  try {
    if (typeof showProjectNotice === 'function') {
      showProjectNotice(__t('Changes could not be saved to this device. Storage may be full.'), 9000);
    }
  } catch { /* sessiz */ }
}

/* Manuel mod: dosya kaydedildikten/ açıldıktan sonraki durumun imzası.
   Kapanışta canlı durum bu imzayla aynıysa "kaydedilmemiş değişiklik" yoktur
   ve boşuna "kaydet?" sorulmaz. Olay saymak yerine gerçek durumu karşılaştırır;
   böylece bir değişiklik yolu scheduleSave çağırmayı unutsa bile veri kaybı
   riski yoktur (imza değişir → soru sorulur). */
let manualSavedHash = null;
function manualStateSignature() {
  if (typeof createStateSnapshot !== 'function') return '';
  const projects = [];
  if (typeof workspaceManager !== 'undefined' && workspaceManager && workspaceManager.ready) {
    for (const id of workspaceManager.order) {
      const project = workspaceManager.projects.get(id);
      if (!project) continue;
      projects.push({ id: project.id, name: project.name, state: project.snapshot });
    }
  }
  const camera = typeof captureCameraTransform === 'function' ? captureCameraTransform() : null;
  const pose = typeof capturePose3d === 'function' ? capturePose3d() : null;
  return JSON.stringify({ state: createStateSnapshot(), projects, camera, pose });
}
function markManualClean() {
  manualSavedHash = manualStateSignature();
}

/* Manuel modda gcImages kapalıdır (diskteki otomatik panolara ait görseller
   silinmesin diye). Bu yüzden arka arkaya dosya açıp kapatan kullanıcıda
   görseller IDB'de birikiyordu. Yalnızca BAŞARILI bir .tail kaydından sonra
   çalışır: dosya, o an panolardaki tüm görselleri kendi içine gömdüğü için
   kalan sahipsiz kayıtları silmek güvenlidir. Geri al/yinele yığınlarındaki
   görseller korunur. */
let imagePruneInFlight = false;
async function pruneUnusedImagesNow() {
  if (imagePruneInFlight) return 0;
  if (typeof inUseImageIds !== 'function') return 0;
  if (typeof imageWriteInFlight !== 'undefined' && imageWriteInFlight > 0) return 0;
  imagePruneInFlight = true;
  try {
    const used = inUseImageIds();
    if (typeof collectWorkspaceImageIds === 'function') collectWorkspaceImageIds(used);
    /* Diskte duran ama bu oturumda yüklü olmayan panoların görsellerini de
       koru: kullanıcı otomatik moda dönerse o panolar geri gelir. (Anahtar
       sabiti 26-projects.js'te tanımlı; burada yükleme sırasında erişmemek
       için düz metin kullanılıyor.) */
    try {
      for (const [key, value] of await idbEntries('meta')) {
        const k = String(key);
        let record = null;
        if (k.startsWith('project:')) record = value;
        else if (k === 'state') { try { record = JSON.parse(value); } catch { record = null; } }
        const snapshot = record && (record.state || record.snapshot || record);
        for (const item of (snapshot && snapshot.items) || []) {
          if (item && item.kind === 'image' && item.imageId) used.add(item.imageId);
        }
      }
    } catch { /* sessiz */ }
    for (const json of [...undoStack, ...redoStack]) {
      try {
        const snap = JSON.parse(json);
        for (const item of (snap && snap.items) || []) {
          if (item && item.kind === 'image' && item.imageId) used.add(item.imageId);
        }
      } catch { /* bozuk anlık görüntü */ }
    }
    let removed = 0;
    for (const [key] of await idbEntries('images')) {
      /* Temizlik sürerken yeni görsel yazımı başladıysa dur. */
      if (typeof imageWriteInFlight !== 'undefined' && imageWriteInFlight > 0) return removed;
      if (used.has(key)) continue;
      await idbDel('images', key);
      removed++;
    }
    return removed;
  } finally {
    imagePruneInFlight = false;
  }
}

/* ---------------- arka plan opaklığı ---------------- */
/** Slider'ın içindeki yüzde etiketini thumb'ı takip edecek şekilde günceller. */
function paintOpacityValue(p) {
  const val = document.getElementById('bgOpacityVal');
  if (!val) return;
  const pct = Math.round(clamp(p, 0, 1) * 100);
  val.textContent = pct + '%';
  // Sağ uca yaklaşınca etiket thumb'ın soluna geçer (taşmasın).
  val.classList.toggle('is-left', p > 0.72);
  // Tooltip kaldırıldı: değer slider'ın altındaki yüzde etiketinde duruyor.
  // Ekran okuyucular için aria-label güncel kalsın.
  const box = document.getElementById('opacityCtl');
  if (box) {
    box.setAttribute('aria-label', 'Opacity: %' + pct);
  }
}

function applyBackdrop() {
  const v = typeof state.bg === 'number' ? state.bg : 1;
  backdropEl.style.opacity = String(v);
  const slider = $('#bgOpacity');
  if (slider && document.activeElement !== slider) slider.value = Math.round(v * 100);
  syncRangeFill(slider);
  paintOpacityValue(v);
}

function setBg(v, save = true) {
  state.bg = clamp(v, 0, 1);
  applyBackdrop();
  if (save) scheduleSave();
}

let pendingProjectRecord = null;
/* Başarılı her IndexedDB yazımında artar (bkz. autoBackup: boşta yedek yok). */
let saveSerial = 0;

async function saveNow() {
  /* Manuel modda otomatik IndexedDB kaydı yok — yalnızca .tail dosyası kalıcıdır.
     importBackupPayload (.tail açma) bu fonksiyonu kullanmaz; doğrudan idbPut yapar. */
  if (!isPersistenceAuto()) return;
  /* İçe aktarma sonrası yeniden yükleme sırasında canlı (eski) tahta
     import edilen kaydın üstüne yazılmasın. */
  if (persistenceSuspendedForReload) return;
  clearTimeout(saveTimer);
  /* Debounce kimliğini de temizle: aksi halde "bekleyen kayıt var mı?"
     kontrolü (autoBackup boşta atlama) süresi dolmuş bir zamanlayıcıyı
     hâlâ bekliyor sanır. */
  saveTimer = null;
  // Pano mimarisi hazırsa anlık görüntüyü panoya özel kayıtla birlikte
  // hazırla; kamera/poz verisi de bu karede dondurulur.
  const staged = typeof stageActiveProjectSave === 'function' ? stageActiveProjectSave() : null;
  pendingStateJSON = staged ? staged.json : JSON.stringify(createStateSnapshot());
  pendingProjectRecord = staged || null;
  if (saveInFlight) return saveInFlight;

  saveInFlight = (async () => {
    while (pendingStateJSON !== null) {
      const json = pendingStateJSON;
      const project = pendingProjectRecord;
      pendingStateJSON = null;
      pendingProjectRecord = null;
      try {
        const saveT0 = performance.now();
        await idbPut('meta', 'state', json);
        if (project) await persistStagedProject(project);
        /* Teşhis paneli (Ctrl+Alt+P) için son kaydın süresi ve boyutu. */
        try {
          window.__tailrefLastSaveStats = {
            ms: Math.round((performance.now() - saveT0) * 10) / 10,
            kb: Math.round(new TextEncoder().encode(json).byteLength / 1024),
          };
        } catch { /* sessiz */ }
        flashStatus();
        /* Değişmezlik sayacı: otomatik yedek zamanlayıcısı, son yedekten
           beri gerçekten yeni bir kayıt yazıldı mı diye buna bakar. Boşta
           duran uygulamada her 5 dakikada aynı panoyu diske yazmayı önler. */
        saveSerial++;
      } catch (e) {
        console.warn('could not save', e);
        notifyPersistenceError();
        /* Bu değişiklik diske yazılamadı: yedek zamanlayıcısı "değişiklik
           yok" diyip geçmesin, bir sonraki turda disk yedeği denensin. */
        lastBackupSerial = -1;
      }
    }
  })().finally(() => {
    saveInFlight = null;
  });

  return saveInFlight;
}

/* Bekleyen debounce'u iptal edip mevcut durumu hemen diske yazar.
   Pencere kapanırken ve sekme gizlenirken çağrılır. */
async function flushSave() {
  if (!appReady || !db) return;
  if (persistenceSuspendedForReload) return;
  clearTimeout(saveTimer);
  saveTimer = null;
  try {
    await saveNow();
    if (saveInFlight) await saveInFlight;
  } catch (e) {
    console.warn('Emergency save failed', e);
  }
}

/* ---------------- otomatik yedek ---------------- */
function blobAsDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = () => reject(r.error);
    r.readAsDataURL(blob);
  });
}

/* ---------------- .tail dosyası (manuel kayıt modu) ----------------
   autoBackup ile aynı payload biçimi; tek fark diske tek bir sıkıştırılmış
   dosya yazılmasıdır. gzip ana süreçte uygulanır (renderer'ı bloklamaz). */
/** Yedeğe girecek görseller: yalnızca panolarda (canlı tahta, çöp, açık
    panolar) gerçekten referanslanan kimlikler. IDB'de unutulmuş sahipsiz
    görseller .tail/yedek dosyasını şişirmez; manuel modda gcImages
    çalışmadığı için bu filtre olmadan dosya her kayıtta büyüyordu. */
function collectSavableImageIds() {
  const used = typeof inUseImageIds === 'function' ? inUseImageIds() : new Set();
  /* .tail ve yedek dosyaları geri al/yinele yığınlarını taşımaz; yalnızca
     panolarda/çöpte görünen görseller gerekir. Geçmişi de katan liste,
     dosyaya hiç görünmeyen "hayalet" görseller ekliyordu (şişkinlik).
     gcImages ayrı yoldur ve geçmişi korumaya devam eder. */
  if (typeof collectWorkspaceImageIds === 'function') collectWorkspaceImageIds(used, false);
  return used;
}

/* Panoya bağlı görselleri data URL'e çevirir. Sıralı FileReader zinciri çok
   görselli panolarda kaydı uzatıyordu; 4'lü gruplarla paralel okunur. */
async function collectBoardImages() {
  const usedImages = collectSavableImageIds();
  const entries = (await idbEntries('images')).filter(([id, rec]) =>
    !!(rec && rec.blob && usedImages.has(id)));
  const encoded = await mapInBatches(entries, 4, async ([id, rec]) => {
    try {
      return { id, name: rec.name || 'image', dataUrl: await blobAsDataUrl(rec.blob) };
    } catch (e) {
      console.warn('backup image could not be encoded', id, e);
      return null;
    }
  });
  /* Fotoğrafı kodlanamayan pano "eksiksiz" diye işaretlenmemeli: aksi halde
     dosyayı yeniden açan kullanıcının IndexedDB'sindeki sağlam kopya,
     temizlik sırasında silinirdi. */
  return { images: encoded.filter(Boolean), complete: encoded.every(Boolean) };
}

/** .tail ve otomatik yedek için tek ortak gövde. */
async function buildBoardPayload() {
  const workspace = workspaceManager && workspaceManager.ready
    ? workspaceManager.serializeWorkspace()
    : null;
  const imageData = await collectBoardImages();
  return {
    version: 2, createdAt: new Date().toISOString(),
    state: createStateSnapshot(), workspace,
    images: imageData.images,
    /* Görsel listesi eksiksiz mi? .tail/yedek yazarken true; acil kopyalar
       görselleri bilerek dışarıda bıraktığı için bu bayrağı koymaz, böylece
       içe aktarmada IndexedDB görselleri yanlışlıkla silinmez. */
    imagesComplete: imageData.complete,
  };
}

async function buildTailPayload() {
  /* Manuel modda saveNow() diske yazmaz; yine de etkin panonun anlık
     görüntüsü .tail dosyasına yansımalı. */
  if (workspaceManager && workspaceManager.activeProject) {
    workspaceManager.activeProject.capture();
  }
  await saveNow();
  return buildBoardPayload();
}

let tailSaveInFlight = false;
async function saveAsTail() {
  if (!window.tailref || !window.tailref.saveTail) return false;
  /* Ctrl+S'ye üst üste basmak iki yerel kayıt kutusu açıyordu; tek uçuş. */
  if (tailSaveInFlight) return false;
  tailSaveInFlight = true;
  try {
    const payload = await buildTailPayload();
    const project = workspaceManager && workspaceManager.activeProject
      ? workspaceManager.activeProject.name : '';
    const suggested = (project || 'board').replace(/[\\/:*?"<>|]/g, '_').slice(0, 80) || 'board';
    const res = await window.tailref.saveTail(JSON.stringify(payload), suggested);
    if (res && res.ok) {
      showProjectNotice(__t('Board saved: ') + res.file, 4000);
      markManualClean();
      /* Dosya artık panodaki tüm görselleri içeriyor: IDB'de birikmiş
         sahipsiz görselleri temizle (bkz. pruneUnusedImagesNow). */
      pruneUnusedImagesNow().catch(() => { /* sessiz */ });
      return true;
    }
    if (res && res.canceled) return false; // kullanıcı iptal etti
    showProjectNotice(__t('Could not save: ') + (res && res.error || __t('unknown error')), 6000);
    return false;
  } catch (e) {
    showProjectNotice(__t('Could not save: ') + e.message, 6000);
    return false;
  } finally {
    tailSaveInFlight = false;
  }
}

async function openTailFile() {
  if (!window.tailref || !window.tailref.openTail) return false;
  try {
    const res = await window.tailref.openTail();
    if (!res || !res.ok) {
      if (res && res.canceled) return false;
      showProjectNotice('Could not open: ' + (res && res.error || 'hata'), 6000);
      return false;
    }
    /* Otomatik modda panolar yedekli olduğundan ve açma öncesi son hâl
       diske yazıldığından onay sorulmaz; manuel modda dosya tek kalıcı
       depo olduğu için sorulur (sürükle-bırak yoluyla aynı sözleşme). */
    if (!isPersistenceAuto() &&
        !(await appConfirm(__t('This file will be loaded in place of the current boards. Continue?')))) return false;
    /* Açma mevcut panoların üzerine yazar. Otomatik modda son hâli diske
       yaz (yedekler zaten var); manuel modda otomatik yedek olmadığı için
       canlı durumun acil kopyasını al — yanlış dosya seçilirse geri dönüş
       noktası kalsın. */
    if (isPersistenceAuto()) await flushSave();
    else await saveEmergencyCopy(true);
    /* Import sürerken ve reload sırasında pagehide flush'ı eski tahtayı
       import edilen kaydın üstüne yazmasın. */
    suspendPersistenceForReload();
    try {
      await importBackupPayload(res.payload);
    } catch (importError) {
      resumePersistenceAfterFailedImport();
      throw importError;
    }
    location.reload();
    return true;
  } catch (e) {
    showProjectNotice('Could not open .tail: ' + e.message, 6000);
    return false;
  }
}

let backupInFlight = false;
/* Son başarılı yedekteki saveSerial. Zamanlayıcı boştayken aynı panoyu
   tekrar tekrar diske yazmasın: yalnızca yeni kayıt varsa yedek alınır.
   -1 = bu oturumda henüz yedek yok (açılıştaki ilk yedek her zaman alınır). */
let lastBackupSerial = -1;
/* Ana süreçteki sağlık kontrolü için pano öğesi sayısı (dosyayı yeniden
   okuyup JSON.parse etmesin). */
function boardItemCount(payload) {
  let total = 0;
  const workspace = payload && payload.workspace;
  if (workspace && Array.isArray(workspace.projects) && workspace.projects.length) {
    for (const record of workspace.projects) {
      const snapshot = record && record.state;
      if (snapshot && Array.isArray(snapshot.items)) total += snapshot.items.length;
    }
  } else if (payload && payload.state && Array.isArray(payload.state.items)) {
    total += payload.state.items.length;
  }
  return total;
}
/* Yedek saklama sınırı (aday 4): localStorage 'tailref-backup-limit' —
   yoksa/bozuksa undefined döner ve main eski sabit 20'yi kullanır (parite). */
function backupLimitFromSettings() {
  try {
    const raw = localStorage.getItem('tailref-backup-limit');
    if (raw === null || raw === '') return undefined;
    const n = Number(raw);
    if (Number.isFinite(n) && n >= 1) return Math.floor(n);
  } catch { /* sessiz — özel mod vb. */ }
  return undefined;
}
async function autoBackup() {
  if (!isPersistenceAuto()) return;
  if (backupInFlight || !window.tailref || !window.tailref.autoBackup) return;
  /* Son yedekten beri yeni kayıt yoksa disk yazımı yapma. Uçuşta bir kayıt
     varsa (saveInFlight/pending) bu bir değişikliktir: yedek alınır. */
  if (lastBackupSerial >= 0 && saveSerial === lastBackupSerial &&
      !saveInFlight && pendingStateJSON === null && saveTimer === null) {
    return;
  }
  backupInFlight = true;
  try {
    await saveNow();
    /* Yedeğe giren kaydın serisini sabitle: payload hazırlanırken yeni bir
       kayıt oluşursa (saveSerial artar) bir sonraki tur yine yedek alır. */
    const serialAtBackup = saveSerial;
    const payload = await buildBoardPayload();
    const res = await window.tailref.autoBackup(
      JSON.stringify(payload),
      backupLimitFromSettings(),
      { items: boardItemCount(payload), images: payload.images.length }
    );
    /* Ana süreç yazamadıysa (disk dolu/izin) sessiz kalma. */
    if (res && res.ok === false) {
      console.warn('auto backup failed', res.error);
      notifyPersistenceError();
    } else {
      lastBackupSerial = serialAtBackup;
    }
  } catch (e) {
    console.warn('auto backup could not be created', e);
    notifyPersistenceError();
  } finally {
    backupInFlight = false;
  }
}

let backupTimer = null;
function configureBackupInterval(minutes, persist = true) {
  clearInterval(backupTimer);
  backupTimer = null;
  const n = Number(minutes);
  if (n > 0) backupTimer = setInterval(autoBackup, n * 60 * 1000);
  /* `persist=false` yalnızca mod değişiminde kullanılır: manuel moda geçerken
     aralığı 0 yazmak, otomatik moda dönünce yedeklemeyi kapatıyordu. */
  if (persist) {
    try { localStorage.setItem('tailref-backup-interval', String(n)); } catch { /* sessiz */ }
  }
}
/* Açılışta moda göre zamanlayıcı kur; kayıtlı aralık ayarını değiştirme. */
configureBackupInterval(
  isPersistenceAuto() ? Number(localStorage.getItem('tailref-backup-interval') || 5) : 0,
  false
);

let flashTimer = null;
function flashStatus() {
  setItemCountLabel();
}

function itemLabel() {
  const imgs  = state.items.filter(i => i.kind === 'image').length;
  const texts = state.items.filter(i => i.kind === 'text').length;
  if (!imgs && !texts) return __t('0 items');
  const parts = [];
  if (imgs)  parts.push(imgs + ' ' + __t('image'));
  if (texts) parts.push(texts + ' ' + __t('text'));
  return parts.join(' · ');
}
/* Dil değişince sayaç etiketi (dinamik yazım) yeniden çevrilsin. */
if (window.L10N && window.L10N.onChange) {
  window.L10N.onChange(() => { try { setItemCountLabel(); } catch { /* sessiz */ } });
}

/* Önceden alınmış bir anlık görüntüyü yığına yazar. Sürükleyici
   (slider) etkileşimlerinde snapshot pointerdown anında alınır ama
   yalnız ilk gerçek değişiklikte yığına girer: kaydırıcıya sadece
   dokunmak boş bir geri-alma adımı bırakmaz. */
function pushUndoRaw(snap) {
  undoStack.push(snap);
  /* Adım sınırı kullanıcı ayarından (tailref-undo-steps); boşsa mevcut
     60. while: sınır düşürüldüğünde fazla kayıtlar hemen boşaltılır. */
  const undoLimit = (typeof tailrefUndoLimit === 'function') ? tailrefUndoLimit(60) : 60;
  while (undoStack.length > undoLimit) {
    const dropped = undoStack.shift();
    if (typeof inkUndoRasterDropRaw === 'function') inkUndoRasterDropRaw(dropped);
    if (typeof maskSnapReleaseRaw === 'function') maskSnapReleaseRaw(dropped);
  }
  if (redoStack.length) {
    if (typeof inkUndoRasterDropStack === 'function') inkUndoRasterDropStack(redoStack);
    if (typeof maskSnapReleaseStack === 'function') maskSnapReleaseStack(redoStack);
    redoStack.length = 0;
  }
}

function pushUndo() {
  const t0 = performance.now();
  /* A3 devamı: maske src tokenize — snapshot'ta yalnız srcRef kalır. */
  const snap = maskSnapStringify(createStateSnapshot());
  pushUndoRaw(snap);
  if (typeof inkPerfSpan === 'function') {
    inkPerfSpan('undoSnap', performance.now() - t0);
    inkPerfCount('undoSnapBytes', snap.length);
  }
}

/** Sürüp bitirilmemiş vuruşu iptal eder. Kullanıcı kalem hâlâ basılıyken
    Ctrl+Z'ye basarsa geri alma önceki kayda iner, sonra pointerup geçerli
    vuruşu yeniden ekliyordu; vuruş "geri alınmamış" gibi görünüyordu. */
function undoCancelActiveStroke() {
  try {
    if (typeof inkEditorIsOpen === 'function' && inkEditorIsOpen() &&
        typeof inkEditorUi !== 'undefined' && inkEditorUi) {
      if (inkEditorUi.gizmoDrag || inkEditorUi.marquee || inkEditorUi.lasso) {
        if (typeof inkEditorCancelSelection === 'function') inkEditorCancelSelection();
      } else if (inkEditorUi.stroke && typeof inkEditorDropStroke === 'function') {
        inkEditorDropStroke();
      }
    }
  } catch { /* sessiz */ }
  try {
    if (typeof inkPointer !== 'undefined' && inkPointer && typeof inkCancelStroke === 'function') {
      inkCancelStroke();
    }
  } catch { /* sessiz */ }
}

function undo() {
  undoCancelActiveStroke();
  // Bozuk ya da bayat (vuruşu artık bulunmayan) kayıtlar sessizce yutulur;
  // kullanıcı Ctrl+Z'ye bastığında hiçbir şey olmaması yerine bir önceki
  // geçerli kayda düşülür. Hiçbir kayıt uygulanamazsa (yığın boş ya da
  // tamamen bayat) görünür bildirim gösterilir — sessiz ölüm yok.
  let guard = 0;
  let applied = false;
  while (undoStack.length && guard++ < 12) {
    const raw = undoStack.pop();
    let parsed = null;
    try { parsed = JSON.parse(raw); } catch { continue; }
    // Vuruş commit'leri delta kaydı tutar: tüm panoyu yeniden kurmaya gerek yok.
    const delta = typeof inkStrokeEntry === 'function' ? inkStrokeEntry(parsed) : null;
    if (delta) {
      if (typeof inkApplyStrokeEntry === 'function' && inkApplyStrokeEntry(delta, 'undo')) {
        redoStack.push(raw);
        applied = true;
        return;
      }
      if (typeof inkUndoRasterDropRaw === 'function') inkUndoRasterDropRaw(raw);
      if (typeof maskSnapReleaseRaw === 'function') maskSnapReleaseRaw(raw);
      continue;
    }
    // Artımlı geri yükleme için önceki çizim durumunu sakla: yalnızca
    // gerçekten değişen katman/bölge yeniden raster edilir.
    const prevInk = state.ink;
    /* Kamera (yakınlaştırma/kaydırma) geri-alınacak bir düzenleme değil:
       snapshot'taki görünüm uygulanırsa son işlemden sonra yakınlaştıran
       kullanıcının görünümü Ctrl+Z'de eski yerine sıçrar. Görünüm korunur. */
    const keepView = state.view;
    redoStack.push(maskSnapStringify(createStateSnapshot()));
    restoreSnapshot(parsed);
    state.view = keepView;
    selection.clear();
    editingId = null;
    applyView(); applyBackdrop(); syncAll(); scheduleSave();
    if (typeof inkAfterRestore === 'function') inkAfterRestore(prevInk);
    applied = true;
    return;
  }
  if (!applied && typeof showProjectNotice === 'function') {
    showProjectNotice('Nothing to undo', 1600);
  }
}

function redo() {
  undoCancelActiveStroke();
  /* undo() ile aynı sözleşme: hiçbir kayıt uygulanamazsa görünür bildirim. */
  let guard = 0;
  let applied = false;
  while (redoStack.length && guard++ < 12) {
    const raw = redoStack.pop();
    let parsed = null;
    try { parsed = JSON.parse(raw); } catch { continue; }
    const delta = typeof inkStrokeEntry === 'function' ? inkStrokeEntry(parsed) : null;
    if (delta) {
      if (typeof inkApplyStrokeEntry === 'function' && inkApplyStrokeEntry(delta, 'redo')) {
        undoStack.push(raw);
        applied = true;
        return;
      }
      if (typeof inkUndoRasterDropRaw === 'function') inkUndoRasterDropRaw(raw);
      if (typeof maskSnapReleaseRaw === 'function') maskSnapReleaseRaw(raw);
      continue;
    }
    const prevInk = state.ink;
    const keepView = state.view;
    undoStack.push(maskSnapStringify(createStateSnapshot()));
    restoreSnapshot(parsed);
    state.view = keepView;
    selection.clear();
    editingId = null;
    applyView(); applyBackdrop(); syncAll(); scheduleSave();
    if (typeof inkAfterRestore === 'function') inkAfterRestore(prevInk);
    applied = true;
    return;
  }
  if (!applied && typeof showProjectNotice === 'function') {
    showProjectNotice('Nothing to redo', 1600);
  }
}

/* =========================================================
   görünüm
   ========================================================= */
let viewScrollGuardRaf = 0;
function applyView() {
  const v = state.view;
  world.style.transform = `translate(${v.x}px, ${v.y}px) scale(${v.scale})`;
  world.style.setProperty('--inv', String(1 / v.scale));
  /* Güvenlik ağı: sahne kaydırılırsa tüm ekran↔dünya hesapları kayar.
     AŞAMA-ÖLÇÜM (zoom-drill): bu okuma transform YAZIMININ hemen ardından
     gelirse her zoom/pan olayında ZORLAMALI SENKRON LAYOUT çalışır — 120
     öğelik tahtada 300 wheel'de 2,3-2,7 sn longtask (ort ~125 ms/kare).
     Düzeltme: okuma+yazma kare sınırına (rAF, tek kez) kaydırılır; panel
     davranışı değişmez, per-olay layout temizlenmez → layout yalnız bir
     kez/frame doğal akışta çalışır. */
  if (!viewScrollGuardRaf) {
    viewScrollGuardRaf = requestAnimationFrame(() => {
      viewScrollGuardRaf = 0;
      if (stage.scrollLeft || stage.scrollTop) { stage.scrollLeft = 0; stage.scrollTop = 0; }
    });
  }
  zoomEl.textContent = Math.round(v.scale * 100) + '%';
  if (typeof queueToolbarLayout === 'function') queueToolbarLayout();
  if (typeof updateItemBar === 'function') updateItemBar();
  if (typeof updateGroupTitles === 'function') updateGroupTitles();
  if (typeof scheduleLinks === 'function') scheduleLinks();
  if (typeof inkViewChanged === 'function') inkViewChanged();
}

/* =========================================================
   bağlantı okları ("Bind")
   İki fotoğraf seçilip Bağla denince ilk seçilenden ikinciye
   bir ok çizilir; ok her zaman fotoğrafların kenarına yapışık
   kalır, nereye taşınırsa taşınsın kopmaz.
   ========================================================= */
const SVG_NS = 'http://www.w3.org/2000/svg';
const linkLayerEl = $('#linkLayer');
const linkNodes = new Map();
let linkRaf = 0;

/* TailRef app · connection arrows, zoom, fit, framing */
'use strict';

function linkExists(a, b) {
  return (Array.isArray(state.links) ? state.links : [])
    .some(l => (l.from === a && l.to === b) || (l.from === b && l.to === a));
}

function scheduleLinks() {
  if (linkRaf) return;
  linkRaf = requestAnimationFrame(() => { linkRaf = 0; updateLinks(); });
}

/** Öğenin merkezinden (dx,dy) yönünde çıkınca dikdörtgen kenarına düşen dünya noktası */
function rectEdge(it, dx, dy) {
  const c = itemCenter(it);
  const rot = (it.rot || 0) * Math.PI / 180;
  const cos = Math.cos(rot), sin = Math.sin(rot);
  // yönü öğenin kendi eksenine çevir
  const lx = dx * cos + dy * sin;
  const ly = -dx * sin + dy * cos;
  const hw = it.w / 2, hh = (it.h || 0) / 2;
  const tx = Math.abs(lx) > 1e-6 ? hw / Math.abs(lx) : Infinity;
  const ty = Math.abs(ly) > 1e-6 ? hh / Math.abs(ly) : Infinity;
  const t = Math.min(tx, ty);
  const px = lx * t, py = ly * t;
  return {
    x: c.x + px * cos - py * sin,
    y: c.y + px * sin + py * cos,
  };
}

function linkNode(id) {
  let n = linkNodes.get(id);
  if (n) return n;
  const g = document.createElementNS(SVG_NS, 'g');
  g.setAttribute('class', 'lk');
  const line = document.createElementNS(SVG_NS, 'line');
  line.setAttribute('class', 'lkLine');
  const head = document.createElementNS(SVG_NS, 'polygon');
  head.setAttribute('class', 'lkHead');
  const dot = document.createElementNS(SVG_NS, 'circle');
  dot.setAttribute('class', 'lkDot');
  dot.setAttribute('r', '3');
  g.appendChild(line);
  g.appendChild(head);
  g.appendChild(dot);
  linkLayerEl.appendChild(g);
  n = { g, line, head, dot };
  linkNodes.set(id, n);
  return n;
}

function updateLinks() {
  if (!linkLayerEl) return;
  const sc = state.view.scale, ox = state.view.x, oy = state.view.y;
  const links = Array.isArray(state.links) ? state.links : [];
  const live = new Set();

  for (const l of links) {
    const a = getItem(l.from), b = getItem(l.to);
    if (!a || !b || a === b) continue;

    const ca = itemCenter(a), cb = itemCenter(b);
    let dx = cb.x - ca.x, dy = cb.y - ca.y;
    const d = Math.hypot(dx, dy);
    if (d < 1e-3) continue;
    dx /= d; dy /= d;

    const pa = rectEdge(a, dx, dy);
    const pb = rectEdge(b, -dx, -dy);
    let sx = pa.x * sc + ox, sy = pa.y * sc + oy;
    let ex = pb.x * sc + ox, ey = pb.y * sc + oy;

    let ux = ex - sx, uy = ey - sy;
    const dist = Math.hypot(ux, uy);
    if (dist < 3) continue;
    ux /= dist; uy /= dist;

    const pad = 3;
    sx += ux * pad; sy += uy * pad;
    ex -= ux * pad; ey -= uy * pad;

    const headLen = Math.min(13, Math.max(7, dist * 0.42));
    const headW = headLen * 0.60;
    const bx = ex - ux * headLen, by = ey - uy * headLen;
    const nx = -uy, ny = ux;

    live.add(l.id);
    const n = linkNode(l.id);
    n.line.setAttribute('x1', sx.toFixed(2));
    n.line.setAttribute('y1', sy.toFixed(2));
    n.line.setAttribute('x2', bx.toFixed(2));
    n.line.setAttribute('y2', by.toFixed(2));
    n.head.setAttribute('points', [
      `${ex.toFixed(2)},${ey.toFixed(2)}`,
      `${(bx + nx * headW).toFixed(2)},${(by + ny * headW).toFixed(2)}`,
      `${(bx - nx * headW).toFixed(2)},${(by - ny * headW).toFixed(2)}`,
    ].join(' '));
    n.dot.setAttribute('cx', sx.toFixed(2));
    n.dot.setAttribute('cy', sy.toFixed(2));
  }

  for (const [id, n] of [...linkNodes]) {
    if (!live.has(id)) { n.g.remove(); linkNodes.delete(id); }
  }
}

/** Seçimdeki öğeleri sırayla birbirine bağlar; bağlantı varsa kaldırır */
function toggleLink() {
  const ids = [...selection].filter(id => getItem(id));
  if (ids.length < 2) return;
  if (!Array.isArray(state.links)) state.links = [];
  pushUndo();
  for (let i = 0; i < ids.length - 1; i++) {
    const a = ids[i], b = ids[i + 1];
    const idx = state.links.findIndex(l =>
      (l.from === a && l.to === b) || (l.from === b && l.to === a));
    if (idx >= 0) state.links.splice(idx, 1);
    else state.links.push({ id: 'lk_' + newId(), from: a, to: b });
  }
  updateLinks();
  updateLinkButton();
  scheduleSave();
}

function updateLinkButton() {
  const btn = $('#btnLink');
  if (!btn) return;
  const ids = [...selection];
  const needsTwo = ids.length < 2;
  btn.disabled = needsTwo;
  // Devre dışıyken nedeni tooltip'te yazsın.
  btn.title = needsTwo
    ? __t('Select at least 2 items to link (L)')
    : __t('Link or unlink the selected images (L)');
  let on = ids.length >= 2;
  if (on) {
    for (let i = 0; i < ids.length - 1; i++) {
      if (!linkExists(ids[i], ids[i + 1])) { on = false; break; }
    }
  }
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  // Seçim özellikleri panelindeki Bağla düğmesi üsttekiyle aynı durumu izler.
  const itemBtn = $('#btnItemLink');
  if (itemBtn) {
    itemBtn.disabled = needsTwo;
    itemBtn.title = btn.title;
    itemBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
}

/* Dil değişince Bağla düğmesi başlıkları tazelensin. */
if (window.L10N && window.L10N.onChange) {
  window.L10N.onChange(() => { try { updateLinkButton(); } catch { /* sessiz */ } });
}

function zoomAt(screenPoint, factor) {
  const s0 = state.view.scale;
  const s1 = clamp(s0 * factor, MIN_SCALE, MAX_SCALE);
  if (s1 === s0) return;
  const wx = (screenPoint.x - state.view.x) / s0;
  const wy = (screenPoint.y - state.view.y) / s0;
  state.view.scale = s1;
  state.view.x = screenPoint.x - wx * s1;
  state.view.y = screenPoint.y - wy * s1;
  applyView();
  scheduleSave();
}

function fitAll(padding = 80) {
  if (!state.items.length) return;
  const b = boundsOf(state.items, 0);
  const vw = stage.clientWidth, vh = stage.clientHeight;
  const s = clamp(
    Math.min((vw - padding * 2) / Math.max(b.w, 1), (vh - padding * 2) / Math.max(b.h, 1)),
    MIN_SCALE, MAX_SCALE
  );
  state.view.scale = s;
  state.view.x = vw / 2 - (b.x + b.w / 2) * s;
  state.view.y = vh / 2 - (b.y + b.h / 2) * s;
  applyView();
  scheduleSave();
}

function zoomTo100() {
  const p = { x: stage.clientWidth / 2, y: stage.clientHeight / 2 };
  const w = screenToWorld(p);
  state.view.scale = 1;
  state.view.x = p.x - w.x;
  state.view.y = p.y - w.y;
  applyView();
  scheduleSave();
}

/** Seçili öğeleri (yoksa hepsini) görünür alana sığdır */
function frameSelection(pad = 56) {
  const items = selection.size
    ? state.items.filter(i => selection.has(i.id))
    : state.items;
  if (!items.length) return;
  const b = boundsOf(items, 0);
  const vw = stage.clientWidth, vh = stage.clientHeight;
  const sx = (vw - pad * 2) / Math.max(b.w, 1);
  const sy = (vh - pad * 2) / Math.max(b.h, 1);
  const s = clamp(Math.min(sx, sy), MIN_SCALE, MAX_SCALE);
  state.view.scale = s;
  state.view.x = vw / 2 - (b.x + b.w / 2) * s;
  state.view.y = vh / 2 - (b.y + b.h / 2) * s;
  applyView();
  scheduleSave();
}

/* TailRef app · item DOM creation/update, sync, item bar */
'use strict';

/* =========================================================
   DOM üretimi
   ========================================================= */
/* Metin düzenlemesinde ilk gerçek girişte düzenleme öncesi durumu yığına
   yazan işaret. startEdit doldurur, commit/blur temizler. */
let textEditUndoId = null;

/* contenteditable metnini modele çevirir. Chromium Shift+Enter'da <br>,
   Enter'da <div> üretir; düz textContent ikisini de yeni satır saymaz ve
   yazı yeniden yüklenince tek satıra çöküyordu (kullanıcı hatası gibi
   görünen veri kaybı). Blok sınırları ve <br> burada '\n' olur. */
function editableTextValue(root) {
  let out = '';
  /* Blok sınırı = tek satır sonu. Boş satırlar (<div><br></div>) BR'den bir,
     blok sınırından bir olmak üzere İKİ kez sayılıyordu; kullanıcının
     yazdığı boş satırlar her kayıtta çoğalıyordu. lineBreak() ardışık
     satır sonlarını birleştirir, BR kendi satır sonunu korur. */
  const lineBreak = () => { if (out && !out.endsWith('\n')) out += '\n'; };
  const walk = node => {
    for (const child of node.childNodes) {
      if (child.nodeType === 3) { out += child.nodeValue; continue; }
      if (child.nodeType !== 1) continue;
      const tag = child.tagName;
      if (tag === 'BR') { out += '\n'; continue; }
      const block = tag === 'DIV' || tag === 'P' || tag === 'LI' || tag === 'BLOCKQUOTE';
      if (block) lineBreak();
      walk(child);
      if (block) lineBreak();
    }
  };
  walk(root);
  return out.replace(/\n+$/, '');
}

function createItemEl(it) {
  const el = document.createElement('div');
  el.className = 'item';
  el.dataset.id = it.id;
  // Türü sınıf olarak da taşı: fotoğraflara yuvarlak köşe, yazıya ayrı davranış.
  el.classList.add(it.kind === 'image' ? 'is-image' : 'is-text');

  if (it.kind === 'image') {
    // Filtre, opaklık ve kırpma ayrı bir sarmalayıcıda tutulur. Böylece
    // sürükleme sırasında öğenin transform katmanı ile görsel efekt
    // katmanı birbirine karışmaz; çift görüntü/hayalet oluşmaz.
    const media = document.createElement('div');
    media.className = 'media';
    const img = document.createElement('img');
    img.draggable = false;
    img.alt = '';
    const c = imgCache.get(it.imageId);
    if (c) img.src = c.url;
    media.appendChild(img);
    el.appendChild(media);
    el.title = c ? c.name : '';

    /* Kilitli fotoğrafın sağ üstünde görünen rozet. Öğe döndüğünde
       ters döndürülür; boyutu --inv ile ekran ölçeğinde sabit kalır. */
    const lockBadge = document.createElement('div');
    lockBadge.className = 'lockBadge';
    lockBadge.setAttribute('aria-hidden', 'true');
    lockBadge.innerHTML = '<svg viewBox="0 0 24 24"><use href="#icon-lock"/></svg>';
    el.appendChild(lockBadge);
  } else {
    const t = document.createElement('div');
    t.className = 'text';
    // Metin yalnızca düzenleme sırasında contenteditable olur. Aksi halde
    // tek tıkla seçilen yazı, klavye odağını içeride tutup Delete/Backspace
    // kısayolunu yutuyordu.
    t.contentEditable = 'false';
    t.spellcheck = false;
    t.textContent = it.text || '';
    el.appendChild(t);

    /* Dinleyiciler createItemEl sırasındaki nesneye kapanır; geri al/yinele
       sonrası syncAll aynı DOM'u yeni nesneyle günceller. Kapanan eski
       nesneye yazmak metni sessizce kaybettiriyordu → her zaman güncel
       öğeyi çöz. */
    const liveItem = () => getItem(it.id) || it;
    t.addEventListener('input', () => {
      const cur = liveItem();
      cur.text = editableTextValue(t);
      cur.w = textAutoWidth(cur);
      el.style.width = cur.w + 'px';
      cur.h = t.offsetHeight || cur.h;
      scheduleSave();
      updateInspector();
    });
    /* İlk gerçek girişten ÖNCE snapshot: düzenleme oturumu başına tek
       geri-alma adımı. Tarayıcının kendi geri/yinele komutları (historyUndo)
       zaten metni değiştirir; onlar için ikinci adım açmayız. */
    t.addEventListener('beforeinput', e => {
      if (textEditUndoId !== it.id) return;
      if (e.inputType === 'historyUndo' || e.inputType === 'historyRedo') return;
      textEditUndoId = null;
      pushUndo();
    });
    t.addEventListener('pointerdown', e => {
      if (editingId === it.id) e.stopPropagation();
    });
    t.addEventListener('focusout', e => {
      if (editingId !== it.id) return;
      // panelden boyut/renk ayarı yapılıyorsa yazıyı silme
      if (e.relatedTarget && inspectorEl.contains(e.relatedTarget)) return;
      editingId = null;
      textEditUndoId = null;
      t.contentEditable = 'false';
      el.classList.remove('editing');
      const cur = liveItem();
      if (!(cur.text || '').trim()) {
        removeItems([it.id], false, { toTrash: false });
      } else {
        cur.h = t.offsetHeight || cur.h;
        scheduleSave();
        syncAll();
      }
    });
  }

  const hs = document.createElement('div');
  hs.className = 'handles';
  for (const [hx, hy, cls] of HANDLES) {
    const d = document.createElement('div');
    d.className = 'handle ' + cls;
    d.dataset.hx = hx; d.dataset.hy = hy;
    hs.appendChild(d);
  }
  const rot = document.createElement('div');
  rot.className = 'handle rot';
  rot.dataset.rot = '1';
  hs.appendChild(rot);
  el.appendChild(hs);

  return el;
}

/* Ekran ve dışa aktarımın AYNI filtre dilini konuşması için tek kaynak:
   sıcaklık pozitifse sıcak (sepia+doymuşluk), negatifse serin (hue-rotate)
   ton; değerler yüzdeyle ölçeklenir. 15-menu-export ctx.filter dizgisiyle
   birebir aynıdır. */
function imageFilterCss(gray, bright, contrast, temp) {
  const parts = [];
  if (gray) parts.push(`grayscale(${gray}%)`);
  if (temp > 0) {
    parts.push(`sepia(${Math.min(60, temp * 0.6)}%)`);
    parts.push(`saturate(${Math.round(100 + temp * 0.35)}%)`);
  } else if (temp < 0) {
    const t = -temp;
    parts.push(`hue-rotate(${Math.min(30, t * 0.3)}deg)`);
    parts.push(`saturate(${Math.round(100 - t * 0.2)}%)`);
    parts.push(`brightness(${Math.round(100 + t * 0.05)}%)`);
  }
  if (bright !== 100) parts.push(`brightness(${bright}%)`);
  if (contrast !== 100) parts.push(`contrast(${contrast}%)`);
  return parts.join(' ');
}

function updateItemEl(it, el) {
  // Konumu left/top yerine transform ile sürüyoruz: her karede layout
  // tetiklenmez, compositor katmanı taşınır ve sürükleme sırasında eski
  // karelerin "hayaleti" ekranda kalmaz.
  if (el.style.left !== '0px') el.style.left = '0px';
  if (el.style.top !== '0px') el.style.top = '0px';
  const widthValue = it.w + 'px';
  if (el.style.width !== widthValue) el.style.width = widthValue;
  const zValue = String(10 + (Number(it.z) || 1));
  if (el.style.zIndex !== zValue) el.style.zIndex = zValue;
  /* Yatay/dikey aynala: öğenin kendisi çevrilir (görsel + üstündeki çizim).
     scale, rotate'ten SONRA gelir — aynalama döndürülmüş eksen çiftidir
     ve dışa aktarımdaki ctx.scale sırasıyla birebir uyuşur. */
  const flipValue = (it.flipH ? -1 : 1) * (it.flipV ? -1 : 1);
  const transformValue = `translate3d(${it.x}px, ${it.y}px, 0) rotate(${it.rot || 0}deg) scale(${it.flipH ? -1 : 1}, ${it.flipV ? -1 : 1})`;
  if (el.style.transform !== transformValue) el.style.transform = transformValue;
  /* Kilit rozeti öğeyle birlikte dönmesin diye ters açı CSS'e taşınır. */
  const rotValue = String(Number(it.rot) || 0) + 'deg';
  if (el.style.getPropertyValue('--rot') !== rotValue) el.style.setProperty('--rot', rotValue);

  if (it.kind === 'image') {
    const heightValue = it.h + 'px';
    if (el.style.height !== heightValue) el.style.height = heightValue;
    // Cache sonradan doldurulursa (örn. çöpten geri getirme) img.src güncellensin
    const img = el.querySelector('.media img');
    if (img && it.imageId) {
      const c = imgCache.get(it.imageId);
      if (c) {
        if (img.src !== c.url) { img.src = c.url; el.title = c.name; }
      } else if (!imageLoadFailures.has(it.imageId)) {
        // Önbellekte yoksa (geri al/yinele veya tahliye sonrası) tembel yükle.
        ensureImageCached(it.imageId).then(value => {
          if (!el.isConnected || elMap.get(it.id) !== el) return;
          img.src = value.url;
          el.title = value.name;
        }).catch(() => { /* kalıcı hata: tekrar denemeyi bırak */ });
      }
    }
    // Görsele bağlı çizim katmanları öğenin içinde yaşar; transformu
    // otomatik olarak görselle birlikte hareket eder.
    if (typeof inkSyncItem === 'function') inkSyncItem(it, el);
  } else {
    if (el.style.height !== 'auto') el.style.height = 'auto';
    const t = el.firstChild;
    /* Yükseklik yalnızca içerik/stil değiştiğinde yeniden ölçülür. Her
       sync çağrısında offsetHeight okumak, stil yazmalarıyla serpişince
       her öğede forced reflow üretir; büyük tahtalarda kare başına
       yüzlerce kez layout tetiklenip donmaya yol açıyordu. Metin, boyut,
       kalınlık, arka plan, renk, genişlik veya düzenleme durumu aynıysa
       mevcut yükseklik zaten geçerlidir. */
    const textSig = `${it.text || ''}|${it.fontSize || FONT_SIZE}|${it.fontFamily || ''}|${it.bold ? 1 : 0}|${it.bg || ''}|${it.color || ''}|${it.w}|${editingId === it.id ? 1 : 0}`;
    const textStyleChanged = el.dataset.textSig !== textSig;
    t.style.fontSize   = (it.fontSize || FONT_SIZE) + 'px';
    /* Aday 7: öğe ailesi boşsa CSS varsayılanı (Inter yığını). */
    t.style.fontFamily = it.fontFamily || '';
    t.style.color      = it.color || '#fff';
    t.style.fontWeight = it.bold ? 700 : 400;
    t.style.background = it.bg || 'transparent';
    if (document.activeElement !== t && t.textContent !== (it.text || '')) {
      t.textContent = it.text || '';
    }
    if (editingId !== it.id) t.contentEditable = 'false';
    // yüksekliği ölç (transform öncesi layout px = dünya birimi)
    if (textStyleChanged || document.activeElement === t || !it.h) {
      it.h = t.offsetHeight || it.h || 0;
      el.dataset.textSig = textSig;
    }
  }

  el.classList.toggle('sel', selection.has(it.id));
  el.classList.toggle('editing', editingId === it.id);
  el.classList.toggle('important', !!it.important);
  el.classList.toggle('locked', !!it.locked);
  if (it.important) el.style.setProperty('--imp', impColorOf(it));
  else el.style.removeProperty('--imp');

  // Opaklık/filtre/kırpma yalnızca içeriğe uygulanır (tutamaçlar tam
  // görünür kalsın). Varsayılan değerlerde özellik tamamen kaldırılır;
  // böylece gereksiz GPU filtre katmanı oluşmaz.
  const media = el.firstChild;
  if (media && media.style) {
    const alpha = alphaOf(it);
    if (alpha < 1) media.style.opacity = String(alpha);
    else media.style.removeProperty('opacity');

    const cropTop = Number(it.cropTop) || 0;
    const cropRight = Number(it.cropRight) || 0;
    const cropBottom = Number(it.cropBottom) || 0;
    const cropLeft = Number(it.cropLeft) || 0;
    if (cropTop || cropRight || cropBottom || cropLeft) {
      media.style.clipPath = `inset(${cropTop}% ${cropRight}% ${cropBottom}% ${cropLeft}%)`;
    } else {
      media.style.removeProperty('clip-path');
    }

    const gray = Number(it.fGray) || 0;
    const bright = it.fBright === undefined ? 100 : Number(it.fBright);
    const contrast = it.fContrast === undefined ? 100 : Number(it.fContrast);
    const temp = Number(it.fTemp) || 0;
    if (gray || bright !== 100 || contrast !== 100 || temp) {
      media.style.filter = imageFilterCss(gray, bright, contrast, temp);
    } else {
      media.style.removeProperty('filter');
    }
  }

  // bağlantı okları öğeyle birlikte hareket etsin
  if (typeof scheduleLinks === 'function') scheduleLinks();
}

function syncAll() {
  const seen = new Set();
  let freshIndex = 0;
  for (const it of state.items) {
    seen.add(it.id);
    let el = elMap.get(it.id);
    if (!el) {
      // Geri al/yinele sırasında aynı kimlikli eski kopya hâlâ sönüyorsa kaldır.
      const orphan = world.querySelector(`.item.item-leaving[data-id="${it.id}"]`);
      if (orphan) orphan.remove();
      el = createItemEl(it);
      elMap.set(it.id, el);
      el.style.setProperty('--stagger', String(Math.min(freshIndex, 8)));
      freshIndex++;
      if (!motionReduced()) {
        el.classList.add('item-enter');
        setTimeout(() => {
          el.classList.remove('item-enter');
          el.style.removeProperty('--stagger');
        }, 620);
      }
      world.appendChild(el);
    }
    updateItemEl(it, el);
  }
  for (const [id, el] of [...elMap]) {
    if (!seen.has(id)) {
      elMap.delete(id);
      retireItemEl(el);
    }
  }
  hintEl.classList.toggle('hidden', state.items.length > 0);
  setItemCountLabel();
  updateInspector();
  updateItemBar();
  updateGroupFrame();
  updateLinkButton();
  scheduleLinks();
  // Aşırı büyük tahtalarda kullanıcıyı erken uyar (kurtarma yolu gösterilir).
  if (typeof maybeWarnOverload === 'function') maybeWarnOverload();
  if (typeof inkSyncDom === 'function') inkSyncDom();
}

function syncSelection() {
  const gid = selectedGroupId();
  for (const [id, el] of elMap) {
    el.classList.toggle('sel', selection.has(id));
    // grup seçiliyken tek tek tutamaçlar yerine grubun tutamaçları kullanılır
    el.classList.toggle('grouped', !!gid && selection.has(id));
  }
  updateInspector();
  updateItemBar();
  updateGroupFrame();
  updateLinkButton();
  // Mod anahtarı seçime göre "Drawing" düğmesini etkinleştirir/pasifleştirir.
  if (typeof modeSyncUi === 'function') modeSyncUi();
}

/* =========================================================
   yazı paneli
   ========================================================= */
const inspectorEl = $('#inspector');
const fsRangeEl   = $('#fsRange');
const fsInputEl   = $('#fsInput');
const itemBarEl   = $('#itemBar');
const itemAlphaEl = $('#itemAlpha');
const alphaValEl  = $('#alphaVal');
const itemBarTitleEl = $('#itemBarTitle');
const btnImportant = $('#btnImportant');
const btnLock = $('#btnLock');
const btnPalette = $('#btnPalette');
const btnArrange = $('#btnArrange');
const btnExportImageEl = $('#btnExportImage');
const fGrayEl = $('#fGray');
const fBrightEl = $('#fBright');
const fContrastEl = $('#fContrast');
const fTempEl = $('#fTemp');
const fOpacityEl = $('#fOpacity');
const fGrayValEl = $('#fGrayVal');
const fBrightValEl = $('#fBrightVal');
const fContrastValEl = $('#fContrastVal');
const fTempValEl = $('#fTempVal');
const fOpacityValEl = $('#fOpacityVal');
const btnImageRotL = $('#btnImageRotL');
const btnImageRotR = $('#btnImageRotR');
const btnImageFlipH = $('#btnImageFlipH');
const btnImageFlipV = $('#btnImageFlipV');
const ieRatioGroupEl = $('#ieRatioGroup');
const btnResetFilter = $('#btnResetFilter');
const btnEditImage = $('#btnEditImage');
const cropTopEl = $('#cropTop');
const cropRightEl = $('#cropRight');
const cropBottomEl = $('#cropBottom');
const cropLeftEl = $('#cropLeft');
const cropTopValEl = $('#cropTopVal');
const cropRightValEl = $('#cropRightVal');
const cropBottomValEl = $('#cropBottomVal');
const cropLeftValEl = $('#cropLeftVal');
const imageEditorEl = $('#imageEditor');
const btnImageEditorClose = $('#btnImageEditorClose');

const alphaOf = it => (typeof it.alpha === 'number' ? it.alpha : 1);

/** Kırpma okumaları gerçek piksele çevrilir: kaydırıcı yüzde, panel px gösterir.
    Değer, slider yerine DOĞRUDAN öğeden okunur (senkron sırası: slider atanır
    üstte/sağda, okuma fazla-bayat olamaz). */
function updateCropPxOutputs(it) {
  if (!it || it.kind !== 'image' || typeof it.w !== 'number') return;
  const pairs = [
    [cropTopValEl, it.h, it.cropTop],
    [cropBottomValEl, it.h, it.cropBottom],
    [cropLeftValEl, it.w, it.cropLeft],
    [cropRightValEl, it.w, it.cropRight],
  ];
  for (const [out, dim, crop] of pairs) {
    if (!out) continue;
    const v = clamp(Number(crop) || 0, 0, 100);
    out.textContent = String(Math.round(v / 100 * dim)) + ' px';
  }
}

/** Seçili görseller — grup seçiliyse grubun bütün görselleri birlikte gelir */
function selectedImageItems() {
  const list = [];
  for (const id of selection) {
    const it = getItem(id);
    if (it && it.kind === 'image') list.push(it);
  }
  return list;
}

function worldToScreen(p) {
  return { x: p.x * state.view.scale + state.view.x, y: p.y * state.view.scale + state.view.y };
}

function updateItemBar() {
  const its = selectedImageItems();
  const it = its[0];
  if (!it) {
    /* Seçim yokken "Seçim Özellikleri" paneli görünmez. Seçim yapılınca
       yeniden açılır; konumu kayıtlı olduğu için yerine döner. Ayrı
       penceredeyse o pencere de kapanır (geri takılmaz). */
    if (itemBarEl.dataset.detached === '1'
        && typeof tailrefCloseDetachedPanel === 'function') {
      tailrefCloseDetachedPanel(itemBarEl, false);
    } else {
      hidePanel(itemBarEl);
    }
    itemBarEl.classList.remove('multi');
    itemBarTitleEl.textContent = 'No selection';
    const itemGroupBtn = $('#btnItemGroup');
    if (itemGroupBtn) {
      itemGroupBtn.disabled = true;
      itemGroupBtn.title = 'Group at least two items (G)';
      itemGroupBtn.setAttribute('aria-pressed', 'false');
    }
    hidePanel(imageEditorEl, syncStudioPanelState);
    syncStudioPanelState();
    hidePanel(document.getElementById('impWheel'));
    if (typeof updateInspector === 'function') updateInspector();
    return;
  }

  itemBarEl.classList.remove('is-empty');
  /* Araç çubuğu katlıyken (bar-collapsed-ui) seçim özellikleri paneli
     de katlı kalır (kullanıcı isteği: "paneli gizli moda alırsam bu
     seçim özellikleri paneli de gizlensin onla beraber"). Bar açılınca
     unfoldItemBarFromBar gerçekten bilinçli şekilde geri getirir. */
  if (!document.body.classList.contains('bar-collapsed-ui')) {
    showPanel(itemBarEl);
    prepareFloatingPanel(itemBarEl);
  } else if (itemBarEl.hidden) {
    /* Panel bar katlıyken sahnede görünmez — tucked işaretle ki bar
       açıldığında çubuğun yanından (unfold) geri gelsin. */
    itemBarEl.dataset.tucked = '1';
  }
  if (isPanelVisible(impWheelEl)) positionImpWheel();
  itemBarEl.classList.toggle('multi', its.length > 1);
  itemBarTitleEl.textContent = its.length > 1 ? its.length + ' image' : 'Image';
  const groupBtn = $('#btnItemGroup');
  if (groupBtn) {
    const grouped = !!selectedGroupId();
    groupBtn.disabled = selection.size < 2;
    groupBtn.title = groupBtn.disabled
      ? 'Group at least two items (G)'
      : grouped
        ? 'Ungroup (G)'
        : 'Group the selected items (G)';
    groupBtn.setAttribute('aria-pressed', grouped ? 'true' : 'false');
  }

  const pct = Math.round(alphaOf(it) * 100);
  if (document.activeElement !== itemAlphaEl) itemAlphaEl.value = String(pct);
  syncRangeFill(itemAlphaEl);
  alphaValEl.textContent = pct + '%';
  if (fGrayEl && document.activeElement !== fGrayEl) fGrayEl.value = String(it.fGray || 0);
  if (fBrightEl && document.activeElement !== fBrightEl) fBrightEl.value = String(it.fBright === undefined ? 100 : it.fBright);
  if (fContrastEl && document.activeElement !== fContrastEl) fContrastEl.value = String(it.fContrast === undefined ? 100 : it.fContrast);
  if (fTempEl && document.activeElement !== fTempEl) fTempEl.value = String(Number(it.fTemp) || 0);
  const tempNow = Number(it.fTemp) || 0;
  if (fTempValEl) fTempValEl.textContent = (tempNow > 0 ? '+' : '') + tempNow;
  if (fGrayValEl) fGrayValEl.textContent = String(Number(it.fGray) || 0) + '%';
  if (fBrightValEl) fBrightValEl.textContent = Math.round((it.fBright === undefined ? 100 : Number(it.fBright)) - 100) + '%';
  if (fContrastValEl) fContrastValEl.textContent = Math.round((it.fContrast === undefined ? 100 : Number(it.fContrast)) - 100) + '%';
  if (fOpacityValEl) fOpacityValEl.textContent = '%' + pct;
  if (btnImageFlipH) btnImageFlipH.setAttribute('aria-pressed', it.flipH ? 'true' : 'false');
  if (btnImageFlipV) btnImageFlipV.setAttribute('aria-pressed', it.flipV ? 'true' : 'false');
  /* Programatik slider değeri atamaları 'input' olayı üretmez; dolgu
     CSS'i burada da tazelenmeli ki seçim değişince eski grafik kalmasın. */
  if (typeof syncImageSliderFills === 'function') syncImageSliderFills();
  updateCropPxOutputs(it);
  if (cropTopEl) cropTopEl.value = String(it.cropTop || 0);
  if (cropRightEl) cropRightEl.value = String(it.cropRight || 0);
  if (cropBottomEl) cropBottomEl.value = String(it.cropBottom || 0);
  if (cropLeftEl) cropLeftEl.value = String(it.cropLeft || 0);
  const paletteBlocked = its.every(item => item.paletteGenerated);
  btnPalette.disabled = paletteBlocked;
  btnPalette.classList.toggle('is-blocked', paletteBlocked);
  btnPalette.dataset.tooltip = paletteBlocked
    ? __t('A new palette cannot be created from the palette image')
    : __t('Pick 10 key colors from different hues and values of the photo');
  // "Arrange" en az iki öğe ister; boyutlar korunur, aralar eşit boşluk olur.
  const arrangeBlocked = selection.size < 2;
  btnArrange.disabled = arrangeBlocked;
  btnArrange.classList.toggle('is-blocked', arrangeBlocked);
  btnArrange.dataset.tooltip = arrangeBlocked
    ? __t('Select at least two items to arrange')
    : __t('Arrange the selected images with small gaps between them, keeping their sizes');
  /* Dışa aktarma tek bir fotoğraf için anlamlı: düzenlenmemiş fotoğraflar
     kaynak baytlarıyla, kırpma/filtre/çizim varsa görünen sonuçla yazılır.
     Birden fazla görsel seçiliyken düğme kapalıdır. */
  if (btnExportImageEl) {
    const exportBlocked = its.length !== 1;
    btnExportImageEl.disabled = exportBlocked;
    btnExportImageEl.classList.toggle('is-blocked', exportBlocked);
    btnExportImageEl.title = exportBlocked
      ? 'Select a single photo to export'
      : 'Export the selected photo as PNG with crop, filter, drawing and rotation';
  }
  const selGid = selectedGroupId();
  const anyImportant = selGid ? isGroupImportant(selGid) : its.some(i => i.important);
  btnImportant.setAttribute('aria-pressed', anyImportant ? 'true' : 'false');
  const impColor = selGid
    ? (isGroupImportant(selGid) ? groupImpColor(selGid) : '')
    : (its.find(i => i.important) ? impColorOf(its.find(i => i.important)) : '');
  if (impColor) itemBarEl.style.setProperty('--imp', impColor);
  else itemBarEl.style.removeProperty('--imp');

  if (typeof updateInspector === 'function') updateInspector();
  if (typeof inkSyncScopeVisual === 'function') inkSyncScopeVisual();
}

/* Dil değişince seçim çubuğu tooltip'leri (dinamik yazım) tazelensin. */
if (window.L10N && window.L10N.onChange) {
  window.L10N.onChange(() => { try { updateItemBar(); } catch { /* sessiz */ } });
}

/* TailRef app · groups, titles, frames, group selection */
'use strict';

/* ---------------- gruplar (iç içe destekli) ---------------- */
function groupMembersOf(gid) {
  return gid ? state.items.filter(i => i.groupId === gid) : [];
}

function groupParentOf(gid) {
  return (state.groupParents && state.groupParents[gid]) || null;
}

function childGroupIds(gid) {
  const out = [];
  for (const [g, p] of Object.entries(state.groupParents || {})) {
    if (p === gid) out.push(g);
  }
  return out;
}

/** Tahtadaki bütün grup kimlikleri (üst gruplar dahil) */
function allGroupIds() {
  const set = new Set();
  for (const it of state.items) {
    let g = it.groupId;
    const seen = new Set();
    while (g && !seen.has(g)) { seen.add(g); set.add(g); g = groupParentOf(g); }
  }
  for (const g of Object.keys(state.groupParents || {})) set.add(g);
  return [...set];
}

/** Grubun içindeki bütün öğeler (alt gruplar dahil) */
function groupItemsDeep(gid, seen = new Set()) {
  if (!gid || seen.has(gid)) return [];
  seen.add(gid);
  const out = groupMembersOf(gid).slice();
  for (const c of childGroupIds(gid)) out.push(...groupItemsDeep(c, seen));
  return out;
}

/** Bir grubun doğrudan çocuk sayısı (öğe + alt grup) */
function groupUnitCount(gid) {
  return groupMembersOf(gid).length + childGroupIds(gid).length;
}

function outermostGroupOf(it) {
  let g = it && it.groupId;
  const seen = new Set();
  while (g && groupParentOf(g) && !seen.has(g)) { seen.add(g); g = groupParentOf(g); }
  return g || null;
}

/** gid, ancestor grubunun içinde mi? */
function groupInside(gid, ancestor) {
  let g = groupParentOf(gid);
  const seen = new Set();
  while (g && !seen.has(g)) {
    if (g === ancestor) return true;
    seen.add(g);
    g = groupParentOf(g);
  }
  return false;
}

/** Grubu çöz: öğeler ve alt gruplar bir üst seviyeye taşınır */
function dissolveGroup(gid) {
  const parent = groupParentOf(gid);
  for (const it of groupMembersOf(gid)) {
    if (parent) it.groupId = parent; else delete it.groupId;
  }
  for (const c of childGroupIds(gid)) {
    if (parent) state.groupParents[c] = parent; else delete state.groupParents[c];
  }
  if (state.groupParents) delete state.groupParents[gid];
  if (state.groupTitles) delete state.groupTitles[gid];
  if (state.groupImportant) delete state.groupImportant[gid];
}

/** Boş kalmış grup kayıtlarını temizle */
function pruneGroups() {
  const alive = new Set();
  for (const it of state.items) {
    let g = it.groupId;
    const seen = new Set();
    while (g && !seen.has(g)) { seen.add(g); alive.add(g); g = groupParentOf(g); }
  }
  for (const [g, p] of Object.entries(state.groupParents || {})) {
    if (!alive.has(g) || (p && !alive.has(p))) delete state.groupParents[g];
  }
  for (const g of Object.keys(state.groupTitles || {})) if (!alive.has(g)) delete state.groupTitles[g];
  for (const g of Object.keys(state.groupImportant || {})) if (!alive.has(g)) delete state.groupImportant[g];
}

/** Seçimi en içteki gruplara/tek öğelere böler */
function selectionUnits() {
  const sel = new Set(selection);
  const groups = allGroupIds().filter(gid => {
    const deep = groupItemsDeep(gid);
    return deep.length >= 2 && deep.every(i => sel.has(i.id));
  });
  const maximal = groups.filter(gid => !groups.some(o => o !== gid && groupInside(gid, o)));
  const used = new Set();
  const units = maximal.map(gid => {
    const deep = groupItemsDeep(gid);
    deep.forEach(i => used.add(i.id));
    return { type: 'group', gid, items: deep };
  });
  for (const id of sel) if (!used.has(id) && getItem(id)) units.push({ type: 'item', id });
  return units;
}

/* ---------------- grup başlıkları ---------------- */
const groupTitlesEl = $('#groupTitles');
const groupTitleEls = new Map();   // gid -> DOM

function groupTitleOf(gid) {
  return (state.groupTitles && state.groupTitles[gid]) || '';
}

function setGroupTitle(gid, value) {
  if (!state.groupTitles) state.groupTitles = {};
  const v = String(value || '').replace(/\s+/g, ' ').trim().slice(0, 90);
  if (v) state.groupTitles[gid] = v;
  else delete state.groupTitles[gid];
  scheduleSave();
}

function isGroupActive(gid) {
  const members = groupItemsDeep(gid);
  return members.length >= 2 && members.every(m => selection.has(m.id));
}

/** Seçim tam olarak tek bir grubu kaplıyorsa o grubun kimliği (en dıştaki) */
function selectedGroupId() {
  if (selection.size < 2) return null;
  let best = null;
  for (const gid of allGroupIds()) {
    const deep = groupItemsDeep(gid);
    if (deep.length < 2 || deep.length !== selection.size) continue;
    if (!deep.every(i => selection.has(i.id))) continue;
    if (!best || groupInside(best, gid)) best = gid;
  }
  return best;
}

/** Grup seviyesindeki "önemli" — sadece dış çizgileri renklendirir, fotoğraflara dokunmaz */
function isGroupImportant(gid) {
  return !!(state.groupImportant && state.groupImportant[gid]);
}

/** Grubun önemli rengi (eski kayıtlarda true ise kırmızı) */
function groupImpColor(gid) {
  const v = state.groupImportant && state.groupImportant[gid];
  return (typeof v === 'string' && v) ? v : IMP_FALLBACK;
}

function setGroupImportant(gid, on, color) {
  if (!state.groupImportant) state.groupImportant = {};
  if (on) state.groupImportant[gid] = color || randomImpColor();
  else delete state.groupImportant[gid];
  updateGroupFrame();
}

function focusGroupTitle(gid) {
  const el = groupTitleEls.get(gid);
  if (!el) return;
  const t = el.querySelector('.gtText');
  t.focus({ preventScroll: true });
  try {
    const r = document.createRange();
    r.selectNodeContents(t); r.collapse(false);
    const s = window.getSelection(); s.removeAllRanges(); s.addRange(r);
  } catch (e) {}
}

function makeGroupTitleEl(gid) {
  const el = document.createElement('div');
  el.className = 'gt';
  el.dataset.gid = gid;
  /* Düzenleme oturumunun başlangıç başlığı: Escape bunu geri yükler,
     geri-alma adımı da yalnız başlık gerçekten değiştiyse açılır. */
  let titleBase = null;

  const text = document.createElement('div');
  text.className = 'gtText';
  text.dataset.ph = 'Group title…';
  text.spellcheck = false;
  text.setAttribute('role', 'textbox');
  text.setAttribute('aria-label', 'Group title');

  text.addEventListener('pointerdown', e => e.stopPropagation());
  text.addEventListener('click', e => {
    e.stopPropagation();
    // başlığa tıklayınca o grup seçilir (iç içe gruplarda iç gruba geçmek için)
    if (selectedGroupId() !== gid) {
      selection = new Set(groupItemsDeep(gid).map(i => i.id));
      syncSelection();
    }
  });
  text.addEventListener('dblclick', e => e.stopPropagation());

  text.addEventListener('focus', () => {
    titleBase = groupTitleOf(gid);
  });

  text.addEventListener('keydown', e => {
    e.stopPropagation();
    if (e.key === 'Enter') { e.preventDefault(); text.blur(); }
    else if (e.key === 'Escape') {
      e.preventDefault();
      /* Model input sırasında güncellendiği için groupTitleOf(gid) artık
         YAZILAN değeri döndürür; vazgeçmek için oturum başındaki başlık
         geri yüklenir. Blur, aynı değere dönüldüğü için undo adımı açmaz. */
      if (titleBase !== null) text.textContent = titleBase;
      text.blur();
    }
  });

  text.addEventListener('input', () => {
    setGroupTitle(gid, text.textContent);
  });

  text.addEventListener('blur', () => {
    const base = titleBase;
    titleBase = null;
    const v = text.textContent.replace(/\s+/g, ' ').trim().slice(0, 90);
    text.textContent = v;
    /* Geri-alma anlık görüntüsü düzenleme ÖNCESİ başlıkla alınır; böylece
       Ctrl+Z eski başlığa döner. Başlık değişmediyse (Escape dâhil) adım
       açılmaz. */
    if (base !== null && v !== base) {
      setGroupTitle(gid, base);
      pushUndo();
    }
    setGroupTitle(gid, v);
    updateGroupTitles();
  });

  el.appendChild(text);
  groupTitlesEl.appendChild(el);
  return el;
}

/** Her grubun başlığını grubun üstünde göster */
let updatingGroupTitles = false;
function updateGroupTitles() {
  // odaktaki başlık kaldırılırken blur tetiklenip burayı yeniden çağırabiliyor;
  // iç içe çağrı DOM'u bozmasın diye koruma
  if (updatingGroupTitles) return;
  updatingGroupTitles = true;
  try {
    updateGroupTitlesInner();
  } finally {
    updatingGroupTitles = false;
  }
}

function updateGroupTitlesInner() {
  const groups = new Map();
  for (const gid of allGroupIds()) {
    const deep = groupItemsDeep(gid);
    if (deep.length >= 2 && groupUnitCount(gid) >= 2) groups.set(gid, deep);
  }

  for (const gid of [...groupTitleEls.keys()]) {
    if (!groups.has(gid)) {
      const old = groupTitleEls.get(gid);
      groupTitleEls.delete(gid);
      if (old && old.parentNode) {
        try { old.parentNode.removeChild(old); } catch { /* blur sırasında taşınmış olabilir */ }
      }
    }
  }

  const focusGid = selectedGroupId();

  for (const [gid, members] of groups) {
    let el = groupTitleEls.get(gid);
    if (!el) { el = makeGroupTitleEl(gid); groupTitleEls.set(gid, el); }

    const focused = gid === focusGid;
    const text = el.querySelector('.gtText');
    el.classList.toggle('active', focused);
    el.classList.toggle('important', isGroupImportant(gid));
    if (isGroupImportant(gid)) el.style.setProperty('--imp', groupImpColor(gid));
    else el.style.removeProperty('--imp');
    if (document.activeElement !== text) {
      const v = groupTitleOf(gid);
      if (text.textContent !== v) text.textContent = v;
    }
    text.contentEditable = focused ? 'plaintext-only' : 'false';
    text.tabIndex = focused ? 0 : -1;
    const hasTitle = !!groupTitleOf(gid);
    el.classList.toggle('empty', !hasTitle);
    // boş başlık yalnızca grup seçiliyken görünür (tahta temiz kalsın)
    el.hidden = !hasTitle && !focused;
    if (el.hidden) continue;

    const b = boundsOf(members, 0);
    const p1 = worldToScreen({ x: b.x, y: b.y });
    const p2 = worldToScreen({ x: b.x + b.w, y: b.y });
    const cx = (p1.x + p2.x) / 2;
    el.style.visibility = 'hidden';
    const w = Math.min(el.offsetWidth || 120, window.innerWidth - 20);
    el.style.left = clamp(cx, w / 2 + 10, window.innerWidth - w / 2 - 10) + 'px';
    const minTop = document.body.classList.contains('bar-hidden') ? 46 : 124;
    el.style.top  = clamp(p1.y - 8, minTop, window.innerHeight - 10) + 'px';
    el.style.visibility = '';
  }
}

function updateGroupFrame() {
  const groups = new Map();
  for (const gid of allGroupIds()) {
    const deep = groupItemsDeep(gid);
    if (deep.length >= 2 && groupUnitCount(gid) >= 2) groups.set(gid, deep);
  }

  // dağılmış grupların çerçevelerini kaldır
  for (const [gid, el] of groupFrameEls) {
    if (!groups.has(gid)) { el.remove(); groupFrameEls.delete(gid); }
  }

  const focusGid = selectedGroupId();
  const pad = 14;
  for (const [gid, members] of groups) {
    let el = groupFrameEls.get(gid);
    if (!el) {
      el = document.createElement('div');
      el.className = 'gframe';
      for (let i = 0; i < 4; i++) {
        const tick = document.createElement('i');
        tick.className = 'gtick t' + i;
        el.appendChild(tick);
      }
      // grup boyutlandırma tutamaçları (sağ/sol/üst/alt + köşeler)
      for (const [hx, hy, cls] of HANDLES) {
        const h = document.createElement('b');
        h.className = 'ghandle ' + cls;
        h.dataset.hx = hx; h.dataset.hy = hy;
        el.appendChild(h);
      }
      groupFramesEl.appendChild(el);
      groupFrameEls.set(gid, el);
    }
    el.dataset.gid = gid;
    const b = boundsOf(members, 0);
    el.style.left   = (b.x - pad) + 'px';
    el.style.top    = (b.y - pad) + 'px';
    el.style.width  = (b.w + pad * 2) + 'px';
    el.style.height = (b.h + pad * 2) + 'px';
    el.classList.toggle('active', isGroupActive(gid));
    el.classList.toggle('important', isGroupImportant(gid));
    if (isGroupImportant(gid)) el.style.setProperty('--imp', groupImpColor(gid));
    else el.style.removeProperty('--imp');
    el.classList.toggle('nested', !!groupParentOf(gid));
    el.classList.toggle('focus', gid === focusGid);
    el.style.zIndex = gid === focusGid ? 14 : 10;
  }

  updateGroupTitles();
}

/** Seçilenleri grupla; tek bir grup seçiliyse o grubu çöz */
function groupSelection() {
  if (selection.size < 2) return;
  const units = selectionUnits();
  if (!units.length) return;
  /* Çözme değilse en az iki birim gerekir. Kontrol pushUndo'dan ÖNCE
     yapılmalı: eskiden önce snapshot alınıp geri atılıyordu, bu da
     yine de yineleme (redo) geçmişini siliyordu. */
  const dissolving = units.length === 1 && units[0].type === 'group';
  if (!dissolving && units.length < 2) return;

  pushUndo();

  // tek grup seçili -> grubu çöz (iç içe gruplar korunur)
  if (dissolving) {
    dissolveGroup(units[0].gid);
    syncSelection();
    scheduleSave();
    return;
  }

  // yeni üst grup: seçilen gruplar ve tek öğeler onun altına girer
  const g = 'g_' + newId();
  if (!state.groupParents) state.groupParents = {};
  for (const u of units) {
    if (u.type === 'group') state.groupParents[u.gid] = g;
    else {
      const it = getItem(u.id);
      if (it) it.groupId = g;
    }
  }

  selection = new Set(units.flatMap(u => u.type === 'group' ? u.items.map(i => i.id) : [u.id]));
  syncSelection();
  setTimeout(() => focusGroupTitle(g), 30);
  scheduleSave();
}

/* TailRef app · text inspector, image filters, crop */
'use strict';

function selectedTextItem() {
  if (editingId) {
    const it = getItem(editingId);
    if (it && it.kind === 'text') return it;
  }
  if (selection.size === 1) {
    const it = getItem([...selection][0]);
    if (it && it.kind === 'text') return it;
  }
  return null;
}

function updateInspector() {
  const it = selectedTextItem();
  if (it) {
    showPanel(inspectorEl);
    // Kayıtlı konum ilk tutuşta uygulanınca panel aniden zıplıyordu.
    prepareFloatingPanel(inspectorEl);
  } else {
    hidePanel(inspectorEl);
  }
  if (!it) return;

  const fs = Math.round(it.fontSize || FONT_SIZE);
  if (document.activeElement !== fsRangeEl) fsRangeEl.value = String(clamp(fs, 8, 240));
  if (document.activeElement !== fsInputEl) fsInputEl.value = String(fs);
  $('#btnBold').setAttribute('aria-pressed', it.bold ? 'true' : 'false');
  $('#btnTextBg').setAttribute('aria-pressed', it.bg && it.bg !== 'transparent' ? 'true' : 'false');

}

function textAutoWidth(it) {
  const fs = it.fontSize || FONT_SIZE;
  const lines = String(it.text || '').split('\n');
  const longest = lines.reduce((m, l) => Math.max(m, l.length), 0);
  return clamp(Math.round(longest * fs * 0.62 + 28), 200, 1600);
}

function restyle(it, refreshInspector = true) {
  const el = elMap.get(it.id);
  if (el) {
    if (it.kind === 'text') {
      it.w = textAutoWidth(it);
      el.style.width = it.w + 'px';
    }
    updateItemEl(it, el);
  }
  scheduleSave();
  if (refreshInspector) updateInspector();
}

inspectorEl.addEventListener('click', e => {
  const btn = e.target.closest('button');
  if (!btn) return;
  const it = selectedTextItem();
  if (!it) return;

  /* Metin görünümünü değiştiren her düğme geri alınabilir olmalı;
     kopyala/sil kendi adımını atar. */
  if (btn.dataset.color) {
    pushUndo();
    it.color = btn.dataset.color;
    restyle(it);
    return;
  }

  const fs = it.fontSize || FONT_SIZE;
  switch (btn.dataset.act) {
    case 'fs+': pushUndo(); it.fontSize = clamp(fs + 4, 8, 400); break;
    case 'fs-': pushUndo(); it.fontSize = clamp(fs - 4, 8, 400); break;
    case 'bold': pushUndo(); it.bold = !it.bold; break;
    case 'bg': {
      pushUndo();
      const opts = [null, 'rgba(0,0,0,.35)', 'rgba(0,0,0,.72)', 'rgba(255,255,255,.88)'];
      const idx  = opts.indexOf(it.bg || null);
      it.bg = opts[(idx + 1) % opts.length];
      break;
    }
    case 'dup': duplicateSelection(); return;
    case 'del': removeItems([it.id], true); return;
    default: return;
  }
  restyle(it);
});

/* yazı boyutu: kaydırıcı + sayı kutusu */
function setTextSize(value, undo = false) {
  const it = selectedTextItem();
  if (!it) return;
  if (undo) pushUndo();
  it.fontSize = clamp(Math.round(Number(value) || FONT_SIZE), 8, 400);
  if (fsRangeEl.value !== String(it.fontSize)) fsRangeEl.value = String(clamp(it.fontSize, 8, 240));
  if (document.activeElement !== fsInputEl) fsInputEl.value = String(it.fontSize);
  // Slider sürüklenirken paneli her input'ta yeniden taşımak odağı bozuyordu.
  restyle(it, false);
}
bindSliderUndo(fsRangeEl, () => !!selectedTextItem());
fsRangeEl.addEventListener('input', () => setTextSize(fsRangeEl.value));
fsInputEl.addEventListener('change', () => setTextSize(fsInputEl.value, true));
fsInputEl.addEventListener('keydown', e => {
  if (e.key === 'Enter') { e.preventDefault(); fsInputEl.blur(); }
  if (e.key === 'Escape') { e.preventDefault(); updateInspector(); fsInputEl.blur(); }
});

/* ---------------- seçili görsel paneli ---------------- */

/* Kaydırıcı geri alma: anlık görüntü pointerdown anında alınır, yığına
   yalnız ilk GERÇEK input'ta yazılır. Kaydırıcıya sadece dokunup bırakmak
   boş bir geri-alma adımı bırakmaz. Klavye ile ince ayarda (pointer yok)
   her input kendi adımıdır; değer değişmeden input gelmez. */
function bindSliderUndo(control, enabled) {
  if (!control) return;
  let armed = null;
  let pointerActive = false;
  const ready = () => (typeof enabled === 'function' ? enabled() : true);
  control.addEventListener('pointerdown', () => {
    pointerActive = true;
    armed = ready() ? maskSnapStringify(createStateSnapshot()) : null;
  });
  const end = () => { pointerActive = false; armed = null; };
  control.addEventListener('pointerup', end);
  control.addEventListener('pointercancel', end);
  control.addEventListener('change', end);
  control.addEventListener('input', () => {
    if (!ready()) { armed = null; return; }
    if (armed) { const snap = armed; armed = null; pushUndoRaw(snap); return; }
    if (!pointerActive) pushUndo();
  });
}

/* Opaklık: üst çubuktaki itemAlpha ile panel içindeki fOpacity AYNI değer
   sürer; iki kaydırıcı senkron kalır, okumalar yüzde gösterir. */
function applyImageAlpha(val) {
  const its = selectedImageItems();
  if (!its.length) return;
  const pct = String(clamp(Math.round(val * 100), 5, 100));
  for (const it of its) {
    it.alpha = clamp(Number(pct) / 100, 0, 1);
    const el = elMap.get(it.id);
    const media = el && el.firstChild;
    if (media && media.style) {
      if (it.alpha < 1) media.style.opacity = String(it.alpha);
      else media.style.removeProperty('opacity');
    }
  }
  /* Her iki kontrol de aynı değerden okur — hangisi sürüklenirse sürüklesin. */
  if (document.activeElement !== itemAlphaEl) itemAlphaEl.value = pct;
  syncRangeFill(itemAlphaEl);
  if (document.activeElement !== fOpacityEl) fOpacityEl.value = pct;
  syncRangeFill(fOpacityEl);
  alphaValEl.textContent = pct + '%';
  if (fOpacityValEl) fOpacityValEl.textContent = '%' + pct;
  syncImageSliderFills();
  scheduleSave();
}

bindSliderUndo(itemAlphaEl, () => selectedImageItems().length > 0);
itemAlphaEl.addEventListener('input', () => {
  applyImageAlpha(Number(itemAlphaEl.value) / 100);
});

bindSliderUndo(fOpacityEl, () => selectedImageItems().length > 0);
fOpacityEl.addEventListener('input', () => {
  applyImageAlpha(Number(fOpacityEl.value) / 100);
});

/* Renk bölümü kaydırıcıları — okumalar: doygunluk ham %, parlaklık/kontrast
   sapma %, sıcaklık işaretli sayı. */
function getImageFilterValues() {
  return {
    gray: Number(fGrayEl.value),
    bright: Number(fBrightEl.value),
    contrast: Number(fContrastEl.value),
    temp: Number(fTempEl.value) || 0,
  };
}

/* Programatik değer atamalarında (elle giriş, hazır ayar, seçim
   senkronu) kaydırıcı dolgusu CSS'i --fill tazelenmeli: .value atamak
   'input' olayı üretmez, dolgu eski yerde kalırdı (kullanıcı raporu:
   "elimle sayı girince slider bozuluyor"). */
function syncImageSliderFills() {
  for (const ctl of [fGrayEl, fBrightEl, fContrastEl, fTempEl, fOpacityEl, cropTopEl, cropRightEl, cropBottomEl, cropLeftEl]) {
    syncRangeFill(ctl);
  }
}

function syncFilterReadouts(v) {
  if (fGrayValEl) fGrayValEl.textContent = String(v.gray) + '%';
  if (fBrightValEl) fBrightValEl.textContent = Math.round(v.bright - 100) + '%';
  if (fContrastValEl) fContrastValEl.textContent = Math.round(v.contrast - 100) + '%';
  if (fTempValEl) fTempValEl.textContent = (v.temp > 0 ? '+' : '') + v.temp;
}

function applyImageFilters() {
  const its = selectedImageItems();
  if (!its.length) return;
  const v = getImageFilterValues();
  for (const it of its) {
    it.fGray = v.gray;
    it.fBright = v.bright;
    it.fContrast = v.contrast;
    it.fTemp = v.temp;
    const el = elMap.get(it.id);
    if (el) updateItemEl(it, el);
  }
  syncFilterReadouts(v);
  syncImageSliderFills();
  scheduleSave();
}

for (const control of [fGrayEl, fBrightEl, fContrastEl, fTempEl]) {
  bindSliderUndo(control, () => selectedImageItems().length > 0);
  control.addEventListener('input', applyImageFilters);
}

btnResetFilter.onclick = () => {
  if (!selectedImageItems().length) return;
  pushUndo();
  fGrayEl.value = '0';
  fBrightEl.value = '100';
  fContrastEl.value = '100';
  fTempEl.value = '0';
  applyImageFilters();
};

/* -------- döndürme ve aynalama -------- */
function rotateImageSelection(delta) {
  const its = selectedImageItems();
  if (!its.length) return;
  pushUndo();
  for (const it of its) {
    it.rot = ((Math.round(it.rot || 0) + delta) % 360 + 360) % 360;
    const el = elMap.get(it.id);
    if (el) updateItemEl(it, el);
  }
  scheduleSave();
}

function flipImageSelection(axis) {
  const its = selectedImageItems();
  if (!its.length) return;
  pushUndo();
  for (const it of its) {
    if (axis === 'h') it.flipH = !it.flipH;
    else it.flipV = !it.flipV;
    const el = elMap.get(it.id);
    if (el) updateItemEl(it, el);
  }
  const first = its[0];
  if (btnImageFlipH) btnImageFlipH.setAttribute('aria-pressed', first.flipH ? 'true' : 'false');
  if (btnImageFlipV) btnImageFlipV.setAttribute('aria-pressed', first.flipV ? 'true' : 'false');
  scheduleSave();
}

if (btnImageRotL) btnImageRotL.addEventListener('click', () => rotateImageSelection(-90));
if (btnImageRotR) btnImageRotR.addEventListener('click', () => rotateImageSelection(90));
if (btnImageFlipH) btnImageFlipH.addEventListener('click', () => flipImageSelection('h'));
if (btnImageFlipV) btnImageFlipV.addEventListener('click', () => flipImageSelection('v'));

/* -------- kırpma -------- */
/** Kaydırıcıları ve px okumalarını seçili ilk görselden yeniler. */
function syncCropControls() {
  const its = selectedImageItems();
  const it = its[0];
  if (!it || it.kind !== 'image') return;
  cropTopEl.value = String(it.cropTop || 0);
  cropRightEl.value = String(it.cropRight || 0);
  cropBottomEl.value = String(it.cropBottom || 0);
  cropLeftEl.value = String(it.cropLeft || 0);
  for (const ctl of [cropTopEl, cropRightEl, cropBottomEl, cropLeftEl]) syncRangeFill(ctl);
  updateCropPxOutputs(it);
}

function applyCrop() {
  const its = selectedImageItems();
  if (!its.length) return;
  const values = {
    cropTop: Number(cropTopEl.value), cropRight: Number(cropRightEl.value),
    cropBottom: Number(cropBottomEl.value), cropLeft: Number(cropLeftEl.value),
  };
  for (const it of its) {
    Object.assign(it, values);
    const el = elMap.get(it.id);
    if (el) updateItemEl(it, el);
  }
  updateCropPxOutputs(its[0]);
  syncImageSliderFills();
  scheduleSave();
}

for (const control of [cropTopEl, cropRightEl, cropBottomEl, cropLeftEl]) {
  bindSliderUndo(control, () => selectedImageItems().length > 0);
  control.addEventListener('input', applyCrop);
}

/* ---- sağdaki okumaları elle girilebilir yap (kullanıcı isteği:
   "sağdaki değerlere iki kez tıklayıp değeri kendim girmek istiyorum")
   → çift tık satır içi kutu açar; Enter/odak kaybı işler, Esc vazgeçer. ---- */
function makeValueEditable(out, apply) {
  if (!out) return;
  out.classList.add('ieValEditable');
  out.title = 'Double-click to type manually';
  out.addEventListener('dblclick', () => {
    if (out.querySelector('input')) return;
    const prevText = out.textContent;
    const inp = document.createElement('input');
    inp.type = 'text';
    inp.className = 'ieValInput';
    inp.value = prevText.replace(/[%,]|px/g, '').trim();
    out.textContent = '';
    out.appendChild(inp);
    inp.focus();
    inp.select();
    let done = false;
    const commit = ok => {
      if (done) return;
      done = true;
      const raw = String(inp.value).replace(/,/, '.').replace(/[^\d.+-]/g, '');
      inp.remove();
      const v = parseFloat(raw);
      if (ok && Number.isFinite(v)) apply(v);
      /* uygulanamadıysa eski yazı geri gelsin */
      if (!out.textContent) out.textContent = prevText;
    };
    inp.addEventListener('keydown', e => {
      e.stopPropagation();
      if (e.key === 'Enter') { e.preventDefault(); commit(true); }
      else if (e.key === 'Escape') { e.preventDefault(); commit(false); }
    });
    inp.addEventListener('blur', () => commit(true));
  });
}

/* Renk bölümü: okumalar kaydırıcı dilini konuşur — doygunluk ham %,
   parlaklık/kontrast sapma % (kutuya yazılan = 100 + fark), sıcaklık işaretli. */
makeValueEditable(fGrayValEl, v => {
  if (!selectedImageItems().length) return;
  pushUndo();
  fGrayEl.value = String(clamp(Math.round(v), 0, 100));
  applyImageFilters();
});
makeValueEditable(fBrightValEl, v => {
  if (!selectedImageItems().length) return;
  pushUndo();
  fBrightEl.value = String(clamp(Math.round(v + 100), 0, 200));
  applyImageFilters();
});
makeValueEditable(fContrastValEl, v => {
  if (!selectedImageItems().length) return;
  pushUndo();
  fContrastEl.value = String(clamp(Math.round(v + 100), 0, 200));
  applyImageFilters();
});
makeValueEditable(fTempValEl, v => {
  if (!selectedImageItems().length) return;
  pushUndo();
  fTempEl.value = String(clamp(Math.round(v), -100, 100));
  applyImageFilters();
});
makeValueEditable(fOpacityValEl, v => {
  if (!selectedImageItems().length) return;
  pushUndo();
  applyImageAlpha(clamp(Math.round(v), 5, 100) / 100);
});

/* Kırpma: kutucuk px bekler → yüzdelik kaydırıcıya çevrilir.
   Üst/Alt çokluğu öğe yüksekliği, Sağ/Sol genişliği ölçek alır. */
function makeCropOutputEditable(out, slider, dim) {
  makeValueEditable(out, px => {
    const it = selectedImageItems()[0];
    if (!it || it.kind !== 'image') return;
    const base = dim === 'h' ? Number(it.h) : Number(it.w);
    if (!base) return;
    pushUndo();
    slider.value = String(clamp(Math.round(px / base * 100), 0, 45));
    applyCrop();
  });
}
makeCropOutputEditable(cropTopValEl, cropTopEl, 'h');
makeCropOutputEditable(cropBottomValEl, cropBottomEl, 'h');
makeCropOutputEditable(cropLeftValEl, cropLeftEl, 'w');
makeCropOutputEditable(cropRightValEl, cropRightEl, 'w');

/* Oran hazır ayarları: merkez sabit kalarak görünür alanı hedef orana
   daraltır. Serbest->yalnızca işaret; kırpma değerlerine dokunmaz. */
function applyCropRatio(ratio) {
  const its = selectedImageItems();
  if (!its.length || !ratio) return;
  for (const it of its) {
    const top = Number(it.cropTop) || 0, right = Number(it.cropRight) || 0;
    const bottom = Number(it.cropBottom) || 0, left = Number(it.cropLeft) || 0;
    const wv = Math.max(0, 1 - (left + right) / 100);
    const hv = Math.max(0, 1 - (top + bottom) / 100);
    const itemW = Number(it.w) || 1, itemH = Number(it.h) || 1;
    const cur = (itemW * wv) / Math.max(1e-6, itemH * hv);
    let nTop = top, nRight = right, nBottom = bottom, nLeft = left;
    if (cur > ratio) {
      /* görünür alan hedeften geniş → yanlardan büyüteç */
      const targetWv = (itemH * hv * ratio) / itemW;
      const room = Math.max(0, Math.min(45 - left, 45 - right));
      const extra = Math.min(Math.max(0, (wv - targetWv) / 2 * 100), room);
      nLeft = clamp(left + extra, 0, 45);
      nRight = clamp(right + extra, 0, 45);
    } else if (cur < ratio) {
      const targetHv = (itemW * wv) / (itemH * ratio);
      const room = Math.max(0, Math.min(45 - top, 45 - bottom));
      const extra = Math.min(Math.max(0, (hv - targetHv) / 2 * 100), room);
      nTop = clamp(top + extra, 0, 45);
      nBottom = clamp(bottom + extra, 0, 45);
    }
    Object.assign(it, {
      cropTop: Math.round(nTop), cropRight: Math.round(nRight),
      cropBottom: Math.round(nBottom), cropLeft: Math.round(nLeft),
    });
    const el = elMap.get(it.id);
    if (el) updateItemEl(it, el);
  }
  syncCropControls();
  scheduleSave();
}

if (ieRatioGroupEl) {
  ieRatioGroupEl.addEventListener('click', e => {
    const btn = e.target.closest('button[data-ratio]');
    if (!btn) return;
    const ratio = Number(btn.dataset.ratio) || 0;
    for (const b of ieRatioGroupEl.querySelectorAll('button[data-ratio]')) {
      b.classList.toggle('on', b === btn);
    }
    if (ratio && selectedImageItems().length) {
      pushUndo();
      applyCropRatio(ratio);
    }
  });
}

btnEditImage.onclick = () => {
  openStudioPanel(imageEditorEl);
};
btnImageEditorClose.onclick = () => closeStudioPanel(imageEditorEl);

btnImportant.onclick = () => {
  const its = selectedImageItems();
  if (!its.length) return;
  pushUndo();

  // Grup seçiliyse: sadece grubun dış çizgileri kırmızı olur, fotoğraflar değişmez
  const gid = selectedGroupId();
  if (gid) {
    const on = !isGroupImportant(gid);
    setGroupImportant(gid, on);
    btnImportant.setAttribute('aria-pressed', on ? 'true' : 'false');
    scheduleSave();
    updateItemBar();
    return;
  }

  const on = !its.every(i => i.important);
  const color = on ? randomImpColor() : '';
  for (const it of its) {
    it.important = on;
    if (on) it.impColor = color;
    else delete it.impColor;
    const el = elMap.get(it.id);
    if (el) {
      el.classList.toggle('important', on);
      if (on) el.style.setProperty('--imp', color);
      else el.style.removeProperty('--imp');
    }
  }
  btnImportant.setAttribute('aria-pressed', on ? 'true' : 'false');
  updateGroupFrame();
  scheduleSave();
};

/* TailRef app · dominant palette, color wheel, important color
   ------------------------------------------------------------------
   FAZ 3-3: palet hattı OKLCH/OKLab'da çalışır (56-ink-color.js):
     • aday üretim   — pikseller OKLab'ta toplanır; LCH eşikleri algısal
     • boşluk ölçümü — paletteGap OKLCH H/L/C üzerinde
     • ton doldurma  — inkOkLchToBytes ile shade üretimi
     • sıralama      — gri chroması + OKLCH hue sırası
   colorDistance sRGB bayt hipoteni kalır (bayt eşikleri kalibre
   edilmeden davranış kaymasın). Eski HSV üçlülerü (rgbToHsvTriplet /
   hsvToRgbTriplet / hsvToHex / hexToHsv) SİLİNDİ — ölü kod kalmaz.
   ========================================================= */
'use strict';

function colorDistance(a, b) {
  return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
}

const PALETTE_SIZE = 10;
const PALETTE_COLUMNS = 5;
const PALETTE_HUE_BINS = 24;      // 15°'lik bağımsız OKLCH hue aileleri
const PALETTE_LIGHT_BINS = 4;
/* FAZ 3-3: doygunluk/düzey eşiği HSV'den OKLCH'ye taşındı.
   NEUTRAL_CHROMA 0.015: algısal gri eşiği. CHROMA_NORM 0.25 ≈ tam
   doygun referansı (eski s 0..1 ölçeğine normalize için). */
const PALETTE_NEUTRAL_CHROMA = 0.015;
const PALETTE_VIVID_CHROMA = 0.075;
const PALETTE_CHROMA_NORM = 0.25;

// Hue + L + chroma farkını birlikte ölçer. Düşük chromada hue
// önemsizleşir — eski HSV formülünün şekli, algısal uzayda.
function paletteGap(a, b) {
  const cA = Math.min(1, Math.max(0, a.c / PALETTE_CHROMA_NORM));
  const cB = Math.min(1, Math.max(0, b.c / PALETTE_CHROMA_NORM));
  const dh = Math.min(Math.abs(a.h - b.h), 360 - Math.abs(a.h - b.h));
  const hueGap = (dh / 180) * Math.min(cA, cB);
  return Math.hypot(hueGap * 1.45, Math.abs(a.l - b.l), Math.abs(cA - cB) * 0.6);
}

function buildPaletteCandidates(pixels) {
  const bins = new Map();
  for (let i = 0; i < pixels.length; i += 4) {
    if (pixels[i + 3] < 128) continue;
    const lch = inkRgbBytesToOkLch(pixels[i], pixels[i + 1], pixels[i + 2]);
    const neutral = lch.c < PALETTE_NEUTRAL_CHROMA || lch.l < 0.07;
    const family = neutral
      ? 'n'
      : String(Math.min(PALETTE_HUE_BINS - 1, Math.floor(lch.h / (360 / PALETTE_HUE_BINS))));
    const lBin = Math.min(PALETTE_LIGHT_BINS - 1, Math.floor(lch.l * PALETTE_LIGHT_BINS));
    const key = family + '|' + lBin;
    const bin = bins.get(key) || { family, sum: [0, 0, 0], count: 0 };
    bin.sum[0] += lch.L; bin.sum[1] += lch.a; bin.sum[2] += lch.b; bin.count++;
    bins.set(key, bin);
  }
  return [...bins.values()].map(bin => {
    const L = bin.sum[0] / bin.count, A = bin.sum[1] / bin.count, B = bin.sum[2] / bin.count;
    const lch = inkOkLabToOkLch(L, A, B);
    const rgbB = inkOkLabToBytes(L, A, B);
    const rgb = [rgbB.r, rgbB.g, rgbB.b];
    // Alan büyüklüğü logaritmayla sönümlenir: aynı tondaki dev bir alan
    // paletin birkaç slotunu birden ele geçiremez. Canlılık payı
    // algısal chroma'dan gelir (0.25 = tam doygun referansı).
    const vivid = Math.min(1, lch.c / PALETTE_CHROMA_NORM);
    const score = Math.log1p(bin.count) * (0.45 + 0.55 * vivid);
    return { rgb, count: bin.count, family: bin.family, h: lch.h, c: lch.c, l: lch.l, score };
  }).sort((a, b) => b.score - a.score);
}

function pickPaletteColors(candidates) {
  if (!candidates.length) return fillPaletteToTen([[128, 128, 128]]);
  const total = candidates.reduce((sum, c) => sum + c.count, 0);
  // Çok küçük kenar/yumuşatma lekelerini ele; canlı küçük detaylar korunur.
  const minCount = Math.max(10, Math.round(total * 0.0015));
  const minVividCount = Math.max(6, Math.round(total * 0.0004));
  const usable = candidates.filter(c =>
    c.count >= minCount || (c.c >= PALETTE_VIVID_CHROMA && c.count >= minVividCount));
  const source = usable.length ? usable : candidates;

  const byFamily = new Map();
  for (const c of source) {
    if (!byFamily.has(c.family)) byFamily.set(c.family, []);
    byFamily.get(c.family).push(c);
  }
  const families = [...byFamily.entries()].map(([family, list]) => {
    list.sort((a, b) => b.score - a.score);
    return { family, list, top: list[0] };
  }).sort((a, b) => b.top.score - a.top.score);

  const chromaticFamilies = families.filter(f => f.family !== 'n').length;
  const neutralCap = chromaticFamilies ? 2 : PALETTE_SIZE;
  const selected = [];
  let neutralUsed = 0;
  const accept = (c, minGap) => {
    if (selected.length >= PALETTE_SIZE) return false;
    if (c.family === 'n' && neutralUsed >= neutralCap) return false;
    for (const chosen of selected) {
      if (paletteGap(c, chosen) < minGap) return false;
      if (colorDistance(c.rgb, chosen.rgb) < 24) return false;
    }
    selected.push(c);
    if (c.family === 'n') neutralUsed++;
    return true;
  };

  // 1. geçiş: her hue ailesinden yalnızca bir anahtar renk alınır.
  // Böylece tek bir rengin tonları paleti doldurmaz, farklı hue'lar kaçmaz.
  for (const fam of families) {
    for (const c of fam.list) {
      if (accept(c, 0.16)) break;
    }
    if (selected.length >= PALETTE_SIZE) break;
  }
  // 2. geçiş: görselde 10'dan az hue ailesi varsa boşlukları, seçilenlerden
  // en bağımsız (hue + value farkı en büyük) renklerle doldur.
  while (selected.length < PALETTE_SIZE) {
    let best = null, bestPriority = -1;
    for (const c of source) {
      if (selected.includes(c)) continue;
      if (c.family === 'n' && neutralUsed >= neutralCap) continue;
      let gap = Infinity;
      for (const chosen of selected) {
        gap = Math.min(gap, paletteGap(c, chosen));
      }
      if (gap < 0.14) continue;
      if (selected.some(chosen => colorDistance(c.rgb, chosen.rgb) < 24)) continue;
      const priority = c.score * gap;
      if (priority > bestPriority) { bestPriority = priority; best = c; }
    }
    if (!best) break;
    selected.push(best);
    if (best.family === 'n') neutralUsed++;
  }

  return sortPaletteColors(fillPaletteToTen(selected.map(c => c.rgb)));
}

function fillPaletteToTen(rgbList) {
  const colors = rgbList.map(rgb => rgb.slice());
  const bases = colors.map(rgb => {
    const lch = inkRgbBytesToOkLch(rgb[0], rgb[1], rgb[2]);
    return { h: lch.h, c: lch.c };
  });
  // Ton çeşitliliği azsa boşlukları tek bir rengin tonlarıyla değil,
  // seçilen renklerin tamamına sırayla dağıtarak doldur.
  // FAZ 3-3: shade düzlemi OKLCH — v (0.2..0.99) → L, s katmanı → chroma
  // katmanı (0.04·s ≈ 0.01 c, 0.02·s ≈ 0.005 c tabanları korunarak).
  for (const l of [0.2, 0.34, 0.48, 0.62, 0.76, 0.9, 0.99]) {
    for (const base of bases) {
      if (colors.length >= PALETTE_SIZE) break;
      for (const [c, threshold] of [[Math.max(0.01, base.c * 0.9), 14], [Math.max(0.005, base.c * 0.35), 18]]) {
        if (colors.length >= PALETTE_SIZE) break;
        const shade = inkOkLchToBytes(l, c, base.h);
        const rgb = [shade.r, shade.g, shade.b];
        if (colors.every(col => colorDistance(col, rgb) >= threshold)) colors.push(rgb);
      }
    }
    if (colors.length >= PALETTE_SIZE) break;
  }
  const grays = [16, 44, 72, 100, 128, 156, 184, 212, 240];
  for (const g of grays) {
    if (colors.length >= PALETTE_SIZE) break;
    const rgb = [g, g, g];
    if (colors.every(col => colorDistance(col, rgb) >= 10)) colors.push(rgb);
  }
  while (colors.length < PALETTE_SIZE) colors.push([128, 128, 128]);
  return colors.slice(0, PALETTE_SIZE);
}

function sortPaletteColors(rgbList) {
  return rgbList.map(rgb => {
    const lch = inkRgbBytesToOkLch(rgb[0], rgb[1], rgb[2]);
    return { rgb, h: lch.h, c: lch.c, l: lch.l };
  }).sort((a, b) => {
    const aNeutral = a.c < PALETTE_NEUTRAL_CHROMA, bNeutral = b.c < PALETTE_NEUTRAL_CHROMA;
    if (aNeutral !== bNeutral) return aNeutral ? 1 : -1;
    if (aNeutral) return a.l - b.l;
    return (a.h - b.h) || (a.l - b.l);
  });
}

function paletteHex(rgb) {
  return '#' + rgb.map(v => Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0')).join('').toUpperCase();
}

function renderPaletteCard(colors) {
  const cols = PALETTE_COLUMNS, rows = Math.ceil(PALETTE_SIZE / cols);
  const padX = 32, padTop = 60, boxW = 130, boxH = 116, gapX = 14, labelH = 24, rowGap = 18;
  const rowStep = boxH + labelH + rowGap;
  const canvas = document.createElement('canvas');
  canvas.width = padX * 2 + cols * boxW + (cols - 1) * gapX;
  canvas.height = padTop + rows * rowStep - rowGap + 18;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#f4f3ef'; ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#202124'; ctx.font = '700 23px "Segoe UI", Arial, sans-serif';
  ctx.fillText('TailRef COLOR PALETTE', padX, 40);
  ctx.fillStyle = 'rgba(32,33,36,.55)'; ctx.font = '600 12px "Segoe UI", Arial, sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText('10 KEY COLORS · HUE + VALUE', canvas.width - padX, 39);
  ctx.textAlign = 'left';

  colors.forEach((c, i) => {
    const x = padX + (i % cols) * (boxW + gapX);
    const y = padTop + Math.floor(i / cols) * rowStep;
    const hex = paletteHex(c.rgb);
    ctx.fillStyle = hex;
    if (typeof ctx.roundRect === 'function') {
      ctx.beginPath(); ctx.roundRect(x, y, boxW, boxH, 7); ctx.fill();
    } else {
      ctx.fillRect(x, y, boxW, boxH);
    }
    ctx.strokeStyle = 'rgba(0,0,0,.16)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = '#2b2c2f'; ctx.font = '600 15px "Segoe UI", Arial, sans-serif';
    ctx.fillText(hex, x + 2, y + boxH + 19);
  });
  return canvas;
}

async function createDominantPalette() {
  const it = selectedImageItems().find(item => !item.paletteGenerated);
  if (!it) return;
  const cached = imgCache.get(it.imageId);
  if (!cached || !cached.img) return;

  const src = cached.img;
  const sample = document.createElement('canvas');
  const sw = 200, sh = Math.max(1, Math.round((src.naturalHeight / src.naturalWidth) * sw));
  sample.width = sw; sample.height = Math.min(sh, 200);
  const sg = sample.getContext('2d', { willReadFrequently: true });
  sg.drawImage(src, 0, 0, sample.width, sample.height);
  const pixels = sg.getImageData(0, 0, sample.width, sample.height).data;
  const colors = pickPaletteColors(buildPaletteCandidates(pixels));
  const canvas = renderPaletteCard(colors);

  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
  if (!blob) return;
  const file = new File([blob], 'tailref-renk-paleti.png', { type: 'image/png' });
  await addFiles([file], { x: it.x + it.w + 36, y: it.y }, { paletteGenerated: true });
}

btnPalette.onclick = () => createDominantPalette();

$('#btnItemDup').onclick = () => duplicateSelection();
$('#btnItemDel').onclick = () => deleteSelection();

/* ---------------- önemli rengi çarkı ----------------
   Düğmenin üstünde bekleyince altında renk çarkı açılır;
   tıklanan renk seçili görsele / gruba atanır.
   FAZ 3-3: eski hsvToHex/hexToHsv SİLİNDİ; çark artık fırça çarkıyla
   aynı yardımcılardan beslenir — inkWheelStateToHex (halka kimliği
   eski saf ton tanımıyla birebir; koşu beyaza OKLCH-L'de gider) ve
   inkHexToWheelState (ters eşleme, çark açısı köşe seçicidir). */
const impWrapEl   = $('#impWrap');
const impWheelEl  = $('#impWheel');
const wheelDiscEl = $('#wheelDisc');
const wheelDotEl  = $('#wheelDot');
const wheelPrevEl = $('#wheelPrev');
const wheelHexEl  = $('#wheelHex');
let wheelShowTimer = 0, wheelHideTimer = 0;

function placeWheelDot(hex) {
  const c = /^#[0-9a-f]{6}$/i.test(hex) ? hex : IMP_FALLBACK;
  const st = inkHexToWheelState(c);
  const r = wheelDiscEl.getBoundingClientRect();
  const rad = (r.width / 2) * Math.max(0, Math.min(1, st.s));
  const a = st.h * Math.PI / 180;
  wheelDotEl.style.left = (r.width / 2 + Math.cos(a) * rad) + 'px';
  wheelDotEl.style.top  = (r.height / 2 + Math.sin(a) * rad) + 'px';
  wheelDotEl.style.background = c;
}

function setWheelPreview(hex) {
  const c = /^#[0-9a-f]{6}$/i.test(hex) ? hex : IMP_FALLBACK;
  wheelPrevEl.style.background = c;
  wheelHexEl.textContent = c.toUpperCase();
  placeWheelDot(c);
}

/** imlecin çark üzerindeki rengi (konum da güncellenir) */
function wheelPickAt(ev) {
  const r = wheelDiscEl.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const dx = ev.clientX - cx, dy = ev.clientY - cy;
  const maxR = Math.max(1, r.width / 2);
  const dist = Math.min(Math.hypot(dx, dy), maxR);
  const hue = ((Math.atan2(dy, dx) * 180 / Math.PI) + 360) % 360;
  const sat = dist / maxR;
  const hex = inkWheelStateToHex(hue, sat, 1);
  wheelDotEl.style.left = (r.width / 2 + Math.cos(hue * Math.PI / 180) * dist) + 'px';
  wheelDotEl.style.top  = (r.height / 2 + Math.sin(hue * Math.PI / 180) * dist) + 'px';
  wheelDotEl.style.background = hex;
  wheelPrevEl.style.background = hex;
  wheelHexEl.textContent = hex.toUpperCase();
  return hex;
}

function currentImpColor() {
  const its = selectedImageItems();
  const gid = selectedGroupId();
  if (gid) return isGroupImportant(gid) ? groupImpColor(gid) : '';
  const marked = its.find(i => i.important);
  return marked ? impColorOf(marked) : '';
}

/** Çarkı, görünür olduğu panelin dışına taşmadan ••• düğmesine hizalar. */
function positionImpWheel() {
  if (!impWheelEl || impWheelEl.hidden || !btnImportant) return;
  /* Çark, açıldığı itemBar'ın HEMEN ÜSTÜNDE yaşar: itemBar tutulup
     yükseltilince (kayan z bandı 2300+) sabit 2400 sınıfının ALTINA
     düşüyordu — "çark panelin altında kalıyor, renk seçilmiyor". */
  if (typeof floatingPanelZ === 'function') {
    const host = document.getElementById('itemBar');
    if (host) impWheelEl.style.zIndex = String(floatingPanelZ(host) + 4);
  }
  const anchor = btnImportant.getBoundingClientRect();
  const width = impWheelEl.offsetWidth || 168;
  const height = impWheelEl.offsetHeight || 190;
  const margin = 8;
  const gap = 8;

  let left = anchor.left + anchor.width / 2 - width / 2;
  let top = anchor.bottom + gap;
  let up = false;

  // Altında yer yoksa çarkı düğmenin üstüne al.
  if (top + height > innerHeight - margin) {
    top = anchor.top - height - gap;
    up = top >= margin;
  }
  // Her iki taraf da sığmıyorsa görünür alanda tut.
  top = clamp(top, margin, Math.max(margin, innerHeight - height - margin));
  left = clamp(left, margin, Math.max(margin, innerWidth - width - margin));

  impWheelEl.classList.toggle('up', up);
  impWheelEl.style.left = `${Math.round(left)}px`;
  impWheelEl.style.top = `${Math.round(top)}px`;
  impWheelEl.style.marginLeft = '0px';
}

function showImpWheel() {
  if (!selectedImageItems().length) return;
  impWheelEl.classList.remove('up');
  impWheelEl.style.marginLeft = '0px';
  showPanel(impWheelEl);
  positionImpWheel();
  requestAnimationFrame(positionImpWheel);
  setWheelPreview(currentImpColor() || IMP_FALLBACK);
}

function hideImpWheel() {
  clearTimeout(wheelShowTimer);
  clearTimeout(wheelHideTimer);
  hidePanel(impWheelEl);
}

impWrapEl.addEventListener('pointerenter', () => {
  clearTimeout(wheelShowTimer);
  clearTimeout(wheelHideTimer);
  wheelShowTimer = setTimeout(showImpWheel, 420);
});
impWrapEl.addEventListener('pointerleave', () => {
  clearTimeout(wheelShowTimer);
  clearTimeout(wheelHideTimer);
  wheelHideTimer = setTimeout(hideImpWheel, 220);
});

// Çark artık panelin dışında (body çocuğu) olduğu için düğmeden çarka
// geçerken kapanma sayacı iptal edilir; çarktan çıkınca yeniden başlar.
impWheelEl.addEventListener('pointerenter', () => {
  clearTimeout(wheelHideTimer);
  clearTimeout(wheelShowTimer);
});
impWheelEl.addEventListener('pointerleave', () => {
  clearTimeout(wheelHideTimer);
  wheelHideTimer = setTimeout(hideImpWheel, 240);
});

wheelDiscEl.addEventListener('pointermove', ev => {
  if (ev.buttons) return;
  wheelPickAt(ev);
});

wheelDiscEl.addEventListener('pointerdown', ev => {
  ev.preventDefault();
  ev.stopPropagation();
  const hex = wheelPickAt(ev);
  applyImpColor(hex);
  hideImpWheel();
});

/** seçili görsele/gruba istenen önemli rengini atar */
function applyImpColor(color) {
  const its = selectedImageItems();
  if (!its.length) return;
  pushUndo();

  const gid = selectedGroupId();
  if (gid) {
    // grup seçili: sadece grup çizgileri/başlığı renklenir, fotoğraflar değişmez
    setGroupImportant(gid, true, color);
  } else {
    for (const it of its) {
      it.important = true;
      it.impColor = color;
      const el = elMap.get(it.id);
      if (el) {
        el.classList.add('important');
        el.style.setProperty('--imp', color);
      }
    }
    updateGroupFrame();
  }

  btnImportant.setAttribute('aria-pressed', 'true');
  scheduleSave();
  updateItemBar();
}

// çark dışına tıklanınca kapat
window.addEventListener('pointerdown', ev => {
  if (isPanelVisible(impWheelEl) &&
      !impWrapEl.contains(ev.target) &&
      !impWheelEl.contains(ev.target)) {
    hideImpWheel();
  }
}, true);

// Panel içeriği kaydırılınca düğme yer değiştirir; çarkı kapat.
itemBarEl.querySelector('.itemBarContent')?.addEventListener('scroll', () => {
  if (isPanelVisible(impWheelEl)) hideImpWheel();
}, { passive: true });

window.addEventListener('resize', () => {
  updateItemBar();
  if (isPanelVisible(impWheelEl)) positionImpWheel();
});

/* TailRef app · add files/text, editing, removal */
'use strict';

/* =========================================================
   öğe işlemleri
   ========================================================= */
async function addFiles(fileList, atWorld, options = {}) {
  const all = Array.from(fileList).filter(f => f);
  /* Sessiz yutma bug'ı: video/PDF gibi desteklenmeyen dosyalar hiçbir
     geri bildirim olmadan kayboluyordu. Kullanıcı artık nedenini görür. */
  const skipped = all.filter(f => f.type && !f.type.startsWith('image/'));
  if (skipped.length) {
    try { toast('Only images and GIFs can be added to the board · video support in development', 4200); }
    catch { /* toast yoksa sessiz kalma davranışına geri dön */ }
  }
  const files = all.filter(f => f && f.type && f.type.startsWith('image/'));
  if (!files.length) return;
  const paletteGenerated = !!options.paletteGenerated;

  pushUndo();
  const base = atWorld || screenToWorld({ x: stage.clientWidth / 2, y: stage.clientHeight / 2 });
  const added = [];

  for (let i = 0; i < files.length; i++) {
    const f = files[i];
    let entry;
    try {
      entry = await decodeImage(f);
    } catch (e) {
      console.warn('image could not open: ', f.name, e);
      continue;
    }

    const imageId = 'img_' + newId();
    /* Blob yazılıp öğeye bağlanana kadar GC turu denk gelirse görsel
       "sahipsiz" sanılıp silinebilir; sayaç GC'yi bekletir. */
    beginImageWrite();
    try {
      await idbPut('images', imageId, { blob: f, name: f.name || 'pasted.png', savedAt: Date.now() });
      setImgCache(imageId, { img: entry.img, url: entry.url, name: f.name || '' });

      // doğal boyut, ekranın %55'inden büyükse küçült
      let w = entry.img.naturalWidth  || 400;
      let h = entry.img.naturalHeight || 300;
      const maxW = (stage.clientWidth / state.view.scale) * 0.55;
      if (w > maxW) { const k = maxW / w; w *= k; h *= k; }

      const it = {
        id: 'it_' + newId(),
        kind: 'image',
        imageId,
        x: 0, y: 0,
        w, h, rot: 0, z: nextZ(),
      };
      // Üretilen palet görselinden tekrar palet üretilmesini engelle.
      if (paletteGenerated) it.paletteGenerated = true;
      state.items.push(it);
      added.push(it);
    } finally {
      endImageWrite();
    }
  }

  if (!added.length) return;

  // tek görsel: imlecin/tuval merkezinin tam ortasına
  // çoklu görsel: yan yana dizmek yerine boyutlarına dokunmadan kareye yakın blok
  layoutAdded(added, base);

  selection = new Set(added.map(it => it.id));
  syncAll();
  if (added.length > 1) fitItemsIfNeeded(added);
  scheduleSave();
}

/** Görselleri boyutlarını değiştirmeden, kareye en yakın ızgaraya yerleştirir */
function layoutAdded(items, base, gap = 22) {
  const n = items.length;
  if (!n) return;
  if (n === 1) {
    items[0].x = base.x - items[0].w / 2;
    items[0].y = base.y - items[0].h / 2;
    return;
  }

  let best = null;
  for (let cols = 1; cols <= n; cols++) {
    const rows = Math.ceil(n / cols);
    const colW = new Array(cols).fill(0);
    const rowH = new Array(rows).fill(0);
    items.forEach((it, i) => {
      const c = i % cols, r = Math.floor(i / cols);
      if (it.w > colW[c]) colW[c] = it.w;
      if (it.h > rowH[r]) rowH[r] = it.h;
    });
    const W = colW.reduce((s, w) => s + w, 0) + gap * (cols - 1);
    const H = rowH.reduce((s, h) => s + h, 0) + gap * (rows - 1);
    const empty = rows * cols - n;
    // kareye yakınlık + boş hücre cezası
    const score = Math.abs(Math.log(W / Math.max(H, 1))) + empty * 0.08;
    if (!best || score < best.score) best = { cols, colW, rowH, W, H, score };
  }

  const { cols, colW, rowH, W, H } = best;
  const top = base.y - H / 2;
  const left = base.x - W / 2;
  items.forEach((it, i) => {
    const c = i % cols, r = Math.floor(i / cols);
    let x = left;
    for (let k = 0; k < c; k++) x += colW[k] + gap;
    let y = top;
    for (let k = 0; k < r; k++) y += rowH[k] + gap;
    it.x = x + (colW[c] - it.w) / 2;
    it.y = y + (rowH[r] - it.h) / 2;
  });
}

/** Blok ekrana sığmıyorsa görünümü bloğa sığdır (yakınlaştırmaz) */
function fitItemsIfNeeded(items, padding = 70) {
  if (!items.length) return;
  const b = boundsOf(items, 0);
  const vw = stage.clientWidth, vh = stage.clientHeight;
  const s = clamp(
    Math.min((vw - padding * 2) / Math.max(b.w, 1), (vh - padding * 2) / Math.max(b.h, 1)),
    MIN_SCALE, MAX_SCALE
  );
  if (s >= state.view.scale) return;
  state.view.scale = s;
  state.view.x = vw / 2 - (b.x + b.w / 2) * s;
  state.view.y = vh / 2 - (b.y + b.h / 2) * s;
  applyView();
}

function decodeImage(blob) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => resolve({ img, url });
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('decode')); };
    img.src = url;
  });
}

function addText(worldPos) {
  pushUndo();
  /* Aday 7: kullanıcı varsayılanları (punto/aile) — anahtar yoksa
     mevcut davranış (FONT_SIZE + CSS ailesi). */
  const textDefs = (typeof window.tailrefTextDefaults === 'function')
    ? window.tailrefTextDefaults() : { size: FONT_SIZE, family: '' };
  const it = {
    id: 'it_' + newId(),
    kind: 'text',
    text: '',
    x: worldPos.x, y: worldPos.y,
    w: 260, h: 44, rot: 0, z: nextZ(),
    fontSize: textDefs.size, color: '#ffffff', bold: false, bg: 'rgba(0,0,0,.35)',
  };
  if (textDefs.family) it.fontFamily = textDefs.family;
  state.items.push(it);
  selection = new Set([it.id]);
  syncAll();
  /* Yeni yazının eklenmesi zaten pushUndo ile kaydedildi; ilk tuşta
     ikinci bir "boş yazı" adımı açılmasın. */
  startEdit(it, { fresh: true });
}

function startEdit(it, options = {}) {
  const el = elMap.get(it.id);
  if (!el) return;
  editingId = it.id;
  /* Metin düzenlemesi geri alınabilir olmalı: ilk gerçek girişte
     (beforeinput) düzenleme ÖNCESİ durum yığına yazılır. Yeni eklenen
     yazıda bu gerekmez (ekleme adımı zaten var). */
  textEditUndoId = options.fresh ? null : it.id;
  if (typeof setAddTool === 'function') setAddTool('text');
  el.classList.add('editing');
  const t = el.querySelector('.text');
  t.contentEditable = 'true';
  // preventScroll şart: sahne kaydırılırsa tuval görsel olarak kayar.
  t.focus({ preventScroll: true });
  const r = document.createRange();
  r.selectNodeContents(t);
  r.collapse(false);
  const s = getSelection();
  s.removeAllRanges();
  s.addRange(r);
  /* Enter = commit, Shift+Enter = satır sonu (çizim programı kalıbı).
     Daha önce Enter içeriğe kendi halinde yeni satır düşürüyor, editör
     açık kalıyordu; naif kullanıcı yazıyı bitiremiyordu. */
  if (!t.dataset.enterBound) {
    t.dataset.enterBound = '1';
    t.addEventListener('keydown', e => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        e.stopPropagation();
        commitEdit();
      }
    });
  }
  updateInspector();

}

function commitEdit() {
  if (!editingId) return;
  const id = editingId;
  const it = getItem(id);
  const el = elMap.get(id);
  const t = el && el.querySelector('.text');
  editingId = null;
  textEditUndoId = null;
  if (t) {
    if (document.activeElement === t) t.blur();
    t.contentEditable = 'false';
  }
  if (it && it.kind === 'text' && !(it.text || '').trim()) {
    removeItems([id], false, { toTrash: false });
  } else if (el) {
    el.classList.remove('editing');
  }
  updateInspector();
}

function removeItems(ids, save = true, options = {}) {
  const list = [...new Set(ids)].filter(id => getItem(id));
  if (!list.length) return;
  if (save) pushUndo();

  const set = new Set(list);
  const toTrash = options.toTrash !== false;
  const now = Date.now();
  const batchId = 'tb_' + newId();
  const removedLinks = (Array.isArray(state.links) ? state.links : [])
    .filter(link => set.has(link.from) || set.has(link.to));
  let flew = false;

  if (toTrash) {
    for (const id of list) {
      const it = getItem(id);
      const el = elMap.get(id);
      state.trash.push(makeTrashEntry(it, now, batchId, removedLinks));
      if (el) {
        const flying = it.kind === 'image' && flyItemToTrash(it, el);
        if (flying) flew = true;
        elMap.delete(id);
        if (!flying) retireItemEl(el);
        else el.remove();
      }
    }
  } else {
    for (const id of list) {
      const el = elMap.get(id);
      if (el) {
        elMap.delete(id);
        retireItemEl(el);
      }
    }
  }

  state.items = state.items.filter(i => !set.has(i.id));
  if (typeof inkHandleItemsRemoved === 'function') inkHandleItemsRemoved(set);
  for (const id of list) selection.delete(id);
  // silinen öğelere bağlı okları temizle
  if (Array.isArray(state.links)) {
    state.links = state.links.filter(l => !set.has(l.from) && !set.has(l.to));
  }
  pruneGroups();
  syncAll();
  if (toTrash) {
    showTrashDock();
    updateTrashUI(true);
    if (!flew) pulseTrashDock('catch');
  }
  if (save) scheduleSave();
}

function deleteSelection() {
  if (!selection.size) return;
  /* Kilit sözleşmesi: kilitli görsel taşınamaz, ölçeklenemez — silinmesi de
     beklenmez. Delete tuşu, öğe çubuğu ve sağ tık menüsü hep buradan geçer;
     kilitliler atlanır ve kullanıcı uyarılır (yanlışlıkla veri kaybı olmaz). */
  const locked = [];
  const free = [];
  for (const id of selection) {
    const it = getItem(id);
    if (!it) continue;
    (it.locked ? locked : free).push(id);
  }
  if (locked.length) {
    if (typeof showProjectNotice === 'function') {
      showProjectNotice(locked.length === 1
        ? 'Locked image: unlock it to delete.'
        : locked.length + ' locked images: unlock them to delete.', 2600);
    }
    if (!free.length) return;
  }
  removeItems(free, true);
}

/* =========================================================
   ÇÖP KUTUSU
   Silinen öğeler burada bekler; süresi dolunca görsel blob'u
   ile birlikte kalıcı olarak temizlenir.
   ========================================================= */
const trashDockEl = $('#trashDock');
const btnTrashDockEl = $('#btnTrashDock');
const trashCountEl = $('#trashCount');
const trashPanelEl = $('#trashPanel');
const trashListEl = $('#trashList');
const trashEmptyEl = $('#trashEmpty');
const trashTitleEl = $('#trashTitle');
const trashRetentionLabelEl = $('#trashRetentionLabel');
const btnTrashRestoreAllEl = $('#btnTrashRestoreAll');
const btnTrashPurgeEl = $('#btnTrashPurge');
const btnTrashCloseEl = $('#btnTrashClose');
const trashRetentionSelectEl = $('#trashRetention');
const trashHeadEl = trashPanelEl ? trashPanelEl.querySelector('.trashHead') : null;

const imageLoadPromises = new Map();
let trashClockTimer = null;
let trashGcTimer = null;
let trashPulseTimer = null;
let trashRenderedSignature = '';
let trashIdleTimer = null;
const TRASH_IDLE_MS = 7000;
const TRASH_PANEL_POS_KEY = 'tailref-trash-panel-pos';
let trashPanelPos = null;
try {
  const savedPos = JSON.parse(localStorage.getItem(TRASH_PANEL_POS_KEY) || 'null');
  if (savedPos && Number.isFinite(savedPos.left) && Number.isFinite(savedPos.top)) {
    trashPanelPos = { left: savedPos.left, top: savedPos.top };
  }
} catch { /* sessiz */ }

/* TailRef app · trash dock, entries, fly animations */
'use strict';

function scheduleTrashIdle() {
  clearTimeout(trashIdleTimer);
  trashIdleTimer = null;
  if (!trashDockEl || isPanelVisible(trashPanelEl)) return;
  trashIdleTimer = setTimeout(() => {
    trashIdleTimer = null;
    if (!trashDockEl || isPanelVisible(trashPanelEl)) return;
    if (trashDockEl.matches(':hover') || trashDockEl.contains(document.activeElement)) {
      scheduleTrashIdle();
      return;
    }
    trashDockEl.classList.add('is-idle');
  }, TRASH_IDLE_MS);
}

function showTrashDock(restartIdle = true) {
  if (!trashDockEl) return;
  trashDockEl.classList.remove('is-idle');
  if (restartIdle) scheduleTrashIdle();
}

function trashDockHotZone(x, y) {
  const margin = 120;
  return x >= innerWidth - margin && y >= innerHeight - margin;
}

function clampTrashPanelPosition(left, top, width, height) {
  const margin = 12;
  /* Çöp paneli de diğer yüzen panellerle aynı sınırlara uyar: başlığı üst
     dock'un (#barDock) altında, gövdesi alt dock'un üstünde kalır. Aksi halde
     panel pencere sürükleme şeridine giriyor, orada tıklama pencereyi taşıyor
     ve panel bir daha tutulamıyordu (bkz. 17-floating-panels.js). */
  const topLimit = typeof floatingTopLimit === 'function' ? floatingTopLimit() : margin;
  const bottomLimit = typeof floatingBottomLimit === 'function' ? floatingBottomLimit() : innerHeight - margin;
  const maxTop = Math.max(topLimit, bottomLimit - height);
  return {
    left: clamp(left, margin, Math.max(margin, innerWidth - width - margin)),
    top: clamp(top, topLimit, maxTop),
  };
}

function persistTrashPanelPosition() {
  try {
    if (trashPanelPos) localStorage.setItem(TRASH_PANEL_POS_KEY, JSON.stringify(trashPanelPos));
    else localStorage.removeItem(TRASH_PANEL_POS_KEY);
  } catch { /* sessiz */ }
}

function normalizeTrash(value) {
  if (!Array.isArray(value)) return [];
  const now = Date.now();
  return value
    .filter(entry => entry && entry.item && entry.item.id)
    .map(entry => {
      const deletedAt = Number(entry.deletedAt);
      const safeDeletedAt = Number.isFinite(deletedAt) ? deletedAt : now;
      const expiresAt = Number(entry.expiresAt);
      return {
        id: entry.id || 'tr_' + newId(),
        item: entry.item,
        deletedAt: safeDeletedAt,
        expiresAt: Number.isFinite(expiresAt)
          ? expiresAt
          : safeDeletedAt + trashRetentionMinutes * 60000,
        batchId: entry.batchId || '',
        groups: Array.isArray(entry.groups) ? entry.groups.filter(g => g && g.id) : [],
        links: Array.isArray(entry.links) ? entry.links.filter(l => l && l.from && l.to) : [],
      };
    });
}

function trashRetentionText(minutes = trashRetentionMinutes) {
  if (minutes >= 60 && minutes % 60 === 0) return (minutes / 60) + ' saat';
  return minutes + ' dakika';
}

function groupChainSnapshot(gid) {
  const chain = [];
  let g = gid;
  const seen = new Set();
  while (g && !seen.has(g)) {
    seen.add(g);
    chain.push({
      id: g,
      parent: groupParentOf(g) || null,
      title: (state.groupTitles && state.groupTitles[g]) || '',
      important: (state.groupImportant && state.groupImportant[g]) || '',
    });
    g = groupParentOf(g);
  }
  return chain;
}

function makeTrashEntry(it, now, batchId, links) {
  return {
    id: 'tr_' + newId(),
    item: JSON.parse(JSON.stringify(it)),
    deletedAt: now,
    expiresAt: now + trashRetentionMinutes * 60000,
    batchId,
    groups: groupChainSnapshot(it.groupId),
    links: links.map(link => ({ ...link })),
  };
}

function pulseTrashDock(kind = 'catch') {
  if (!trashDockEl) return;
  showTrashDock();
  trashDockEl.classList.remove('is-catching', 'is-restoring');
  void trashDockEl.offsetWidth;
  trashDockEl.classList.add(kind === 'restore' ? 'is-restoring' : 'is-catching');
  clearTimeout(trashPulseTimer);
  trashPulseTimer = setTimeout(() => {
    trashDockEl.classList.remove('is-catching', 'is-restoring');
  }, 600); // Biraz daha uzun
  if (trashCountEl) {
    trashCountEl.classList.remove('count-pop');
    void trashCountEl.offsetWidth;
    trashCountEl.classList.add('count-pop');
  }
}

function flyItemToTrash(it, el) {
  if (!el || it.kind !== 'image' || motionReduced() || !btnTrashDockEl) return false;
  const rect = el.getBoundingClientRect();
  const target = btnTrashDockEl.getBoundingClientRect();
  if (!rect.width || !rect.height || !target.width) return false;

  const clone = el.cloneNode(true);
  clone.querySelectorAll('.handles').forEach(node => node.remove());
  clone.classList.remove('sel', 'editing', 'dragging', 'important', 'locked', 'grouped', 'item-enter', 'item-leaving');
  clone.removeAttribute('data-id');
  clone.classList.add('trashFly');
  clone.style.position = 'fixed';
  clone.style.left = rect.left + 'px';
  clone.style.top = rect.top + 'px';
  clone.style.width = rect.width + 'px';
  clone.style.height = rect.height + 'px';
  clone.style.margin = '0';
  clone.style.pointerEvents = 'none';
  clone.style.zIndex = '2600';
  clone.style.transformOrigin = '50% 50%';
  clone.style.transform = `rotate(${it.rot || 0}deg)`;
  clone.style.borderRadius = getComputedStyle(el).borderRadius;
  // Klon dünya transform'u dışında, doğrudan ekran pikselinde durur.
  clone.style.setProperty('--inv', '1');
  document.body.appendChild(clone);

  const startX = rect.left + rect.width / 2;
  const startY = rect.top + rect.height / 2;
  const endX = target.left + target.width / 2;
  const endY = target.top + target.height / 2;
  const dx = endX - startX;
  const dy = endY - startY;
  const targetScale = Math.max(0.05, Math.min(0.24, target.width / Math.max(rect.width, rect.height) * 0.62));
  // Daha yumuşak yay: arc ve spin azaltıldı
  const arc = Math.min(60, Math.max(16, Math.abs(dx) * 0.05 + Math.abs(dy) * 0.03));
  const spin = (it.rot || 0) + (dx >= 0 ? 8 : -8);
  const duration = 680; // Biraz daha uzun = daha yumuşak
  const delay = Math.min(120, (Number(it.z) || 1) % 4 * 24);

  const animation = clone.animate([
    { transform: `translate3d(0,0,0) rotate(${it.rot || 0}deg) scale(1)`, opacity: 1, offset: 0 },
    { transform: `translate3d(${dx * 0.5}px, ${dy * 0.3 - arc}px, 0) rotate(${spin * 0.4}deg) scale(.75)`, opacity: .95, offset: .6 },
    { transform: `translate3d(${dx}px, ${dy}px, 0) rotate(${spin * 0.05}deg) scale(${targetScale})`, opacity: .04, offset: 1 },
  ], {
    duration,
    delay,
    easing: 'cubic-bezier(.25,.1,.15,1)', // Daha yumuşak easing
    fill: 'both',
  });

  let cleaned = false;
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    clone.remove();
  };
  animation.onfinish = () => {
    cleanup();
    pulseTrashDock('catch');
  };
  animation.oncancel = cleanup;
  setTimeout(cleanup, duration + delay + 120);
  return true;
}

/* TailRef app · image cache, trash list and countdowns */
'use strict';

function loadImage(imageId) {
  if (!imageId) return Promise.resolve({ status: 'missing' });
  const cached = imgCache.get(imageId);
  if (cached) return Promise.resolve({ status: 'ok', value: cached });
  const pending = imageLoadPromises.get(imageId);
  if (pending) return pending;
  const load = (async () => {
    let rec;
    try {
      rec = await idbGet('images', imageId);
    } catch {
      imageLoadFailures.add(imageId);
      return { status: 'error' };
    }
    if (!rec || !rec.blob) {
      imageLoadFailures.add(imageId);
      return { status: 'missing' };
    }
    try {
      const entry = await decodeImage(rec.blob);
      const value = { img: entry.img, url: entry.url, name: rec.name || '' };
      setImgCache(imageId, value);
      return { status: 'ok', value };
    } catch {
      imageLoadFailures.add(imageId);
      return { status: 'decode-failed' };
    }
  })().finally(() => imageLoadPromises.delete(imageId));
  imageLoadPromises.set(imageId, load);
  return load;
}

async function ensureImageCached(imageId) {
  if (!imageId) throw new Error('missing image id');
  const result = await loadImage(imageId);
  if (result.status !== 'ok') throw new Error(result.status);
  return result.value;
}

/* Görsel blob'u IDB'ye yazılıp tahtadaki öğeye bağlanana kadar geçen kısa
   aralıkta GC turu denk gelirse blob "sahipsiz" sanılıp silinebilir. Bu
   sayaç > 0 iken GC hiç çalışmaz (sonraki turda temizler). */
let imageWriteInFlight = 0;
function beginImageWrite() { imageWriteInFlight++; }
function endImageWrite() { if (imageWriteInFlight > 0) imageWriteInFlight--; }

function scheduleGcImages(delay = 4000) {
  clearTimeout(trashGcTimer);
  trashGcTimer = setTimeout(() => {
    trashGcTimer = null;
    gcImages();
  }, delay);
}

function purgeExpiredTrash(options = {}) {
  const now = Date.now();
  const before = state.trash.length;
  state.trash = state.trash.filter(entry => entry.expiresAt > now);
  const removed = before - state.trash.length;
  if (!removed) return 0;
  // Kalıcı silinen görsellerin bağlı çizim katmanları artık geri gelmeyeceği
  // için vuruş verileri de temizlenir. (Geri getirilebilir çöpte korunur.)
  if (typeof inkPruneOrphanLayers === 'function') {
    inkPruneOrphanLayers();
    inkSyncDom();
    // FAZ 8.A: prune artık 'remove' olayı yayıyor — abone paneli taşır.
  }
  if (options.save !== false) scheduleSave();
  if (options.render !== false) updateTrashUI(true);
  scheduleGcImages(3500);
  return removed;
}

function trashTimeLabel(entry) {
  const seconds = Math.max(0, Math.ceil((entry.expiresAt - Date.now()) / 1000));
  return Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0');
}

function updateTrashCountdowns() {
  if (!trashListEl) return;
  const now = Date.now();
  for (const row of trashListEl.querySelectorAll('[data-trash-expires]')) {
    const expiresAt = Number(row.dataset.trashExpires);
    if (!Number.isFinite(expiresAt)) continue;
    const seconds = Math.max(0, Math.ceil((expiresAt - now) / 1000));
    const next = Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0');
    const time = row.querySelector('.trashTime');
    /* Saniye ilerlese de dakika metni çoğu tick'te aynı; değişmediyse yazma. */
    if (time && time.textContent !== next) time.textContent = next;
  }
}

function hydrateTrashThumb(entry, thumb, img) {
  if (entry.item.kind !== 'image') return;
  const cached = imgCache.get(entry.item.imageId);
  if (cached) {
    img.src = cached.url;
    thumb.classList.add('ready');
    return;
  }
  thumb.classList.add('loading');
  ensureImageCached(entry.item.imageId)
    .then(value => {
      if (!thumb.isConnected) return;
      img.src = value.url;
      thumb.classList.remove('loading');
      thumb.classList.add('ready');
    })
    .catch(() => {
      if (!thumb.isConnected) return;
      thumb.classList.remove('loading');
      thumb.classList.add('missing');
    });
}

function renderTrashList() {
  if (!trashListEl) return;
  trashListEl.replaceChildren();
  if (!state.trash.length) {
    trashListEl.hidden = true;
    if (trashEmptyEl) trashEmptyEl.hidden = false;
    return;
  }
  trashListEl.hidden = false;
  if (trashEmptyEl) trashEmptyEl.hidden = true;

  const fragment = document.createDocumentFragment();
  [...state.trash].sort((a, b) => b.deletedAt - a.deletedAt).forEach((entry, index) => {
    const row = document.createElement('div');
    row.className = 'trashItem';
    row.dataset.trashId = entry.id;
    row.dataset.trashExpires = String(entry.expiresAt);
    row.style.setProperty('--row-index', String(Math.min(index, 8)));
    row.setAttribute('role', 'listitem');

    const thumb = document.createElement('div');
    thumb.className = 'trashThumb';
    if (entry.item.kind === 'image') {
      const img = document.createElement('img');
      img.alt = '';
      img.draggable = false;
      thumb.appendChild(img);
      hydrateTrashThumb(entry, thumb, img);
    } else {
      thumb.classList.add('textThumb');
      thumb.textContent = 'Aa';
    }

    const meta = document.createElement('div');
    meta.className = 'trashMeta';
    const name = document.createElement('b');
    name.textContent = entry.item.kind === 'image' ? 'Photo' : 'Text';
    const detail = document.createElement('span');
    if (entry.item.kind === 'image') {
      detail.textContent = (imgCache.get(entry.item.imageId) && imgCache.get(entry.item.imageId).name) || 'Image';
    } else {
      detail.textContent = String(entry.item.text || 'Empty text').replace(/\s+/g, ' ').slice(0, 48) || 'Empty text';
    }
    const time = document.createElement('span');
    time.className = 'trashTime';
    time.textContent = trashTimeLabel(entry);
    meta.append(name, detail, time);

    const restore = document.createElement('button');
    restore.type = 'button';
    restore.className = 'trashRestore';
    restore.dataset.trashRestore = entry.id;
    restore.textContent = __t('Restore');
    restore.title = __t('Bring this item back to the board');

    row.append(thumb, meta, restore);
    fragment.appendChild(row);
  });
  trashListEl.appendChild(fragment);
  updateTrashCountdowns();
}

function updateTrashUI(forceRender = false) {
  if (!trashDockEl) return;
  const count = state.trash.length;
  const signature = state.trash.map(entry => entry.id).join('|');
  if (trashCountEl) trashCountEl.textContent = String(count);
  trashDockEl.classList.toggle('is-empty', count === 0);
  if (btnTrashDockEl) {
    btnTrashDockEl.setAttribute('aria-expanded', String(isPanelVisible(trashPanelEl)));
    btnTrashDockEl.setAttribute('aria-label', count ? __t('Trash, {n} items', { n: count }) : __t('Open trash'));
  }
  if (trashTitleEl) {
    const images = state.trash.filter(entry => entry.item.kind === 'image').length;
    const texts = state.trash.filter(entry => entry.item.kind === 'text').length;
    const parts = [];
    if (images) parts.push(images + ' ' + __t('photo'));
    if (texts) parts.push(texts + ' ' + __t('text'));
    trashTitleEl.textContent = parts.join(' · ') || __t('Empty');
  }
  if (trashRetentionLabelEl) trashRetentionLabelEl.textContent = trashRetentionText();
  if (btnTrashRestoreAllEl) btnTrashRestoreAllEl.disabled = count === 0;
  if (btnTrashPurgeEl) btnTrashPurgeEl.disabled = count === 0;
  if (forceRender || signature !== trashRenderedSignature) {
    trashRenderedSignature = signature;
    renderTrashList();
  }
  updateTrashCountdowns();
}

/* Dil değişince çöp kutusu rozetleri/başlığı tazelensin. */
if (window.L10N && window.L10N.onChange) {
  window.L10N.onChange(() => { try { updateTrashUI(); } catch { /* sessiz */ } });
}

function startTrashClock() {
  clearInterval(trashClockTimer);
  trashClockTimer = setInterval(() => {
    const removed = purgeExpiredTrash();
    if (!removed) updateTrashCountdowns();
  }, 1000);
}

function configureTrashRetention(minutes, persist = true) {
  const n = Math.min(1440, Math.max(1, Math.round(Number(minutes) || TRASH_RETENTION_DEFAULT)));
  trashRetentionMinutes = n;
  if (persist) {
    try { localStorage.setItem(TRASH_RETENTION_KEY, String(n)); } catch { /* sessiz */ }
  }
  if (trashRetentionSelectEl && trashRetentionSelectEl.value !== String(n)) {
    trashRetentionSelectEl.value = String(n);
  }
  // Mevcut çöpteki bekleme süresini de yeni ayara göre güncelle.
  for (const entry of state.trash) {
    entry.expiresAt = entry.deletedAt + n * 60000;
  }
  purgeExpiredTrash({ render: false, save: false });
  updateTrashUI(true);
  scheduleSave();
  return n;
}

/* TailRef app · trash panel position, restore, purge, drag */
'use strict';

function positionTrashPanel(forceDefault = false) {
  if (!trashPanelEl || trashPanelEl.hidden || !btnTrashDockEl) return;
  const margin = 12;
  const gap = 12;
  const bottomReserve = 88;
  const dockRect = btnTrashDockEl.getBoundingClientRect();
  const width = Math.min(360, innerWidth - margin * 2);
  const rawHeight = trashPanelEl.offsetHeight || 380;
  /* Diğer yüzen paneller gibi üst/alt dock sınırları içinde kal. */
  const topLimit = floatingTopLimit();
  const bottomLimit = floatingBottomLimit();
  const availableHeight = Math.max(220, bottomLimit - topLimit);
  let left;
  let top;
  let panelHeight;

  if (forceDefault) {
    trashPanelPos = null;
    persistTrashPanelPosition();
  }

  if (trashPanelPos) {
    panelHeight = Math.min(rawHeight, availableHeight);
    const clamped = clampTrashPanelPosition(trashPanelPos.left, trashPanelPos.top, width, panelHeight);
    left = clamped.left;
    top = clamped.top;
    trashPanelPos = clamped;
  } else {
    panelHeight = Math.min(rawHeight, Math.max(220, bottomLimit - bottomReserve - topLimit));
    const right = Math.max(margin, innerWidth - dockRect.right);
    top = Math.max(topLimit, innerHeight - bottomReserve - panelHeight);
    const candidate = {
      left: innerWidth - right - width,
      right: innerWidth - right,
      top,
      bottom: top + panelHeight,
    };
    const barVisible = itemBarEl && !itemBarEl.hidden && isPanelVisible(itemBarEl);
    const barRect = barVisible ? itemBarEl.getBoundingClientRect() : null;
    left = candidate.left;
    if (barRect &&
        candidate.left < barRect.right && candidate.right > barRect.left &&
        candidate.top < barRect.bottom && candidate.bottom > barRect.top) {
      const leftOfBar = barRect.left - gap;
      if (leftOfBar - width >= margin) left = leftOfBar - width;
    }
  }

  trashPanelEl.style.left = Math.max(margin, Math.min(left, innerWidth - width - margin)) + 'px';
  trashPanelEl.style.right = 'auto';
  trashPanelEl.style.top = Math.max(topLimit, top) + 'px';
  trashPanelEl.style.bottom = 'auto';
  trashPanelEl.style.width = width + 'px';
  const maxHeightLimit = trashPanelPos ? bottomLimit : bottomLimit - bottomReserve + margin;
  trashPanelEl.style.maxHeight = Math.max(220, maxHeightLimit - Math.max(topLimit, top)) + 'px';
}

function openTrashPanel() {
  if (!trashPanelEl) return;
  showTrashDock(false);
  updateTrashUI(true);
  showPanel(trashPanelEl);
  requestAnimationFrame(() => {
    positionTrashPanel();
    requestAnimationFrame(() => positionTrashPanel());
  });
  if (btnTrashDockEl) btnTrashDockEl.setAttribute('aria-expanded', 'true');
}

function closeTrashPanel() {
  if (!trashPanelEl) return;
  hidePanel(trashPanelEl);
  if (btnTrashDockEl) btnTrashDockEl.setAttribute('aria-expanded', 'false');
  scheduleTrashIdle();
}

function toggleTrashPanel() {
  if (isPanelVisible(trashPanelEl)) closeTrashPanel();
  else openTrashPanel();
}

function restoreTrashGroups(groups) {
  if (!Array.isArray(groups) || !groups.length) return;
  if (!state.groupParents) state.groupParents = {};
  if (!state.groupTitles) state.groupTitles = {};
  if (!state.groupImportant) state.groupImportant = {};
  for (const group of groups) {
    if (!group || !group.id) continue;
    if (!(group.id in state.groupParents) && group.parent) state.groupParents[group.id] = group.parent;
    if (!state.groupTitles[group.id] && group.title) state.groupTitles[group.id] = group.title;
    if (!state.groupImportant[group.id] && group.important) state.groupImportant[group.id] = group.important;
  }
}

function restoreTrashLinks(links) {
  if (!Array.isArray(links) || !links.length) return;
  if (!Array.isArray(state.links)) state.links = [];
  for (const link of links) {
    if (!link || !getItem(link.from) || !getItem(link.to)) continue;
    if (linkExists(link.from, link.to)) continue;
    state.links.push({ id: link.id || 'lk_' + newId(), from: link.from, to: link.to });
  }
}

async function restoreTrashEntries(ids) {
  const wanted = new Set(ids);
  const entries = state.trash.filter(entry => wanted.has(entry.id));
  if (!entries.length) return 0;

  const imageIds = [...new Set(entries
    .filter(entry => entry.item.kind === 'image')
    .map(entry => entry.item.imageId))];
  const readyImages = new Set();
  await Promise.all(imageIds.map(async imageId => {
    try {
      await ensureImageCached(imageId);
      readyImages.add(imageId);
    } catch { /* görsel verisi bulunamadı */ }
  }));

  const restorable = entries.filter(entry =>
    entry.item.kind !== 'image' || readyImages.has(entry.item.imageId));
  if (!restorable.length) {
    alert('Data of the trashed images was not found; could not restore.');
    return 0;
  }

  /* Tahtada zaten duran kayıtlar için geri getirilecek bir şey yok.
     Bunları sessizce temizle ve boş bir geri-alma adımı bırakma. */
  const fresh = restorable.filter(entry => !getItem(entry.item.id));
  if (!fresh.length) {
    const staleIds = new Set(restorable.map(entry => entry.id));
    state.trash = state.trash.filter(entry => !staleIds.has(entry.id));
    scheduleSave();
    updateTrashUI(true);
    return 0;
  }

  pushUndo();
  const restoredIds = new Set(restorable.map(entry => entry.id));
  state.trash = state.trash.filter(entry => !restoredIds.has(entry.id));
  const restored = [];
  for (const entry of restorable) {
    if (getItem(entry.item.id)) continue;
    const item = JSON.parse(JSON.stringify(entry.item));
    item.z = nextZ();
    state.items.push(item);
    restored.push({ item, entry });
    restoreTrashGroups(entry.groups);
    restoreTrashLinks(entry.links);
  }

  if (!restored.length) {
    scheduleSave();
    updateTrashUI(true);
    return 0;
  }
  
  // Geri getirme, geri al (Ctrl+Z) ile aynı görünsün: syncAll yeni öğeleri
  // .item-enter sınıfıyla yerinde belirir (kademeli fade + hafif yukarı
  // kayma + büyüme). Çöpten uçuş animasyonu kaldırıldı.
  selection = new Set(restored.map(r => r.item.id));
  selectionOrder = restored.map(r => r.item.id);
  syncAll();

  pulseTrashDock('restore');
  updateTrashUI(true);
  scheduleSave();
  return restored.length;
}

async function restoreAllTrash() {
  return restoreTrashEntries(state.trash.map(entry => entry.id));
}

async function purgeAllTrash() {
  if (!state.trash.length) return;
  const count = state.trash.length;
  if (!(await appConfirm(__t('Permanently delete the {n} items in the trash?', { n: count })))) return;
  pushUndo();
  state.trash = [];
  // Çöp tamamen boşaltıldı: öksüz kalan görsele bağlı çizim katmanlarını sil.
  if (typeof inkPruneOrphanLayers === 'function') {
    inkPruneOrphanLayers();
    inkSyncDom();
    // FAZ 8.A: prune artık 'remove' olayı yayıyor — abone paneli taşır.
  }
  updateTrashUI(true);
  scheduleSave();
  scheduleGcImages(10000);
}

if (btnTrashDockEl) btnTrashDockEl.onclick = toggleTrashPanel;
if (btnTrashCloseEl) btnTrashCloseEl.onclick = closeTrashPanel;
if (btnTrashRestoreAllEl) btnTrashRestoreAllEl.onclick = () => restoreAllTrash();
if (btnTrashPurgeEl) btnTrashPurgeEl.onclick = () => purgeAllTrash();

/* Escape açık çöp panelini kapatır (uygulama geneli kural: Esc en üstteki
   UI'ı iptal eder). Olay burada yutulur; aksi hâlde tahta dinleyicisi de
   Esc'i görüp seçimi temizlerdi. Metin düzenlemesi sürüyorsa Esc önce onu
   bitirir (panel açıkken tahtada yazı düzenlenebilir). Onay penceresi ana
   süreçte açıldığından buraya tuş ulaşmaz. */
document.addEventListener('keydown', event => {
  if (event.key !== 'Escape') return;
  if (!trashPanelEl || !isPanelVisible(trashPanelEl)) return;
  const ae = document.activeElement;
  const isTextField = ae && (
    ae.isContentEditable ||
    ae.tagName === 'TEXTAREA' ||
    (ae.tagName === 'INPUT' &&
      !/^(range|checkbox|radio|button|submit|reset|color|file)$/i.test(ae.type || 'text'))
  );
  if (isTextField) return;
  event.preventDefault();
  event.stopPropagation();
  closeTrashPanel();
});

/* Dock 7 sn dokunulmazsa yumuşakça çekilir; sağ-alt sıcak bölgeye
   fare girince veya dock'a odaklanınca geri gelir. */
if (trashDockEl) {
  trashDockEl.addEventListener('pointerenter', () => showTrashDock());
  trashDockEl.addEventListener('pointerleave', () => {
    if (!trashDockEl.contains(document.activeElement)) scheduleTrashIdle();
  });
  trashDockEl.addEventListener('focusin', () => showTrashDock());
  trashDockEl.addEventListener('focusout', () => scheduleTrashIdle());
  trashDockEl.addEventListener('pointerdown', () => showTrashDock());
}

let trashPointerInHotZone = false;
document.addEventListener('pointermove', event => {
  if (event.pointerType === 'touch' || !trashDockEl) return;
  const inside = trashDockHotZone(event.clientX, event.clientY);
  if (!inside) {
    trashPointerInHotZone = false;
    return;
  }
  if (!trashPointerInHotZone || trashDockEl.classList.contains('is-idle')) {
    trashPointerInHotZone = true;
    showTrashDock();
  }
}, { passive: true });
if (trashListEl) {
  trashListEl.addEventListener('click', event => {
    const button = event.target.closest('[data-trash-restore]');
    if (!button) return;
    restoreTrashEntries([button.dataset.trashRestore]);
  });
}
document.addEventListener('pointerdown', event => {
  if (!isPanelVisible(trashPanelEl)) return;
  if (trashPanelEl.contains(event.target) || trashDockEl.contains(event.target)) return;
  closeTrashPanel();
});

/* Çöp panelini başlığından sürükle; konum hatırlanır.
   Başlığa çift tıklamak varsayılan sağ-alt konuma döndürür. */
/* Sürükleme/kapatma mantığı bu dosyada kaldığı için panel
   floatingPanelSelector'e eklenmez; ancak diğer yüzen panellerle aynı
   davranışı gösterir: -webkit-app-region:no-drag (style.css) ve tıklanınca
   öne alma. Böylece çöp paneli pencere sürükleme şeridine girip
   kaybolamaz. */
if (trashPanelEl) {
  trashPanelEl.dataset.floatingPanel = 'true';
  trashPanelEl.addEventListener('pointerdown', () => raiseFloatingPanel(trashPanelEl), true);
}
let trashPanelDrag = null;
if (trashHeadEl && trashPanelEl) {
  const moveTrashPanelDrag = event => {
    if (!trashPanelDrag || event.pointerId !== trashPanelDrag.pointerId) return;
    const dx = event.clientX - trashPanelDrag.startX;
    const dy = event.clientY - trashPanelDrag.startY;
    if (!trashPanelDrag.moved && Math.abs(dx) + Math.abs(dy) > 3) trashPanelDrag.moved = true;
    const margin = 12;
    const width = trashPanelEl.offsetWidth;
    /* Sürükleme sırasında da üst/alt dock sınırları geçerli: panel pencere
       sürükleme şeridine girerse tıklama pencereyi taşıyor ve panel bir daha
       tutulamıyordu. */
    const height = trashPanelEl.offsetHeight;
    const topLimit = floatingTopLimit();
    const bottomLimit = floatingBottomLimit();
    const maxTop = Math.max(topLimit, bottomLimit - height);
    const left = clamp(trashPanelDrag.left + dx, margin, Math.max(margin, innerWidth - width - margin));
    const top = clamp(trashPanelDrag.top + dy, topLimit, maxTop);
    trashPanelPos = { left, top };
    trashPanelEl.style.left = left + 'px';
    trashPanelEl.style.top = top + 'px';
    trashPanelEl.style.right = 'auto';
    trashPanelEl.style.bottom = 'auto';
    trashPanelEl.style.maxHeight = Math.max(220, bottomLimit - top) + 'px';
    event.preventDefault();
  };
  const endTrashPanelDrag = event => {
    if (!trashPanelDrag) return;
    if (event && event.pointerId !== undefined && event.pointerId !== trashPanelDrag.pointerId) return;
    const moved = trashPanelDrag.moved;
    trashPanelDrag = null;
    trashPanelEl.classList.remove('is-dragging');
    window.removeEventListener('pointermove', moveTrashPanelDrag);
    window.removeEventListener('pointerup', endTrashPanelDrag);
    window.removeEventListener('pointercancel', endTrashPanelDrag);
    if (moved) {
      positionTrashPanel();
      persistTrashPanelPosition();
    }
  };
  trashHeadEl.addEventListener('pointerdown', event => {
    if (event.button !== 0 || !isPanelVisible(trashPanelEl) || trashPanelDrag) return;
    if (event.target.closest('button,input,select,textarea,a,[contenteditable="true"]')) return;
    const rect = trashPanelEl.getBoundingClientRect();
    trashPanelDrag = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      left: rect.left,
      top: rect.top,
      moved: false,
    };
    trashPanelEl.classList.add('is-dragging');
    showTrashDock(false);
    window.addEventListener('pointermove', moveTrashPanelDrag, { passive: false });
    window.addEventListener('pointerup', endTrashPanelDrag);
    window.addEventListener('pointercancel', endTrashPanelDrag);
    event.preventDefault();
    event.stopPropagation();
  });
  trashHeadEl.addEventListener('dblclick', event => {
    if (event.target.closest('button')) return;
    positionTrashPanel(true);
    showTrashDock(false);
  });
}

window.addEventListener('resize', () => {
  if (isPanelVisible(trashPanelEl)) positionTrashPanel();
});

/* TailRef app · duplicate, drag, resize, rotate, marquee */
'use strict';

function duplicateSelection() {
  if (!selection.size) return;
  pushUndo();
  const newSel = [];
  const groupMap = new Map();
  if (!state.groupParents) state.groupParents = {};

  // eski grup zincirini yeni kimliklerle eşle (iç içe gruplar korunur)
  const mapChain = oldGid => {
    if (groupMap.has(oldGid)) return groupMap.get(oldGid);
    const chain = [];
    let g = oldGid;
    const seen = new Set();
    while (g && !seen.has(g)) { seen.add(g); chain.push(g); g = groupParentOf(g); }
    let parent = null;
    for (let i = chain.length - 1; i >= 0; i--) {
      const og = chain[i];
      if (!groupMap.has(og)) groupMap.set(og, 'g_' + newId());
      const ng = groupMap.get(og);
      if (parent) state.groupParents[ng] = parent;
      if (state.groupTitles && state.groupTitles[og]) state.groupTitles[ng] = state.groupTitles[og];
      if (state.groupImportant && state.groupImportant[og]) state.groupImportant[ng] = state.groupImportant[og];
      parent = ng;
    }
    return groupMap.get(oldGid);
  };

  for (const id of selection) {
    const src = getItem(id);
    if (!src) continue;
    const copy = JSON.parse(JSON.stringify(src));
    copy.id = 'it_' + newId();
    copy.x += 24; copy.y += 24;
    copy.z = nextZ();
    if (copy.groupId) copy.groupId = mapChain(copy.groupId);
    state.items.push(copy);
    newSel.push(copy.id);
    // Görsele bağlı çizim katmanları da kopyayla birlikte çoğalır.
    if (typeof inkDuplicateLayers === 'function') inkDuplicateLayers(src.id, copy.id);
  }
  selection = new Set(newSel);
  syncAll();
  scheduleSave();
}

function bringToFront() {
  if (!selection.size) return;
  pushUndo();
  for (const id of selection) {
    const it = getItem(id);
    if (it) it.z = nextZ();
  }
  syncAll();
  scheduleSave();
}

/* Kilit / kilit açma: araç çubuğundaki btnLock ile aynı davranış;
   bağlam menüsünden de erişilebilir olsun diye ortak işleve çıkarıldı. */
function toggleLockSelection() {
  const its = selectedImageItems();
  if (!its.length) return;
  pushUndo();
  const lock = !its.every(it => it.locked);
  its.forEach(it => { it.locked = lock; });
  const btnLock = document.getElementById('btnLock');
  if (btnLock) btnLock.setAttribute('aria-pressed', lock ? 'true' : 'false');
  syncAll();
  scheduleSave();
}

function sendToBack() {
  if (!selection.size) return;
  pushUndo();
  /* Öne getirin aynadaki karşılığı: en küçük z'nin altına, seçimin
     göreli sırasını koruyarak diz (ilk seçilen en altta kalır). Negatif
     z serbest: sıralama yalnızca karşılaştırma yapar. */
  const minZ = state.items.reduce((m, i) => Math.min(m, i.z || 0), 0);
  /* Tıklama sırası (selectionOrder) kopyala/yapıştır ve Ctrl+A gibi
     yollarda güncellenmiyor; eski kimlikler kalınca "arkaya gönder"
     hiçbir şey yapmıyor ya da seçimin yalnız bir kısmını gönderiyordu.
     Önce geçerli tıklama sırası, sonra seçimde kalanlar (kararlı sıra). */
  const ordered = [];
  for (const id of (selectionOrder || [])) {
    if (selection.has(id) && getItem(id) && !ordered.includes(id)) ordered.push(id);
  }
  for (const id of selection) {
    if (!ordered.includes(id) && getItem(id)) ordered.push(id);
  }
  let i = 0;
  for (const id of ordered) {
    const it = getItem(id);
    if (!it) continue;
    it.z = minZ - 1 - i;
    i++;
  }
  syncAll();
  scheduleSave();
}

/* =========================================================
   Ctrl+C/X/V öğe panosu
   Kopyalar orijinal koordinat ve kimlikleriyle saklanır; yeni kimlikler
   yapıştırma anında üretilir, böylece aynı pano defalarca yapıştırılabilir.
   Görsel öğeler imageId ile IndexedDB'deki paylaşımlı kayda referans
   verir; blob kopyalamaya gerek yoktur.
   ========================================================= */
let itemClipboard = [];
let pasteCascade = 0; // art arda yapıştırmalarda +24 ofset birikimi

function copySelectionToClipboard(cut) {
  if (!selection.size) return false;
  const clones = [];
  for (const id of selection) {
    const src = getItem(id);
    if (!src) continue;
    clones.push(JSON.parse(JSON.stringify(src)));
  }
  if (!clones.length) return false;
  itemClipboard = clones;
  pasteCascade = 0;
  if (cut) deleteSelection();
  return true;
}

function pasteItemsFromClipboard() {
  if (!itemClipboard.length) return false;
  /* Metin düzenlemesi açıkken Ctrl+V metnin içine yapıştırmalı;
     öğe panosu devreye girmez (keydown handler'ın typing koruması
     buraya düşmeden iade eder, yine de çifte emniyet). */
  if (typeof editingId !== 'undefined' && editingId) return false;

  pushUndo();
  const groupMap = new Map();
  if (!state.groupParents) state.groupParents = {};

  // eski grup zincirini yeni kimliklerle eşle (duplicateSelection ile aynı desen)
  const mapChain = oldGid => {
    if (groupMap.has(oldGid)) return groupMap.get(oldGid);
    const chain = [];
    let g = oldGid;
    const seen = new Set();
    while (g && !seen.has(g)) { seen.add(g); chain.push(g); g = groupParentOf(g); }
    let parent = null;
    for (let i = chain.length - 1; i >= 0; i--) {
      const og = chain[i];
      if (!groupMap.has(og)) groupMap.set(og, 'g_' + newId());
      const ng = groupMap.get(og);
      if (parent) state.groupParents[ng] = parent;
      if (state.groupTitles && state.groupTitles[og]) state.groupTitles[ng] = state.groupTitles[og];
      if (state.groupImportant && state.groupImportant[og]) state.groupImportant[ng] = state.groupImportant[og];
      parent = ng;
    }
    return groupMap.get(oldGid);
  };

  /* Konum: panoda seçim yoksa kopya demetini görünür alanın merkezine
     getir; seçim varsa duplicate paritesi olan +24 ofsele bas. Seçimle
     art arda yapıştırmalar kademeli kayar ki üst üste binme kör olmasın. */
  let dx = 24 + pasteCascade * 24;
  let dy = 24 + pasteCascade * 24;
  if (!selection.size) {
    const c = screenToWorld({ x: stage.clientWidth / 2, y: stage.clientHeight / 2 });
    const minX = Math.min(...itemClipboard.map(i => i.x || 0));
    const minY = Math.min(...itemClipboard.map(i => i.y || 0));
    dx = c.x - minX;
    dy = c.y - minY;
  }
  pasteCascade++;

  const newSel = [];
  for (const srcClone of itemClipboard) {
    const copy = JSON.parse(JSON.stringify(srcClone));
    const srcId = srcClone.id;
    copy.id = 'it_' + newId();
    copy.x += dx; copy.y += dy;
    copy.z = nextZ();
    if (copy.groupId) copy.groupId = mapChain(copy.groupId);
    state.items.push(copy);
    newSel.push(copy.id);
    // Görsele bağlı çizim katmanları kopyayla gelir. Kaynak kesilip
    // tahtadan silindiyse katmanları ikinci kez çoğaltmamak için
    // yalnızca kaynak hâlâ yaşıyorsa çoğaltılır.
    if (typeof inkDuplicateLayers === 'function' && getItem(srcId)) {
      inkDuplicateLayers(srcId, copy.id);
    }
  }
  selection = new Set(newSel);
  syncAll();
  scheduleSave();
  return true;
}

/* =========================================================
   sürükleme / boyutlandırma / döndürme
   ========================================================= */
let drag = null;
let pendingMove = null;
const MOVE_DRAG_THRESHOLD = 4; // px: bu mesafeden sonra tıklama sürüklemeye dönüşür
let winMoveStart = null;
let dragUiFrame = 0;

// Sürükleme sırasında grup çerçevesi ve panel güncellemelerini kare
// başına bir kez çalıştır. Yüksek Hz'li farelerde her pointermove'da
// layout/paint tetiklenmesi görüntü bozulmasına yol açabiliyordu.
function scheduleDragUI() {
  if (dragUiFrame) return;
  dragUiFrame = requestAnimationFrame(() => {
    dragUiFrame = 0;
    if (!drag) return;
    updateGroupFrame();
  });
}

function cancelDragUI() {
  if (dragUiFrame) cancelAnimationFrame(dragUiFrame);
  dragUiFrame = 0;
}

/* Tutamaç sürüklemesinde geri alma anlık görüntüsü ilk GERÇEK hareketten
   önce alınır. Sadece tıklamak (veya 1-2 px titreme) boş bir geri-alma
   adımı bırakmamalı; eşik geçilince snapshot bir kez yazılır. */
const DRAG_UNDO_THRESHOLD = 2;
function beginDragUndo(current, e) {
  if (current.undoPushed) return true;
  if (Math.hypot(e.clientX - current.sx, e.clientY - current.sy) < DRAG_UNDO_THRESHOLD) return false;
  current.undoPushed = true;
  pushUndo();
  return true;
}

stage.addEventListener('pointerdown', e => {
  pendingMove = null;
  if (editingId) commitEdit();

  /* Askıda kalmış bir DOM metin seçimi (ör. silinen boş yazı öğesinden
     artakalan) Chromium'u kendi native sürüklemesine zorluyordu: marquee
     ve çoklu taşıma pointer akışını öldürüp hayalet sürükleme bırakıyordu.
     Burada temizliyoruz; yazı düzenleme açıkken caret'e dokunmayız. */
  if (!editingId) {
    const sel = document.getSelection ? document.getSelection() : null;
    if (sel && (sel.rangeCount > 1 || !sel.isCollapsed)) sel.removeAllRanges();
  }

  // Panel içindeki bir alan (ör. yazı boyutu kutusu) odakta kalmışsa
  // tuvale dönünce klavye kısayolları yeniden çalışsın.
  const active = document.activeElement;
  if (active && active !== stage &&
      (active.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName))) {
    active.blur();
  }
  if (document.activeElement !== stage) stage.focus({ preventScroll: true });

  // Alt + boş alan sürükle = pencereyi taşı (masaüstü, çerçevesiz)
  if (isDesktop && e.altKey && e.button === 0) {
    const onItem = e.target.closest && (e.target.closest('.item') || e.target.closest('.handle'));
    if (!onItem) {
      e.preventDefault();
      const sx = e.screenX, sy = e.screenY;
      window.tailref.getWindowPos().then(pos => {
        winMoveStart = { sx, sy, px: pos[0], py: pos[1] };
        drag = { mode: 'winmove' };
      });
      return;
    }
  }

  // pan
  if (e.button === 1 || (e.button === 0 && spaceDown)) {
    e.preventDefault();
    drag = { mode: 'pan', sx: e.clientX, sy: e.clientY, vx: state.view.x, vy: state.view.y };
    stage.classList.add('panning');
    return;
  }
  if (e.button !== 0) return;

  // grup çerçevesinin tutamacı -> grubun tamamını ölçekle
  const gHandleEl = e.target.closest && e.target.closest('.ghandle');
  if (gHandleEl) {
    const frameEl = gHandleEl.closest('.gframe');
    const gid = frameEl && frameEl.dataset.gid;
    const members = gid ? groupItemsDeep(gid) : [];
    if (members.length >= 2) {
      e.preventDefault();
      if (!isGroupActive(gid)) {
        selection = new Set(members.map(m => m.id));
        syncSelection();
      }
      startGroupResize(gid, +gHandleEl.dataset.hx, +gHandleEl.dataset.hy, e);
      return;
    }
  }

  const handleEl = e.target.closest && e.target.closest('.handle');
  if (handleEl && selection.size) {
    const itemEl = handleEl.closest('.item');
    const it = itemEl && getItem(itemEl.dataset.id);
    if (!it) return;
    if (it.locked) return;
    e.preventDefault();
    if (handleEl.dataset.rot === '1') startRotate(it, e);
    else startResize(it, +handleEl.dataset.hx, +handleEl.dataset.hy, e);
    return;
  }

  const itemEl = e.target.closest && e.target.closest('.item');
  if (itemEl) {
    const id = itemEl.dataset.id;
    const it = getItem(id);
    if (!it) return;
    if (editingId === id) return; // yazı düzenleniyor

    if (e.shiftKey || e.ctrlKey) {
      // gruplu öğede Shift/Ctrl + tık: grubun tamamını seç/bırak
      const g = outermostGroupOf(it);
      const ids = g ? groupItemsDeep(g).map(i => i.id) : [id];
      if (ids.every(i => selection.has(i))) {
        ids.forEach(i => selection.delete(i));
      } else {
        ids.forEach(i => { selection.add(i); recordSelection(i); });
      }
    } else {
      // gruplu öğeye tıklanınca en dış grubun tamamı seçilir
      const gid = outermostGroupOf(it);
      const memberIds = gid ? groupItemsDeep(gid).map(i => i.id) : [id];
      if (!selection.has(id) || memberIds.some(m => !selection.has(m))) {
        selection = new Set(memberIds);
        selectionOrder = [];
        memberIds.forEach(m => recordSelection(m));
      } else {
        recordSelection(id);
      }
    }
    syncSelection();
    // Tek basışta seç + sürükle: sürüklemeyi pointer 4px hareket edince
    // başlat. Böylece tek tıklama yalnızca seçer; yeni bir öğeyi ikinci
    // kez basmadan doğrudan sürükleyebilirsin.
    pendingMove = (!it.locked && selection.has(id))
      ? { pointerId: e.pointerId, sx: e.clientX, sy: e.clientY }
      : null;
    return;
  }

  // boş alan -> dikdörtgen seçim
  if (!e.shiftKey && !e.ctrlKey) {
    selection.clear(); selectionOrder = [];
    syncSelection();
  }
  drag = {
    mode: 'marquee',
    sx: e.clientX, sy: e.clientY,
    base: new Set(selection),
  };
  showMarquee(e.clientX, e.clientY);
});

function setItemsDragging(ids, on) {
  for (const id of ids) {
    const el = elMap.get(id);
    if (el) el.classList.toggle('dragging', on);
  }
}

/* Tahtadan (öğelerden/boş alan) başlayan NATIVE sürüklemeleri engelle.
   Chromium buna kalkışırsa pointer olaylarını kendine alıp akışımızı
   öldürür: öğeler yerinde kalır, hayalet görüntü + kararma oluşur.
   Dışarıdan dosya düşürme (dragover/drop) etkilenmez; bu yalnızca
   içeriden başlatılan sürükleme yaşamı kapatır. */
window.addEventListener('dragstart', e => {
  const t = e.target;
  if (t && t.closest && t.closest('.item, #stage, #world')) e.preventDefault();
});

function startMove(e) {
  /* Kilitli öğeler konum değiştirmemeli: çoklu seçimde kilitli bir görsel
     varken diğerini sürüklemek kilidi deliyordu. Yalnız hareket edebilen
     öğeler sürükleme listesine girer; seçim olduğu gibi kalır. */
  const ids = [...selection].filter(id => {
    const it = getItem(id);
    return it && !it.locked;
  });
  if (!ids.length) return;
  pushUndo();
  setItemsDragging(ids, true);
  drag = {
    mode: 'move',
    ids,
    sx: e.clientX, sy: e.clientY,
    start: ids.map(id => {
      const it = getItem(id);
      return { id, x: it.x, y: it.y };
    }),
  };
}

function startResize(it, hx, hy, e) {
  const c = itemCenter(it);
  setItemsDragging([it.id], true);
  drag = {
    mode: 'resize',
    ids: [it.id],
    it,
    hx, hy,
    sx: e.clientX, sy: e.clientY,
    w0: it.w, h0: it.h || 0, rot: it.rot || 0,
    cx: c.x, cy: c.y,
  };
}

function startRotate(it, e) {
  const c = itemCenter(it);
  const p = screenToWorld({ x: e.clientX, y: e.clientY });
  setItemsDragging([it.id], true);
  drag = {
    mode: 'rotate',
    ids: [it.id],
    it,
    sx: e.clientX, sy: e.clientY,
    cx: c.x, cy: c.y,
    rot0: it.rot || 0,
    a0: Math.atan2(p.y - c.y, p.x - c.x),
  };
}

/** Grup çerçevesinden çekince grubun tamamı birlikte büyür/küçülür */
function startGroupResize(gid, hx, hy, e) {
  /* Kilitli üyeler ölçeklenmez; hepsi kilitliyse tutamaç hiç iş yapmaz. */
  const members = groupItemsDeep(gid).filter(it => !it.locked);
  if (!members.length) return;
  const pad = 14;
  const b = boundsOf(groupItemsDeep(gid), 0);
  setItemsDragging(members.map(m => m.id), true);
  drag = {
    mode: 'gresize',
    ids: members.map(m => m.id),
    gid, hx, hy,
    sx: e.clientX, sy: e.clientY,
    f: { x: b.x - pad, y: b.y - pad, w: b.w + pad * 2, h: b.h + pad * 2 },
    members: members.map(it => ({
      id: it.id, kind: it.kind,
      x: it.x, y: it.y, w: it.w, h: it.h || 0,
      fontSize: it.fontSize || FONT_SIZE,
    })),
  };
}
function showMarquee(x, y) {
  if (!drag) return;
  const x1 = Math.min(drag.sx, x), y1 = Math.min(drag.sy, y);
  const x2 = Math.max(drag.sx, x), y2 = Math.max(drag.sy, y);
  marqueeEl.style.display = 'block';
  marqueeEl.style.left   = x1 + 'px';
  marqueeEl.style.top    = y1 + 'px';
  marqueeEl.style.width  = (x2 - x1) + 'px';
  marqueeEl.style.height = (y2 - y1) + 'px';
}

window.addEventListener('pointermove', e => {
  if (!drag && pendingMove) {
    if (e.pointerId !== pendingMove.pointerId) return;
    const dx = e.clientX - pendingMove.sx;
    const dy = e.clientY - pendingMove.sy;
    if (Math.hypot(dx, dy) < MOVE_DRAG_THRESHOLD) return;
    const start = pendingMove;
    pendingMove = null;
    // İlk basış noktasını kullan: öğe imlecin altında kalır, sıçrama olmaz.
    startMove({ clientX: start.sx, clientY: start.sy });
  }
  if (!drag) return;

  if (drag.mode === 'winmove') {
    if (winMoveStart) {
      window.tailref.setWindowPos(
        winMoveStart.px + (e.screenX - winMoveStart.sx),
        winMoveStart.py + (e.screenY - winMoveStart.sy)
      );
    }
    return;
  }

  if (drag.mode === 'pan') {
    state.view.x = drag.vx + (e.clientX - drag.sx);
    state.view.y = drag.vy + (e.clientY - drag.sy);
    applyView();
    return;
  }

  if (drag.mode === 'marquee') {
    showMarquee(e.clientX, e.clientY);
    const w1 = screenToWorld({ x: drag.sx, y: drag.sy });
    const w2 = screenToWorld({ x: e.clientX, y: e.clientY });
    const box = {
      x1: Math.min(w1.x, w2.x), y1: Math.min(w1.y, w2.y),
      x2: Math.max(w1.x, w2.x), y2: Math.max(w1.y, w2.y),
    };
    selection = new Set(drag.base);
    for (const it of state.items) {
      const pts = itemCorners(it);
      const xs = pts.map(p => p.x), ys = pts.map(p => p.y);
      if (Math.max(...xs) < box.x1 || Math.min(...xs) > box.x2) continue;
      if (Math.max(...ys) < box.y1 || Math.min(...ys) > box.y2) continue;
      selection.add(it.id);
    }
    syncSelection();
    return;
  }

  if (drag.mode === 'move') {
    const rawDx = (e.clientX - drag.sx) / state.view.scale;
    const rawDy = (e.clientY - drag.sy) / state.view.scale;
    let dx = rawDx, dy = rawDy;
    let lockAxis = null;
    if (e.shiftKey) {
      if (Math.abs(rawDx) > Math.abs(rawDy)) { dy = 0; lockAxis = 'y'; }
      else { dx = 0; lockAxis = 'x'; }
    }

    const place = (ox, oy) => {
      for (const s of drag.start) {
        const it = getItem(s.id);
        if (!it) continue;
        it.x = s.x + dx + ox;
        it.y = s.y + dy + oy;
      }
    };
    place(0, 0);

    // yakındaki kenarlara yapış (Alt basılıysa kapat; aday 9: Snap on
    // board anahtarı '0' ise kalıcı olarak kapalı)
    let snapX = null, snapY = null;
    const snapKapali = e.altKey ||
      (typeof tailrefBoardSnapOn === 'function' && !tailrefBoardSnapOn());
    if (!snapKapali) {
      const movingIds = new Set(drag.start.map(s => s.id));
      const others = state.items.filter(i => !movingIds.has(i.id));
      if (others.length) {
        const moving = drag.start.map(s => getItem(s.id)).filter(Boolean);
        const b = boundsOf(moving, 0);
        snapX = lockAxis === 'x' ? { d: 0, at: 0, o: null } : snapDelta(b, others, 'x');
        snapY = lockAxis === 'y' ? { d: 0, at: 0, o: null } : snapDelta(b, others, 'y');
        if (snapX.d || snapY.d) place(snapX.d, snapY.d);
        showSnapFeedback(b, snapX, snapY, others);
      } else {
        hideSnapFeedback();
      }
    } else {
      hideSnapFeedback();
    }

    for (const s of drag.start) {
      const it = getItem(s.id);
      if (it) updateItemEl(it, elMap.get(it.id));
    }
    scheduleDragUI();
    return;
  }

  if (drag.mode === 'resize') {
    if (!beginDragUndo(drag, e)) return;
    const it = drag.it;
    const hx = drag.hx, hy = drag.hy;
    const r  = drag.rot * Math.PI / 180;
    const cos = Math.cos(r), sin = Math.sin(r);

    // sabit (karşı) köşe, dünya koordinatında
    const anchorLocalX = -hx * drag.w0 / 2;
    const anchorLocalY = -hy * drag.h0 / 2;
    const ax = drag.cx + anchorLocalX * cos - anchorLocalY * sin;
    const ay = drag.cy + anchorLocalX * sin + anchorLocalY * cos;

    const p = screenToWorld({ x: e.clientX, y: e.clientY });
    const vx =  (p.x - ax) * cos + (p.y - ay) * sin;
    const vy = -(p.x - ax) * sin + (p.y - ay) * cos;

    let nw = drag.w0, nh = drag.h0;
    /* Shift basılıyken görsel HİÇ bozulmaz (kullanıcı isteği: "nerden
       tutup çekersek itsek fotoğraf asla bozulmasın"): köşe tutamacı da,
       KENAR/ORTA tutamaç da uniform ölçek yapar — çekilen aks k uygulanır,
       karşı ucun orta noktası (mevcut hesap) sabit kalır. Alt tuşu yine
       serbest deformasyonu getirir (Shift'ten güçlü). */
    const uniformImage = it.kind === 'image' && !e.altKey &&
      (e.shiftKey || (hx !== 0 && hy !== 0));
    if (uniformImage && drag.h0) {
      const ar = drag.w0 / drag.h0;
      let k = hx !== 0 ? Math.abs(vx) / drag.w0 : Math.abs(vy) / drag.h0;
      k = Math.max(k, MIN_SIZE / Math.max(1, drag.w0), MIN_SIZE / Math.max(1, drag.h0));
      nw = drag.w0 * k;
      nh = drag.h0 * k;
    } else {
      if (hx !== 0) nw = Math.max(MIN_SIZE, Math.abs(vx));
      if (hy !== 0) nh = Math.max(MIN_SIZE, Math.abs(vy));
    }

    // merkez, sabit köşeye göre yeniden konumlanır
    const offX = hx * nw / 2;
    const offY = hy * nh / 2;
    const ncx = ax + offX * cos - offY * sin;
    const ncy = ay + offX * sin + offY * cos;

    it.w = nw;
    it.h = nh;
    it.x = ncx - nw / 2;
    it.y = ncy - nh / 2;
    updateItemEl(it, elMap.get(it.id));
    scheduleDragUI();
    return;
  }

  if (drag.mode === 'gresize') {
    if (!beginDragUndo(drag, e)) return;
    const { hx, hy, f } = drag;
    const p = screenToWorld({ x: e.clientX, y: e.clientY });

    // sabit kenar (karşı taraf), dünya koordinatında
    const ax = hx > 0 ? f.x : hx < 0 ? f.x + f.w : f.x + f.w / 2;
    const ay = hy > 0 ? f.y : hy < 0 ? f.y + f.h : f.y + f.h / 2;

    const sx = hx ? Math.abs(p.x - ax) / f.w : null;
    const sy = hy ? Math.abs(p.y - ay) / f.h : null;
    let k = sx !== null && sy !== null ? Math.max(sx, sy) : (sx !== null ? sx : sy);
    if (e.shiftKey && sx !== null && sy !== null) k = Math.min(sx, sy);

    // hiçbir görsel MIN_SIZE'ın altına düşmesin
    let minK = 0.02;
    for (const m of drag.members) {
      if (m.w) minK = Math.max(minK, MIN_SIZE / m.w);
      if (m.h) minK = Math.max(minK, MIN_SIZE / m.h);
    }
    k = Math.max(k, minK);

    const nw = f.w * k, nh = f.h * k;
    const nx = hx > 0 ? ax : hx < 0 ? ax - nw : ax - nw / 2;
    const ny = hy > 0 ? ay : hy < 0 ? ay - nh : ay - nh / 2;

    // bütün öğeler çerçeveye göre aynı oranda büyür/küçülür
    for (const m of drag.members) {
      const it = getItem(m.id);
      if (!it) continue;
      it.w = m.w * k;
      it.h = m.h * k;
      if (it.kind !== 'image') {
        it.fontSize = clamp(m.fontSize * k, 8, 400);
        it.w = textAutoWidth(it);
      }
      it.x = nx + (m.x - f.x) * k;
      it.y = ny + (m.y - f.y) * k;
      updateItemEl(it, elMap.get(it.id));
    }
    scheduleDragUI();
    return;
  }

  if (drag.mode === 'rotate') {
    if (!beginDragUndo(drag, e)) return;
    const p = screenToWorld({ x: e.clientX, y: e.clientY });
    const a = Math.atan2(p.y - drag.cy, p.x - drag.cx);
    let deg = drag.rot0 + (a - drag.a0) * 180 / Math.PI;
    if (e.shiftKey) deg = Math.round(deg / 15) * 15;
    drag.it.rot = deg;
    updateItemEl(drag.it, elMap.get(drag.it.id));
    scheduleDragUI();
  }
});

function finishPointerDrag() {
  pendingMove = null;
  if (!drag) return null;
  const mode = drag.mode;
  const resizeIds = mode === 'resize' || mode === 'gresize' ? (drag.ids || []).slice() : null;
  cancelDragUI();
  setItemsDragging(drag.ids || [], false);
  drag = null;
  winMoveStart = null;
  stage.classList.remove('panning');
  marqueeEl.style.display = 'none';
  hideSnapFeedback();
  if (mode === 'move' || mode === 'resize' || mode === 'gresize' || mode === 'rotate') {
    updateGroupFrame();
    updateItemBar();
  }
  // Görselin boyutu değişti: bağlı katman tuvallerinin DPR-duyarlı
  // tavanını güncelle ve kırpma grubu önbelleğini tazele (FAZ1-6).
  if (resizeIds && typeof inkRelayoutItemsForResize === 'function') {
    inkRelayoutItemsForResize(resizeIds);
  }
  return mode;
}

window.addEventListener('pointerup', e => {
  const mode = finishPointerDrag();
  if (mode && mode !== 'marquee') scheduleSave();
});
window.addEventListener('pointercancel', () => {
  const mode = finishPointerDrag();
  if (mode && mode !== 'marquee') scheduleSave();
});

/* TailRef app · context menu, PNG export, text drawing */
'use strict';

const contextMenuEl = $('#contextMenu');

function hideContextMenu() {
  hidePanel(contextMenuEl, () => {
    if (contextMenuEl.hidden) contextMenuEl.replaceChildren();
  });
}

function enhanceIconButton(button, icon) {
  if (!button || !icon || button.querySelector('.toolIcon')) return;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.classList.add('toolIcon');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');
  use.setAttribute('href', `#icon-${icon}`);
  svg.appendChild(use);
  button.prepend(svg);
}

function setButtonLabel(button, label) {
  if (!button) return;
  // Yeni araç çubuğunda etiket ayrı bir .tlabel içinde; onu güncelle.
  const labelEl = button.querySelector('.tlabel');
  if (labelEl) { labelEl.textContent = label; return; }
  const icon = button.querySelector('.toolIcon');
  button.replaceChildren(...(icon ? [icon] : []), document.createTextNode(label));
}

function renderContextMenu(items, x, y) {
  contextMenuEl.replaceChildren();
  showPanel(contextMenuEl);
  const title = document.createElement('div');
  title.className = 'floatingPanelHead contextMenuHead';
  title.textContent = 'Canvas menu';
  contextMenuEl.appendChild(title);
  let rowIndex = 0;
  for (const item of items) {
    if (item.separator) {
      const separator = document.createElement('div');
      separator.className = 'menuDivider';
      separator.setAttribute('role', 'separator');
      contextMenuEl.appendChild(separator);
      continue;
    }
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'menuItem';
    button.setAttribute('role', 'menuitem');
    button.disabled = !!item.disabled;
    button.style.setProperty('--row-index', String(Math.min(rowIndex++, 10)));
    button.setAttribute('aria-label', [item.label, item.shortcut].filter(Boolean).join(', '));
    enhanceIconButton(button, item.icon);
    const label = document.createElement('span');
    label.className = 'menuLabel';
    label.textContent = item.label;
    button.append(label);
    if (item.shortcut) {
      const shortcut = document.createElement('kbd');
      shortcut.textContent = item.shortcut;
      button.append(shortcut);
    }
    button.addEventListener('click', () => {
      hideContextMenu();
      item.action();
    });
    contextMenuEl.appendChild(button);
  }
  contextMenuEl.style.left = `${Math.max(8, Math.min(x, innerWidth - contextMenuEl.offsetWidth - 8))}px`;
  contextMenuEl.style.top = `${Math.max(8, Math.min(y, innerHeight - contextMenuEl.offsetHeight - 8))}px`;
  prepareFloatingPanel(contextMenuEl, false);
  contextMenuEl.querySelector('.menuItem:not(:disabled)')?.focus();
}

function openContextMenu(x, y, target = null) {
  const itemEl = target && target.closest ? target.closest('.item') : null;
  if (itemEl) {
    const id = itemEl.dataset.id;
    if (id && !selection.has(id)) {
      selection = new Set([id]);
      syncSelection();
    }
  }
  const hasSelection = selection.size > 0;
  const selectedImages = selectedImageItems();
  const clickedItem = itemEl && itemEl.dataset.id ? getItem(itemEl.dataset.id) : null;
  const clickedImage = clickedItem && clickedItem.kind === 'image' ? clickedItem : null;
  renderContextMenu([
    { label: 'Add image…', shortcut: 'Ctrl+O', icon: 'image', action: () => fileInput.click() },
    { label: 'Text add', shortcut: 'T', icon: 'type', action: () => addText(screenToWorld({ x: stage.clientWidth / 2, y: stage.clientHeight / 2 })) },
    { separator: true },
    { label: 'Fit selected', shortcut: 'F', icon: 'fit', disabled: !hasSelection, action: () => frameSelection() },
    // Mod değişimi yalnızca sağdaki segment ve Ctrl/Cmd+1–2 ile yapılır;
    // bağlam menüsünde ikinci bir giriş noktası tutulmaz.
    { label: __t('Fit whole board'), icon: 'fit', action: () => fitAll() },
    { label: __t('Actual size'), shortcut: '1', icon: 'zoom', action: () => zoomTo100() },
    { separator: true },
    { label: __t('Duplicate'), shortcut: 'Ctrl+D', icon: 'copy', disabled: !hasSelection, action: () => duplicateSelection() },
    { label: __t('Copy'), shortcut: 'Ctrl+C', icon: 'copy', disabled: !hasSelection, action: () => copySelectionToClipboard(false) },
    { label: __t('Paste'), shortcut: 'Ctrl+V', icon: 'paste', disabled: !itemClipboard.length, action: () => pasteItemsFromClipboard() },
    { label: __t('Bring forward'), shortcut: 'B', icon: 'front', disabled: !hasSelection, action: () => bringToFront() },
    { label: __t('Send to back'), shortcut: 'Shift+B', icon: 'back', disabled: !hasSelection, action: () => sendToBack() },
    { label: __t('Group / ungroup'), shortcut: 'G', icon: 'group', disabled: selection.size < 2, action: () => groupSelection() },
    { label: __t('Link / unlink'), shortcut: 'L', icon: 'link', disabled: selectedImages.length < 2, action: () => toggleLink() },
    { label: __t('Lock / unlock'), icon: 'lock', disabled: !selectedImages.length, action: () => toggleLockSelection() },
    { label: __t('Delete'), shortcut: 'Del', icon: 'trash', disabled: !hasSelection, action: () => deleteSelection() },
  ], x, y);
}

stage.addEventListener('contextmenu', e => {
  e.preventDefault();
  openContextMenu(e.clientX, e.clientY, e.target);
});
document.addEventListener('pointerdown', e => {
  if (isPanelVisible(contextMenuEl) && !contextMenuEl.contains(e.target)) hideContextMenu();
});
contextMenuEl.addEventListener('keydown', e => {
  const items = [...contextMenuEl.querySelectorAll('.menuItem:not(:disabled)')];
  const index = items.indexOf(document.activeElement);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const step = e.key === 'ArrowDown' ? 1 : -1;
    items[(index + step + items.length) % items.length]?.focus();
  } else if (e.key === 'Home' || e.key === 'End') {
    e.preventDefault();
    items[e.key === 'Home' ? 0 : items.length - 1]?.focus();
  }
});

/* =========================================================
   zoom
   ========================================================= */
stage.addEventListener('wheel', e => {
  /* Vuruş koruması: kalem çizerken öbür elden gelen tekerlek tahtayı
     zoom/pan ediyordu — canlı vuruşun ekran→dünya eşlemesi kayıp
     vuruş yamuluyordu. Canlı vuruşta tekerlek yutulur. */
  if (typeof inkPointer !== 'undefined' && (inkPointer || inkTransform)) {
    e.preventDefault();
    return;
  }
  e.preventDefault();
  /* Sektör standardı tekerlek tercihi (15 Kasım): varsayılan zoom
     (mevcut davranış); "Zoom with scroll wheel" kapalıysa tekerlek
     görünümü kaydırır (Krita/CSP pan). Ctrl her zaman zoom.
     "Natural scroll direction" açıkken deltaY/DeltaX tersine çevrilir. */
  const dir = (typeof tailrefWheelInvert === 'function' && tailrefWheelInvert()) ? -1 : 1;
  if (!e.ctrlKey && typeof tailrefWheelZoom === 'function' && !tailrefWheelZoom()) {
    state.view.x -= e.deltaX * dir;
    state.view.y -= e.deltaY * dir;
    applyView();
    scheduleSave();
    return;
  }
  const factor = Math.exp(-e.deltaY * dir * (e.deltaMode === 1 ? 0.05 : 0.0015));
  zoomAt({ x: e.clientX, y: e.clientY }, factor);
}, { passive: false });

/* =========================================================
   çift tık
   ========================================================= */
stage.addEventListener('dblclick', e => {
  // Alt basılıyken (renk örnekleme/büyüteç) asla metin yazma yeri açma:
  // hızlı klikler çift tık sayılsa bile.
  if (e.altKey) { e.preventDefault(); return; }
  const itemEl = e.target.closest && e.target.closest('.item');
  if (itemEl) {
    const it = getItem(itemEl.dataset.id);
    // yazıya çift tık -> düzenle, görsele çift tık -> üstüne yazı ekle
    if (it && it.kind === 'text') { startEdit(it); return; }
  }
  
  addText(screenToWorld({ x: e.clientX, y: e.clientY }));
});

/* =========================================================
   klavye
   ========================================================= */
/* Ok tuşuyla kaydırma tek bir geri-alma adımına toplanır: tuş basılı
   tutulduğunda her keydown ayrı snapshot üretip yığını dolduruyordu.
   900 ms içindeki ardışık kaydırmalar aynı adımda birleşir; araya başka
   bir geri-alınabilir işlem girerse (yığın boyu değişir) yeni adım açılır. */
let nudgeUndoDepth = -1;
let nudgeUndoAt = 0;
function pushNudgeUndo() {
  const now = Date.now();
  if (nudgeUndoDepth === undoStack.length && now - nudgeUndoAt < 900) {
    nudgeUndoAt = now;
    return;
  }
  pushUndo();
  nudgeUndoDepth = undoStack.length;
  nudgeUndoAt = now;
}

window.addEventListener('keydown', e => {
  // Çizim modu açıkken tahta kısayolları (sil, grupla, bağla, PNG...)
  // çalışmaz. Yalnızca pencere düzeyindeki F11 geçer. Çizim kısayolları
  // kendi dinleyicilerinde (30/36-ink-*) işlenir.
  if (typeof modeIsDraw === 'function' && modeIsDraw() && e.key !== 'F11') return;
  if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) {
    e.preventDefault();
    openContextMenu(innerWidth / 2, innerHeight / 2);
    return;
  }
  if (e.key === 'F11') {
    e.preventDefault();
    if (window.tailref && window.tailref.toggleFullscreen) window.tailref.toggleFullscreen();
    return;
  }
  // Fırça kütüphanesi açıkken tahta kısayolları (sil, grupla, bağla) ve
  // Escape arkadaki panelleri kapatmasın.
  const nativeBrushRoot = document.getElementById('nativeBrushLibrary');
  if (nativeBrushRoot && !nativeBrushRoot.hidden) return;
  if (e.key === 'Escape' && isPanelVisible(contextMenuEl)) {
    e.preventDefault();
    hideContextMenu();
    stage.focus({ preventScroll: true });
    return;
  }
  /* Export modalı açıkken Escape modalı kapatmalı (X butonunun
     "Close (Esc)" etiketiyle sözü bu). Odak formun içinde değilse
     form düzeyindeki dinleyici ateşlenmez; pencere düzeyinde yakala. */
  if (e.key === 'Escape' && exportUi.bound && exportUi.els && !exportUi.els.modal.hidden) {
    e.preventDefault();
    exportHide();
    return;
  }
  if (e.key === 'Escape' && window.tailref && window.tailref.isFullscreen) {
    window.tailref.isFullscreen().then(full => {
      if (full && window.tailref.toggleFullscreen) window.tailref.toggleFullscreen();
    }).catch(() => {});
    if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
  }
  const typing = editingId && document.activeElement &&
                 document.activeElement.classList.contains('text');

  if (typing) {
    if (e.key === 'Escape') { e.preventDefault(); commitEdit(); }
    return;
  }

  const ae = document.activeElement;
  // Yalnızca metin girişi kısayolları yutar. Kaydırıcı, onay kutusu veya
  // düğme odakta kaldığında Ctrl+Z / Ctrl+A gibi kısayollar çalışmaya devam
  // etmeli; aksi hâlde fırça panelindeki bir kaydırıcıya dokunduktan sonra
  // geri al sessizce ölüyordu.
  const isTextField = ae && (
    ae.isContentEditable ||
    ae.tagName === 'TEXTAREA' ||
    (ae.tagName === 'INPUT' &&
      !/^(range|checkbox|radio|button|submit|reset|color|file)$/i.test(ae.type || 'text'))
  );
  if (isTextField) {
    if (e.key === 'Escape') { ae.blur(); syncSelection(); }
    return;
  }

  const mod = e.ctrlKey || e.metaKey;
  const isButtonFocused = ae && ae.closest &&
    ae.closest('button, a, [role="button"]');
  if (isButtonFocused && !mod) return;

  if (e.code === 'Space') {
    spaceDown = true;
    stage.classList.add('space');
    e.preventDefault();
    return;
  }

  /* Faz 3a: tahta kombinasyonları (Ctrl+Z/Y/A/D/S/E/O) keymap 'board'
     grubundan çözülür; keymap yoksa eski hardcoded tuşlar geçerli kalır
     (parite). Ctrl+Shift+Z paritesi: shift'li basış redo yapar (pose3d
     kalıbı). Ctrl+0/+/-/T zoom ve panel kısayolları sabittir. */
  const modKey = (mod && e.key && e.key.length === 1) ? e.key.toLowerCase() : '';
  let boardModAct = '';
  if (modKey) {
    if (window.tailrefKeymap) {
      boardModAct = window.tailrefKeymap.actionFor('ctrl+' + modKey, 'board');
    } else {
      const legacyMap = {
        z: 'board.undo', y: 'board.redo', a: 'board.selectAll',
        d: 'board.duplicate', s: 'board.save', e: 'board.export', o: 'board.open',
        c: 'board.copy', x: 'board.cut', v: 'board.paste',
      };
      boardModAct = legacyMap[modKey] || '';
    }
  }

  if (boardModAct === 'board.undo') {
    e.preventDefault();
    if (e.shiftKey) redo(); else undo();
    return;
  }
  if (boardModAct === 'board.redo') { e.preventDefault(); redo(); return; }
  if (boardModAct === 'board.selectAll') {
    e.preventDefault();
    selection = new Set(state.items.map(i => i.id));
    syncSelection();
    return;
  }
  if (boardModAct === 'board.duplicate') { e.preventDefault(); duplicateSelection(); return; }
  if (boardModAct === 'board.copy') { e.preventDefault(); copySelectionToClipboard(false); return; }
  if (boardModAct === 'board.cut') { e.preventDefault(); copySelectionToClipboard(true); return; }
  /* Öğe panosu boşken Ctrl+V'i native'e bırak: işletim sistemi panosundaki
     görsel 'paste' olayı üzerinden tahtaya düşer. */
  if (boardModAct === 'board.paste') {
    const pasted = pasteItemsFromClipboard();
    if (pasted) e.preventDefault();
    return;
  }
  if (boardModAct === 'board.save') {
    /* Ctrl+Shift+S 3D yakalamaya ayrıldı (src/app/22-init.js). */
    if (e.shiftKey) return;
    e.preventDefault();
    /* Manuel modda Ctrl+S .tail dosyasına kaydeder; otomatik modda IndexedDB'ye. */
    if (isPersistenceAuto()) {
      /* Otomatik modda Ctrl+S eskiden görünür bir geri bildirim vermiyordu:
         kullanıcı kaydedildi mi diye emin olamıyordu. */
      Promise.resolve(saveNow()).then(() => {
        try { showProjectNotice(__t('Saved to this device.'), 1800); }
        catch { /* sessiz */ }
      }).catch(() => { /* hata saveNow içinde bildirilir */ });
    } else {
      saveAsTail();
    }
    return;
  }
  if (boardModAct === 'board.export') { e.preventDefault(); openExportDialog(); return; }
  if (boardModAct === 'board.open') {
    e.preventDefault();
    /* Manuel modda Ctrl+O .tail dosyası açar; otomatik modda görsel içe aktarır. */
    if (isPersistenceAuto()) fileInput.click();
    else openTailFile();
    return;
  }
  // Zoom: Ctrl/Cmd + 0 sıfırla, + yakınlaştır, − uzaklaştır
  if (mod && (e.key === '0' || e.code === 'Digit0' || e.code === 'Numpad0')) {
    e.preventDefault(); zoomTo100(); return;
  }
  if (mod && (e.key === '+' || e.key === '=' || e.code === 'NumpadAdd')) {
    e.preventDefault(); zoomByFactor(ZOOM_STEP); return;
  }
  if (mod && (e.key === '-' || e.key === '_' || e.code === 'NumpadSubtract')) {
    e.preventDefault(); zoomByFactor(1 / ZOOM_STEP); return;
  }
  if (mod && e.key.toLowerCase() === 't') {
    // Çizim modunda Ctrl+T serbest dönüştürmedir; tahta paneli kısayolu
    // yalnızca referans modunda çalışır.
    if (typeof modeIsDraw === 'function' && modeIsDraw()) return;
    e.preventDefault();
    if (toggleTop) toggleTop();
    return;
  }

  /* Geriye gönder: 'b' tek tuş keymap'te "Öne getir"e bağlı; imza motoru
     shift bileşimlerini temsil edemediğinden Shift+B sabit kısayoldur
     (layers grubundaki Shift+N paritesi). */
  if (e.shiftKey && !mod && (e.key === 'B' || e.key === 'b')) {
    e.preventDefault();
    sendToBack();
    return;
  }

  /* Tur 4b: tahta tek tuşları keymap tablosundan çözülür
     (TODO-4b-keymap.md §4). Eski switch anahtarları eylem id'lerine
     döner; varsayılan tuşlar birebir aynı davranışı üretir. Ctrl/Shift
     bileşim akışları yukarıda zaten iade edildiği/ele alındığı için
     çözüm koşulu bilerek aynıdır (Ctrl+G gibi akışlar korunur). */
  let boardAction = '';
  if (window.tailrefKeymap && e.key && e.key.length === 1) {
    boardAction = window.tailrefKeymap.actionFor(e.key.toLowerCase(), 'board');
  }

  switch (boardAction || e.key) {
    case 'Delete':
    case 'Backspace':
      e.preventDefault();
      deleteSelection();
      break;
    case 'Escape':
      selection.clear(); selectionOrder = [];
      syncSelection();
      closeStudioPanel(helpEl);
      break;
    case 'board.fit':
      if (selection.size) frameSelection();
      else fitAll();
      break;
    case 'board.toggleBar':
      toggleBarManually();
      break;
    case 'board.zoom100':
      zoomTo100();
      break;
    case 'board.addText': {
      const c = screenToWorld({ x: stage.clientWidth / 2, y: stage.clientHeight / 2 });
      addText(c);
      break;
    }
    case 'board.help':
      openStudioPanel(helpEl);
      break;
    case 'board.bringFront':
      bringToFront();
      break;
    case 'board.group':
      groupSelection();
      break;
    case 'board.link':
      toggleLink();
      break;
    case 'board.important': {
      if (!selection.size) break;
      pushUndo();
      // grup seçili: sadece grup çizgileri kırmızı olur
      const gid = selectedGroupId();
      if (gid) {
        setGroupImportant(gid, !isGroupImportant(gid));
        scheduleSave();
        updateItemBar();
        break;
      }
      const on = ![...selection].every(id => { const i = getItem(id); return i && i.important; });
      const color = on ? randomImpColor() : '';
      for (const id of selection) {
        const it = getItem(id);
        if (!it) continue;
        it.important = on;
        if (on) it.impColor = color;
        else delete it.impColor;
        const el = elMap.get(it.id);
        if (el) {
          el.classList.toggle('important', on);
          if (on) el.style.setProperty('--imp', color);
          else el.style.removeProperty('--imp');
        }
      }
      scheduleSave();
      updateItemBar();
      updateGroupFrame();
      break;
    }
    case 'board.bgLeft':
      setBg(state.bg - 0.1);
      break;
    case 'board.bgRight':
      setBg(state.bg + 0.1);
      break;
    case 'ArrowLeft': case 'ArrowRight': case 'ArrowUp': case 'ArrowDown': {
      if (!selection.size) break;
      e.preventDefault();
      const step = e.shiftKey ? 10 : 1;
      const dx = e.key === 'ArrowLeft' ? -step : e.key === 'ArrowRight' ? step : 0;
      const dy = e.key === 'ArrowUp' ? -step : e.key === 'ArrowDown' ? step : 0;
      /* Kilitli görseller ok tuşuyla da oynamamalı (sürüklemedeki kilitle
         aynı sözleşme); yalnız hareket edebilenler kaydırılır. */
      const movable = [];
      for (const id of selection) {
        const it = getItem(id);
        if (it && !it.locked) movable.push(it);
      }
      if (!movable.length) break;
      pushNudgeUndo();
      for (const it of movable) {
        it.x += dx; it.y += dy;
        updateItemEl(it, elMap.get(it.id));
      }
      updateItemBar();
      updateGroupFrame();
      scheduleSave();
      break;
    }
  }
});

window.addEventListener('keyup', e => {
  if (e.code === 'Space') {
    spaceDown = false;
    stage.classList.remove('space');
  }
});
window.addEventListener('blur', () => {
  spaceDown = false;
  stage.classList.remove('space');
});

/* =========================================================
   pano + sürükle-bırak
   ========================================================= */
window.addEventListener('paste', e => {
  const items = e.clipboardData && e.clipboardData.items;
  if (!items) return;
  const files = [];
  for (const it of items) {
    if (it.kind === 'file' && it.type.startsWith('image/')) {
      const f = it.getAsFile();
      if (f) files.push(f);
    }
  }
  if (files.length) {
    e.preventDefault();
    addFiles(files, null);
  }
});

stage.addEventListener('dragover', e => {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'copy';
});

stage.addEventListener('drop', e => {
  e.preventDefault();
  const files = e.dataTransfer.files;
  if (files && files.length) {
    addFiles(files, screenToWorld({ x: e.clientX, y: e.clientY }));
  }
});

/* =========================================================
   PNG dışa aktarma
   ========================================================= */
function wrapLines(ctx, text, maxW) {
  const out = [];
  for (const para of String(text).split('\n')) {
    if (!para) { out.push(''); continue; }
    const words = para.split(/(\s+)/);
    let line = '';
    for (const w of words) {
      const test = line + w;
      if (ctx.measureText(test).width > maxW && line.trim()) {
        out.push(line.replace(/\s+$/, ''));
        line = w.replace(/^\s+/, '');
      } else {
        line = test;
      }
    }
    out.push(line);
  }
  return out.length ? out : [''];
}

/* Dışa aktarma çekirdeği: kapsam + kenar boşluğu + hedef boyut + arka
   plan → tuval. PNG düğmesi detaylı Dışa Aktar penceresini açar;
   önizleme ve indirme aynı hattı kullanır. */
const EXPORT_MAX_PX = 16000;

function exportComputeBounds(scope, sketchOnly) {
  if (sketchOnly) {
    const ib = typeof inkGlobalWorldBounds === 'function' ? inkGlobalWorldBounds() : null;
    if (!ib || ib.w < 1 || ib.h < 1) return null;
    return { items: [], b: { x: ib.x, y: ib.y, w: ib.w, h: ib.h } };
  }
  if (scope === 'viewport') {
    const vw = stage.clientWidth, vh = stage.clientHeight;
    const s = Math.max(1e-4, Number(state.view.scale) || 1);
    const b = {
      x: (0 - state.view.x) / s,
      y: (0 - state.view.y) / s,
      w: vw / s,
      h: vh / s,
    };
    return { items: state.items, b };
  }
  const secili = scope === 'selection' && selection.size > 0;
  const items = secili ? state.items.filter(i => selection.has(i.id)) : state.items;
  const hasInk = typeof inkViewportStrokeCount === 'function' && inkViewportStrokeCount() > 0;
  if (!items.length && !hasInk) return null;
  const b = boundsOf(items, 0);
  // Sadece çizim varsa veya notlar görsellerin dışına taşıyorsa tuvali büyüt.
  // (Seçim varsa dışa aktarım seçili öğelerle sınırlı kalır.)
  if (!secili && typeof inkGlobalWorldBounds === 'function') {
    const ib = inkGlobalWorldBounds();
    if (ib) {
      const x0 = Math.min(b.x, ib.x);
      const y0 = Math.min(b.y, ib.y);
      const x1 = Math.max(b.x + b.w, ib.x + ib.w);
      const y1 = Math.max(b.y + b.h, ib.y + ib.h);
      b.x = x0; b.y = y0; b.w = x1 - x0; b.h = y1 - y0;
    }
  }
  if (b.w < 1 || b.h < 1) return null;
  return { items, b };
}

/* Verilen öğe listesini ve dünya dikdörtgenini tuvale çizer. Dışa
   aktarma kapsamları ile ayrı penceredeki canlı referans görüntüsü aynı
   çizim hattını paylaşır. opts: {includeInk, pad, finalW, finalH, bg, bgColor} */
async function renderExportCanvas(items, b, opts) {
  const pad = opts.pad | 0;

  // Dışa aktarımda görsel eksik kalmasın: seçili görselleri önbelleğe al.
  await Promise.all(items
    .filter(it => it.kind === 'image' && it.imageId)
    .map(it => ensureImageCached(it.imageId).catch(() => null)));

  const W = Math.max(1, Math.ceil(b.w + pad * 2));
  const H = Math.max(1, Math.ceil(b.h + pad * 2));
  const k = Math.min(opts.finalW / W, opts.finalH / H, EXPORT_MAX_PX / Math.max(W, H));

  const canvas = document.createElement('canvas');
  canvas.width  = Math.round(W * k);
  canvas.height = Math.round(H * k);
  const ctx = canvas.getContext('2d');
  ctx.scale(k, k);

  if (opts.bg === 'white') {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, W, H);
  } else if (opts.bg === 'custom') {
    ctx.fillStyle = opts.bgColor || '#ffffff';
    ctx.fillRect(0, 0, W, H);
  } else if (opts.bg === 'board') {
    const bgA = typeof state.bg === 'number' ? state.bg : 1;
    if (bgA > 0.01) {
      ctx.fillStyle = `rgba(21,21,26,${bgA})`;
      ctx.fillRect(0, 0, W, H);
    }
  }

  // Global çizim katmanları: alttakiler görsellerden önce, üsttekiler sonra.
  if (opts.includeInk !== false && typeof inkDrawGlobalForExport === 'function') inkDrawGlobalForExport(ctx, b, pad, 'below');

  for (const it of [...items].sort(byZ)) {
    const c = itemCenter(it);
    ctx.save();
    ctx.translate(c.x - b.x + pad, c.y - b.y + pad);
    ctx.rotate((it.rot || 0) * Math.PI / 180);
    /* Ekranla aynı sıra: aynalama döndürülmüş eksende uygulanır
       (06-render'daki scale(±1,±1) ile birebir). */
    ctx.scale(it.flipH ? -1 : 1, it.flipV ? -1 : 1);

    ctx.globalAlpha = alphaOf(it);

    if (it.kind === 'image') {      const cached = imgCache.get(it.imageId);
      if (cached && cached.img) {
        // Ekrandaki hafif yuvarlatılmış köşeler dışa aktarımda da korunur.
        const r = Math.min(3, it.w / 2, it.h / 2);
        ctx.save();
        ctx.beginPath();
        if (typeof ctx.roundRect === 'function') {
          ctx.roundRect(-it.w / 2, -it.h / 2, it.w, it.h, r);
        } else {
          const x = -it.w / 2, y = -it.h / 2;
          const w = it.w, h = it.h;
          ctx.moveTo(x + r, y);
          ctx.lineTo(x + w - r, y);
          ctx.quadraticCurveTo(x + w, y, x + w, y + r);
          ctx.lineTo(x + w, y + h - r);
          ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
          ctx.lineTo(x + r, y + h);
          ctx.quadraticCurveTo(x, y + h, x, y + h - r);
          ctx.lineTo(x, y + r);
          ctx.quadraticCurveTo(x, y, x + r, y);
          ctx.closePath();
        }
        ctx.clip();

        // Ekrandaki kırpma ve filtreleri tuvale de uygula.
        const cropTop = clamp(Number(it.cropTop) || 0, 0, 100) / 100;
        const cropRight = clamp(Number(it.cropRight) || 0, 0, 100) / 100;
        const cropBottom = clamp(Number(it.cropBottom) || 0, 0, 100) / 100;
        const cropLeft = clamp(Number(it.cropLeft) || 0, 0, 100) / 100;
        const cw = it.w * Math.max(0, 1 - cropLeft - cropRight);
        const ch = it.h * Math.max(0, 1 - cropTop - cropBottom);
        if (cw > 0 && ch > 0) {
          const gray = Number(it.fGray) || 0;
          const bright = it.fBright === undefined ? 100 : Number(it.fBright);
          const contrast = it.fContrast === undefined ? 100 : Number(it.fContrast);
          const temp = Number(it.fTemp) || 0;
          const filters = [];
          if (gray) filters.push(`grayscale(${gray}%)`);
          if (temp > 0) {
            filters.push(`sepia(${Math.min(60, temp * 0.6)}%)`);
            filters.push(`saturate(${Math.round(100 + temp * 0.35)}%)`);
          } else if (temp < 0) {
            const t = -temp;
            filters.push(`hue-rotate(${Math.min(30, t * 0.3)}deg)`);
            filters.push(`saturate(${Math.round(100 - t * 0.2)}%)`);
            filters.push(`brightness(${Math.round(100 + t * 0.05)}%)`);
          }
          if (bright !== 100) filters.push(`brightness(${bright}%)`);
          if (contrast !== 100) filters.push(`contrast(${contrast}%)`);
          if (filters.length) ctx.filter = filters.join(' ');
          if (cropTop || cropRight || cropBottom || cropLeft) {
            ctx.beginPath();
            ctx.rect(
              -it.w / 2 + it.w * cropLeft,
              -it.h / 2 + it.h * cropTop,
              cw, ch
            );
            ctx.clip();
          }
          ctx.drawImage(cached.img, -it.w / 2, -it.h / 2, it.w, it.h);
        }
        ctx.restore();
        if (opts.includeInk !== false && typeof inkDrawAttachedForExport === 'function') inkDrawAttachedForExport(ctx, it);
      }
    } else {
      drawTextItem(ctx, it);
    }

    ctx.globalAlpha = 1;

    // "önemli" işaretli öğe: kendi renginde çerçeve
    if (it.important) {
      const w = it.w, h = it.h || 0;
      const impC = impColorOf(it);
      ctx.save();
      ctx.strokeStyle = impC;
      ctx.lineWidth = 4;
      ctx.shadowColor = hexToRgba(impC, 0.7);
      ctx.shadowBlur = 18;
      ctx.beginPath();
      if (typeof ctx.roundRect === 'function') ctx.roundRect(-w / 2 - 5, -h / 2 - 5, w + 10, h + 10, 4);
      else ctx.rect(-w / 2 - 5, -h / 2 - 5, w + 10, h + 10);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  if (opts.includeInk !== false && typeof inkDrawGlobalForExport === 'function') inkDrawGlobalForExport(ctx, b, pad, 'above');

  return { canvas, W, H, k };
}

/* Dışa aktarma kapsamından tuval üretir. */
async function renderExportCore(opts) {
  const bilgi = exportComputeBounds(opts.scope, opts.sketchOnly);
  if (!bilgi) return null;
  return renderExportCanvas(bilgi.items, bilgi.b, opts);
}

/* Ayrı panel penceresindeki canlı referans görüntüsü: verilen dünya
   dikdörtgenini hedef piksel boyutunda çizer. Raf görüntüsü panel
   penceresine veri URL'si olarak taşınır. */
async function renderBoardRegion(worldRect, outW, outH, opts) {
  const cfg = opts && typeof opts === 'object' ? opts : {};
  if (!worldRect) return null;
  const w = Number(worldRect.w);
  const h = Number(worldRect.h);
  if (!(w > 0) || !(h > 0)) return null;
  const items = Array.isArray(state.items) ? state.items : [];
  return renderExportCanvas(items, {
    x: Number(worldRect.x) || 0,
    y: Number(worldRect.y) || 0,
    w, h,
  }, {
    pad: 0,
    finalW: Math.max(1, Math.round(Number(outW) || w)),
    finalH: Math.max(1, Math.round(Number(outH) || h)),
    bg: cfg.bg || 'board',
    bgColor: cfg.bgColor || '',
    includeInk: cfg.includeInk !== false,
  });
}

async function renderBoardRegionDataUrl(worldRect, outW, outH, opts) {
  const result = await renderBoardRegion(worldRect, outW, outH, opts);
  if (!result || !result.canvas) return '';
  try { return result.canvas.toDataURL('image/webp', 0.86); } catch { return ''; }
}

/* ---- Dışa Aktar penceresi -------------------------------------------
   Kapsam (tüm pano / seçili / görüş alanı), biçim (PNG/JPEG/WebP),
   ölçek + DPI + belirli boyut, çizim katmanı seçenekleri, arka plan,
   kalite, metadata; canlı önizleme + boyut/dosya tahmini.
   Tercihler localStorage'da hatırlanır. */

const exportUi = {
  els: {}, bound: false, scaleVal: 1, ratio: 1,
  previewToken: 0, previewTimer: 0,
};

const EXPORT_FORMATS = {
  png:  { mime: 'image/png',  ext: 'png', hint: 'Lossless; supports transparent background.' },
  jpeg: { mime: 'image/jpeg', ext: 'jpg', hint: 'For photos and small files; no transparency.' },
  webp: { mime: 'image/webp', ext: 'webp', hint: 'As transparent as PNG, as small a file as JPEG.' },
  avif: { mime: 'image/avif', ext: 'avif', hint: 'Modern codec — smallest file; disabled on unsupported builds.' },
  bmp:  { mime: 'image/bmp',  ext: 'bmp', hint: 'Uncompressed raw pixels; almost any program opens them.', enc: 'bmp' },
  ico:  { mime: 'image/x-icon', ext: 'ico', hint: 'Icon file; scaled to at most 256×256.', enc: 'ico' },
  pdf:  { mime: 'application/pdf', ext: 'pdf', hint: 'Embeds the image in the document; for printing and sharing.', enc: 'pdf' },
};

function exportDefaultName() {
  const d = new Date();
  const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}-${String(d.getHours()).padStart(2, '0')}${String(d.getMinutes()).padStart(2, '0')}`;
  return `tailref-${stamp}`;
}

function exportLoadPrefs() {
  try { return JSON.parse(localStorage.getItem('tailref:export:v1') || '{}'); } catch { return {}; }
}

function exportSavePrefs(p) {
  try { localStorage.setItem('tailref:export:v1', JSON.stringify(p)); } catch { /* yoksay */ }
}

function exportBoyutYazisi(bayt) {
  if (bayt < 1024) return `${Math.round(bayt)} B`;
  if (bayt < 1024 * 1024) return `${Math.round(bayt / 1024)} KB`;
  return `${(bayt / (1024 * 1024)).toFixed(1)} MB`;
}

/* Kayıt klasörü satırını exportUi.saveDir'e göre çizer. */
function exportKayitKlasoruYaz() {
  const els = exportUi.els;
  if (!els || !els.dirText) return;
  els.dirText.textContent = exportUi.saveDir || 'Browser default';
  els.dirText.title = exportUi.saveDir || '';
  els.dirText.classList.toggle('is-empty', !exportUi.saveDir);
  els.dirClear.hidden = !exportUi.saveDir;
}

/* Klasörü ayarlar + prefs'e hemen yazar (aktarmadan bağımsız kalsın). */
function exportKayitKlasoruAyarla(dir) {
  exportUi.saveDir = dir || '';
  exportKayitKlasoruYaz();
  try { exportSavePrefs({ ...exportLoadPrefs(), saveDir: exportUi.saveDir }); } catch { /* yoksay */ }
}

/* Kalite parametresi yalnızca bu biçimlerde anlamlı. */
const EXPORT_QUALITY_RE = /jpeg|webp|avif/;

function exportFormatDestekli(format) {
  if (format !== 'avif') return true;
  if (exportUi.avifDestek === undefined) {
    try {
      exportUi.avifDestek = document.createElement('canvas')
        .toDataURL('image/avif').indexOf('data:image/avif') === 0;
    } catch { exportUi.avifDestek = false; }
  }
  return exportUi.avifDestek;
}

/* Aktif biçimi baytlara çevirir: kaliteli biçimler toBlob kullanır,
   BMP/ICO/PDF özel kodlayıcıdan geçer. */
function exportEncode(canvas, format, quality) {
  const f = EXPORT_FORMATS[format];
  if (f && f.enc === 'bmp') return canvasToBmpBlob(canvas);
  if (f && f.enc === 'ico') return canvasToIcoBlob(canvas);
  if (f && f.enc === 'pdf') return canvasToPdfBlob(canvas);
  return new Promise(res => canvas.toBlob(res, f.mime, quality));
}

function exportBind() {
  if (exportUi.bound) return true;
  const modal = document.getElementById('exportModal');
  if (!modal) return false;
  const form = modal.querySelector('#exportForm');
  const q = sel => modal.querySelector(sel);
  const els = {
    modal, form,
    pcanvas: q('#exPreviewCanvas'),
    info: q('#exInfo'),
    w: q('#exW'), h: q('#exH'), lock: q('#exLock'),
    exactRow: q('#exExactRow'),
    qualityRow: q('#exQualityRow'), quality: q('#exQuality'), qualityVal: q('#exQualityVal'),
    scaleGroup: q('#exScaleGroup'), dpiGroup: q('#exDpiGroup'),
    padGroup: q('#exPadGroup'),
    inkLayer: q('#exInkLayer'), sketchOnly: q('#exSketchOnly'),
    meta: q('#exMeta'), metaWrap: q('#exMetaWrap'),
    bgColor: q('#exBgColor'),
    formatHint: q('#exFormatHint'),
    name: q('#exName'),
    dirText: q('#exDirText'), dirBtn: q('#exDirBtn'), dirClear: q('#exDirClear'),
    advBtn: q('#exAdvBtn'),
    chipDim: q('#exChipDim'), chipFmt: q('#exChipFmt'), chipSize: q('#exChipSize'),
    download: q('#exDownload'),
    close: q('#exClose'),
    tileSel: q('#exTileSel'), tileSelSub: q('#exTileSelSub'),
  };
  if (!els.pcanvas || !els.download) return false;
  els.pctx = els.pcanvas.getContext('2d');
  exportUi.els = els;

  // Son tercihler
  const prefs = exportLoadPrefs();
  /* Eski sürüm kaydı (pad yok): beyaz arka plan kalıntısını temizle —
     varsayılan "fotoğraf neyse o" olsun. */
  if (prefs.pad === undefined) prefs.bg = 'transparent';
  const setRadio = (name, val) => {
    const el = form.querySelector(`input[name="${name}"][value="${val}"]`);
    if (el) el.checked = true;
  };
  if (prefs.format && EXPORT_FORMATS[prefs.format]) setRadio('exFormat', prefs.format);
  if (prefs.bg) setRadio('exBg', prefs.bg);
  if (Number.isFinite(prefs.quality)) els.quality.value = String(prefs.quality);
  els.qualityVal.textContent = `%${els.quality.value}`;
  els.scaleVal = 1;
  exportUi.scaleVal = Number.isFinite(prefs.scaleVal) ? prefs.scaleVal : 1;
  /* Kenar boşluğu: varsayılan Yok — içerik orijinal boyutuyla çıkar. */
  exportUi.pad = Number.isFinite(prefs.pad) ? Number(prefs.pad) : 0;
  if (prefs.lock === false) els.lock.checked = false;
  els.inkLayer.checked = prefs.inkInclude !== false;
  els.sketchOnly.checked = prefs.sketchOnly === true;
  els.meta.checked = prefs.meta === true && true;
  exportUi.saveDir = typeof prefs.saveDir === 'string' ? prefs.saveDir : '';
  exportKayitKlasoruYaz();

  // AVIF bu Chromium'da kodlanamıyorsa kartı kilitler.
  const avifInp = form.querySelector('input[name="exFormat"][value="avif"]');
  if (avifInp) {
    avifInp.disabled = !exportFormatDestekli('avif');
    const avifKart = avifInp.closest('.exFmt');
    if (avifKart) avifKart.classList.toggle('is-disabled', avifInp.disabled);
    if (avifInp.disabled && avifInp.checked) setRadio('exFormat', 'png');
  }

  // Ölçek + DPI düğmeleri
  els.scaleGroup.addEventListener('click', e => {
    const btn = e.target.closest('button[data-scale]');
    if (!btn) return;
    exportUi.scaleVal = btn.dataset.scale === 'custom' ? null : (Number(btn.dataset.scale) || 1);
    if (exportUi.scaleVal === null) exportBelirliDoldur();
    exportSyncScaleUi();
    exportSchedulePreview();
  });
  els.dpiGroup.addEventListener('click', e => {
    const btn = e.target.closest('button[data-dpi]');
    if (!btn) return;
    exportUi.scaleVal = Number(btn.dataset.dpi) / 72;
    exportSyncScaleUi();
    exportSchedulePreview();
  });
  // Kenar boşluğu düğmeleri (Yok / Az / Normal)
  els.padGroup.addEventListener('click', e => {
    const btn = e.target.closest('button[data-pad]');
    if (!btn) return;
    exportUi.pad = Number(btn.dataset.pad) || 0;
    exportSyncScaleUi();
    exportSchedulePreview();
  });

  // Kayıt klasörü: Gözat → ana süreçte klasör seçme penceresi
  els.dirBtn.addEventListener('click', async () => {
    const api = window.tailref;
    if (!api || typeof api.chooseDirectory !== 'function') return;
    const res = await api.chooseDirectory();
    if (res && res.ok && res.dir) exportKayitKlasoruAyarla(res.dir);
  });
  els.dirClear.addEventListener('click', () => exportKayitKlasoruAyarla(''));

  // Daha fazla ayar: sade ↔ ileri mod
  els.advBtn.addEventListener('click', () => {
    const acik = modal.classList.toggle('is-adv');
    els.advBtn.setAttribute('aria-expanded', acik ? 'true' : 'false');
  });

  form.addEventListener('submit', e => { e.preventDefault(); void exportPerform(); });
  q('#exCancel').addEventListener('click', exportHide);
  els.close.addEventListener('click', exportHide);
  form.addEventListener('keydown', e => {
    if (e.key === 'Escape') { e.stopPropagation(); exportHide(); }
  });
  modal.addEventListener('mousedown', e => { if (e.target === modal) exportHide(); });

  form.addEventListener('change', () => { exportSyncFormatUi(); exportSchedulePreview(); });
  els.quality.addEventListener('input', () => {
    els.qualityVal.textContent = `%${els.quality.value}`;
    exportSchedulePreview();
  });
  els.w.addEventListener('input', () => {
    if (els.lock.checked && exportUi.ratio > 0) {
      els.h.value = String(Math.max(16, Math.round((Number(els.w.value) || 16) / exportUi.ratio)));
    }
    exportSchedulePreview();
  });
  els.h.addEventListener('input', () => {
    if (els.lock.checked) {
      els.w.value = String(Math.max(16, Math.round((Number(els.h.value) || 16) * exportUi.ratio)));
    }
    exportSchedulePreview();
  });
  els.bgColor.addEventListener('input', exportSchedulePreview);

  exportUi.bound = true;
  exportSyncFormatUi();
  exportSyncScaleUi();
  return true;
}

function exportReadFormat() {
  const el = exportUi.els.form.querySelector('input[name="exFormat"]:checked');
  return el ? el.value : 'png';
}

function exportSyncFormatUi() {
  const els = exportUi.els;
  let fmt = exportReadFormat();
  if (!exportFormatDestekli(fmt)) {
    // Desteklenmeyen biçim (ör. AVIF'siz sürüm) → PNG'e dön.
    const pngInp = els.form.querySelector('input[name="exFormat"][value="png"]');
    if (pngInp) pngInp.checked = true;
    fmt = 'png';
  }
  els.formatHint.textContent = EXPORT_FORMATS[fmt].hint;
  els.qualityRow.hidden = !EXPORT_QUALITY_RE.test(fmt);
  const png = fmt === 'png';
  els.meta.disabled = !png;
  els.metaWrap.classList.toggle('is-disabled', !png);
  if (!png) els.meta.checked = false;
  // JPEG saydamlığı desteklemez: saydam seçiliyse beyaza döndür.
  const bgSel = els.form.querySelector('input[name="exBg"]:checked');
  if (fmt === 'jpeg' && bgSel && bgSel.value === 'transparent') {
    els.form.querySelector('input[name="exBg"][value="white"]').checked = true;
  }
  els.bgColor.hidden = !bgSel || bgSel.value !== 'custom';
}

function exportSyncScaleUi() {
  const els = exportUi.els;
  for (const btn of els.scaleGroup.querySelectorAll('button[data-scale]')) {
    const v = btn.dataset.scale;
    const aktif = v === 'custom' ? exportUi.scaleVal === null
      : Math.abs(Number(v) - (exportUi.scaleVal || 0)) < 1e-9;
    btn.classList.toggle('is-active', aktif);
  }
  for (const btn of els.dpiGroup.querySelectorAll('button[data-dpi]')) {
    const dpi = Number(btn.dataset.dpi);
    btn.classList.toggle('is-active',
      exportUi.scaleVal !== null && Math.abs(dpi / 72 - exportUi.scaleVal) < 0.01);
  }
  for (const btn of els.padGroup.querySelectorAll('button[data-pad]')) {
    btn.classList.toggle('is-active', Math.abs((Number(btn.dataset.pad) || 0) - (exportUi.pad || 0)) < 1e-9);
  }
  els.exactRow.hidden = exportUi.scaleVal !== null;
}

function exportReadCfg() {
  const els = exportUi.els;
  const form = els.form;
  const val = name => {
    const el = form.querySelector(`input[name="${name}"]:checked`);
    return el ? el.value : null;
  };
  const format = val('exFormat') || 'png';
  let bg = val('exBg') || 'transparent';
  if (format === 'jpeg' && bg === 'transparent') bg = 'white';
  return {
    format,
    scope: val('exScope') || 'all',
    sketchOnly: els.sketchOnly.checked,
    includeInk: els.inkLayer.checked,
    meta: els.meta.checked,
    bg, bgColor: els.bgColor.value,
    scaleVal: exportUi.scaleVal,
    pad: exportUi.pad || 0,
    quality: clamp(Number(els.quality.value) || 92, 50, 100),
    lock: els.lock.checked,
    saveDir: exportUi.saveDir || '',
    name: (els.name.value.trim() || exportDefaultName()),
  };
}

/* Geçerli kapsamın ham boyutu (pad dahil, ölçeksiz). */
function exportBaseDims(cfg) {
  const bilgi = exportComputeBounds(cfg.scope, cfg.sketchOnly);
  if (!bilgi) return null;
  const b = bilgi.b;
  /* Kenar boşluğu: varsayılan 0 (içerik orijinal boyutuyla çıkar). */
  const pad = cfg.scope === 'viewport' ? 0 : (Number(cfg.pad) || 0);
  return {
    pad,
    W0: Math.max(1, Math.ceil(b.w + pad * 2)),
    H0: Math.max(1, Math.ceil(b.h + pad * 2)),
  };
}

/* "Custom size" W×H kutularını geçerli içeriğin gerçek pikseliyle doldurur. */
function exportBelirliDoldur() {
  const els = exportUi.els;
  const temel = exportBaseDims(exportReadCfg());
  if (!temel) return;
  els.w.value = String(temel.W0);
  els.h.value = String(temel.H0);
}

function exportFinalDims(cfg) {
  const temel = exportBaseDims(cfg);
  if (!temel) return null;
  exportUi.ratio = temel.W0 / temel.H0;
  let tw, th;
  if (cfg.scaleVal === null) {
    const twIstenen = Math.round(clamp(Number(exportUi.els.w.value) || temel.W0, 16, EXPORT_MAX_PX));
    const thIstenen = Math.round(clamp(Number(exportUi.els.h.value) || temel.H0, 16, EXPORT_MAX_PX));
    const k = Math.min(twIstenen / temel.W0, thIstenen / temel.H0, EXPORT_MAX_PX / Math.max(temel.W0, temel.H0));
    tw = Math.round(temel.W0 * k); th = Math.round(temel.H0 * k);
  } else {
    const k = Math.min(cfg.scaleVal, EXPORT_MAX_PX / Math.max(temel.W0, temel.H0));
    tw = Math.round(temel.W0 * k); th = Math.round(temel.H0 * k);
  }
  return { pad: temel.pad, W0: temel.W0, H0: temel.H0, tw: Math.max(1, tw), th: Math.max(1, th) };
}

function openExportDialog() {
  if (!exportBind()) return;
  const els = exportUi.els;
  const selVar = selection.size > 0;
  const selInput = els.form.querySelector('input[name="exScope"][value="selection"]');
  selInput.disabled = !selVar;
  els.tileSel.classList.toggle('is-disabled', !selVar);
  els.tileSelSub.textContent = selVar ? `${selection.size} items` : 'No selection';
  if (!selVar && selInput.checked) {
    els.form.querySelector('input[name="exScope"][value="all"]').checked = true;
  }
  if (!els.name.value.trim()) els.name.value = exportDefaultName();
  if (exportUi.scaleVal === null) exportBelirliDoldur();
  /* Sade açılış: ileri kontroller kapalı başlar; yalnız kayıtlı tercihler
     sade düzende görünmüyorsa (özel ölçek / ileri biçim) açık başlat. */
  const kayitliFmt = exportReadFormat();
  const sadeDegil = exportUi.scaleVal === null
    || (![1, 2].includes(exportUi.scaleVal))
    || (kayitliFmt !== 'png' && kayitliFmt !== 'jpeg');
  els.modal.classList.toggle('is-adv', sadeDegil);
  els.advBtn.setAttribute('aria-expanded', sadeDegil ? 'true' : 'false');
  els.modal.hidden = false;
  exportSchedulePreview();
}

function exportHide() {
  exportUi.els.modal.hidden = true;
  exportSavePrefs(exportReadCfg());
}

function exportSchedulePreview() {
  clearTimeout(exportUi.previewTimer);
  exportUi.previewTimer = setTimeout(() => { void exportUpdatePreview(); }, 120);
}

async function exportUpdatePreview() {
  const token = ++exportUi.previewToken;
  const els = exportUi.els;
  const cfg = exportReadCfg();
  const dims = exportFinalDims(cfg);
  if (!dims) {
    els.chipDim.textContent = 'Nothing to export.';
    els.chipFmt.textContent = '—';
    els.chipSize.textContent = '—';
    els.download.disabled = true;
    return;
  }
  els.download.disabled = false;
  const maxSide = 320;
  const kp = Math.min(maxSide / Math.max(dims.tw, dims.th), 1);
  const pvW = Math.max(1, Math.round(dims.tw * kp));
  const pvH = Math.max(1, Math.round(dims.th * kp));
  const sonuc = await renderExportCore({
    scope: cfg.scope, sketchOnly: cfg.sketchOnly, includeInk: cfg.includeInk,
    pad: dims.pad, finalW: pvW, finalH: pvH, bg: cfg.bg, bgColor: cfg.bgColor,
  });
  if (token !== exportUi.previewToken || !sonuc) return;
  els.pcanvas.width = pvW;
  els.pcanvas.height = pvH;
  els.pctx.clearRect(0, 0, pvW, pvH);
  els.pctx.drawImage(sonuc.canvas, 0, 0);
  const kalite = EXPORT_QUALITY_RE.test(cfg.format) ? cfg.quality / 100 : undefined;
  const blob = await exportEncode(sonuc.canvas, cfg.format, kalite);
  if (token !== exportUi.previewToken) return;
  const oran = (dims.tw * dims.th) / Math.max(1, pvW * pvH);
  const tahmin = blob ? blob.size * oran : 0;
  els.chipDim.textContent = `${dims.tw} × ${dims.th} px`;
  els.chipFmt.textContent = cfg.format.toUpperCase();
  els.chipSize.textContent = blob ? `~${exportBoyutYazisi(tahmin)}` : '—';
}

async function exportPerform() {
  const els = exportUi.els;
  const cfg = exportReadCfg();
  const dims = exportFinalDims(cfg);
  if (!dims) { alert('Nothing to export.'); return; }
  els.download.disabled = true;
  try {
    const sonuc = await renderExportCore({
      scope: cfg.scope, sketchOnly: cfg.sketchOnly, includeInk: cfg.includeInk,
      pad: dims.pad, finalW: dims.tw, finalH: dims.th, bg: cfg.bg, bgColor: cfg.bgColor,
    });
    if (!sonuc) { alert('Nothing to export.'); return; }
    const f = EXPORT_FORMATS[cfg.format];
    const kalite = EXPORT_QUALITY_RE.test(cfg.format) ? cfg.quality / 100 : undefined;
    let blob = await exportEncode(sonuc.canvas, cfg.format, kalite);
    if (!blob) { alert('Could not create the file.'); return; }
    if (cfg.format === 'png' && cfg.meta) {
      try { blob = await pngMetadataGom(blob, dims); } catch { /* yalın yaz */ }
    }
    const adi = cfg.name.replace(/[\\/:*?"<>|]+/g, '_');
    const dosyaAdi = adi.toLowerCase().endsWith('.' + f.ext) ? adi : `${adi}.${f.ext}`;
    if (cfg.saveDir && window.tailref && window.tailref.exportImage) {
      /* Seçili klasöre doğrudan yaz (pencere açılmaz). */
      const bytes = new Uint8Array(await blob.arrayBuffer());
      const res = await window.tailref.exportImage(bytes, dosyaAdi, f.mime, cfg.saveDir);
      if (res && res.ok) {
        if (typeof showProjectNotice === 'function') showProjectNotice('Exported: ' + res.file, 4200);
      } else {
        alert('Export failed: ' + (res && res.error ? res.error : 'bilinmeyen hata'));
        return;
      }
    } else {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = dosyaAdi;
      a.click();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    }
    exportSavePrefs({
      format: cfg.format, bg: cfg.bg, quality: cfg.quality,
      scaleVal: cfg.scaleVal, lock: cfg.lock, pad: cfg.pad, saveDir: cfg.saveDir,
      inkInclude: cfg.includeInk, sketchOnly: cfg.sketchOnly, meta: cfg.meta,
    });
    exportHide();
  } finally {
    els.download.disabled = false;
  }
}

/* Hızlı PNG dışa aktarma: diyalog açmadan tüm panoyu (öğeler + global ve
   bağlı çizim katmanları) PNG olarak indirir. v5Toolbar'ın "png" eylemi
   ve eski exportPNG çağrıları buraya düşer; tercihleri kaydetmez, panoyu
   değiştirmez. Dönen değer: dosya yazıldıysa true. */
async function exportPNG() {
  const bilgi = exportComputeBounds('all', false);
  if (!bilgi) { return false; }
  const b = bilgi.b;
  const sonuc = await renderExportCore({
    scope: 'all', sketchOnly: false, includeInk: true,
    pad: 0,
    finalW: Math.max(1, Math.round(b.w)),
    finalH: Math.max(1, Math.round(b.h)),
    bg: 'transparent',
  });
  if (!sonuc) return false;
  const blob = await exportEncode(sonuc.canvas, 'png', undefined);
  if (!blob) return false;
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = exportDefaultName() + '.png';
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  return true;
}

/* PNG tEXt metadata parçası ekler (IHDR'den sonra). Yalnızca ASCII. */
function pngCrc32(bayt) {
  let c = ~0;
  for (let i = 0; i < bayt.length; i += 1) {
    c ^= bayt[i];
    for (let k = 0; k < 8; k += 1) c = (c >>> 1) ^ (0xEDB88320 & -(c & 1));
  }
  return ~c >>> 0;
}

async function pngMetadataGom(blob, dims) {
  const buf = new Uint8Array(await blob.arrayBuffer());
  const imza = [137, 80, 78, 71, 13, 10, 26, 10];
  for (let i = 0; i < 8; i += 1) if (buf[i] !== imza[i]) return blob;
  const d = new Date();
  const metin = `TailRef Studio | ${d.toISOString()} | ${dims.tw}x${dims.th}px`;
  const veri = new TextEncoder().encode(metin.replace(/[^\x20-\x7E]/g, '?'));
  const tur = new TextEncoder().encode('tEXt');
  const kelime = new TextEncoder().encode('Comment');
  const chunkVeri = new Uint8Array(kelime.length + 1 + veri.length);
  chunkVeri.set(kelime, 0);
  chunkVeri[kelime.length] = 0;
  chunkVeri.set(veri, kelime.length + 1);
  const ihdrSon = 8 + 4 + 4 + 13 + 4; // imza + IHDR uzunluk + tur + veri + crc
  const cikti = new Uint8Array(buf.length + 12 + chunkVeri.length);
  cikti.set(buf.subarray(0, ihdrSon), 0);
  const uz = chunkVeri.length;
  cikti[ihdrSon] = (uz >>> 24) & 255;
  cikti[ihdrSon + 1] = (uz >>> 16) & 255;
  cikti[ihdrSon + 2] = (uz >>> 8) & 255;
  cikti[ihdrSon + 3] = uz & 255;
  cikti.set(tur, ihdrSon + 4);
  cikti.set(chunkVeri, ihdrSon + 8);
  const crcGirdi = new Uint8Array(4 + uz);
  crcGirdi.set(tur, 0);
  crcGirdi.set(chunkVeri, 4);
  const crc = pngCrc32(crcGirdi);
  const crcYeri = ihdrSon + 8 + uz;
  cikti[crcYeri] = (crc >>> 24) & 255;
  cikti[crcYeri + 1] = (crc >>> 16) & 255;
  cikti[crcYeri + 2] = (crc >>> 8) & 255;
  cikti[crcYeri + 3] = crc & 255;
  cikti.set(buf.subarray(ihdrSon), crcYeri + 4);
  return new Blob([cikti], { type: 'image/png' });
}

/* ---- Özel biçim kodlayıcıları ---------------------------------------
   PNG/JPEG/WebP/AVIF tarayıcının toBlob hattından çıkar; BMP, ICO ve
   PDF elle kodlanır (bağımlılık yok, tek dosyalık çıktı). */

/* 32 bit BMP — BITMAPV4 başlığı, alfa kanalı korunur. */
function canvasToBmpBlob(canvas) {
  const w = canvas.width, h = canvas.height;
  const img = canvas.getContext('2d').getImageData(0, 0, w, h).data;
  const satirHam = w * 4;
  const pad = (4 - (satirHam % 4)) % 4;
  const satir = satirHam + pad;
  const baslik = 14 + 108; // dosya başlığı + BITMAPV4HEADER
  const veri = satir * h;
  const buf = new Uint8Array(baslik + veri);
  const dv = new DataView(buf.buffer);
  buf[0] = 0x42; buf[1] = 0x4D; // 'BM'
  dv.setUint32(2, baslik + veri, true);
  dv.setUint32(10, baslik, true);
  dv.setUint32(14, 108, true);          // V4 başlık boyutu
  dv.setInt32(18, w, true);
  dv.setInt32(22, h, true);             // pozitif = aşağıdan yukarıya
  dv.setUint16(26, 1, true);            // düzlem
  dv.setUint16(28, 32, true);           // bpp
  dv.setUint32(30, 3, true);            // BI_BITFIELDS
  dv.setUint32(34, veri, true);
  dv.setInt32(38, 2835, true);          // 72 DPI
  dv.setInt32(42, 2835, true);
  dv.setUint32(54, 0x00FF0000, true);   // R maskesi
  dv.setUint32(58, 0x0000FF00, true);   // G
  dv.setUint32(62, 0x000000FF, true);   // B
  dv.setUint32(66, 0xFF000000, true);   // A
  dv.setUint32(70, 0x73524742, true);   // LCS 'sRGB'
  for (let y = 0; y < h; y += 1) {
    const kaynak = (h - 1 - y) * satirHam;
    let hedef = baslik + y * satir;
    for (let x = 0; x < w; x += 1) {
      const i = kaynak + x * 4;
      buf[hedef] = img[i + 2];
      buf[hedef + 1] = img[i + 1];
      buf[hedef + 2] = img[i];
      buf[hedef + 3] = img[i + 3];
      hedef += 4;
    }
  }
  return new Blob([buf], { type: 'image/bmp' });
}

/* ICO — PNG verisini simge kabına gömer; 256px üstü ölçeklenir. */
async function canvasToIcoBlob(canvas) {
  const en = canvas.width, boy = canvas.height;
  const k = Math.min(256 / en, 256 / boy, 1);
  const w = Math.max(1, Math.round(en * k));
  const h = Math.max(1, Math.round(boy * k));
  const kare = document.createElement('canvas');
  kare.width = w; kare.height = h;
  kare.getContext('2d').drawImage(canvas, 0, 0, w, h);
  const pngBlob = await new Promise(res => kare.toBlob(res, 'image/png'));
  const png = new Uint8Array(await pngBlob.arrayBuffer());
  const buf = new Uint8Array(6 + 16 + png.length);
  const dv = new DataView(buf.buffer);
  dv.setUint16(0, 0, true);    // rezerve
  dv.setUint16(2, 1, true);    // tür: simge
  dv.setUint16(4, 1, true);    // görüntü adedi
  buf[6] = w >= 256 ? 0 : w;   // 0 = 256
  buf[7] = h >= 256 ? 0 : h;
  buf[8] = 0; buf[9] = 0;      // palet rengi / rezerve
  dv.setUint16(10, 1, true);   // düzlem
  dv.setUint16(12, 32, true);  // bpp
  dv.setUint32(14, png.length, true);
  dv.setUint32(18, 22, true);  // PNG başlangıcı
  buf.set(png, 22);
  return new Blob([buf], { type: 'image/x-icon' });
}

/* PDF 1.4 — tek sayfa, JPEG (DCTDecode) gömülü; 1px = 1pt. */
async function canvasToPdfBlob(canvas) {
  const W = canvas.width, H = canvas.height;
  const jpegBlob = await new Promise(res => canvas.toBlob(res, 'image/jpeg', 0.92));
  const jpeg = new Uint8Array(await jpegBlob.arrayBuffer());
  const parcalar = [];
  let offset = 0;
  const objOffsets = [];
  const yaz = bayt => { parcalar.push(bayt); offset += bayt.length; };
  const ascii = s => yaz(new TextEncoder().encode(s));

  ascii('%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n');
  objOffsets[1] = offset;
  ascii('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
  objOffsets[2] = offset;
  ascii('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n');
  objOffsets[3] = offset;
  ascii(`3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /XObject << /Im0 4 0 R >> /ProcSet [/PDF /ImageC] >> /Contents 5 0 R >>\nendobj\n`);
  objOffsets[4] = offset;
  ascii(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${W} /Height ${H} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);
  yaz(jpeg);
  ascii('\nendstream\nendobj\n');
  const icerik = `q\n${W} 0 0 ${H} 0 0 cm\n/Im0 Do\nQ`;
  objOffsets[5] = offset;
  ascii(`5 0 obj\n<< /Length ${icerik.length} >>\nstream\n${icerik}\nendstream\nendobj\n`);
  const xrefKonum = offset;
  let xref = 'xref\n0 6\n0000000000 65535 f \n';
  for (let i = 1; i <= 5; i += 1) xref += `${String(objOffsets[i]).padStart(10, '0')} 00000 n \n`;
  ascii(xref);
  ascii(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefKonum}\n%%EOF\n`);
  return new Blob(parcalar, { type: 'application/pdf' });
}

/* Seçili fotoğrafı dışa aktarır.

   Düzenlenmemiş fotoğraflarda IndexedDB'deki kaynak blob'u yeniden
   kodlanmadan diske yazılır (JPEG/PNG/WebP fark etmez): sıfır kayıp.

   Kırpma, filtre veya görsele bağlı çizim varsa kaynak baytlar ekranda
   görüneni içermez. Özellikle "New canvas" ile oluşturulan beyaz tuvalde
   bütün çizim ayrı bir katmanda durur; ham kaynağı yazmak bomboş bir sayfa
   üretir. Bu durumda öğe, göründüğü gibi kaynak çözünürlüğünde
   düzleştirilip PNG olarak yazılır. */
function imageItemHasVisibleInk(it) {
  if (!it || typeof inkLayersForOwner !== 'function') return false;
  let layers = [];
  try { layers = inkLayersForOwner(it.id); } catch { return false; }
  return layers.some(layer => layer
    && layer.visible !== false
    && !(layer.opacity <= 0.001)
    && Array.isArray(layer.strokes)
    && layer.strokes.length > 0);
}

/** Ham kaynak baytları görünen sonuçtan farklı mı? */
function imageItemNeedsComposite(it) {
  if (!it) return false;
  const cropKeys = ['cropTop', 'cropRight', 'cropBottom', 'cropLeft'];
  if (cropKeys.some(key => (Number(it[key]) || 0) > 0)) return true;
  if ((Number(it.fGray) || 0) > 0) return true;
  if (it.fBright !== undefined && Number(it.fBright) !== 100) return true;
  if (it.fContrast !== undefined && Number(it.fContrast) !== 100) return true;
  return imageItemHasVisibleInk(it);
}

/** Öğeyi kırpma + filtre + bağlı çizim katmanlarıyla kaynak çözünürlüğünde
    (en fazla 8192 px / 40 MP) tek bir tuvale düzleştirir. */
function renderImageItemForExport(it) {
  const cached = imgCache.get(it.imageId);
  const img = cached && cached.img;
  if (!img) return null;

  const naturalW = img.naturalWidth || img.width || 1;
  const naturalH = img.naturalHeight || img.height || 1;
  const baseW = Math.max(1, Number(it.w) || naturalW);
  const baseH = Math.max(1, Number(it.h) || naturalH);
  const cropTop = clamp(Number(it.cropTop) || 0, 0, 100) / 100;
  const cropRight = clamp(Number(it.cropRight) || 0, 0, 100) / 100;
  const cropBottom = clamp(Number(it.cropBottom) || 0, 0, 100) / 100;
  const cropLeft = clamp(Number(it.cropLeft) || 0, 0, 100) / 100;
  const visibleW = Math.max(1, baseW * (1 - cropLeft - cropRight));
  const visibleH = Math.max(1, baseH * (1 - cropTop - cropBottom));

  /* Kaynak piksel yoğunluğunu koru; tuval öğeleri zaten 1:1'dir. */
  let scale = Math.max(1, naturalW / baseW, naturalH / baseH);
  scale = Math.min(
    scale,
    8192 / Math.max(visibleW, visibleH),
    Math.sqrt((40 * 1000 * 1000) / Math.max(1, visibleW * visibleH))
  );
  if (!Number.isFinite(scale) || scale <= 0) scale = 1;

  const W = Math.max(1, Math.round(visibleW * scale));
  const H = Math.max(1, Math.round(visibleH * scale));
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.setTransform(1, 0, 0, 1, 0, 0);
  /* Kırpılan görünür alanın sol üstü tuvale (0,0) gelsin. */
  ctx.translate(
    (baseW / 2 - baseW * cropLeft) * scale,
    (baseH / 2 - baseH * cropTop) * scale
  );
  ctx.scale(scale, scale);

  const gray = Number(it.fGray) || 0;
  const bright = it.fBright === undefined ? 100 : Number(it.fBright);
  const contrast = it.fContrast === undefined ? 100 : Number(it.fContrast);
  const filters = [];
  if (gray) filters.push(`grayscale(${gray}%)`);
  if (bright !== 100) filters.push(`brightness(${bright}%)`);
  if (contrast !== 100) filters.push(`contrast(${contrast}%)`);

  ctx.save();
  if (filters.length) ctx.filter = filters.join(' ');
  ctx.drawImage(img, -baseW / 2, -baseH / 2, baseW, baseH);
  ctx.restore();

  /* Bağlı çizim katmanları: ekrandaki sıra, opaklık ve karışım aynen. */
  if (typeof inkDrawAttachedForExport === 'function' && typeof inkLayersForOwner === 'function') {
    for (const layer of inkLayersForOwner(it.id)) {
      if (!layer || layer.visible === false || layer.opacity <= 0.001) continue;
      if (!Array.isArray(layer.strokes) || !layer.strokes.length) continue;
      const ready = inkRuntime && inkRuntime.itemCanvases
        ? inkRuntime.itemCanvases.get(layer.id) : null;
      const dirty = !!(inkRuntime && inkRuntime.dirtyLayers && inkRuntime.dirtyLayers.has(layer.id));
      if (typeof inkRebuildItemLayer === 'function' && (!ready || dirty)) {
        inkRebuildItemLayer(layer);
      }
    }
    inkDrawAttachedForExport(ctx, { ...it, w: baseW, h: baseH });
  }

  /* Öğe döndürülmüşse ekrandaki yönelim korunur. */
  const deg = Number(it.rot) || 0;
  if (Math.abs(deg % 360) < 0.0001) return canvas;
  const rad = (deg * Math.PI) / 180;
  const cos = Math.abs(Math.cos(rad));
  const sin = Math.abs(Math.sin(rad));
  const outW = Math.max(1, Math.round(W * cos + H * sin));
  const outH = Math.max(1, Math.round(W * sin + H * cos));
  const rotated = document.createElement('canvas');
  rotated.width = outW;
  rotated.height = outH;
  const rctx = rotated.getContext('2d');
  if (!rctx) return canvas;
  rctx.translate(outW / 2, outH / 2);
  rctx.rotate(rad);
  rctx.drawImage(canvas, -W / 2, -H / 2);
  canvas.width = 0;
  canvas.height = 0;
  return rotated;
}

/** Blob'u masaüstünde kaydetme penceresine (yoksa indirmeye) yazar. */
async function writeImageExport(blob, fileName) {
  try {
    const bytes = new Uint8Array(await blob.arrayBuffer());
    if (window.tailref && window.tailref.exportImage) {
      const res = await window.tailref.exportImage(bytes, fileName, blob.type || '');
      if (res && res.ok) {
        if (typeof showProjectNotice === 'function') showProjectNotice('Exported: ' + res.file, 4200);
        return true;
      }
      if (res && res.canceled) return false;
      alert('Export failed: ' + (res && res.error ? res.error : 'bilinmeyen hata'));
      return false;
    }
    /* Tarayıcı yedeği: aynı blob'u indirir, yeniden kodlama yapmaz. */
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = fileName;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    return true;
  } catch (error) {
    alert('Export failed: ' + (error && error.message ? error.message : String(error)));
    return false;
  }
}

async function exportSelectedImageLossless() {
  const list = typeof selectedImageItems === 'function' ? selectedImageItems() : [];
  if (list.length !== 1) {
    alert('Select a single photo to export.');
    return false;
  }
  const it = list[0];
  if (!it || !it.imageId) {
    alert('The selected item is not a photo.');
    return false;
  }
  let rec = null;
  try { rec = await idbGet('images', it.imageId); } catch { rec = null; }
  if (!rec || !rec.blob) {
    alert('Photo source not found.');
    return false;
  }
  /* Kullanıcı tuvali yeniden adlandırdıysa görünen ad önceliklidir. */
  const nameSource = String(it.title || it.name || rec.name || 'fotograf');

  if (imageItemNeedsComposite(it)) {
    await ensureImageCached(it.imageId).catch(() => null);
    const canvas = renderImageItemForExport(it);
    if (canvas) {
      const blob = await new Promise(res => canvas.toBlob(res, 'image/png'));
      canvas.width = 0;
      canvas.height = 0;
      if (!blob) { alert('PNG could not be created.'); return false; }
      const baseName = nameSource.replace(/\.[a-z0-9]+$/i, '') || 'fotograf';
      return writeImageExport(blob, baseName + '.png');
    }
    /* Düzleştirme başarısız olduysa kaynak baytlara düş. */
  }

  return writeImageExport(rec.blob, nameSource);
}

