if (typeof window !== 'undefined') {
  window.NativeBrushLibrary = NativeBrushLibrary;
  window.NativeBrushCategories = NativeBrushCategories;
}

function inkNativeBrushDefaults() {
  return NativeBrushLibrary.map(brush => {
    const copy = Object.assign({}, brush);
    copy.tipOptions = Object.assign({}, brush.tipOptions || {});
    copy.dynamics = Object.assign({}, brush.dynamics || {});
    return copy;
  });
}

/* =========================================================
   önizleme · S eğrisi
   ========================================================= */
/**
 * Fırça kartlarında kullanılan S eğrisi önizlemesi. Motorun gerçek
 * damla üretimini kullanır; böylece uç, akış ve basınç karakteri
 * kartta da görünür.
 */
/** Kart önizlemesinde kullanılacak mürekkep rengi: tema metin rengi.
    Sabit krem renk, açık temalarda krem kart üzerinde görünmez kalıyordu. */
function inkPreviewInkColor() {
  try {
    const value = getComputedStyle(document.documentElement)
      .getPropertyValue('--text').trim();
    if (value) return value;
  } catch { /* sessiz */ }
  return '#ece6da';
}

/* Tek kaynak anahtar üretici: bake önbelleği, disk katmanı ve
   asenkron boya yardımcısı AYNI anahtarı kullanmak zorunda. */
function inkPreviewBakeKey(target, cssW, cssH, options = {}) {
  const dpr = Math.min(2, Number(options.dpr) || window.devicePixelRatio || 1);
  const pxW = Math.max(1, Math.round(cssW * dpr));
  const pxH = Math.max(1, Math.round(cssH * dpr));
  let sig = '';
  try {
    const raw = JSON.stringify(target);
    let h = 0;
    for (let i = 0; i < raw.length; i += 1) h = (h * 31 + raw.charCodeAt(i)) & 0x7fffffff;
    sig = h;
  } catch { sig = 0; }
  const color = options.color || inkPreviewInkColor();
  return { key: target.id + '|' + pxW + 'x' + pxH + '|' + sig + '|' + color, pxW, pxH, dpr, color, sig };
}

function renderStrokePreview(canvas, brush, options = {}) {
  if (!canvas || !canvas.getContext) return;
  let target = brush || null;
  try {
    if (!target && typeof inkGetBrush === 'function') {
      target = inkGetBrush(inkState().brushId);
    }
  } catch { /* durum henüz hazır değilse sessiz */ }
  if (!target) return;

  const dpr = Math.min(2, Number(options.dpr) || window.devicePixelRatio || 1);
  const cssW = Math.max(1, Number(options.width) || canvas.clientWidth || 280);
  const cssH = Math.max(1, Number(options.height) || canvas.clientHeight || 72);
  const pxW = Math.max(1, Math.round(cssW * dpr));
  const pxH = Math.max(1, Math.round(cssH * dpr));
  if (canvas.width !== pxW) canvas.width = pxW;
  if (canvas.height !== pxH) canvas.height = pxH;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cssW, cssH);

  /* DÜZELTME (profiler bulgusu): kategori kartları her yeniden kurulumda
     54-noktalık S eğrisini damban damga boyuyordu; 40 kartlık listede
     ~50-60 ms. Fırça imzası değişmediyse biten bitmapi önbellekten
     basar; imza değişirse yeniden boyar. */
  const info = inkPreviewBakeKey(target, cssW, cssH, options);
  const previewColor = info.color;
  const cacheKey = info.key;
  const hit = inkPreviewBakeCache.get(cacheKey);
  if (hit && hit.width === info.pxW && hit.height === info.pxH) {
    ctx.drawImage(hit, 0, 0, cssW, cssH);
    return;
  }
  /* tanı: kaç resim diske rağmen yeniden boyandı (regen) — sondada okunur */
  try {
    window.__previewRegen = (window.__previewRegen || 0) + 1;
    window.__previewRegenFrom = window.__previewRegenFrom || [];
    if (window.__previewRegenFrom.length < 40) {
      window.__previewRegenFrom.push(
        new Error('regen').stack.split('\n').filter(Boolean).slice(1, 4).join(' « '));
    }
  } catch { /* sessiz */ }

  const inset = Math.max(7, cssW * 0.085);
  const amp = Math.max(3, cssH * 0.26);
  const points = [];
  const count = 54;
  for (let i = 0; i <= count; i++) {
    const t = i / count;
    const angle = t * Math.PI * 2;
    points.push({
      x: inset + t * (cssW - inset * 2),
      // S profili: kartın solundan sağına uzanan tek nefeslik eğri.
      y: cssH * 0.5 + Math.sin(angle) * amp,
      p: 0.2 + 0.8 * Math.pow(Math.max(0, Math.sin(Math.PI * t)), 0.62),
      s: t,
    });
  }

  const brushSize = Number.isFinite(target.size) ? target.size : 24;
  const previewSize = clamp(
    Number(options.sizePx) || (2 + brushSize * 0.2),
    2,
    cssH * 0.5
  );
  const opacity = clamp(
    Number(options.opacity) ||
      Math.max(0.45, Number.isFinite(target.opacity) ? target.opacity : 1),
    0.08, 1
  );
  // Çok düşük akışlı fırçalar (ıslak üstü ıslak gibi) kart önizlemesinde
  // neredeyse görünmez kalıyordu. Önizleme akışına taban koyuyoruz; bu
  // yalnızca karttaki S eğrisini etkiler, fırçanın kendi ayarını değiştirmez.
  const previewFlow = Math.max(0.22, Number.isFinite(target.flow) ? target.flow : 1);
  const preview = {
    id: 'preview:' + target.id,
    kind: 'stroke',
    tool: 'brush',
    color: previewColor,
    size: 1,
    opacity,
    hardness: Number.isFinite(target.hardness) ? target.hardness : 0.8,
    spacing: Number.isFinite(target.spacing) ? target.spacing : 0.08,
    speedSize: Number.isFinite(target.speedSize) ? target.speedSize : 0,
    flow: previewFlow,
    flowJitter: Number.isFinite(target.flowJitter) ? target.flowJitter : 0,
    taperStart: Number.isFinite(target.taperStart) ? target.taperStart : 0,
    taperEnd: Number.isFinite(target.taperEnd) ? target.taperEnd : 0,
    brushId: target.id,
    scatter: Number.isFinite(target.scatter) ? target.scatter : 0,
    points,
  };
  if (typeof inkDrawStrokeOnContext === 'function') {
    // Yol tabanlı fırçalar ctx.strokeStyle'ı kullanır; kart önizlemesinde
    // tema metin rengini açıkça uygula (varsayılan beyaz kalmasın).
    ctx.strokeStyle = preview.color;
    ctx.fillStyle = preview.color;
    inkDrawStrokeOnContext(ctx, preview, {
      mapPoint: p => ({ x: p.x, y: p.y }),
      sizePx: previewSize,
      brush: target,
    });
  }
  /* Önbelleğe yaz: sonraki kurulumlar drawImage ile basar. */
  try {
    const copy = document.createElement('canvas');
    copy.width = pxW;
    copy.height = pxH;
    copy.getContext('2d').drawImage(canvas, 0, 0);
    inkPreviewBakeCache.set(cacheKey, copy);
    const LIMIT = 320;
    if (inkPreviewBakeCache.size > LIMIT) {
      inkPreviewBakeCache.delete(inkPreviewBakeCache.keys().next().value);
    }
    /* Aynı bitmapi diske kalıcı yaz: sonraki açılışlar yeniden
       boyamadan okur (bkz. aşağıdaki disk katmanı). LAG DÜZELTMESI:
       geçici önizlemeler (disk:false — oluşturucu canlı önizlemesi
       gibi) her ara durumda diske yazılıp IndexedDB'yi dolduruyordu. */
    if (options.disk !== false) inkPreviewDiskQueueWrite(cacheKey, copy);
  } catch { /* önbellek yazılamazsa sessiz */ }
}

/* =========================================================
   AÇILIŞ hızlandırma: boş-zaman kuyruğu
   ---------------------------------------------------------
   Kart önizlemede bake-cache olmasına rağmen ilk açılışta
   önbellek boştur; her kart ~30-50 ms senkron boyama açılışı
   bloklar (startup-probe: presets=1.35 s + kütüphane=0.47 s).
   UI-DOM'u hemen kurarız; kanva boyamalarını boş zamana
   erteleriz. Kullanıcı araya girerse (kütüphane açarsa) o
   güncelleme zaten senkron yeniden kurar; boyamalar UI'ı hiçbir
   zaman engellemez.
   ========================================================= */
const inkNativeIdleQueue = [];
let inkNativeIdleScheduled = false;

function inkNativeIdleDrain(deadline) {
  while (inkNativeIdleQueue.length && (!deadline || deadline.timeRemaining() > 12)) {
    const fn = inkNativeIdleQueue.shift();
    try { fn(); } catch { /* tek iş başarısızsa kuyruğun geri kalanı koşar */ }
  }
  if (inkNativeIdleQueue.length) inkNativeIdleSchedule();
  else inkNativeIdleScheduled = false;
}

function inkNativeIdleSchedule() {
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(inkNativeIdleDrain, { timeout: 1000 });
  } else {
    setTimeout(() => inkNativeIdleDrain(null), 40);
  }
}

function inkNativeWhenIdle(fn) {
  inkNativeIdleQueue.push(fn);
  if (!inkNativeIdleScheduled) {
    inkNativeIdleScheduled = true;
    inkNativeIdleSchedule();
  }
}

/** Kart önizleme bitmap önbelleği (renderStrokePreview tüketir). */
const inkPreviewBakeCache = new Map();

/* =========================================================
   DISKE KALICI ÖNİZLEME ÖNBELLEĞİ
   ---------------------------------------------------------
   Bake önbelleği RAM'dedir; her açılışta boş başlar ve 40
   fırçanın kartı yeniden boyanır (boş-zamanda, ama zayıf
   makinelerde yine de harcanan iştir). Windows Gezgini'nin
   thumbcache'i ve tarayıcıların favicon depoları gibi: bir
   kez üret, diske yaz (IndexedDB 'meta', 'nbprev|' öneki),
   sonraki açılışlarda okuyup bellek önbelleğini doldur.

   GÜVENCE: önbellek yalnız TÜRETİLMİŞ görüntüdür, fırça
   verisinin kendisi değildir. Anahtar = fırça özellik
   özeti + piksel boyutu + tema rengi; bunlardan biri
   değişirse disk kaydı eşleşmez ve normal yoldan yeniden
   üretilir. Kayıt bozuksa/eksikse ilk açılıştaki davranış
   (yeniden boyama) hiçbir performansı garantiye almadan
   aynen devam eder.

   BAKIM: kayıt sayısı 400'ü aşarsa en eski %25 kademeyle
   temizlenir (silinen/düzenlenen fırçaların ölü kayıtları
   böylece kendi kendine düşer).
   ========================================================= */
const INK_PREVIEWS_DB_PREFIX = 'nbprev|';
const inkPreviewDiskState = {
  warmed: false, failing: false, written: null, queue: [], busy: false,
  diskBlobs: null, inflight: null, readPromise: null, deferTimer: 0,
};

/* Boya yolları disk okumayı beklerken UI'ı kısıklamak için:
   okuma bitince ya da timeout'ta çözülür (bozuk/eksik veritabanı
   durumu = normal regen yolu). */
function inkPreviewDiskReady(timeoutMs = 400) {
  const s = inkPreviewDiskState;
  if (!s.readPromise || s.warmed) return Promise.resolve(null);
  return Promise.race([
    s.readPromise,
    new Promise(res => setTimeout(res, timeoutMs)),
  ]);
}

/* Açılışta: diskteki 'nbprev|*' kayıtlarını oku, anahtarları
   bilinen/yazılmış olarak işaretle, sonra boş-zamanda teker
   teker decode edip bellek önbelleğini doldur. Decode adımlıdır
   (tick başına bir resim): bellek/enerji ani yüklenmez. */
async function inkPreviewDiskWarm() {
  const s = inkPreviewDiskState;
  if (s.warmed || s.failing) return;
  if (typeof db === 'undefined' || !db || typeof idbEntries !== 'function') { s.failing = true; return; }
  if (!s.readPromise) {
    s.readPromise = new Promise(res => { s.readResolve = res; });
  }
  let entries;
  try {
    entries = await idbEntries('meta');
  } catch {
    s.failing = true;
    try { if (s.readResolve) s.readResolve(null); } catch { /* sessiz */ }
    return;
  }
  let hits = entries.filter(([k, v]) =>
    typeof k === 'string' && k.startsWith(INK_PREVIEWS_DB_PREFIX) &&
    v && (v.png instanceof Blob));
  /* bakım: çöp birikimini sınırla (silinen fırçaların kayıtları) */
  try {
    if (hits.length > 400) {
      const taktir = hits
        .map(h => h)
        .sort((a, b) => (a[1].ts || 0) - (b[1].ts || 0))
        .slice(0, Math.ceil(hits.length * 0.25));
      for (const [k] of taktir) { try { await idbDel('meta', k); } catch { /* sessiz */ } }
      const silinen = new Set(taktir.map(([k]) => k));
      hits = hits.filter(([k]) => !silinen.has(k));
    }
  } catch { /* bakım başarısızsa sessiz */ }
  /* DB anahtarları 'nbprev|' ÖNEKLİ; bellek önbelleği ve boya yolları
     HAM cacheKey kullanır → öneki burada sıyır. */
  const ham = k => k.slice(INK_PREVIEWS_DB_PREFIX.length);
  s.written = new Set(hits.map(([k]) => ham(k)));
  /* boya yollarının birebir bekleyip decode edebileceği blob haritası */
  s.diskBlobs = new Map(hits.map(([k, v]) => [ham(k), v.png]));
  s.warmed = true;
  try {
    if (window.__bootMark) {
      window.__bootMark('preview-disk:' + hits.length + ' record');
    }
  } catch { /* sessiz */ }
  try { if (s.readResolve) s.readResolve(null); } catch { /* sessiz */ }

  /* Decode sırası önemli: şerit resimleri (72×38) açılışın kritik
     yolu — önce onlar, tek idare. Büyük kartlar sonra, boş zamanla.
     Anahtarın 2. parçası 'PxWxPxH'; ondan şerit tanınır. */
  const kayitBoyutu = key => {
    const m = /^(\d+)x(\d+)$/.exec((key.split('|')[1] || ''));
    return m ? { w: +m[1], h: +m[2] } : { w: 0, h: 0 };
  };
  const minik = [], buyuk = [];
  for (const kayit of hits) {
    const d = kayitBoyutu(ham(kayit[0]));
    (d.w > 0 && d.w <= 160 && d.h <= 80 ? minik : buyuk).push(kayit);
  }
  const sirada = minik.concat(buyuk);
  let idx = 0;
  const decodeBurst = deadline => {
    while (idx < sirada.length && (!deadline || deadline.timeRemaining() > 10)) {
      const [dbKey, val] = sirada[idx++];
      inkPreviewDiskDecodeOne(ham(dbKey), val);
    }
    if (idx < sirada.length) {
      if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(decodeBurst, { timeout: 1500 });
      } else {
        setTimeout(() => decodeBurst(null), 20);
      }
    }
  };
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(decodeBurst, { timeout: 500 });
  } else {
    setTimeout(() => decodeBurst(null), 40);
  }
}

/* Tek kaydı dekode edip bellek önbelleğine koy. Kayıt bozuksa
   düşürülür; sonsuz retry olmadan normal yoldan yeniden üretilir. */
function inkPreviewDiskDecodeOne(key, val) {
  let bmp = null;
  try { bmp = createImageBitmap(val.png); } catch { bmp = null; }
  const yerlestir = bitmap => {
    if (bitmap && bitmap.width > 0 && inkPreviewBakeCache.size <= 260) {
      inkPreviewBakeCache.set(key, bitmap);
    } else if (bitmap) {
      bitmap.close ? bitmap.close() : null;
    }
  };
  if (bmp && typeof bmp.then === 'function') {
    bmp.then(yerlestir).catch(() => {
      try { idbDel('meta', INK_PREVIEWS_DB_PREFIX + key); } catch { /* sessiz */ }
      if (inkPreviewDiskState.written) inkPreviewDiskState.written.delete(key);
    });
  } else {
    yerlestir(null); /* senkron desteklenmiyorsa sessizce geç */
  }
}

/* "decode-inflight": aynı anahtara denk gelen birden fazla boya
   isteği tek decode paylaşır. */
function inkPreviewDecodeStored(key) {
  const s = inkPreviewDiskState;
  if (!s.inflight) s.inflight = new Map();
  if (s.inflight.has(key)) return s.inflight.get(key);
  const blob = s.diskBlobs && s.diskBlobs.get(key);
  if (!blob) return Promise.resolve(null);
  const konus = createImageBitmap(blob).then(bmp => {
    if (!bmp || !(bmp.width > 0)) return null;
    if (inkPreviewBakeCache.size <= 300) inkPreviewBakeCache.set(key, bmp);
    return bmp;
  }).catch(() => {
    try { idbDel('meta', INK_PREVIEWS_DB_PREFIX + key); } catch { /* sessiz */ }
    if (s.written) s.written.delete(key);
    return null;
  });
  s.inflight.set(key, konus);
  konus.finally(() => { try { s.inflight.delete(key); } catch { /* sessiz */ } });
  return konus;
}

/* Asenkron boya yolu: bellek önbelleğine bakar → yoksa diski bekler
   (kısa timeout) → decode edip basar → o da yoksa normal regen yolu.
   UI'ı hiçbir yerde engellemez; boya işi tabii idle'tadır. */
function inkPaintPreviewAsync(canvas, brush, options = {}) {
  const fallback = () => renderStrokePreview(canvas, brush, options);
  if (!canvas || !canvas.getContext || !brush) return fallback();
  const dpr = Math.min(2, Number(options.dpr) || window.devicePixelRatio || 1);
  const cssW = Math.max(1, Number(options.width) || canvas.clientWidth || 280);
  const cssH = Math.max(1, Number(options.height) || canvas.clientHeight || 72);
  const info = inkPreviewBakeKey(brush, cssW, cssH, options);
  const hit = inkPreviewBakeCache.get(info.key);
  if (hit && hit.width === info.pxW && hit.height === info.pxH) {
    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, cssW, cssH);
      ctx.drawImage(hit, 0, 0, cssW, cssH);
      return;
    }
  }
  return inkPreviewDiskReady(300).then(() => {
    if (!canvas.isConnected) return null;
    return inkPreviewDecodeStored(info.key);
  }).then(bmp => {
    if (!canvas.isConnected) return null;
    if (bmp && bmp.width === info.pxW && bmp.height === info.pxH) {
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, cssW, cssH);
        ctx.drawImage(bmp, 0, 0, cssW, cssH);
        return bmp;
      }
    }
    return fallback();
  }).catch(() => { try { if (canvas.isConnected) fallback(); } catch { /* sessiz */ } });
}

/* renderStrokePreview bake'i disk yazım kuyruğuna alır; aynı
   anahtar bir kez yazılır (zaten dispte olan pas geçilir). */
function inkPreviewDiskQueueWrite(cacheKey, canvas) {
  const s = inkPreviewDiskState;
  if (s.failing) return;
  if (s.written && s.written.has(cacheKey)) return; // dispte var, dokunma
  if (s.queue.some(w => w.key === cacheKey)) return;
  s.queue.push({ key: cacheKey, canvas });
  inkPreviewDiskFlush();
}

/* DÜZELTME (profiler bulgusu): toBlob PNG kodlaması ana iş teknikte
   senkron sayılır — sıcak vuruş akışında 94 çağrı / 274 ms örneklendi
   (probe E bölümü). Düzeltmeler: canlı vuruş aktifken hiç kodlama
   yapılmaz; kalem araları boş-zamana (requestIdleCallback) dilimlenir
   ve döngü başına 8 blob bütçe uygulanır — kalan bir sonraki boş çevrede. */
async function inkPreviewDiskFlush() {
  const s = inkPreviewDiskState;
  if (s.busy || s.failing) return;
  if (typeof db === 'undefined' || !db) return; // veritabanı açılmadan yazılmaz
  const cUi = (typeof inkEditorUi !== 'undefined' && inkEditorUi) ? inkEditorUi : null;
  if (cUi && cUi.stroke) {
    /* Canlı vuruş varken PNG kodlama ertelenir; bırakınca boş çevrede. */
    if (!s.deferTimer) {
      s.deferTimer = setTimeout(() => { s.deferTimer = 0; inkPreviewDiskFlush(); }, 300);
    }
    return;
  }
  s.busy = true;
  const idleStep = () => new Promise(resolve => {
    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(resolve, { timeout: 120 });
    } else {
      setTimeout(resolve, 12);
    }
  });
  try {
    let budget = 8;
    while (s.queue.length && budget > 0) {
      const item = s.queue.shift();
      if (s.written && s.written.has(item.key)) continue; // warm arada diski okudu, gereksiz
      if (!(item.canvas && item.canvas.width > 0)) continue;
      /* Kodlamayı boş-zamana bırak: vuruş rasterı önceliği kalsın. */
      await idleStep();
      let blob = null;
      try {
        blob = await new Promise(res => {
          try { item.canvas.toBlob(b => res(b), 'image/png'); }
          catch { res(null); }
        });
      } catch { blob = null; }
      if (!blob) continue;
      try { await idbPut('meta', INK_PREVIEWS_DB_PREFIX + item.key, { png: blob, ts: Date.now() }); }
      catch { s.failing = true; break; }
      if (s.written) s.written.add(item.key);
      budget -= 1;
    }
  } finally {
    s.busy = false;
  }
  /* Bütçe bitti, kuyruk kalan: bir sonraki boş çevreye planla. */
  if (s.queue.length && !s.failing && !s.deferTimer) {
    s.deferTimer = setTimeout(() => { s.deferTimer = 0; inkPreviewDiskFlush(); }, 200);
  }
}

/* DÜZELTME (profiler bulgusu): fırça geçişinde soğuk kategori 40-60 kartın
   önizlemesini ~1.5-3 ms/kart boyuyordu → geçiş ~100 ms boğuluyordu.
   Prewarm: boşta (requestIdleCallback) kart boyutlarında boş kanvalara
   aynı seçeneklerle önizleme boyar; inkPreviewBakeCache dolunca gerçek
   kart kurulumu drawImage ile basar. ~150-250 ms iş arka planda
   dilimlere bölünür; ilk gerçek geçiş sonrası geçişler anlık olur. */
const inkNativePrewarmState = { queue: null, throttle: 0 };

async function inkNativePrewarmStep(deadline) {
  const state = inkNativePrewarmState;
  if (!state.queue) return;
  while (state.queue.length && (!deadline || deadline.timeRemaining() > 8)) {
    const brush = state.queue.pop();
    try {
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const compactOps = {
        width: 150, height: 46,
        sizePx: Math.max(2, Math.min(16, (brush.size || 8) * 0.22 + 2)),
      };
      const largeOps = {
        width: 620, height: 78,
        sizePx: Math.max(3, Math.min(24, (brush.size || 8) * 0.32 + 2)),
      };
      /* büyük kart + kompakt kart: kart kurulsumları birebir aynı
         seçenekler olmalı ki önbellek anahtarı vursun (pxW×pxH dahil). */
      const sizler = [
        dpr === 1 ? compactOps : { ...compactOps, dpr },
        dpr === 1 ? largeOps : { ...largeOps, dpr },
        dpr === 1 ? { width: 72, height: 38 } : { width: 72, height: 38, dpr },
      ];
      for (const ops of sizler) {
        const info = inkPreviewBakeKey(brush, ops.width, ops.height, ops);
        const hit = inkPreviewBakeCache.get(info.key);
        if (hit && hit.width === info.pxW && hit.height === info.pxH) continue;
        /* DISK KATMANI AWARE: kayıt diskte varsa decode et — yeniden
           boyamak yerine ucuza ısıt. Kayıt hiç yoksa üret. */
        try { await inkPreviewDiskReady(300); } catch { /* sessiz */ }
        const bmp = await inkPreviewDecodeStored(info.key);
        if (bmp) continue;
        const off = document.createElement('canvas'); // çöp: yalnız önbelleği ısıtır
        renderStrokePreview(off, brush, ops);
      }
    } catch { /* tek fırça başarısızsa kuyruktan çıkar */ }
  }
  if (state.queue.length) {
    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(inkNativePrewarmStep, { timeout: 1200 });
    } else {
      setTimeout(() => inkNativePrewarmStep(null), 40);
    }
  }
}

function inkNativePrewarmStrokePreviews() {
  const now = performance.now();
  if (now - inkNativePrewarmState.throttle < 2500) return; // önceden sırada/ısıtılmış
  inkNativePrewarmState.throttle = now;
  const brushes = (typeof inkState === 'function' ? (inkState().brushes || []) : [])
    .filter(b => b && !/eraser|silgi/i.test(b.id || ''));
  if (!brushes.length) return;
  inkNativePrewarmState.queue = brushes.slice();
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(inkNativePrewarmStep, { timeout: 1200 });
  } else {
    setTimeout(() => inkNativePrewarmStep(null), 60);
  }
}

/* =========================================================
   motor entegrasyonu
   ========================================================= */
function setActiveBrush(brushId, options = {}) {
  if (typeof inkState !== 'function') return null;
  /* Vuruş koruması: canlı vuruşta fırça yuvasına gelen dokunuş vuruşu
     iptal edip fırçayı değiştiriyordu (inkSetTool → inkCancelStroke).
     Kalemle çizerken avuç kütüphaneye değerse vuruş ayakta kalır. */
  if (typeof inkPointer !== 'undefined' && (inkPointer || inkTransform)) return null;
  const ink = inkState();
  let brush = ink.brushes.find(b => b.id === brushId) || null;
  if (!brush && typeof inkGetBrush === 'function') brush = inkGetBrush(brushId);
  if (!brush) return null;

  const tool = options.tool || (brush.tool === 'pencil' ? 'pencil' : 'brush');
  if (typeof inkSetTool === 'function') {
    /* deferUi: defaults uygulanıp sıralar oturduktan sonra setActiveBrush
       TEK bir inkSyncUI çağırır (çifte senkron kaldırıldı). */
    inkSetTool(tool, { brushId: brush.id, deferUi: true });
  } else {
    ink.tool = tool;
    ink.brushId = brush.id;
  }
  ink.brushId = brush.id;

  if (options.applyDefaults !== false) {
    const defaults = {
      size: brush.size,
      opacity: brush.opacity,
      hardness: brush.hardness,
      spacing: brush.spacing,
      /* Kullanıcı tercihi: fırça seçimi yumuşatmayı her zaman %5'e
         getirir. Önceki davranış kütüphane ön ayarındaki değeri
         (%50-58) basıyordu; yüksek yumuşatma çizgiyi gecikmeli
         takip ettirdiği için el hissi yorucuydu. Smoothing, One-Euro
         gecikme parametresidir: 0.05 = anlık takip. */
      smoothing: 0.05,
      pressureCurve: brush.pressureCurve,
      speedSize: brush.speedSize,
      flow: brush.flow,
      flowJitter: brush.flowJitter,
      scatter: brush.scatter,
      taperStart: brush.taperStart,
      taperEnd: brush.taperEnd,
    };
    for (const key of Object.keys(defaults)) {
      const value = defaults[key];
      if (Number.isFinite(value)) ink[key] = value;
    }
  }

  if (typeof inkPreviewBrush === 'function') inkPreviewBrush();
  if (typeof inkSyncUI === 'function') inkSyncUI();
  if (typeof dpSyncToolbar === 'function') dpSyncToolbar();
  if (typeof inkRadialTouch === 'function') inkRadialTouch(brush.id);
  if (typeof scheduleSave === 'function') scheduleSave();
  // Arka planda kart önizlemlerini ısıt: sonraki geçişler anlık olsun.
  if (typeof inkNativePrewarmStrokePreviews === 'function') {
    try { inkNativePrewarmStrokePreviews(); } catch { /* sessiz */ }
  }
  return brush;
}

/* =========================================================
   arayüz · iki sütunlu kütüphane + hızlı fırça şeridi
   ========================================================= */
const inkNativeBrushUi = {
  bound: false,
  activeCategory: 'sketch',
  creatorOnly: false,
  creatorBaseId: '',
  lastFocus: null,
  contextMenu: null,
  dragCategory: '',
  els: {},
  testStrokes: [],
  testRedoStrokes: [],
  testActiveStroke: null,
  testStrokeSeq: 0,
  testResizeObserver: null,
  /* Canlı vuruşun TAM ağırlıklı birikim tamponu (opaklık hariç). */
  testWeights: null,
  testWeightsValid: false,
  uploadedTip: null,
};

async function inkNativeBrushTipFromPng(file) {
  if (!file || (file.type !== 'image/png' && !/\.png$/i.test(file.name || ''))) {
    throw new Error('Only PNG images are supported.');
  }
  if (file.size > 20 * 1024 * 1024) {
    throw new Error('PNG file cannot exceed the 20 MB limit.');
  }
  if (typeof createImageBitmap !== 'function') {
    throw new Error('This environment cannot open this PNG image.');
  }

  const image = await createImageBitmap(file);
  try {
    if (!image.width || !image.height) throw new Error('PNG image is empty.');
    const scale = Math.min(1, 1024 / Math.max(image.width, image.height));
    const width = Math.max(1, Math.round(image.width * scale));
    const height = Math.max(1, Math.round(image.height * scale));
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error('PNG image could not be processed.');
    ctx.drawImage(image, 0, 0, width, height);
    const pixels = ctx.getImageData(0, 0, width, height);
    const data = pixels.data;
    let hasTransparency = false;
    for (let i = 3; i < data.length; i += 4) {
      if (data[i] < 250) {
        hasTransparency = true;
        break;
      }
    }

    let edgeLuminance = 0;
    let edgeCount = 0;
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (x !== 0 && y !== 0 && x !== width - 1 && y !== height - 1) continue;
        const i = (y * width + x) * 4;
        edgeLuminance += data[i] * 0.2126 + data[i + 1] * 0.7152 + data[i + 2] * 0.0722;
        edgeCount++;
      }
    }
    const invertLuminance = !hasTransparency && edgeLuminance / edgeCount >= 127.5;
    for (let i = 0; i < data.length; i += 4) {
      const luminance = data[i] * 0.2126 + data[i + 1] * 0.7152 + data[i + 2] * 0.0722;
      const alpha = hasTransparency
        ? data[i + 3]
        : (invertLuminance ? 255 - luminance : luminance);
      data[i] = data[i + 1] = data[i + 2] = 255;
      data[i + 3] = Math.round(alpha);
    }
    ctx.putImageData(pixels, 0, 0);

    const tipId = 'tip_' + newId();
    inkRuntime.importedTips.set(tipId, canvas.toDataURL('image/png'));
    return {
      tipId,
      width,
      height,
      name: String(file.name || 'PNG brush tip').replace(/\.png$/i, '').slice(0, 40),
    };
  } finally {
    image.close();
  }
}

function inkNativeCustomBrushFromForm() {
  const field = id => document.getElementById('nativeBrushCustom' + id);
  const value = (id, fallback = 0) => {
    const raw = Number(field(id)?.value);
    return Number.isFinite(raw) ? raw : fallback;
  };
  const scatterX = value('ScatterX') / 100;
  const scatterY = value('ScatterY') / 100;
  const textureId = field('Texture')?.value || 'none';
  const dualBrushId = field('DualBrush')?.value || '';
  const dualScale = value('DualScale', 100) / 100;
  const categoryId = document.getElementById('nativeBrushCustomCategory')?.value || 'custom';
  const category = inkNativeCategoryById(categoryId);
  const categoryVisible = category && !category.virtual &&
    !(inkState().deletedCategories || []).includes(categoryId);
  return inkNormalizeBrush({
    id: 'custom-brush-' + newId(),
    name: (document.getElementById('nativeBrushCustomName')?.value || '').trim(),
    kind: inkNativeBrushUi.uploadedTip ? 'abr' : 'procedural',
    tip: document.getElementById('nativeBrushCustomTip')?.value || 'circle',
    tipId: inkNativeBrushUi.uploadedTip ? inkNativeBrushUi.uploadedTip.tipId : '',
    width: inkNativeBrushUi.uploadedTip ? inkNativeBrushUi.uploadedTip.width : undefined,
    height: inkNativeBrushUi.uploadedTip ? inkNativeBrushUi.uploadedTip.height : undefined,
    tipOptions: {},
    category: categoryVisible ? categoryId : 'custom',
    badge: categoryVisible && categoryId !== 'custom' ? category.name : 'Custom',
    description: inkNativeBrushUi.uploadedTip
      ? 'Custom brush tip created from a PNG image'
      : 'Custom brush created by the user',
    size: value('Size', 24),
    opacity: value('Opacity', 100) / 100,
    hardness: value('Hardness', 80) / 100,
    angle: value('Angle') * Math.PI / 180,
    roundness: value('Roundness', 100) / 100,
    spacing: value('Spacing', 8) / 100,
    flow: value('Flow', 100) / 100,
    flowJitter: value('FlowJitter') / 100,
    scatter: 0,
    scatterX,
    scatterY,
    scatterCount: value('Count', 1),
    scatterCountJitter: value('CountJitter') / 100,
    smoothing: value('Smoothing', 45) / 100,
    taperStart: value('TaperStart') / 100,
    taperEnd: value('TaperEnd') / 100,
    tipVariants: Math.round(clamp(value('TipVariants', 1), 1, 8)),
    tipSeed: Math.round(value('TipSeed', 0)),
    stampFlipX: value('FlipX', 0) / 100,
    stampFlipY: value('FlipY', 0) / 100,
    tipRotation: value('TipRotation', 0) / 100,
    texture: textureId !== 'none',
    textureId,
    textureDepth: value('TextureDepth', 26) / 100,
    textureScale: value('TextureScale', 100) / 100,
    textureBrightness: value('TextureBrightness') / 100,
    textureContrast: value('TextureContrast', 100) / 100,
    textureEachTip: !!field('TextureEachTip')?.checked,
    noise: value('Noise') / 100,
    wetEdges: value('WetEdges') / 100,
    airbrush: !!field('Airbrush')?.checked,
    dual: dualBrushId ? {
      brushId: dualBrushId,
      diameter: Math.max(1, value('Size', 24) * dualScale),
      scale: dualScale,
      spacing: value('DualSpacing', 100) / 100,
      scatter: value('DualScatter') / 100,
      blend: field('DualBlend')?.value || 'source-over',
      hardness: 0.6,
      roundness: 1,
      angle: 0,
      flow: 0.72,
    } : null,
    colorDynamics: {
      background: field('Background')?.value || '#ffffff',
      foregroundBackground: value('ColorMix') / 100,
      hueJitter: value('HueJitter') / 100,
      saturationJitter: value('SaturationJitter') / 100,
      brightnessJitter: value('BrightnessJitter') / 100,
      purity: value('Purity') / 100,
    },
    dynamics: {
      sizeMin: value('SizeMin') / 100,
      sizeMax: value('SizeMax', 100) / 100,
      src: field('SizeSource')?.value || 'pressure',
      sizeJitter: value('SizeJitter') / 100,
      angleJitter: value('AngleJitter') / 100,
      roundnessMin: value('RoundnessMin', 100) / 100,
      roundnessJitter: value('RoundnessJitter') / 100,
      scatterJitter: value('ScatterJitter') / 100,
      spacingJitter: value('SpacingJitter') / 100,
      opacityMin: value('OpacityMin') / 100,
      opacityJitter: value('OpacityJitter') / 100,
      opacitySrc: field('OpacitySource')?.value || 'pressure',
    },
  });
}

/* Seçilen fırçanın ayarlarını oluşturucu formuna taşır. Yalnızca form
   alanları doldurulur; kaynak fırça nesnesi asla değiştirilmez. Böylece
   hazır fırçalar "base" olarak kullanılıp üzerine yeni bir özel fırça
   oluşturulabilir. */
function inkNativeLoadBrushIntoCreator(brush) {
  if (!brush || typeof brush !== 'object') return false;
  const field = id => document.getElementById('nativeBrushCustom' + id);
  const num = (value, fallback) => Number.isFinite(Number(value))
    ? Number(value) : fallback;
  const setRange = (id, value, fallback) => {
    const el = field(id);
    if (!el) return;
    el.value = String(Math.round(num(value, fallback)));
  };
  const setSelect = (id, value, fallback) => {
    const el = field(id);
    if (!el) return;
    const next = value == null ? '' : String(value);
    el.value = Array.from(el.options || []).some(option => option.value === next)
      ? next : (fallback == null ? '' : String(fallback));
  };
  const setCheck = (id, value) => {
    const el = field(id);
    if (el) el.checked = !!value;
  };

  const dyn = brush.dynamics || {};
  const color = brush.colorDynamics || {};
  const dual = brush.dual || null;
  const name = document.getElementById('nativeBrushCustomName');
  if (name) name.value = (brush.name || 'Brush') + ' Copy';

  inkNativeSyncCreatorCategoryOptions(brush.category);
  const categorySelect = document.getElementById('nativeBrushCustomCategory');
  if (categorySelect && brush.category &&
      Array.from(categorySelect.options || []).some(option => option.value === brush.category)) {
    categorySelect.value = brush.category;
  }

  setSelect('Tip', brush.tip || 'circle', 'circle');
  setRange('Size', num(brush.size, 24), 24);
  setRange('Hardness', num(brush.hardness, 0.6) * 100, 60);
  setRange('Angle', num(brush.angle, 0) * 180 / Math.PI, 0);
  setRange('Roundness', num(brush.roundness, 1) * 100, 100);
  setRange('Spacing', num(brush.spacing, 0.1) * 100, 10);
  setRange('SpacingJitter', num(dyn.spacingJitter, 0) * 100, 0);
  setRange('Opacity', num(brush.opacity, 1) * 100, 100);
  setRange('Flow', num(brush.flow, 1) * 100, 100);
  setRange('FlowJitter', num(brush.flowJitter, 0) * 100, 0);
  setRange('TipVariants', num(brush.tipVariants, 1), 1);
  setRange('TipSeed', num(brush.tipSeed, 0), 0);
  setRange('FlipX', num(brush.stampFlipX, 0) * 100, 0);
  setRange('FlipY', num(brush.stampFlipY, 0) * 100, 0);
  setRange('TipRotation', num(brush.tipRotation, 0) * 100, 0);

  setSelect('SizeSource', dyn.src || 'pressure', 'pressure');
  setRange('SizeMin', num(dyn.sizeMin, 0.18) * 100, 18);
  setRange('SizeMax', num(dyn.sizeMax, 1) * 100, 100);
  setRange('SizeJitter', num(dyn.sizeJitter, 0) * 100, 0);
  setRange('AngleJitter', num(dyn.angleJitter, 0) * 100, 0);
  setRange('RoundnessMin', num(dyn.roundnessMin, 1) * 100, 100);
  setRange('RoundnessJitter', num(dyn.roundnessJitter, 0) * 100, 0);

  setRange('ScatterX', num(brush.scatterX, 0) * 100, 0);
  setRange('ScatterY', num(brush.scatterY, 0) * 100, 0);
  setRange('ScatterJitter', num(dyn.scatterJitter, 0) * 100, 0);
  setRange('Count', num(brush.scatterCount, 1), 1);
  setRange('CountJitter', num(brush.scatterCountJitter, 0) * 100, 0);

  setSelect('Texture', brush.textureId || (brush.texture ? 'paper' : 'none'), 'none');
  setRange('TextureScale', num(brush.textureScale, 1) * 100, 100);
  setRange('TextureDepth', num(brush.textureDepth, 0.26) * 100, 26);
  setRange('TextureBrightness', num(brush.textureBrightness, 0) * 100, 0);
  setRange('TextureContrast', num(brush.textureContrast, 1) * 100, 100);
  setCheck('TextureEachTip', brush.textureEachTip);

  setSelect('DualBrush', dual && dual.brushId ? dual.brushId : '', '');
  setSelect('DualBlend', dual && dual.blend ? dual.blend : 'source-over', 'source-over');
  setRange('DualScale', num(dual && dual.scale, 1) * 100, 100);
  setRange('DualSpacing', num(dual && dual.spacing, 1) * 100, 100);
  setRange('DualScatter', num(dual && dual.scatter, 0) * 100, 0);

  const background = field('Background');
  if (background) {
    background.value = /^#[0-9a-f]{6}$/i.test(color.background || '')
      ? color.background : '#ffffff';
  }
  setRange('ColorMix', num(color.foregroundBackground, 0) * 100, 0);
  setRange('HueJitter', num(color.hueJitter, 0) * 100, 0);
  setRange('SaturationJitter', num(color.saturationJitter, 0) * 100, 0);
  setRange('BrightnessJitter', num(color.brightnessJitter, 0) * 100, 0);
  setRange('Purity', num(color.purity, 0) * 100, 0);

  setSelect('OpacitySource', dyn.opacitySrc || 'pressure', 'pressure');
  setRange('OpacityMin', num(dyn.opacityMin, 0.35) * 100, 35);
  setRange('OpacityJitter', num(dyn.opacityJitter, 0) * 100, 0);
  setRange('Noise', num(brush.noise, 0) * 100, 0);
  setRange('WetEdges', num(brush.wetEdges, 0) * 100, 0);
  setCheck('Airbrush', brush.airbrush);
  setRange('Smoothing', num(brush.smoothing, 0.45) * 100, 45);
  setRange('TaperStart', num(brush.taperStart, 0) * 100, 0);
  setRange('TaperEnd', num(brush.taperEnd, 0) * 100, 0);

  // İçe aktarılmış uç varsa formun PNG ucu olarak taşınır; orijinal
  // fırçanın tipId'si paylaşılır, silinmez/değiştirilmez.
  const hasTip = brush.kind === 'abr' && brush.tipId &&
    typeof inkRuntime !== 'undefined' && inkRuntime.importedTips.has(brush.tipId);
  inkNativeBrushUi.uploadedTip = hasTip ? {
    tipId: brush.tipId,
    width: brush.width || 0,
    height: brush.height || 0,
    name: (brush.name || 'Brush') + ' ucu',
  } : null;
  if (hasTip) inkLoadAbrTip(brush.tipId);
  const status = document.getElementById('nativeBrushCustomPngStatus');
  if (status) {
    status.textContent = hasTip
      ? (brush.name || 'Brush') + ' tip taken as the base. Change the name and settings before saving.'
      : 'Transparent PNG recommended; a white background is converted to a mask automatically.';
  }
  inkNativeSyncCustomCreator();
  return true;
}

/* Aynı ayarlarla ikinci bir özel fırça oluşmasını engeller. "Create"
   butonuna basılı tutulan Enter/Space ya da üst üste tıklama, listede
   görünmeyen kopyalar biriktiriyordu (206 adet "Yeni Fırça" bu yüzden).
   `id` dışındaki tüm alanlar aynıysa yeni kayıt eklenmez, mevcut seçilir. */
function inkNativeBrushSignature(brush) {
  return inkBrushSignature(brush);
}

function inkNativeFindSameCustomBrush(brushes, brush) {
  const signature = inkNativeBrushSignature(brush);
  if (!signature) return null;
  return (Array.isArray(brushes) ? brushes : []).find(item =>
    item && !inkNativeIsDefaultBrush(item) &&
    inkNativeBrushSignature(item) === signature) || null;
}

function inkNativeCreatorTestEnsureSize() {
  const { testCanvas, testLive } = inkNativeBrushUi.els;
  if (!testCanvas || !testLive) return null;
  const rect = testCanvas.getBoundingClientRect();
  const width = Math.max(0, rect.width);
  const height = Math.max(0, rect.height);
  if (!width || !height) return null;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const pixelWidth = Math.max(1, Math.round(width * dpr));
  const pixelHeight = Math.max(1, Math.round(height * dpr));
  const resized = testCanvas.width !== pixelWidth || testCanvas.height !== pixelHeight ||
    testLive.width !== pixelWidth || testLive.height !== pixelHeight;
  if (resized) {
    testCanvas.width = testLive.width = pixelWidth;
    testCanvas.height = testLive.height = pixelHeight;
    /* Boyut değişince ağırlık tamponu yeniden kurulmalı. */
    inkNativeBrushUi.testWeightsValid = false;
  }
  return { width, height, dpr, pixelWidth, pixelHeight, resized };
}

/* Vuruş CİHAZ PİKSELİ uzayında, kimlik dönüşümüyle çizilir. Çift tampon
   (dual scratch) kutusunu transform'dan bağımsız piksel hesabıyla kurar;
   DPR'li transform + CSS koordinatı birleşimi kutuyu kırpıyor, bırakınca
   vuruşun bir kısmı eksik/kaydırılmış görünüyordu (canlı ≠ final). */
function inkNativeCreatorTestDrawStroke(ctx, entry, size, extra) {
  if (!ctx || !entry || !entry.stroke || !entry.brush) return 0;
  const brush = entry.brush;
  const pw = size.pixelWidth;
  const ph = size.pixelHeight;
  const opts = Object.assign({
    mapPoint: point => ({ x: point.x * pw, y: point.y * ph }),
    /* Fırça çapı CSS px → cihaz px (önceden DPR transform'u yapıyordu). */
    sizePx: brush.size * size.dpr,
    pointScale: { x: pw, y: ph },
    brush,
  }, extra || {});
  return inkDrawStrokeOnContext(ctx, entry.stroke, opts) | 0;
}

/* Canlı katmanın ağırlık tamponu: damlalar TAM ağırlıkla (opaklık hariç)
   birikir. Canlı görüntü = tampon × stroke.opacity; commit de tek geçişte
   aynı kompoziti üretir → çizerken görünen ile bırakınca çıkan birebir. */
function inkNativeCreatorTestWeights(size) {
  let canvas = inkNativeBrushUi.testWeights;
  if (!canvas) {
    canvas = document.createElement('canvas');
    inkNativeBrushUi.testWeights = canvas;
    inkNativeBrushUi.testWeightsValid = false;
  }
  if (canvas.width !== size.pixelWidth || canvas.height !== size.pixelHeight) {
    canvas.width = size.pixelWidth;
    canvas.height = size.pixelHeight;
    inkNativeBrushUi.testWeightsValid = false;
  }
  const ctx = canvas.getContext('2d', { colorSpace: 'srgb' });
  if (!ctx) return null;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  /* Çift tampon (commit) yolu damga örneklemesini 'high' kalitede yapar;
     canlı birikim de aynı kaliteyi kullanmalı (piksel paritesi). */
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  return { canvas, ctx };
}

function inkNativeCreatorTestResetWeights(size) {
  const w = inkNativeCreatorTestWeights(size);
  if (!w) return null;
  w.ctx.globalCompositeOperation = 'source-over';
  w.ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
  inkNativeBrushUi.testWeightsValid = true;
  return w;
}

function inkNativeCreatorTestCompositeLive(entry, size) {
  const live = inkNativeBrushUi.els.testLive;
  const weights = inkNativeBrushUi.testWeights;
  if (!live || !weights || !entry) return;
  const ctx = live.getContext('2d', { colorSpace: 'srgb' });
  if (!ctx) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = clamp(
    entry.stroke.opacity === undefined ? 1 : entry.stroke.opacity, 0, 1);
  ctx.drawImage(weights, 0, 0);
  ctx.globalAlpha = 1;
}

function inkNativeCreatorTestSyncButtons() {
  const undo = inkNativeBrushUi.els.testUndo;
  if (undo) undo.disabled = !inkNativeBrushUi.testStrokes.length;
}

function inkNativeCreatorTestRender() {
  const size = inkNativeCreatorTestEnsureSize();
  if (!size) return;
  const { testCanvas, testLive } = inkNativeBrushUi.els;
  const ctx = testCanvas.getContext('2d', { colorSpace: 'srgb' });
  const liveCtx = testLive.getContext('2d', { colorSpace: 'srgb' });
  if (!ctx || !liveCtx) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
  for (const entry of inkNativeBrushUi.testStrokes) {
    inkNativeCreatorTestDrawStroke(ctx, entry, size);
  }
  liveCtx.setTransform(1, 0, 0, 1, 0, 0);
  liveCtx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
  const active = inkNativeBrushUi.testActiveStroke;
  if (active) {
    if (active.pathMode) {
      inkNativeCreatorTestDrawStroke(liveCtx, active, size);
    } else {
      /* Boyut değiştiyse tampon geçersizdir: vuruşu yeniden biriktir.
         stableOnly: sayaç sözleşmesi artımlı çizerken ile aynı kalsın
         (uçtaki 2 segment ertelenir; bırakışta tam çizim yapılır). */
      if (!inkNativeBrushUi.testWeightsValid) {
        const w = inkNativeCreatorTestResetWeights(size);
        if (w) {
          active.drawnDabs = inkNativeCreatorTestDrawStroke(w.ctx, active, size, {
            skipDabs: 0, dualDirect: true, stableOnly: true,
          });
        }
      }
      inkNativeCreatorTestCompositeLive(active, size);
    }
  }
  inkNativeCreatorTestSyncButtons();
}

function inkNativeCreatorTestAddPoint(event, force = false) {
  const entry = inkNativeBrushUi.testActiveStroke;
  const canvas = inkNativeBrushUi.els.testCanvas;
  if (!entry || !canvas) return;
  const rect = canvas.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const rawX = clamp((event.clientX - rect.left) / rect.width, 0, 1);
  const rawY = clamp((event.clientY - rect.top) / rect.height, 0, 1);
  const points = entry.stroke.points;
  const previous = points[points.length - 1];
  if (previous && !force && Math.hypot(rawX - previous.x, rawY - previous.y) < 0.001) return;
  const brush = entry.brush;
  const smoothing = clamp(brush.smoothing || 0, 0, 0.95) * 0.7;
  const x = previous ? previous.x + (rawX - previous.x) * (1 - smoothing) : rawX;
  const y = previous ? previous.y + (rawY - previous.y) * (1 - smoothing) : rawY;
  const elapsed = previous ? Math.max(1, event.timeStamp - (previous.time || event.timeStamp)) : 1;
  const distance = previous
    ? Math.hypot((x - previous.x) * rect.width, (y - previous.y) * rect.height)
    : 0;
  const rawPressure = event.pointerType === 'pen' && event.pressure > 0
    ? event.pressure : 0.65;
  const pressureCurve = Number.isFinite(brush.pressureCurve) ? brush.pressureCurve : 1;
  points.push({
    x,
    y,
    /* Profil (aday 5): test tuvali de ana çizimle aynı basınç haritasını
       izler (inkCurvePressure = fırça eğrisi × tablet profili). */
    p: inkCurvePressure(rawPressure, pressureCurve),
    s: Math.min(1, distance / (elapsed * 0.8)),
    time: event.timeStamp,
  });
}

function inkNativeCreatorTestUndo() {
  if (!inkNativeBrushUi.testStrokes.length) return false;
  inkNativeBrushUi.testRedoStrokes.push(inkNativeBrushUi.testStrokes.pop());
  inkNativeCreatorTestRender();
  inkNativeCreatorTestSyncButtons();
  return true;
}

function inkNativeCreatorTestRedo() {
  if (!inkNativeBrushUi.testRedoStrokes.length) return false;
  inkNativeBrushUi.testStrokes.push(inkNativeBrushUi.testRedoStrokes.pop());
  inkNativeCreatorTestRender();
  inkNativeCreatorTestSyncButtons();
  return true;
}

function inkNativeCreatorIsTextEntry(node) {
  if (!node) return false;
  if (node.isContentEditable) return true;
  if (node.tagName === 'TEXTAREA') return true;
  if (node.tagName === 'INPUT') {
    const type = String(node.type || 'text').toLowerCase();
    return !/^(range|checkbox|radio|button|submit|reset|color|file)$/.test(type);
  }
  return false;
}

function inkNativeCreatorTestBind() {
  const canvas = inkNativeBrushUi.els.testCanvas;
  const color = inkNativeBrushUi.els.testColor;
  const clear = inkNativeBrushUi.els.testClear;
  const undo = inkNativeBrushUi.els.testUndo;
  if (!canvas || canvas.dataset.bound === 'true') return;
  canvas.dataset.bound = 'true';
  canvas.addEventListener('pointerdown', event => {
    if (event.button !== 0 || inkNativeBrushUi.testActiveStroke) return;
    event.preventDefault();
    canvas.focus();
    /* LAG DÜZELTMESİ: kayıtlı vuruşları AKTİF vuruş yokken tazele;
       aktif vuruş canlı katmanda yaşayacak (aşağıda). */
    inkNativeCreatorTestRender();
    const brush = inkNativeCustomBrushFromForm();
    inkNativeBrushUi.testActiveStroke = {
      brush,
      drawnDabs: 0,
      stroke: {
        id: 'brush-test-' + (++inkNativeBrushUi.testStrokeSeq),
        kind: 'stroke',
        tool: 'brush',
        color: color ? color.value : '#d4a24a',
        size: 1,
        opacity: brush.opacity,
        hardness: brush.hardness,
        spacing: brush.spacing,
        speedSize: brush.speedSize,
        flow: brush.flow,
        flowJitter: brush.flowJitter,
        scatter: brush.scatter,
        taperStart: brush.taperStart,
        taperEnd: brush.taperEnd,
        brushId: brush.id,
        points: [],
      },
    };
    inkNativeCreatorTestAddPoint(event, true);
    try { canvas.setPointerCapture(event.pointerId); } catch { /* sentetik olay */ }
    /* İlk dabları TAM ağırlıkla birikim tamponuna yaz; canlı katman
       tamponun opaklıkla tek geçişli kompozitidir (commit ile aynı). */
    const startSize = inkNativeCreatorTestEnsureSize();
    if (!startSize) return;
    const weights = inkNativeCreatorTestResetWeights(startSize);
    if (!weights) return;
    const entry = inkNativeBrushUi.testActiveStroke;
    /* stableOnly: canlı çizerken uçtaki 2 segment ve bitiş incelmesi
       ertelenir (editörün referans modeli). Böylece büyüyen vuruşta
       erken damlalara yanlış taper uygulanmaz; bırakışta kuyruk aynı
       birikime eklenir → canlı kompozit = tek geçişli commit. */
    entry.drawnDabs = inkNativeCreatorTestDrawStroke(weights.ctx, entry, startSize, {
      skipDabs: 0,
      dualDirect: true,
      stableOnly: true,
    });
    inkNativeCreatorTestCompositeLive(entry, startSize);
  });
  canvas.addEventListener('pointermove', event => {
    if (!inkNativeBrushUi.testActiveStroke) return;
    event.preventDefault();
    const coalesced = typeof event.getCoalescedEvents === 'function'
      ? event.getCoalescedEvents() : [];
    const samples = coalesced.length ? coalesced : [event];
    for (const sample of samples) inkNativeCreatorTestAddPoint(sample);
    /* LAG DÜZELTMESİ: her pointermove TÜM kayıtlı vuruşları + aktif
       vuruşu sıfırdan boyuyordu (uzun vuruşta O(n²)). Kayıtlı kanvas
       canlı vuruş sırasında DEĞİŞMEZ — dokunulmaz. Canlı katmanda
       yalnız YENİ dablar çizilir (inkDrawStrokeOnContext skipDabs
       sözleşmesi, dönüş = işlenen dab sayısı). Yol-modu (sert/sabit
       basınç) fırçada skipDabs işlemez → o modda canlı temizlenip
       tam çizim yapılır; mod yükseltmesi (dab→yol) güvenlidir. */
    const size = inkNativeCreatorTestEnsureSize();
    if (!size) return;
    const liveCtx = inkNativeBrushUi.els.testLive.getContext('2d', { colorSpace: 'srgb' });
    if (!liveCtx) return;
    const entry = inkNativeBrushUi.testActiveStroke;
    liveCtx.setTransform(1, 0, 0, 1, 0, 0);
    const eligible = !entry.pathMode &&
      typeof inkStrokePathEligible === 'function' &&
      inkStrokePathEligible(entry.stroke, entry.brush, entry.brush.size * size.dpr);
    if (eligible) {
      entry.pathMode = true;
      /* Yol modu damla birikimi kullanmaz: canlı katman tam çizilir. */
      const w = inkNativeCreatorTestWeights(size);
      if (w) w.ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
      inkNativeBrushUi.testWeightsValid = false;
      liveCtx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
      inkNativeCreatorTestDrawStroke(liveCtx, entry, size);
    } else if (entry.pathMode) {
      /* Yol moduna yükselmiş vuruş dab moduna DÖNMEZ; tam çizim
         (içeride artık dab yolu kullanılsa da) eski davranış kadar
         doğrudur, bozulma olmaz. */
      liveCtx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
      inkNativeCreatorTestDrawStroke(liveCtx, entry, size);
    } else {
      const weights = inkNativeCreatorTestWeights(size);
      if (!weights) return;
      if (!inkNativeBrushUi.testWeightsValid) {
        /* Boyut değişti: birikimi sıfırdan kur. stableOnly burada da
           açık olmalı; yoksa büyümekte olan vuruşun sonuna erken taper
           uygulanır ve tampon ile commit uyuşmaz. */
        weights.ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
        inkNativeBrushUi.testWeightsValid = true;
        entry.drawnDabs = inkNativeCreatorTestDrawStroke(weights.ctx, entry, size, {
          skipDabs: 0, dualDirect: true, stableOnly: true,
        });
      } else {
        const drawn = inkNativeCreatorTestDrawStroke(weights.ctx, entry, size, {
          skipDabs: entry.drawnDabs | 0, dualDirect: true, stableOnly: true,
        });
        /* dab sayısı monoton büyür; beklenmedik düşüşte sayacı koru. */
        entry.drawnDabs = Math.max(entry.drawnDabs | 0, drawn);
      }
      inkNativeCreatorTestCompositeLive(entry, size);
    }
  });
  const finish = event => {
    const entry = inkNativeBrushUi.testActiveStroke;
    if (!entry) return;
    if (event && Number.isFinite(event.clientX)) inkNativeCreatorTestAddPoint(event, true);
    /* LAG DÜZELTMESİ: bırakışta TAM yeniden boyama yerine vuruşu
       kayıtlı kanvasa BİR kez boya (vuruş rasterı vuruş kimliğine
       göre deterministik — tam render ile birebir). Canlı temizlenir. */
    const size = inkNativeCreatorTestEnsureSize();
    if (size && entry.stroke.points.length > 1) {
      const ctx = inkNativeBrushUi.els.testCanvas.getContext('2d', { colorSpace: 'srgb' });
      if (ctx) {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        /* Tek geçişli tam çizim = canlı kompozitin aynısı (parite). */
        inkNativeCreatorTestDrawStroke(ctx, entry, size);
      }
    }
    const liveCtx = inkNativeBrushUi.els.testLive.getContext('2d', { colorSpace: 'srgb' });
    if (liveCtx && size) {
      liveCtx.setTransform(1, 0, 0, 1, 0, 0);
      liveCtx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
    }
    if (size) {
      const w = inkNativeCreatorTestWeights(size);
      if (w) {
        w.ctx.clearRect(0, 0, size.pixelWidth, size.pixelHeight);
        inkNativeBrushUi.testWeightsValid = false;
      }
    }
    if (entry.stroke.points.length > 1) {
      inkNativeBrushUi.testStrokes.push(entry);
      inkNativeBrushUi.testRedoStrokes.length = 0;
    }
    inkNativeBrushUi.testActiveStroke = null;
    try { canvas.releasePointerCapture(event.pointerId); } catch { /* capture bırakılmış olabilir */ }
    inkNativeCreatorTestSyncButtons();
  };
  canvas.addEventListener('pointerup', finish);
  canvas.addEventListener('pointercancel', () => {
    inkNativeBrushUi.testActiveStroke = null;
    inkNativeBrushUi.testWeightsValid = false;
    inkNativeCreatorTestRender();
  });
  clear?.addEventListener('click', () => {
    inkNativeBrushUi.testStrokes.length = 0;
    inkNativeBrushUi.testRedoStrokes.length = 0;
    inkNativeBrushUi.testActiveStroke = null;
    inkNativeBrushUi.testWeightsValid = false;
    inkNativeCreatorTestRender();
    inkNativeCreatorTestSyncButtons();
  });
  undo?.addEventListener('click', () => {
    inkNativeCreatorTestUndo();
    canvas.focus();
  });
  // Ctrl/Cmd+Z, tuval odakta olmasa da (ör. bir kaydırıcıyken) test
  // çizimlerini geri alır. Metin alanlarında yerel geri almayı bozmayız.
  window.addEventListener('keydown', event => {
    const root = inkNativeBrushUi.els.root;
    if (!root || root.hidden) return;
    const target = event.target instanceof Element ? event.target : null;
    const focused = document.activeElement instanceof Element ? document.activeElement : null;
    const inCreator = node => !!(node && node.closest && node.closest('.nbCreator'));
    if (!inkNativeBrushUi.creatorOnly && !inCreator(target) && !inCreator(focused)) return;
    if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
    const key = String(event.key || '').toLowerCase();
    if (key !== 'z' && key !== 'y') return;
    if (inkNativeCreatorIsTextEntry(target)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (key === 'y' || event.shiftKey) inkNativeCreatorTestRedo();
    else inkNativeCreatorTestUndo();
  }, true);
  if (typeof ResizeObserver === 'function') {
    inkNativeBrushUi.testResizeObserver = new ResizeObserver(inkNativeCreatorTestRender);
    inkNativeBrushUi.testResizeObserver.observe(canvas.parentElement);
  }
}

function inkNativeSyncCreatorCategoryOptions(preferred) {
  const select = document.getElementById('nativeBrushCustomCategory');
  if (!select) return;
  const categories = inkNativeAssignableCategories();
  const signature = categories.map(category => category.id + '\u0000' + category.name).join('|');
  const wanted = preferred || select.value;
  if (select.dataset.signature !== signature) {
    select.replaceChildren();
    for (const category of categories) {
      select.add(new Option(category.name, category.id));
    }
    select.dataset.signature = signature;
  }
  if (wanted && categories.some(category => category.id === wanted)) {
    select.value = wanted;
  } else if (categories.some(category => category.id === 'custom')) {
    select.value = 'custom';
  } else if (categories.length) {
    select.value = categories[0].id;
  }
}

function inkNativeSyncCustomCreator() {
  const brush = inkNativeCustomBrushFromForm();
  inkNativeSyncCreatorCategoryOptions();
  const preview = inkNativeBrushUi.els.creatorPreview;
  if (preview) {
    /* Oluşturucu paneli gizliyse boyamayı atla (darbokaz düzeltmesi);
       panel açıldığında inkPreviewFlushStale → refreshPreviews zinciri
       inkNativeSyncCustomCreator'i yeniden çağırıp görünürken boyar. */
    if (inkPreviewCanvasVisible(preview)) {
      /* LAG DÜZELTMESI: form okunuşu HER ÇAĞRIDA rastgele id üretiyordu
         ('custom-brush-' + newId()) — bake önbellek anahtarı tüm fırça
         JSON'unun hash'i + id içerdiğinden önbellek asla tutmuyor, her
         slider tığı tam pişirme + diske PNG kuyruğu demekti (ölçüm:
         20 adımlık sürükleme = 21 regen, disk kuyruğu 123). Önizlemede
         KARARLI kimlik kullan: aynı parametreler = aynı anahtar = cache
         vuruşu. name/description boyamada etkisiz — onlar da sabit. */
      const previewBrush = Object.assign({}, brush, {
        id: 'custom-brush-preview',
        name: '',
        description: '',
      });
      renderStrokePreview(preview, previewBrush, {
        width: 440, height: 120, sizePx: 42, disk: false,
      });
    } else {
      inkNativeBrushUi.previewDirty = true;
    }
  }
  const selected = inkGetBrush(inkState().brushId);
  const remove = inkNativeBrushUi.els.creatorDelete;
  if (remove) remove.disabled = !selected || inkNativeIsDefaultBrush(selected);
  const tipSelect = document.getElementById('nativeBrushCustomTip');
  if (tipSelect) tipSelect.disabled = !!inkNativeBrushUi.uploadedTip;
  const clearTip = document.getElementById('nativeBrushCustomPngClear');
  if (clearTip) clearTip.hidden = !inkNativeBrushUi.uploadedTip;
  for (const input of document.querySelectorAll('#nativeBrushCustomControls input[type="range"]')) {
    const id = input.id.replace(/^nativeBrushCustom/, '');
    const output = document.getElementById(input.id + 'Val');
    if (!input || !output) continue;
    output.textContent = id === 'Size' ? input.value + ' px' :
      id === 'Angle' ? input.value + '°' :
        id === 'Count' || id === 'TipVariants' || id === 'TipSeed' ? input.value :
          id === 'TextureBrightness' ? (Number(input.value) > 0 ? '+' : '') + input.value + '%' :
            input.value + '%';
  }
}

function inkNativeNormalizeCategoryRecord(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const id = String(raw.id || '').trim();
  const name = String(raw.name || '').trim().replace(/\s+/g, ' ').slice(0, 40);
  if (!id || !name) return null;
  if (id === 'favorites' || NativeBrushCategories.some(cat => cat.id === id)) return null;
  let title = String(raw.title || '').trim();
  if (!title) title = name.toLocaleUpperCase('tr-TR');
  const hint = String(raw.hint || '').trim() || (name + ' brushes in category');
  return { id, name, title, hint, custom: true };
}

function inkNativeAllCategories() {
  const list = [NativeBrushVirtualCategories[0], ...NativeBrushCategories];
  const seen = new Set(list.map(cat => cat.id));
  for (const category of inkNativeLibrary.customCategories) {
    if (!category || !category.id || seen.has(category.id)) continue;
    seen.add(category.id);
    list.push(category);
  }
  return list;
}

function inkNativeEffectiveCategoryOrder(ids) {
  const available = new Set(ids);
  const out = [];
  const seen = new Set();
  for (const id of inkNativeLibrary.categoryOrder) {
    if (typeof id !== 'string' || !available.has(id) || seen.has(id)) continue;
    out.push(id);
    seen.add(id);
  }
  for (const id of ids) {
    if (seen.has(id)) continue;
    out.push(id);
    seen.add(id);
  }
  return out;
}

function inkNativeCategoryById(id) {
  return inkNativeAllCategories().find(cat => cat.id === id) || null;
}

function inkNativeBrushCategoryName(id) {
  const cat = inkNativeCategoryById(id);
  return cat ? cat.name : 'Brush';
}

function inkNativeVisibleCategories() {
  const deleted = new Set(inkState().deletedCategories || []);
  const all = inkNativeAllCategories();
  const byId = new Map(all.map(cat => [cat.id, cat]));
  return inkNativeEffectiveCategoryOrder(all.map(cat => cat.id))
    .map(id => byId.get(id))
    .filter(cat => cat && !deleted.has(cat.id));
}

/** Oluşturucuda ve "kategoriye taşı" menüsünde seçilebilecek gerçek
    kategoriler. "Favorites" sanal bir filtredir; hedef olamaz. */
function inkNativeAssignableCategories() {
  return inkNativeVisibleCategories().filter(cat => !cat.virtual);
}

function inkNativeVisibleBrushes() {
  const ink = inkState();
  const deletedBrushes = new Set(ink.deletedBrushIds || []);
  const deletedCategories = new Set(ink.deletedCategories || []);
  return (ink.brushes || []).filter(brush =>
    !deletedBrushes.has(brush.id) && !deletedCategories.has(brush.category));
}

function inkNativeFavoriteSet() {
  return new Set(Array.isArray(inkNativeLibrary.favorites)
    ? inkNativeLibrary.favorites : []);
}

function inkNativeIsFavorite(brushId) {
  return inkNativeFavoriteSet().has(brushId);
}

/** Bir kategorinin görünen fırçaları. "favorites" sanal kategorisi
    yıldızlanan tüm fırçaları döndürür. */
function inkNativeBrushesForCategory(categoryId) {
  const brushes = inkNativeVisibleBrushes();
  if (categoryId === 'favorites') {
    const favorites = inkNativeFavoriteSet();
    return brushes.filter(brush => favorites.has(brush.id));
  }
  return brushes.filter(brush => brush.category === categoryId);
}

function inkNativeCurrentBrushRecords() {
  const defaults = new Set(
    (typeof inkDefaultBrushes === 'function' ? inkDefaultBrushes() : [])
      .map(brush => brush && brush.id)
      .filter(Boolean)
  );
  return (inkState().brushes || [])
    .filter(brush => brush && brush.id && !defaults.has(brush.id))
    .map(brush => ({
      version: 2,
      brush,
      tipDataUrl: brush.tipId
        ? (inkRuntime.importedTips.get(brush.tipId) || '') : '',
      dualTipDataUrl: brush.dual && brush.dual.tipId
        ? (inkRuntime.importedTips.get(brush.dual.tipId) || '') : '',
    }));
}

function inkNativeMergePersistedBrushes(records) {
  if (!Array.isArray(records) || !records.length) return;
  const ink = inkState();
  const defaults = new Set(
    (typeof inkDefaultBrushes === 'function' ? inkDefaultBrushes() : [])
      .map(brush => brush && brush.id)
      .filter(Boolean)
  );
  for (const rec of records) {
    const source = rec && rec.brush && typeof rec.brush === 'object'
      ? rec.brush : rec;
    if (!source || !source.id || defaults.has(source.id)) continue;
    const tipDataUrl = rec.tipDataUrl || rec.dataUrl || '';
    const dualDataUrl = rec.dualTipDataUrl || rec.dualDataUrl || '';
    if (tipDataUrl && source.tipId) {
      if (!inkRuntime.importedTips.has(source.tipId)) {
        inkRuntime.importedTips.set(source.tipId, tipDataUrl);
        inkLoadAbrTip(source.tipId);
      }
    }
    if (dualDataUrl && source.dual && source.dual.tipId) {
      if (!inkRuntime.importedTips.has(source.dual.tipId)) {
        inkRuntime.importedTips.set(source.dual.tipId, dualDataUrl);
        inkLoadAbrTip(source.dual.tipId);
      }
    }
    if (!ink.brushes.some(brush => brush.id === source.id)) {
      const kind = source.kind === 'abr' || source.kind === 'procedural'
        ? source.kind : (tipDataUrl ? 'abr' : 'procedural');
      ink.brushes.push(inkNormalizeBrush(Object.assign({}, source, {
        kind,
        tipId: source.tipId || '',
      })));
    }
  }
}

/** Global kütüphane kaydını canlı çizim durumuna uygular. Proje
    değişiminde de çağrılır; böylece kaydedilmemiş fırçalar ve özel
    kategoriler kaybolmaz. */
/* Eski sürümlerde içe aktarılan .abr fırçaları `category: ''` ile
   kaydediliyordu; kütüphane kategori filtresi bu kayıtları hiçbir
   listede göstermiyordu. Proje kaydından gelen eski fırçaları da
   burada onar (kütüphane yüklenmeden önce bile). */
function inkNativeRepairBrushCategories() {
  const ink = inkState();
  const defaults = new Set(
    (typeof inkDefaultBrushes === 'function' ? inkDefaultBrushes() : [])
      .map(brush => brush && brush.id)
      .filter(Boolean)
  );
  for (const brush of ink.brushes || []) {
    if (!brush || defaults.has(brush.id) || brush.category) continue;
    brush.category = 'custom';
    if (!brush.badge) brush.badge = 'Custom';
  }
}

function inkNativeApplyLibraryState() {
  inkNativeRepairBrushCategories();
  if (!inkNativeLibrary.loaded) return;
  const ink = inkState();
  const union = (current, persisted) => [...new Set([
    ...(Array.isArray(current) ? current : []),
    ...(Array.isArray(persisted) ? persisted : []),
  ])];
  ink.deletedCategories = union(ink.deletedCategories, inkNativeLibrary.deletedCategories)
    /* yıldız kategorisi asla silinemeyen sanal filtredir; eski kayıtlardan
       sızmışsa burada da temizlenir */
    .filter(id => id !== 'favorites');
  ink.deletedBrushIds = union(ink.deletedBrushIds, inkNativeLibrary.deletedBrushIds);
  inkNativeMergePersistedBrushes(inkNativeLibrary.brushRecords);
}

function inkNativePruneFavorites() {
  try {
    const visible = new Set(inkNativeVisibleBrushes().map(brush => brush.id));
    inkNativeLibrary.favorites = inkNativeLibrary.favorites
      .filter(id => typeof id === 'string' && visible.has(id));
  } catch { /* sessiz */ }
}

function inkNativeLibrarySnapshot() {
  return {
    version: 1,
    customCategories: inkNativeLibrary.customCategories.map(category => ({
      id: category.id,
      name: category.name,
      title: category.title,
      hint: category.hint,
    })),
    categoryOrder: [...inkNativeLibrary.categoryOrder],
    favorites: [...inkNativeLibrary.favorites],
    deletedCategories: [...(inkNativeLibrary.deletedCategories || [])],
    deletedBrushIds: [...(inkNativeLibrary.deletedBrushIds || [])],
  };
}

async function inkNativePersistLibraryMeta() {
  try {
    if (!db) return;
    await idbPut('meta', INK_NATIVE_LIBRARY_META_KEY, inkNativeLibrarySnapshot());
  } catch (err) {
    console.warn('brush library settings could not be saved', err);
  }
}

/** Fırçaları ve kütüphane ayarlarını birlikte, proje kaydından bağımsız
    olarak hemen diske yazar.
    @param {object} [options]
    @param {boolean} [options.brushes=true] false ise fırça kayıtları
      (uç PNG'leri dahil) yeniden yazılmaz. Favori yıldızı, kategori
      sırası gibi fırça listesini DEĞİŞTİRMEYEN işlemler bunu kullanır:
      aksi hâlde her yıldız tıklaması tüm uç verisini yeniden serileştirip
      diske yazıyordu (çok fırçalı kütüphanede hissedilir takılma). */
async function inkNativePersistLibraryAll(options = {}) {
  try {
    const writeBrushes = options.brushes !== false;
    const ink = inkState();
    inkNativeLibrary.deletedCategories = [...new Set(ink.deletedCategories || [])];
    inkNativeLibrary.deletedBrushIds = [...new Set(ink.deletedBrushIds || [])];
    inkNativePruneFavorites();
    if (writeBrushes && typeof inkPersistImportedBrushes === 'function') {
      await inkPersistImportedBrushes();
    }
    inkNativeLibrary.brushRecords = inkNativeCurrentBrushRecords();
    await inkNativePersistLibraryMeta();
  } catch (err) {
    console.warn('brush library could not be saved', err);
  }
}

async function inkNativeLoadBrushLibrary() {
  try {
    if (!db) return;
    const raw = await idbGet('meta', INK_NATIVE_LIBRARY_META_KEY);
    if (raw && typeof raw === 'object') {
      const seen = new Set();
      inkNativeLibrary.customCategories = (Array.isArray(raw.customCategories)
        ? raw.customCategories : [])
        .map(inkNativeNormalizeCategoryRecord)
        .filter(category => {
          if (!category || seen.has(category.id)) return false;
          seen.add(category.id);
          return true;
        });
      inkNativeLibrary.categoryOrder = Array.isArray(raw.categoryOrder)
        ? raw.categoryOrder.filter(id => typeof id === 'string' && id) : [];
      inkNativeLibrary.favorites = Array.isArray(raw.favorites)
        ? [...new Set(raw.favorites.filter(id => typeof id === 'string' && id))] : [];
      inkNativeLibrary.deletedCategories = Array.isArray(raw.deletedCategories)
        ? [...new Set(raw.deletedCategories.filter(id =>
            typeof id === 'string' && id && id !== 'favorites' && id !== NativeBrushVirtualCategories[0].id))] : [];
      inkNativeLibrary.deletedBrushIds = Array.isArray(raw.deletedBrushIds)
        ? [...new Set(raw.deletedBrushIds.filter(id => typeof id === 'string' && id))] : [];
    }
    const records = await idbGet('meta', 'ink:brushes');
    inkNativeLibrary.brushRecords = Array.isArray(records) ? records : [];
    inkNativeLibrary.loaded = true;
    inkNativeApplyLibraryState();
  } catch (err) {
    console.warn('brush library could not be loaded', err);
  }
}

async function inkNativeToggleFavorite(brushId) {
  if (!brushId) return false;
  const favorites = inkNativeLibrary.favorites;
  const index = favorites.indexOf(brushId);
  if (index >= 0) favorites.splice(index, 1);
  else favorites.push(brushId);
  await inkNativePersistLibraryAll({ brushes: false });
  inkNativeRenderCategories();
  inkNativeRenderBrushList();
  inkNativeSyncMeta();
  return index < 0;
}

async function inkNativeClearFavorites() {
  if (!inkNativeLibrary.favorites.length) return;
  if (!(await appConfirm('Remove all stars from the favorites list?'))) return;
  inkNativeLibrary.favorites = [];
  await inkNativePersistLibraryAll({ brushes: false });
  inkNativeRenderAll();
  inkNativeRenderQuickBrushes();
}

async function inkNativeCreateCategory(rawName) {
  const name = String(rawName || '').trim().replace(/\s+/g, ' ').slice(0, 40);
  if (!name) return { ok: false, error: 'Category name cannot be empty.' };
  const lower = name.toLocaleLowerCase('tr-TR');
  if (inkNativeAllCategories().some(category =>
    category.name.toLocaleLowerCase('tr-TR') === lower)) {
    return { ok: false, error: 'Bu adla bir kategori zaten var.' };
  }
  const base = 'cat_' + String(newId()).replace(/[^a-z0-9_-]/gi, '').slice(0, 28);
  let id = base;
  let suffix = 2;
  while (inkNativeAllCategories().some(category => category.id === id)) {
    id = base + '_' + suffix;
    suffix += 1;
  }
  const category = {
    id,
    name,
    title: name.toLocaleUpperCase('tr-TR'),
    hint: name + ' brushes in category',
    custom: true,
  };
  inkNativeLibrary.customCategories.push(category);
  const allIds = inkNativeAllCategories().map(item => item.id);
  const order = inkNativeEffectiveCategoryOrder(allIds);
  const activeIndex = order.indexOf(inkNativeBrushUi.activeCategory);
  order.splice(activeIndex >= 0 ? activeIndex + 1 : order.length, 0, id);
  inkNativeLibrary.categoryOrder = order;
  inkNativeBrushUi.activeCategory = id;
  await inkNativePersistLibraryAll({ brushes: false });
  // Yeni kategori seçili kalsın: inkNativeRenderAll() içindeki sync,
  // aktif fırçanın kategorisine geri dönebiliyor.
  inkNativeRenderCategories();
  inkNativeRenderBrushList();
  inkNativeSyncMeta();
  inkNativeSyncDualBrushOptions();
  inkNativeSyncCustomCreator();
  return { ok: true, category };
}

async function inkNativeReorderCategory(fromId, toId, before) {
  if (!fromId || !toId || fromId === toId) return;
  const allIds = inkNativeAllCategories().map(category => category.id);
  if (!allIds.includes(fromId) || !allIds.includes(toId)) return;
  const order = inkNativeEffectiveCategoryOrder(allIds);
  const fromIndex = order.indexOf(fromId);
  if (fromIndex < 0) return;
  order.splice(fromIndex, 1);
  let target = order.indexOf(toId);
  if (target < 0) return;
  if (!before) target += 1;
  order.splice(target, 0, fromId);
  inkNativeLibrary.categoryOrder = order;
  await inkNativePersistLibraryAll({ brushes: false });
  inkNativeRenderCategories();
}

async function inkNativeMoveBrushToCategory(brushId, categoryId) {
  const brush = inkState().brushes.find(item => item.id === brushId);
  if (!brush || inkNativeIsDefaultBrush(brush)) return false;
  if (!inkNativeAssignableCategories().some(category => category.id === categoryId)) {
    return false;
  }
  if (brush.category === categoryId) return false;
  const category = inkNativeCategoryById(categoryId);
  brush.category = categoryId;
  brush.badge = categoryId === 'custom' ? 'Custom' : (category ? category.name : '');
  inkNativeBrushUi.activeCategory = categoryId;
  await inkNativePersistLibraryAll();
  inkNativeRenderAll();
  inkNativeRenderQuickBrushes();
  /* Proje kaydı da tazelensin: aksi hâlde eski pano anlık görüntüsü
     yeniden açılışta fırçayı eski kategorisiyle geri getiriyordu
     (kütüphane kaydı doğru olsa bile). */
  if (typeof scheduleSave === 'function') scheduleSave();
  return true;
}

function inkNativeCloseContextMenu() {
  if (!inkNativeBrushUi.contextMenu) return;
  inkNativeBrushUi.contextMenu.remove();
  inkNativeBrushUi.contextMenu = null;
}

function inkNativeShowContextMenuAt(clientX, clientY, actions) {
  inkNativeCloseContextMenu();
  const menu = document.createElement('div');
  menu.className = 'nbContextMenu';
  menu.setAttribute('role', 'menu');
  for (const action of actions) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'nbContextMenu__item';
    item.setAttribute('role', 'menuitem');
    item.textContent = action.label;
    item.disabled = !!action.disabled;
    if (!item.disabled) {
      item.addEventListener('click', () => {
        inkNativeCloseContextMenu();
        action.run();
      });
    }
    menu.appendChild(item);
  }
  document.body.appendChild(menu);
  inkNativeBrushUi.contextMenu = menu;
  const x = Math.min(clientX, window.innerWidth - menu.offsetWidth - 8);
  const y = Math.min(clientY, window.innerHeight - menu.offsetHeight - 8);
  menu.style.left = Math.max(8, x) + 'px';
  menu.style.top = Math.max(8, y) + 'px';
  menu.querySelector('button:not(:disabled)')?.focus();
}

function inkNativeShowContextMenu(event, actions) {
  event.preventDefault();
  inkNativeShowContextMenuAt(event.clientX, event.clientY, actions);
}

function inkNativeShowMoveCategoryMenu(brush, clientX, clientY) {
  if (!brush || inkNativeIsDefaultBrush(brush)) return;
  const actions = inkNativeAssignableCategories()
    .filter(category => category.id !== brush.category)
    .map(category => ({
      label: category.name,
      run: () => inkNativeMoveBrushToCategory(brush.id, category.id),
    }));
  if (!actions.length) {
    actions.push({ label: 'No other category', disabled: true });
  }
  inkNativeShowContextMenuAt(clientX, clientY, actions);
}

function inkNativeIsDefaultBrush(brush) {
  return NativeBrushLibrary.some(item => item.id === brush.id);
}

function inkNativeFallbackBrush() {
  const available = inkNativeVisibleBrushes();
  return available.find(brush => !inkNativeIsDefaultBrush(brush)) ||
    available[0] || null;
}

/* =========================================================
   .abr dışa aktarma
   Fırçanın gerçek ucunu 8 bit gri maske olarak yazar. referans uygulama
   v6.2 düzeni kullanılır: desc (ad) + cbsh (ayarlar) + samp (uç).
   Uygulamanın kendi ayrıştırıcısı bu dosyayı geri okuyabilir.
   ========================================================= */
function inkNativeBrushAbrSample(brush) {
  if (!brush || typeof brush !== 'object') return null;
  const hardness = clamp(Number(brush.hardness) || 0.6, 0, 1);
  let source = null;
  try {
    source = inkBrushSourceCanvas(brush, hardness, 256);
  } catch { source = null; }
  if (!source || !source.width || !source.height) return null;

  // Dosya boyutu için uç en fazla 256 px'e indirilir; en-boy korunur.
  const maxSide = 256;
  const scale = Math.min(1, maxSide / Math.max(source.width, source.height));
  const w = Math.max(1, Math.round(source.width * scale));
  const h = Math.max(1, Math.round(source.height * scale));
  const tip = document.createElement('canvas');
  tip.width = w;
  tip.height = h;
  const tctx = tip.getContext('2d');
  if (!tctx) return null;
  tctx.drawImage(source, 0, 0, w, h);
  const pixels = tctx.getImageData(0, 0, w, h).data;

  // 47 baytlık örneklenmiş uç başlığı + 19 baytlık bitmap başlığı.
  const entry = new Uint8Array(47 + 19 + w * h);
  const ev = new DataView(entry.buffer);
  ev.setUint32(0, 2); // örneklenmiş uç
  ev.setUint32(4, Math.max(1, Math.round(Number(brush.size) || w)));
  ev.setUint32(8, Math.round(clamp(Number(brush.spacing) || 0.1, 0.01, 2) * 100));
  ev.setUint32(12, Math.round((((Number(brush.angle) || 0) * 180 / Math.PI) % 360 + 360) % 360));
  ev.setUint32(16, Math.round(clamp(Number(brush.roundness) || 1, 0.05, 1) * 100));
  ev.setUint32(20, Math.round(hardness * 100));
  ev.setUint32(24, Math.round(clamp(Number(brush.flow) || 1, 0.01, 1) * 100));
  ev.setInt32(47, 0);
  ev.setInt32(51, 0);
  ev.setInt32(55, h);
  ev.setInt32(59, w);
  ev.setUint16(63, 8);
  entry[65] = 0; // sıkıştırmasız
  for (let i = 0; i < w * h; i++) entry[66 + i] = pixels[i * 4 + 3];
  return { entry, w, h, hardness };
}

/** Birden çok fırçayı tek referans uygulama .abr dosyasında yazar. Her fırça
    kendi `desc` + `cbsh` + `samp` üçlüsüyle eklenir. */
function inkNativeBrushesAbrBytes(brushes) {
  const list = (Array.isArray(brushes) ? brushes : [brushes]).filter(Boolean);
  if (!list.length) return null;

  const out = [];
  const u16 = n => { out.push((n >> 8) & 255, n & 255); };
  const u32 = n => {
    out.push((n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255);
  };
  const f64 = n => {
    const t = new Uint8Array(8);
    new DataView(t.buffer).setFloat64(0, n);
    for (let i = 0; i < 8; i++) out.push(t[i]);
  };
  const ascii = s => {
    for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 255);
  };
  const uni = s => {
    const text = String(s || '');
    u32(text.length);
    for (let i = 0; i < text.length; i++) u16(text.charCodeAt(i));
  };
  const id = s => { u32(s.length); ascii(s); };
  const patch32 = (pos, n) => {
    out[pos] = (n >>> 24) & 255;
    out[pos + 1] = (n >>> 16) & 255;
    out[pos + 2] = (n >>> 8) & 255;
    out[pos + 3] = n & 255;
  };
  const descriptor = (cls, fields) => {
    uni(cls);
    id(cls);
    u32(fields.length);
    fields.forEach(fn => fn());
  };
  const numField = (key, unit, value) => {
    id(key);
    ascii('UntF');
    ascii(unit);
    f64(value);
  };
  const textField = (key, value) => {
    id(key);
    ascii('TEXT');
    uni(value);
  };
  const objField = (key, cls, fields) => {
    id(key);
    ascii('Objc');
    descriptor(cls, fields);
  };
  const block = (tag, payload) => {
    ascii('8BIM');
    ascii(tag);
    const sizePos = out.length;
    u32(0);
    const start = out.length;
    payload();
    patch32(sizePos, out.length - start);
    while (out.length % 4) out.push(0);
  };

  u16(6); u16(2);
  let written = 0;
  for (const brush of list) {
    const sample = inkNativeBrushAbrSample(brush);
    if (!sample) continue;
    written += 1;
    const { entry, w, hardness } = sample;
    block('desc', () => {
      u32(1);
      descriptor('brushPreset', [
        () => textField('Nm  ', brush.name || 'Brush'),
      ]);
    });
    block('cbsh', () => {
      u32(16);
      const dyn = brush.dynamics || {};
      const fields = [
        () => numField('Dmtr', '#Pxl', Math.max(1, Number(brush.size) || w)),
        () => numField('Hrdn', '#Prc', hardness * 100),
        () => numField('Spcn', '#Prc', clamp(Number(brush.spacing) || 0.1, 0.01, 2) * 100),
        () => numField('Angl', '#Ang', (((Number(brush.angle) || 0) * 180 / Math.PI) % 360 + 360) % 360),
        () => numField('Rndn', '#Prc', clamp(Number(brush.roundness) || 1, 0.05, 1) * 100),
        () => numField('Flw ', '#Prc', clamp(Number(brush.flow) || 1, 0.01, 1) * 100),
        () => numField('Sctr', '#Prc', clamp(Number(brush.scatter) || 0, 0, 2) * 100),
        () => numField('SzVr', '#Prc', clamp(1 - Number(dyn.sizeMin ?? 0.18), 0, 1) * 100),
        () => numField('AnVr', '#Prc', clamp(Number(dyn.angleJitter) || 0, 0, 1) * 100),
        () => numField('ScVr', '#Prc', clamp(Number(dyn.scatterJitter) || 0, 0, 1) * 100),
      ];
      if (brush.dual && Number(brush.dual.scale)) {
        fields.push(() => objField('Dual', 'dualBrush', [
          () => numField('Dmtr', '#Pxl',
            Math.max(1, (Number(brush.size) || w) * clamp(Number(brush.dual.scale) || 1, 0.1, 4))),
          () => numField('Hrdn', '#Prc', clamp(Number(brush.dual.hardness ?? 0.6), 0, 1) * 100),
          () => numField('Spcn', '#Prc', clamp(Number(brush.dual.spacing ?? 0.1), 0.01, 2) * 100),
          () => numField('Sctr', '#Prc', clamp(Number(brush.dual.scatter) || 0, 0, 2) * 100),
        ]));
      }
      descriptor('computedBrush', fields);
    });
    block('samp', () => {
      u16(1);
      u16(1);
      u32(entry.length);
      for (let i = 0; i < entry.length; i++) out.push(entry[i]);
      while (out.length % 4) out.push(0);
    });
  }
  if (!written) return null;
  return new Uint8Array(out);
}

function inkNativeBrushAbrBytes(brush) {
  return inkNativeBrushesAbrBytes([brush]);
}

function inkNativeSafeFileName(value, fallback = 'firca') {
  return String(value || fallback)
    .replace(/[\\/:*?"<>|]/g, '_')
    .trim()
    .slice(0, 80) || fallback;
}

async function inkNativeSaveAbrFile(bytes, fileName, label) {
  if (!bytes || !bytes.length) {
    window.alert(label + ' could not be prepared as .abr.');
    return false;
  }
  try {
    if (window.tailref && typeof window.tailref.exportAbr === 'function') {
      const res = await window.tailref.exportAbr(bytes, fileName);
      if (res && res.ok) {
        if (typeof showProjectNotice === 'function') {
          showProjectNotice(label + ' exported: ' + res.file, 4200);
        }
        return true;
      }
      if (res && res.canceled) return false;
      window.alert(label + ' export failed: ' +
        (res && res.error ? res.error : 'bilinmeyen hata'));
      return false;
    }
    const blob = new Blob([bytes], { type: 'application/octet-stream' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = fileName;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    return true;
  } catch (error) {
    window.alert(label + ' export failed: ' +
      (error && error.message ? error.message : error));
    return false;
  }
}

async function inkNativeExportBrushAbr(brush) {
  if (!brush) return false;
  let bytes = null;
  try {
    bytes = inkNativeBrushAbrBytes(brush);
  } catch { bytes = null; }
  return inkNativeSaveAbrFile(
    bytes,
    inkNativeSafeFileName(brush.name) + '.abr',
    'Brush'
  );
}

async function inkNativeExportCategoryAbr(categoryId) {
  const category = inkNativeCategoryById(categoryId);
  const brushes = inkNativeBrushesForCategory(categoryId);
  if (!brushes.length) {
    window.alert('No brushes to export in this category.');
    return false;
  }
  let bytes = null;
  try {
    bytes = inkNativeBrushesAbrBytes(brushes);
  } catch { bytes = null; }
  return inkNativeSaveAbrFile(
    bytes,
    inkNativeSafeFileName(category ? category.name : 'kategori') + '.abr',
    category ? '“' + category.name + '” kategorisi' : 'Category'
  );
}

async function inkNativeDeleteBrush(brushId) {
  const ink = inkState();
  const brush = ink.brushes.find(item => item.id === brushId);
  if (!brush || inkNativeIsDefaultBrush(brush)) return false;
  if (!(await appConfirm('“' + brush.name + '” — remove this brush from the library?'))) return false;
  if (!ink.deletedBrushIds.includes(brush.id)) ink.deletedBrushIds.push(brush.id);
  if (ink.brushId === brush.id) {
    const fallback = inkNativeFallbackBrush();
    if (fallback) setActiveBrush(fallback.id);
  }
  inkNativeRenderAll();
  inkNativeRenderQuickBrushes();
  if (typeof inkSyncUI === 'function') inkSyncUI();
  await inkNativePersistLibraryAll({ brushes: false });
  if (typeof scheduleSave === 'function') scheduleSave();
  return true;
}

async function inkNativeDeleteCategory(categoryId) {
  const ink = inkState();
  const category = inkNativeCategoryById(categoryId);
  if (!category || category.virtual) {
    if (category && category.virtual) {
      window.alert('Favorites is a virtual category; it cannot be deleted. You can remove stars one by one.');
    }
    return;
  }
  if (ink.deletedCategories.includes(categoryId)) return;
  const categories = inkNativeVisibleCategories().filter(item => !item.virtual);
  if (categories.length <= 1 && categories.some(item => item.id === categoryId)) {
    window.alert('At least one category must remain in the library.');
    return;
  }
  const contents = inkNativeBrushesForCategory(categoryId);
  /* Onay metni yanlış birleştirilmişti: "… category and its 3 — remove this
     brush …" gibi yarım bir cümle çıkıyordu. Sayıya göre tekil/çoğul kur. */
  const confirmText = contents.length
    ? '“' + category.name + '” category and its ' + contents.length +
      (contents.length === 1 ? ' brush will be removed from the library.'
        : ' brushes will be removed from the library.')
    : '“' + category.name + '” category will be removed from the library.';
  if (!(await appConfirm(confirmText))) return;

  if (!ink.deletedCategories.includes(categoryId)) ink.deletedCategories.push(categoryId);
  for (const brush of contents) {
    if (!inkNativeIsDefaultBrush(brush) && !ink.deletedBrushIds.includes(brush.id)) {
      ink.deletedBrushIds.push(brush.id);
    }
  }
  // Özel kategori kaydını ve sıralamadaki yerini de temizle.
  inkNativeLibrary.customCategories = inkNativeLibrary.customCategories
    .filter(item => item.id !== categoryId);
  inkNativeLibrary.categoryOrder = inkNativeLibrary.categoryOrder
    .filter(id => id !== categoryId);
  if (ink.brushId && contents.some(brush => brush.id === ink.brushId)) {
    const fallback = inkNativeFallbackBrush();
    if (fallback) setActiveBrush(fallback.id);
  }
  inkNativeBrushUi.activeCategory =
    inkNativeVisibleCategories()[0]?.id || '';
  inkNativeRenderAll();
  inkNativeRenderQuickBrushes();
  if (typeof inkSyncUI === 'function') inkSyncUI();
  await inkNativePersistLibraryAll({ brushes: false });
  if (typeof scheduleSave === 'function') scheduleSave();
}

function inkNativeRenderQuickBrushes() {
  const list = document.getElementById('inkPresetList') ||
    (typeof inkUi !== 'undefined' && inkUi.els ? inkUi.els.presetList : null);
  if (!list) return;
  let brushes = [];
  try { brushes = inkNativeVisibleBrushes(); } catch { /* sessiz */ }
  const ink = inkState();
  const signature = brushes.map(b => b.id).join('|');
  if (list.dataset.nbSignature === signature && list.children.length) {
    list.querySelectorAll('.inkPreset').forEach(btn => {
      const on = btn.dataset.brushId === ink.brushId;
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    return;
  }
  list.dataset.nbSignature = signature;
  list.replaceChildren();
  for (const brush of brushes) {
    if (!brush || !brush.id) continue;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'inkPreset' + (brush.id === ink.brushId ? ' active' : '');
    btn.dataset.brushId = brush.id;
    btn.title = brush.name;
    btn.setAttribute('aria-label', brush.name);
    btn.setAttribute('aria-pressed', brush.id === ink.brushId ? 'true' : 'false');
    const canvas = document.createElement('canvas');
    canvas.className = 'inkPresetPreview';
    canvas.setAttribute('aria-hidden', 'true');
    const label = document.createElement('span');
    label.className = 'inkPresetName';
    label.textContent = brush.name;
    btn.append(canvas, label);
    btn.addEventListener('click', () => {
      if (typeof setActiveBrush === 'function') setActiveBrush(brush.id);
    });
    list.appendChild(btn);
    // Şerit önizlemeleri boş-zamanda boyanır (açılışta senkron boyama
    // ~30-50 ms/kart — startup-probe bulgusu). Disk önbelleği varsa
    // kısa bir beklemeden decode edilip basılır; yoksa normal regen.
    // UI kurulumu bu sözleşmeyle asla engellenmez.
    const stripOps = { width: 72, height: 38 };
    inkNativeWhenIdle(() => {
      if (!canvas.isConnected) return; // kart arada kuruludan çıkarıldıysa
      /* Boşaltma anında görünürlük (darbokaz düzeltmesi): panel hâlâ
         gizliyse boyamayı atla, bayat işaretle; panel görünür olduğunda
         inkPreviewFlushStale() bir kez boyar. Kuyruğa bırakma anı ile
         boşaltma anı arasında tema/mod değişebilir. */
      if (!inkPreviewCanvasVisible(canvas)) {
        btn.dataset.nbPreviewStale = '1';
        inkNativeBrushUi.previewDirty = true;
        return;
      }
      if (btn.dataset.nbPreviewStale) delete btn.dataset.nbPreviewStale;
      inkPaintPreviewAsync(canvas, brush, stripOps);
    });
  }
}

function inkNativeRenderCategories() {
  const nav = inkNativeBrushUi.els.categories;
  if (!nav) return;
  nav.replaceChildren();
  const categories = inkNativeVisibleCategories();
  for (const cat of categories) {
    const count = inkNativeBrushesForCategory(cat.id).length;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'nbCategory' +
      (cat.id === inkNativeBrushUi.activeCategory ? ' is-active' : '') +
      (cat.virtual ? ' nbCategory--virtual' : '');
    btn.dataset.category = cat.id;
    btn.draggable = true;
    btn.title = (cat.hint || cat.name) + ' · Drag to reorder';
    btn.setAttribute('aria-pressed', cat.id === inkNativeBrushUi.activeCategory ? 'true' : 'false');
    const name = document.createElement('span');
    name.className = 'nbCategory__name';
    name.textContent = cat.name;
    const meta = document.createElement('span');
    meta.className = 'nbCategory__count';
    meta.textContent = String(count);
    btn.append(name, meta);
    btn.addEventListener('click', () => {
      inkNativeBrushUi.activeCategory = cat.id;
      inkNativeRenderCategories();
      inkNativeRenderBrushList();
      inkNativeSyncMeta();
      inkNativeSyncCustomCreator();
    });
    btn.addEventListener('dragstart', event => {
      inkNativeBrushUi.dragCategory = cat.id;
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        try { event.dataTransfer.setData('text/plain', cat.id); } catch { /* sessiz */ }
      }
      btn.classList.add('is-dragging');
    });
    btn.addEventListener('dragend', () => {
      inkNativeBrushUi.dragCategory = '';
      nav.querySelectorAll('.nbCategory').forEach(item => {
        item.classList.remove('is-dragging', 'is-drop-before', 'is-drop-after');
      });
    });
    btn.addEventListener('dragover', event => {
      const from = inkNativeBrushUi.dragCategory;
      if (!from || from === cat.id) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      const rect = btn.getBoundingClientRect();
      const before = event.clientY < rect.top + rect.height / 2;
      nav.querySelectorAll('.nbCategory').forEach(item => {
        item.classList.remove('is-drop-before', 'is-drop-after');
      });
      btn.classList.add(before ? 'is-drop-before' : 'is-drop-after');
    });
    btn.addEventListener('dragleave', event => {
      if (event.relatedTarget && btn.contains(event.relatedTarget)) return;
      btn.classList.remove('is-drop-before', 'is-drop-after');
    });
    btn.addEventListener('drop', event => {
      event.preventDefault();
      const from = inkNativeBrushUi.dragCategory;
      const before = btn.classList.contains('is-drop-before');
      inkNativeBrushUi.dragCategory = '';
      if (from && from !== cat.id) {
        inkNativeReorderCategory(from, cat.id, before);
      }
    });
    nav.appendChild(btn);
  }

  const add = document.createElement('button');
  add.type = 'button';
  add.className = 'nbCategory nbCategory--add';
  const addName = document.createElement('span');
  addName.className = 'nbCategory__name';
  addName.textContent = '+ New category';
  add.appendChild(addName);
  add.addEventListener('click', () => inkNativeBeginCreateCategory(add));
  nav.appendChild(add);

  if (!categories.length) {
    const empty = document.createElement('p');
    empty.className = 'nbEmpty';
    empty.textContent = 'No category to show.';
    nav.insertBefore(empty, add);
  }
}

/** Kategori rayında satır içi "yeni kategori" formu açar. Electron
    `window.prompt` desteklemediği için kendi küçük formumuzu kullanıyoruz. */
function inkNativeBeginCreateCategory(anchor) {
  if (!inkNativeBrushUi.els.categories || !anchor) return;
  const form = document.createElement('form');
  form.className = 'nbCategoryCreate';
  const input = document.createElement('input');
  input.type = 'text';
  input.maxLength = 40;
  input.placeholder = 'Category name';
  input.setAttribute('aria-label', 'New category name');
  const actions = document.createElement('div');
  actions.className = 'nbCategoryCreate__actions';
  const ok = document.createElement('button');
  ok.type = 'submit';
  ok.textContent = 'Add';
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.textContent = 'Cancel';
  const status = document.createElement('span');
  status.className = 'nbCategoryCreate__status';
  status.setAttribute('role', 'status');
  actions.append(ok, cancel);
  form.append(input, actions, status);
  anchor.replaceWith(form);
  input.focus();

  let busy = false;
  cancel.addEventListener('click', () => {
    if (busy) return;
    inkNativeRenderCategories();
  });
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (busy) return;
    busy = true;
    status.textContent = 'Creating…';
    const result = await inkNativeCreateCategory(input.value);
    if (!result.ok) {
      busy = false;
      status.textContent = result.error || 'Category could not be created.';
      input.focus();
      input.select();
      return;
    }
    // Başarılıysa render zaten formu kaldırır.
  });
  form.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      cancel.click();
    }
  });
}

function inkNativeBrushCard(brush, ink, options = {}) {
  const compact = !!options.compact;
  const isActive = options.active !== undefined
    ? !!options.active : brush.id === ink.brushId;
  const favorite = inkNativeIsFavorite(brush.id);
  // Kart bir <div>: içine yıldız düğmesi yerleştirebilmek için <button>
  // kullanmıyoruz. Klavye erişimi role/tabindex ile korunuyor.
  const card = document.createElement('div');
  card.className = 'nbBrushCard' + (isActive ? ' is-active' : '') +
    (favorite ? ' is-favorite' : '');
  card.dataset.brushId = brush.id;
  card.tabIndex = 0;
  card.setAttribute('role', 'option');
  card.setAttribute('aria-selected', isActive ? 'true' : 'false');
  card.title = brush.description || brush.name;

  const canvas = document.createElement('canvas');
  canvas.className = 'nbBrushCard__canvas';
  canvas.setAttribute('aria-hidden', 'true');
  const meta = document.createElement('span');
  meta.className = 'nbBrushCard__meta';
  const name = document.createElement('span');
  name.className = 'nbBrushCard__name';
  name.textContent = brush.name;
  const size = document.createElement('span');
  size.className = 'nbBrushCard__size';
  size.textContent = (brush.size ? Math.round(brush.size) + ' px' : '');
  meta.append(name, size);

  const star = document.createElement('button');
  star.type = 'button';
  star.className = 'nbBrushCard__star' + (favorite ? ' is-on' : '');
  star.setAttribute('aria-pressed', favorite ? 'true' : 'false');
  star.setAttribute('aria-label', favorite
    ? brush.name + ' — remove from favorites'
    : brush.name + ' — add to favorites');
  star.title = favorite ? 'Remove from favorites' : 'Add to favorites';
  star.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true">' +
    '<path d="M12 2.6l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.4 6.1 20.6l1.2-6.5L2.5 9.5l6.6-.9z"/>' +
    '</svg>';
  star.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    inkNativeToggleFavorite(brush.id);
  });
  star.addEventListener('pointerdown', event => event.stopPropagation());

  card.append(canvas, meta, star);

  const activate = () => {
    if (inkNativeBrushUi.creatorOnly) {
      // Oluşturucuda fırça seçmek onu boyamak için aktif yapmaz; yalnızca
      // ayarlarını forma "taban" olarak taşır. Orijinal fırça değişmez.
      inkNativeBrushUi.creatorBaseId = brush.id;
      inkNativeLoadBrushIntoCreator(brush);
      inkNativeSync();
      return;
    }
    setActiveBrush(brush.id);
    inkNativeSync();
  };
  card.addEventListener('click', activate);
  card.addEventListener('keydown', event => {
    if (event.target !== card) return;
    if (event.key !== 'Enter' && event.key !== ' ' && event.key !== 'Spacebar') return;
    event.preventDefault();
    activate();
  });
  /* Kart boyaması boş-zamana ertelenir (darbokaz düzeltmesi): senkron
     boyama gizli panelde boşa iş olurdu; boşaltma anında panel gizliyse
     bayat işaretlenir, panel görünür olduğunda bir kez boyanır. */
  const cardOps = compact ? {
    width: 150,
    height: 46,
    sizePx: Math.max(2, Math.min(16, brush.size * 0.22 + 2)),
  } : {
    width: 620,
    height: 78,
    sizePx: Math.max(3, Math.min(24, brush.size * 0.32 + 2)),
  };
  inkNativeWhenIdle(() => {
    if (!canvas.isConnected) return;
    if (!inkPreviewCanvasVisible(canvas)) {
      card.dataset.nbPreviewStale = '1';
      inkNativeBrushUi.previewDirty = true;
      return;
    }
    if (card.dataset.nbPreviewStale) delete card.dataset.nbPreviewStale;
    inkPaintPreviewAsync(canvas, brush, cardOps);
  });
  return card;
}

/* Liste her yeniden çizimde replaceChildren() ile baştan kurulur. Aynı
   kategori içinde yapılan işlemlerde (favori yıldızı, fırça silme, isim
   değişimi) bu, kaydırma konumunu sıfırlıyordu: uzun listede aşağıdaki
   bir fırçayı yıldızlayan kullanıcı listenin başına fırlıyordu. Kategori
   değişiminde ise başa dönmek doğru davranış. */
function inkNativeRenderBrushList() {
  const list = inkNativeBrushUi.els.list;
  const previous = list ? list.dataset.category : '';
  const top = list ? list.scrollTop : 0;
  inkNativeRenderBrushListInner();
  if (!list) return;
  if (previous && list.dataset.category === previous) {
    /* Aynı kategori: kullanıcı nerede baktıysa orada kalsın. */
    if (top > 0) list.scrollTop = top;
  } else {
    /* Kategori değişti: yeni liste baştan görünsün. (replaceChildren
       kaydırmayı kendiliğinden sıfırlamıyor; içerik aynı görevde yeniden
       dolduğu için tarayıcı eski kaydırma konumunu koruyor.) */
    list.scrollTop = 0;
  }
}

function inkNativeRenderBrushListInner() {
  const list = inkNativeBrushUi.els.list;
  if (!list) return;
  const categories = inkNativeVisibleCategories();
  const ink = inkState();
  list.replaceChildren();

  // Oluşturucu ekranı: referans tasarımdaki gibi solda tüm kitaplık,
  // ortada ayarlar, sağda önizleme/test alanı.
  if (inkNativeBrushUi.creatorOnly) {
    list.dataset.category = '__creator__';
    let shown = 0;
    for (const category of categories) {
      if (category.virtual) continue;
      const items = inkNativeBrushesForCategory(category.id);
      if (!items.length && category.id !== 'custom') continue;
      const group = document.createElement('div');
      group.className = 'nbBrushGroup';
      const title = document.createElement('div');
      title.className = 'nbBrushGroup__title';
      title.textContent = category.name;
      group.appendChild(title);
      for (const brush of items) {
        group.appendChild(inkNativeBrushCard(brush, ink, {
          compact: true,
          active: brush.id === inkNativeBrushUi.creatorBaseId,
        }));
        shown += 1;
      }
      if (!items.length && category.id === 'custom') {
        const empty = document.createElement('p');
        empty.className = 'nbEmpty nbEmpty--compact';
        empty.textContent = 'You have no custom brushes yet.';
        group.appendChild(empty);
      }
      list.appendChild(group);
    }
    if (!shown) {
      const empty = document.createElement('p');
      empty.className = 'nbEmpty';
      empty.textContent = 'No brushes to show.';
      list.appendChild(empty);
    }
    return;
  }

  const cat = categories.find(item => item.id === inkNativeBrushUi.activeCategory) || categories[0];
  if (!cat) {
    list.dataset.category = '';
    return;
  }
  list.dataset.category = cat.id;
  const items = inkNativeBrushesForCategory(cat.id);
  for (const brush of items) {
    list.appendChild(inkNativeBrushCard(brush, ink));
  }
  if (!items.length) {
    const empty = document.createElement('p');
    empty.className = 'nbEmpty';
    empty.textContent = cat.id === 'favorites'
      ? 'No starred brushes yet. Tap the star at the top right of the cards.'
      : cat.id === 'custom'
        ? 'You have no custom brushes yet. Save your first brush with "Create your own brush" in the brush panel.'
        : cat.virtual
          ? 'No brushes in this category yet.'
          : 'No brushes in this category yet. You can add brushes from the creator.';
    list.appendChild(empty);
  }
}

function inkNativeSyncMeta() {
  const title = inkNativeBrushUi.els.categoryTitle;
  const hint = inkNativeBrushUi.els.categoryHint;
  const count = inkNativeBrushUi.els.count;

  if (inkNativeBrushUi.creatorOnly) {
    let total = 0;
    try { total = inkNativeVisibleBrushes().length; } catch { total = 0; }
    if (title) title.textContent = 'MY LIBRARY';
    if (hint) hint.textContent = 'All brushes by category';
    if (count) count.textContent = total + ' brush';
    return;
  }

  const cat = inkNativeVisibleCategories().find(item =>
    item.id === inkNativeBrushUi.activeCategory) || inkNativeVisibleCategories()[0];
  if (title) title.textContent = cat ? cat.title : 'BRUSH LIBRARY';
  if (hint) hint.textContent = cat ? cat.hint : '';
  if (count) {
    let n = 0;
    try {
      n = cat ? inkNativeBrushesForCategory(cat.id).length : 0;
    } catch { n = 0; }
    count.textContent = n + ' brush';
  }
}

/* Tema değişince fırça önizlemelerini yeniden boyar. Kartlar ve hazır
   şerit bir kez üretilir; mürekkep rengi `--text` değişkeninden geldiği
   için piksel yenilemesi gerekir (DOM'u yeniden kurmadan).

   DARBOKAZ DÜZELTMESİ (16 Kasım 2026 CPU-profiler bulgusu): bake
   anahtarı tema mürekkep rengini içerir; tema her değiştiğinde
   GÖRÜNMEYEN panellerdeki 100+ kart da damla damla yeniden
   damgalanıyordu (createNoiseTip tek başına ~350 ms örneklendi) ve
   tema değişimi ~1,2-2 s ana iş parçacığı duraklamasına dönüşüyordu.
   Şimdi yalnızca görünür önizlemeler boyanır; gizliler "bayat"
   işaretlenir ve panel görünür olduğunda bir kez boyanır. */
function inkPreviewCanvasVisible(canvas) {
  if (!canvas || !canvas.isConnected) return false;
  /* offsetParent, bir ata display:none iken null olur. Önizleme
     kanallarındaki tuvallerin kendisi position:fixed değil; sabit
     konumlu ata içindekilerde de null dönmez. */
  return canvas.offsetParent !== null;
}

/** Bayat önizlemeleri boşa boyamayı önle: gizli kartları atla, iz bırak. */
function inkNativeRefreshPreviews() {
  let stale = 0;
  const list = inkNativeBrushUi.els.list;
  if (list) {
    const compact = !!inkNativeBrushUi.creatorOnly;
    list.querySelectorAll('.nbBrushCard').forEach(card => {
      const brush = typeof inkGetBrush === 'function' ? inkGetBrush(card.dataset.brushId) : null;
      const canvas = card.querySelector('.nbBrushCard__canvas');
      if (!brush || !canvas) return;
      if (!inkPreviewCanvasVisible(canvas)) {
        card.dataset.nbPreviewStale = '1';
        stale++;
        return;
      }
      if (card.dataset.nbPreviewStale) delete card.dataset.nbPreviewStale;
      inkPaintPreviewAsync(canvas, brush, compact ? {
        width: 150,
        height: 46,
        sizePx: Math.max(2, Math.min(16, brush.size * 0.22 + 2)),
      } : {
        width: 620,
        height: 78,
        sizePx: Math.max(3, Math.min(24, brush.size * 0.32 + 2)),
      });
    });
  }
  document.querySelectorAll('#inkPresetList .inkPreset').forEach(btn => {
    const brush = typeof inkGetBrush === 'function' ? inkGetBrush(btn.dataset.brushId) : null;
    const canvas = btn.querySelector('.inkPresetPreview');
    if (!brush || !canvas) return;
    if (!inkPreviewCanvasVisible(canvas)) {
      btn.dataset.nbPreviewStale = '1';
      stale++;
      return;
    }
    if (btn.dataset.nbPreviewStale) delete btn.dataset.nbPreviewStale;
    inkPaintPreviewAsync(canvas, brush, { width: 72, height: 38 });
  });
  /* En az bir gizli kart atlandıysa bayatlık işareti konur; panel
     görünür olduğunda inkPreviewFlushStale() bir kez boyar. */
  if (stale) inkNativeBrushUi.previewDirty = true;
  if (typeof inkPreviewBrush === 'function') inkPreviewBrush();
  if (typeof inkNativeSyncCustomCreator === 'function') inkNativeSyncCustomCreator();
}

/** Panellerin görünür olduğu anlarda çağrılır: tema değişimi sırada
    gizli kalan önizlemeleri şimdi boyar (boş çağrı ~0 maliyet). */
function inkPreviewFlushStale() {
  if (!inkNativeBrushUi.previewDirty) return;
  inkNativeBrushUi.previewDirty = false;
  inkNativeRefreshPreviews();
}

function inkNativeSync() {
  /* Tema değişimi sırada gizli kalan önizlemeleri boşalt (boş çağrı ~0 ms). */
  if (inkNativeBrushUi.previewDirty && typeof inkPreviewFlushStale === 'function') {
    try { inkPreviewFlushStale(); } catch { /* sessiz */ }
  }
  if (!inkNativeBrushUi.els.root) return;
  const ink = inkState();
  const active = inkGetBrush(ink.brushId);
  const visibleCategories = inkNativeVisibleCategories();
  if (active && active.category &&
      visibleCategories.some(category => category.id === active.category)) {
    inkNativeBrushUi.activeCategory = active.category;
  } else if (!visibleCategories.some(category => category.id === inkNativeBrushUi.activeCategory)) {
    inkNativeBrushUi.activeCategory = visibleCategories[0]?.id || '';
  }

  const nav = inkNativeBrushUi.els.categories;
  if (nav) {
    nav.querySelectorAll('.nbCategory').forEach(btn => {
      const on = btn.dataset.category === inkNativeBrushUi.activeCategory;
      btn.classList.toggle('is-active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
  }

  const list = inkNativeBrushUi.els.list;
  const listKey = inkNativeBrushUi.creatorOnly ? '__creator__' : inkNativeBrushUi.activeCategory;
  if (list && list.dataset.category !== listKey) {
    inkNativeRenderBrushList();
  } else if (list) {
    const selectedId = inkNativeBrushUi.creatorOnly
      ? inkNativeBrushUi.creatorBaseId : active.id;
    list.querySelectorAll('.nbBrushCard').forEach(card => {
      const on = card.dataset.brushId === selectedId;
      card.classList.toggle('is-active', on);
      card.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  }
  inkNativeSyncMeta();
  inkNativeSyncCustomCreator();

  document.querySelectorAll('#inkPresetList .inkPreset').forEach(btn => {
    const on = btn.dataset.brushId === active.id;
    btn.classList.toggle('active', on);
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
}

function inkNativeRenderAll() {
  inkNativeRenderCategories();
  inkNativeRenderBrushList();
  inkNativeSyncMeta();
  inkNativeSyncDualBrushOptions();
  inkNativeSync();
}

function inkNativeSyncDualBrushOptions() {
  const select = document.getElementById('nativeBrushCustomDualBrush');
  if (!select) return;
  const selected = select.value;
  const brushes = inkNativeVisibleBrushes();
  select.replaceChildren(new Option('Off', ''));
  for (const brush of brushes) {
    select.add(new Option(brush.name, brush.id));
  }
  select.value = brushes.some(brush => brush.id === selected) ? selected : '';
}

function inkOpenNativeBrushLibrary(anchor, categoryId, options = {}) {
  const root = inkNativeBrushUi.els.root;
  if (!root) return;
  const creatorOnly = !!options.creatorOnly;
  inkNativeBrushUi.lastFocus = anchor || document.activeElement;
  inkNativeBrushUi.creatorOnly = creatorOnly;
  if (inkNativeVisibleCategories().some(cat => cat.id === categoryId)) {
    inkNativeBrushUi.activeCategory = categoryId;
  } else {
    try {
      const active = inkGetBrush(inkState().brushId);
      if (active && inkNativeVisibleCategories().some(cat => cat.id === active.category)) {
        inkNativeBrushUi.activeCategory = active.category;
      }
    } catch { /* sessiz */ }
  }
  root.classList.toggle('nbOverlay--creator-only', creatorOnly);
  if (creatorOnly) {
    inkNativeSyncCreatorCategoryOptions(inkNativeBrushUi.activeCategory);
  }
  inkNativeRenderAll();
  if (inkNativeVisibleCategories().some(cat => cat.id === categoryId)) {
    inkNativeBrushUi.activeCategory = categoryId;
    inkNativeRenderCategories();
    inkNativeRenderBrushList();
    inkNativeSyncMeta();
  }
  root.setAttribute('aria-label', creatorOnly ? 'Brush creator' : 'Brush library');
  const title = root.querySelector('.nbHead h2');
  if (title) title.textContent = creatorOnly ? 'CREATE YOUR OWN BRUSH' : 'BRUSH LIBRARY';
  if (inkNativeBrushUi.els.close) {
    inkNativeBrushUi.els.close.setAttribute(
      'aria-label', creatorOnly ? 'Close the brush creator' : 'Close library'
    );
  }
  root.hidden = false;
  root.setAttribute('aria-hidden', 'false');
  document.body.classList.add('native-brush-open');
  requestAnimationFrame(() => {
    const close = inkNativeBrushUi.els.close;
    if (close) close.focus();
  });
}

function inkCloseNativeBrushLibrary() {
  const root = inkNativeBrushUi.els.root;
  if (!root || root.hidden) return;
  root.hidden = true;
  root.setAttribute('aria-hidden', 'true');
  root.classList.remove('nbOverlay--creator-only');
  inkNativeBrushUi.creatorOnly = false;
  root.setAttribute('aria-label', 'Brush library');
  const title = root.querySelector('.nbHead h2');
  if (title) title.textContent = 'BRUSH LIBRARY';
  if (inkNativeBrushUi.els.close) {
    inkNativeBrushUi.els.close.setAttribute('aria-label', 'Close library');
  }
  document.body.classList.remove('native-brush-open');
  const focus = inkNativeBrushUi.lastFocus;
  if (focus && focus.isConnected && typeof focus.focus === 'function') {
    try { focus.focus(); } catch { /* sessiz */ }
  }
}

function inkInitNativeBrushLibrary() {
  const els = inkNativeBrushUi.els;
  els.root = document.getElementById('nativeBrushLibrary');
  if (!els.root) return;
  els.close = document.getElementById('nativeBrushClose');
  els.categories = document.getElementById('nativeBrushCategories');
  els.list = document.getElementById('nativeBrushList');
  els.categoryTitle = document.getElementById('nativeBrushCategoryTitle');
  els.categoryHint = document.getElementById('nativeBrushCategoryHint');
  els.count = document.getElementById('nativeBrushCount');
  els.creatorPreview = document.getElementById('nativeBrushCreatorPreview');
  els.creatorControls = document.getElementById('nativeBrushCustomControls');
  els.creatorDelete = document.getElementById('nativeBrushCustomDelete');
  els.creatorPng = document.getElementById('nativeBrushCustomPng');
  els.creatorPngButton = document.getElementById('nativeBrushCustomPngButton');
  els.creatorPngClear = document.getElementById('nativeBrushCustomPngClear');
  els.creatorPngStatus = document.getElementById('nativeBrushCustomPngStatus');
  els.testCanvas = document.getElementById('nativeBrushCreatorTestCanvas');
  els.testLive = document.getElementById('nativeBrushCreatorTestLive');
  els.testColor = document.getElementById('nativeBrushCreatorTestColor');
  els.testClear = document.getElementById('nativeBrushCreatorTestClear');
  els.testUndo = document.getElementById('nativeBrushCreatorTestUndo');

  if (!inkNativeBrushUi.bound) {
    inkNativeBrushUi.bound = true;
    inkNativeCreatorTestBind();
    document.addEventListener('pointerdown', event => {
      if (inkNativeBrushUi.contextMenu &&
          !inkNativeBrushUi.contextMenu.contains(event.target)) {
        inkNativeCloseContextMenu();
      }
    }, true);
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !inkNativeBrushUi.contextMenu) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      inkNativeCloseContextMenu();
    }, true);
    els.close?.addEventListener('click', () => inkCloseNativeBrushLibrary());
    els.categories?.addEventListener('contextmenu', event => {
      const target = event.target instanceof Element
        ? event.target.closest('.nbCategory') : null;
      if (!target) return;
      const category = inkNativeCategoryById(target.dataset.category);
      if (!category) return;
      const count = inkNativeBrushesForCategory(category.id).length;
      const actions = [{
        label: count
          ? 'Export as .abr (' + count + ' brush)'
          : 'Export as .abr',
        disabled: count === 0,
        run: () => inkNativeExportCategoryAbr(category.id),
      }];
      if (category.virtual) {
        actions.push({
          label: 'Clear favorites',
          disabled: count === 0,
          run: () => inkNativeClearFavorites(),
        });
      } else {
        actions.push({
          label: 'Delete the category and its brushes',
          run: () => inkNativeDeleteCategory(category.id),
        });
      }
      inkNativeShowContextMenu(event, actions);
    });
    els.list?.addEventListener('contextmenu', event => {
      const target = event.target instanceof Element
        ? event.target.closest('.nbBrushCard') : null;
      if (!target) return;
      const brush = inkState().brushes.find(item => item.id === target.dataset.brushId);
      if (!brush) return;
      const isDefault = inkNativeIsDefaultBrush(brush);
      const favorite = inkNativeIsFavorite(brush.id);
      const x = event.clientX;
      const y = event.clientY;
      inkNativeShowContextMenu(event, [{
        label: favorite ? 'Remove from favorites' : 'Add to favorites',
        run: () => inkNativeToggleFavorite(brush.id),
      }, {
        label: 'Export as .abr',
        run: () => inkNativeExportBrushAbr(brush),
      }, {
        label: 'Move to category…',
        disabled: isDefault,
        run: () => inkNativeShowMoveCategoryMenu(brush, x, y),
      }, {
        label: isDefault ? 'Preset brushes cannot be deleted' : 'Delete brush',
        disabled: isDefault,
        run: () => inkNativeDeleteBrush(brush.id),
      }]);
    });
    els.root.addEventListener('pointerdown', event => {
      const target = event.target instanceof Element ? event.target : null;
      if (!target) return;
      if (target.closest('[data-nb-close]')) inkCloseNativeBrushLibrary();
    });
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || els.root.hidden) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      inkCloseNativeBrushLibrary();
    }, true);
    document.getElementById('btnOpenBrushLibrary')?.addEventListener('click', event => {
      event.preventDefault();
      inkOpenNativeBrushLibrary(event.currentTarget);
    });
    /* LAG DÜZELTMESI: slider 'input' sürükleme boyunca kare başına
       çok kez yanar; senkronu rAF ile kare başına BİR kez indirger
       (aradaki olaylar birleşir — son durum boyanır). */
    let creatorSyncQueued = 0;
    const updateCreator = () => {
      if (creatorSyncQueued) return;
      creatorSyncQueued = requestAnimationFrame(() => {
        creatorSyncQueued = 0;
        inkNativeSyncCustomCreator();
      });
    };
    document.getElementById('nativeBrushCustomName')?.addEventListener('input', updateCreator);
    els.creatorControls?.addEventListener('input', updateCreator);
    els.creatorControls?.addEventListener('change', updateCreator);
    els.creatorPngButton?.addEventListener('click', () => els.creatorPng?.click());
    els.creatorPng?.addEventListener('change', async () => {
      const file = els.creatorPng.files && els.creatorPng.files[0];
      els.creatorPng.value = '';
      if (!file) return;
      try {
        const uploaded = await inkNativeBrushTipFromPng(file);
        inkNativeBrushUi.uploadedTip = uploaded;
        if (els.creatorPngStatus) {
          els.creatorPngStatus.textContent =
            uploaded.name + ' · ' + uploaded.width + '×' + uploaded.height + ' PNG tip ready.';
        }
        inkLoadAbrTip(uploaded.tipId);
        updateCreator();
      } catch (error) {
        if (els.creatorPngStatus) {
          els.creatorPngStatus.textContent = error && error.message
            ? error.message : 'PNG image could not be imported.';
        }
      }
    });
    els.creatorPngClear?.addEventListener('click', () => {
      const uploaded = inkNativeBrushUi.uploadedTip;
      inkNativeBrushUi.uploadedTip = null;
      if (uploaded && !inkState().brushes.some(brush => brush.tipId === uploaded.tipId)) {
        inkRuntime.importedTips.delete(uploaded.tipId);
        inkRuntimeBrushes.abrImages.delete(uploaded.tipId);
      }
      if (els.creatorPngStatus) {
        els.creatorPngStatus.textContent =
          'Transparent PNG recommended; a white background is converted to a mask automatically.';
      }
      updateCreator();
    });
    document.getElementById('nativeBrushCustomCreate')?.addEventListener('click', async () => {
      const brush = inkNativeCustomBrushFromForm();
      const status = document.getElementById('nativeBrushCreatorStatus');
      if (!brush.name) {
        if (status) status.textContent = 'Give the brush a name.';
        document.getElementById('nativeBrushCustomName')?.focus();
        return;
      }
      const ink = inkState();
      ink.deletedCategories = (ink.deletedCategories || [])
        .filter(id => id !== brush.category);
      const duplicate = inkNativeFindSameCustomBrush(ink.brushes, brush);
      if (duplicate) {
        inkNativeBrushUi.activeCategory = duplicate.category || 'custom';
        setActiveBrush(duplicate.id);
        inkNativeRenderAll();
        if (status) {
          status.textContent = 'Bu ayarlarla “' + duplicate.name +
            '” already exists; no new copy was created, the existing brush was selected.';
        }
        return;
      }
      ink.brushes.push(brush);
      inkNativeBrushUi.activeCategory = brush.category;
      setActiveBrush(brush.id);
      inkNativeRenderAll();
      if (status) status.textContent = '“' + brush.name + '” created and saved.';
      if (brush.kind === 'abr' && brush.tipId) inkLoadAbrTip(brush.tipId);
      // Proje kaydı manuel modda olsa bile fırça kütüphanesi hemen
      // IndexedDB'ye yazılır; "Save" alınmasa da fırça kaybolmaz.
      await inkNativePersistLibraryAll();
      if (typeof scheduleSave === 'function') scheduleSave();
    });
    els.creatorDelete?.addEventListener('click', async () => {
      const ink = inkState();
      const brush = inkGetBrush(ink.brushId);
      if (!brush || inkNativeIsDefaultBrush(brush)) return;
      const deleted = await inkNativeDeleteBrush(brush.id);
      if (deleted) {
        const status = document.getElementById('nativeBrushCreatorStatus');
        if (status) status.textContent = 'Custom brush deleted.';
      }
    });
  }
  /* AÇILIŞ: gizli kütüphane panelinin tam kurulumu (kategoriler +
     ~40 kart önizlemesi) boş-zamanda koşar. Kullanıcı paneli açarsa
     inkOpenNativeBrushLibrary senkron yeniden kurar; kurulum
     daha önce yapılmamış olsa bile sonuç aynıdır. */
  inkNativeWhenIdle(inkNativeRenderAll);
  inkNativeCreatorTestSyncButtons();
  requestAnimationFrame(inkNativeCreatorTestRender);
}

/* 31-ink-ui.js içindeki eski fırça şeridi bu iki köprüyü kullanır. */
function inkRenderNativeQuickBrushes() {
  inkNativeRenderQuickBrushes();
}

function inkSyncNativeBrushLibrary() {
  inkNativeSync();
}

/* TailRef app · ink compositor · Porter–Duff tek doğruluk kaynağı
   ------------------------------------------------------------------
   Bu modül, görsele bağlı katman yığınının GÖRÜNTÜ alanı planını üretir.
   Ekran (DOM), editör önizlemesi ve PNG dışa aktarım AYNI planı ve AYNI
   grup rasterını kullanmak zorundadır; aksi hâlde ekranla dışa aktarım
   farklı görünebiliyordu (ekran CSS mix-blend-mode → tüm DOM arka planı,
   dışa aktarım globalCompositeOperation → yalnızca tuval).

   Porter–Duff semantiği (premultiplied yaklaşım, Canvas2D karşılığıyla):

   • source-over  : normal boyama.  a_o = a_s + a_d(1 − a_s)
   • source-atop  : ALFA KİLİDİ ve KIRPMA MASKESİ. Yalnızca hedef alfasının
                    olduğu yere basar.  a_o = a_d;  C_o = C_s·a_d + C_d(1 − a_s)
   • destination-out : silgi. a_o = a_d(1 − a_s)

   Grup / kırpma modeli (referans uygulama anlambilimi):
     Bir katman `clip: true` ise, hemen altındaki ilk görünür "temel"
     katmana kırpılır; ardışık kırpılanlar AYNI temele zincirlenir.
     Temel gizliyse/zayıf görünmezse tüm zincir de görünmez olur.
     Görünstleride grup tek bir pikselden (buffer) bir düzlem olarak
     üstteki yığına girer: buffer = base OVER-RASTER sonra her clip
     source-atop ile buffer'a bırakılır.

   Ayrıca konuşan EDM: map/cache işlemlerine bellek dikkatini getirmek adına
   bu modül ayrı bir `55-ink-mask.js`'e bağımlılığı yoktur.
   ========================================================= */
'use strict';

/* Bellek: katman piksel generations. Herhangi bir katman tuvali boyandığında
   artar; grup raster önbellekleri geçerlilik imzasında bunları kullanır. */
const inkCompositeRuntime = {
  gen: new Map(),        // layerId -> sayı (raster sürümü)
  groups: new Map(),     // baseLayerId -> { canvas, sig, w, h }
};

function inkBumpLayerGen(layerId) {
  if (!layerId) return;
  const cur = inkCompositeRuntime.gen.get(layerId) || 0;
  inkCompositeRuntime.gen.set(layerId, cur + 1);
}

function inkLayerGen(layerId) {
  return inkCompositeRuntime.gen.get(layerId) || 0;
}

/* =========================================================
   Görüntü planı (bottom → top)
   ========================================================= */

/** Bir görselin ekran sırasındaki planı: her giriş ya tek katman, bir
 *  kırpma grubu (base + clipMembers) ya da bir klasör grubu (kind:'group'
 *  + parentId üyeleri, FAZ 1) olur. Gizli/zayıf temeller zinciri taşır
 *  (barrier) AMA görüntüde görünmez.
 *
 *  Düzlem dizinde klasör: [üye1, üye2, ..., GRUP] (alttan → üste)
 *  — üyeler klasör girişinin hemen ALTINDA bitişik tablo. Gezgin bunları
 *  toplayıp tek plan girişine bağlamadan önce geçersiz üye arasına
 *  düz katman girerse (bozuk parent) üyeleri sıradan katman olarak
 *  bırakır; plan içinde ayrımı bozmaz. */
function inkAttachedDisplayPlan(ownerId) {
  const layers = typeof inkOwnerStackLayers === 'function'
    ? inkOwnerStackLayers(ownerId)
    : (typeof inkLayersForOwner === 'function' ? inkLayersForOwner(ownerId) : []);
  const plan = [];
  let pendingMembers = null;
  const flushOrphanMembers = () => {
    if (!pendingMembers) return;
    /* Bitişik olmayan üye: klasör düzlemine giremez AMA üyeliği gerçektir
       (panel parentId gösterir). `bound` ile klasörüne bağlanır — klasörün
       görünürlük/opaklığı bu üyeye de uygulanır. Değişmez: paneldeki üyelik
       ile kompozitörün davranışı ASLA ayrışmaz (hayalet üye yok). */
    for (const member of pendingMembers) {
      plan.push({ base: member, clips: null, members: null, bound: member.parentId || null });
    }
    pendingMembers = null;
  };
  for (const layer of layers) {
    if (layer.kind === 'group') {
      // Klasör: o ana dek biriktirilen bitişik üyeler bu giriş içine girer.
      plan.push({ base: layer, clips: null, members: pendingMembers || [] });
      pendingMembers = null;
    } else if (layer.parentId) {
      (pendingMembers = pendingMembers || []).push(layer);
    } else {
      flushOrphanMembers();
      if (layer.clip && plan.length && plan[plan.length - 1].base.ownerId === layer.ownerId) {
        const entry = plan[plan.length - 1];
        if (!entry.clips) entry.clips = [];
        entry.clips.push(layer);
      } else {
        plan.push({ base: layer, clips: null });
      }
    }
  }
  flushOrphanMembers();
  return plan;
}

/** Plan girişinin bağlı olduğu klasör: `bound` yalnız bitişik olmayan
 *  klasör üyelerinde doludur (üyelik gerçeği — panel parentId). */
function inkBoundGroupOf(entry) {
  return entry && entry.bound && typeof inkLayerById === 'function'
    ? inkLayerById(entry.bound) : null;
}

/** Plan girişi görünür mü? Temel görünür + opak > 0 ise giriş görünür.
 *  Klasöre bağlı (bound) bağımsız üyelerde klasörün görünürlüğü de taşınır. */
function inkPlanEntryVisible(entry) {
  if (!entry || !entry.base) return false;
  if (entry.base.visible === false || entry.base.opacity <= 0.001) return false;
  const bound = inkBoundGroupOf(entry);
  if (bound && (bound.visible === false || (bound.opacity ?? 1) <= 0.001)) return false;
  return true;
}

/* =========================================================
   grup raster üretimi
   ========================================================= */

/** base'den grup tuvali piksel boyutu: base'in kendi pxW/pxH'yi kullanılır;
 *  clip üyeleri aynı boyuta ölçeklenerek basılır (aynı görselin katmanları
 *  normalde zaten aynı boyuttadır). */
function inkGroupSizePixels(entry) {
  const base = entry.base;
  let w = Number.isFinite(base.pxW) && base.pxW > 0 ? base.pxW : 0;
  let h = Number.isFinite(base.pxH) && base.pxH > 0 ? base.pxH : 0;
  if (!w || !h) {
    const it = typeof getItem === 'function' ? getItem(base.ownerId) : null;
    w = w || Math.max(64, Math.round(it ? it.w : 256));
    h = h || Math.max(64, Math.round(it ? it.h : 256));
  }
  return { w, h };
}

function inkMemberRasterOf(layer, override) {
  if (override && override.get(layer.id)) return override.get(layer.id);
  return inkRuntime && inkRuntime.itemCanvases
    ? inkRuntime.itemCanvases.get(layer.id)
    : null;
}

function inkGroupCacheSig(entry, w, h, override) {
  const parts = [w, 'x', h, entry.base.kind || 'attached'];
  // Klasör durum: [üyeler..., base] (alttan → üste); üye boyutu klasör
  // yapısını yeniden üretitmeye zorlar (besim genleri değiştikçe).
  const members = (entry.members || []).concat([entry.base], entry.clips || []);
  for (const layer of members) {
    if (override && override.has(layer.id)) {
      parts.push(layer.id, '#live');
    } else {
      parts.push(layer.id, inkLayerGen(layer.id),
        Math.round((layer.opacity ?? 1) * 1000), layer.blend || 'normal',
        layer.clip ? 1 : 0, layer.visible === false ? 'gizli' : '');
    }
  }
  return parts.join('|');
}

/** Plan girişinin buffer'a bileştirilecek katmanlarını (alttan → üste)
 *  döndürür: klasör ise [üyeler..., clip üyeleri], kırpma zinciri ise
 *  [temel, ...clips]. Klasörün kendisi zabıt pikselsizdir; tek katman
 *  girişi direkt kaynak tuvaliyle geçer. */
function inkCompositeCompositeLayers(entry) {
  const paintList = [];
  if (entry.members && entry.members.length) {
    for (const member of entry.members) paintList.push({ layer: member, over: true });
  } else if (entry.base.kind !== 'group') {
    /* Giriş tabanı: opaklık/blend ekranda grup düzleminde uygulanır
       (flat) — buffer'a pişirilirse çifte uygulanır. */
    paintList.push({ layer: entry.base, over: true, flat: true });
  }
  for (const layer of entry.clips || []) paintList.push({ layer, over: false });
  return paintList.length ? paintList : null;
}

/**
 * Plan girişinin tek düzlem rasterını üretir (bellek önbellekli).
 * Kırpma zinciri VE klasör grubu için ortak yoldur: alttan → üste
 * `inkCompositeCompositeLayers` listesindeki her tuval kendi opaklığıyla
 * basılır; klip üyeleri (over:false) daha önce basılan alfanın İÇİNE
 * düşer (source-atop). Klasörün kendi düzlemi pikselsizdir — yalnızca
 * görünürlük/opaklık/blend taşıyıcısıdır.
 * @param {object} entry plan girişi ({ base, clips, members })
 * @param {Map<string,CanvasRenderingContext2D>} override canlı önizleme
 *        ikameleri (girdi varsa önbellek baypas edilir).
 * @returns {HTMLCanvasElement|null}
 */
function inkCompositeGroupRaster(entry, override) {
  if (!entry || !entry.base) return null;
  const clips = entry.clips || [];
  const members = entry.members || [];
  const baseRaster = inkMemberRasterOf(entry.base, override);
  if (!baseRaster && !clips.length && !members.length) return null;
  // Kırpma zincirsiz tek katman girişi: birleşik raster yok, kaynak gider.
  if (baseRaster && !clips.length && !members.length && !override) return baseRaster;

  const { w, h } = inkGroupSizePixels(entry);
  const sig = inkGroupCacheSig(entry, w, h, override);
  const cacheKey = entry.base.id;
  if (!override) {
    const cached = inkCompositeRuntime.groups.get(cacheKey);
    if (cached && cached.sig === sig && cached.canvas && cached.canvas.width === w
        && cached.canvas.height === h) {
      return cached.canvas;
    }
  }

  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d', { colorSpace: 'srgb' });
  if (!ctx) return null;
  ctx.clearRect(0, 0, w, h);

  // Buffer'a basılacak katman listesi (paintList null olamaz: girdi bu
  // fonksiyona yalnızca çok katmanlı girişlerden ulaşır).
  const paintList = inkCompositeCompositeLayers(entry) || [];
  ctx.save();
  for (const unit of paintList) {
    const layer = unit.layer;
    const raster = inkMemberRasterOf(layer, override);
    if (!raster || layer.visible === false || layer.opacity <= 0.001) continue;
    /* Klip üyeleri: katı atop — süründüğü pager alfa boşsa görünmez
       (referans uygulama anlambilimi). Üyeler: kendi blend'i, taban/klip
       olmadıkça source-over. */
    ctx.globalCompositeOperation = unit.over
      ? (!unit.flat && layer.blend && layer.blend !== 'normal'
        ? layer.blend : 'source-over')
      : 'source-atop';
    ctx.globalAlpha = unit.flat ? 1 : Math.min(1, Math.max(0, layer.opacity ?? 1));
    ctx.drawImage(raster, 0, 0, w, h);
  }
  ctx.restore();

  if (!override) {
    inkCompositeRuntime.groups.set(cacheKey, { canvas, sig, w, h });
  }
  return canvas;
}

/** Plan girişinin ekran/piksel dışa aktarım kaynak tuvalini döndürür. */
function inkCompositeEntryCanvas(entry, override) {
  if (!entry) return null;
  if ((entry.clips && entry.clips.length) || (entry.members && entry.members.length)) {
    const raster = inkCompositeGroupRaster(entry, override);
    // Grup rasterı boyutsuz kalırsa (tuval yoksa) temele düş.
    if (raster && (raster.width || raster.height)) return raster;
  }
  return inkMemberRasterOf(entry.base, override);
}

/** Plan girişinin görüntü opaklığı: gruplar temel opaklığını taşır
 *  (üküye opaklığı rasterde işlenmiştir). Klasöre bağlı (bound) bağımsız
 *  üyede klasörün opaklığı da çarpan olarak girer. */
function inkCompositeEntryOpacity(entry) {
  const base = entry.base;
  let o = Number.isFinite(base.opacity) ? base.opacity : 1;
  const bound = inkBoundGroupOf(entry);
  if (bound) o *= Number.isFinite(bound.opacity) ? bound.opacity : 1;
  return Math.min(1, Math.max(0, o));
}

function inkCompositeEntryBlend(entry) {
  return entry.base && entry.base.blend && entry.base.blend !== 'normal'
    ? entry.base.blend
    : null;
}

/** Plan girişinin üye katman id'leri: klasörse [grup, ...üyeler],
 *  kırpma zinciriyse [temel, ...clips]. Ekran senkronu member tuvalleri
 *  bu listeden gizler/kurtarır. */
function inkCompositeEntryMembers(entry) {
  if (entry.members && entry.members.length) {
    /* Grup düzleminin kendi tuvali yoktur; id'si yine akışta olsun,
       temizlik senkronu (stale) buna dayanır. */
    return [entry.base.id, ...entry.members.map(l => l.id)];
  }
  return entry.clips && entry.clips.length
    ? [entry.base.id, ...entry.clips.map(l => l.id)]
    : null;
}

/* =========================================================
   EKRAN (DOM) birleştirme · görsele bağlı katman tuvalleri
   ========================================================= */

function inkCompositeSyncItem(it, el) {
  if (!it || !el || it.kind !== 'image') return;
  const layers = typeof inkOwnerStackLayers === 'function'
    ? inkOwnerStackLayers(it.id)
    : (typeof inkLayersForOwner === 'function' ? inkLayersForOwner(it.id) : []);
  if (!layers.length) return;
  /* FX dalı (Faz 1 — docs/fx-motoru-spec.md Bölüm 6): etkin efekt varsa
     görüntüyü TEK .inkFxCanvas taşır; katman/grup tuvalleri gizlenir.
     Ekran ile export AYNI inkFxApplyChain'i kullanır (piksel birebir). */
  if (typeof inkFxSyncItem === 'function' && inkFxSyncItem(it, el)) return;
  // Kırpma zinciri VE klasör üyeliği (parentId) birleşik düzlem gerektirir.
  const hasComposite = layers.some(
    l => l.clip || l.parentId || l.kind === 'group');
  if (!hasComposite) {
    // Grupsuz görünüm: eski grup tuvallerini kaldır, üye tuvalleri serbest bırak.
    for (const g of el.querySelectorAll(':scope > .inkGroupCanvas')) g.remove();
    for (const layer of layers) {
      if (!layer.visible || layer.opacity <= 0.001) continue;
      const canvas = inkRuntime && inkRuntime.itemCanvases.get(layer.id);
      if (canvas && canvas.style.display === 'none') canvas.style.display = '';
    }
    return;
  }

  const plan = inkAttachedDisplayPlan(it.id);
  for (const entry of plan) {
    const members = inkCompositeEntryMembers(entry);
    if (!members || !inkPlanEntryVisible(entry)) {
      // Görünmeyen grup: üyeler gizli kalır (grubun görünürlüğü onları taşır).
      const stale = el.querySelector(':scope > .inkGroupCanvas[data-ink-base="' + entry.base.id + '"]');
      if (stale) stale.remove();
      continue;
    }
    const raster = inkCompositeEntryCanvas(entry, null);
    if (!raster || !raster.width || !raster.height) continue;

    let groupCanvas = el.querySelector(
      ':scope > .inkGroupCanvas[data-ink-base="' + entry.base.id + '"]');
    if (!groupCanvas) {
      groupCanvas = document.createElement('canvas');
      groupCanvas.className = 'inkGroupCanvas';
      groupCanvas.dataset.inkBase = entry.base.id;
      groupCanvas.setAttribute('aria-hidden', 'true');
      const handles = el.querySelector(':scope > .handles');
      const baseEl = inkRuntime && inkRuntime.itemCanvases.get(entry.base.id);
      // Tutamaçlardan önce, katman tuvalleriyle aynı yığına yerleşir.
      if (handles) el.insertBefore(groupCanvas, handles);
      else if (baseEl && baseEl.parentNode === el) el.insertBefore(groupCanvas, null);
      else el.appendChild(groupCanvas);
    }
    if (groupCanvas.width !== raster.width || groupCanvas.height !== raster.height) {
      groupCanvas.width = raster.width;
      groupCanvas.height = raster.height;
    }
    const gctx = groupCanvas.getContext('2d', { colorSpace: 'srgb' });
    gctx.setTransform(1, 0, 0, 1, 0, 0);
    gctx.clearRect(0, 0, groupCanvas.width, groupCanvas.height);
    gctx.drawImage(raster, 0, 0);

    // Grup, temel katmanın z sırasını, opaklığını ve blend modunu taşır.
    // Z tabanı: attached + group karışık yığın (plan ile aynı liste).
    const stacked = layers;
    const idx = Math.max(0, stacked.findIndex(l => l.id === entry.base.id));
    groupCanvas.dataset.inkLayer = entry.base.id;
    groupCanvas.style.zIndex = String(2 + idx);
    groupCanvas.style.opacity = String(inkCompositeEntryOpacity(entry));
    const blend = inkCompositeEntryBlend(entry);
    groupCanvas.style.mixBlendMode = blend ? blend : 'normal';
    groupCanvas.style.display = 'block';
  }

  // Grupta/kırpma zincirinde yer alan üye tuvalleri gözden gizle
  // (rasterın kendisi canlı kalır).
  for (const entry of plan) {
    const members = inkCompositeEntryMembers(entry);
    if (!members) continue;
    for (const memberId of members) {
      if (memberId === entry.base.id && entry.base.kind === 'group') continue;
      const canvas = inkRuntime && inkRuntime.itemCanvases.get(memberId);
      if (canvas) canvas.style.display = 'none';
    }
  }
  // Grupta/kırpma zincirinde olmayan katmanların tuvalleri normal akışta kalır.
  // Üyelik (girişe dahil olma) görünürlükten bağımsızdır: gizli grubun
  // üyeleri sırıtmamalı (restore edilirse yarı şeffaf ikizler çizilirdi).
  for (const layer of layers) {
    if (layer.kind !== 'attached') continue;
    const belongs = plan.some(entry => {
      const members = inkCompositeEntryMembers(entry);
      return !!(members && members.includes(layer.id));
    });
    if (!belongs && layer.visible && layer.opacity > 0.001) {
      const canvas = inkRuntime && inkRuntime.itemCanvases.get(layer.id);
      if (canvas && canvas.style.display === 'none') canvas.style.display = '';
    }
  }
}

/** Raster üretiminden sonra grup önbelleklerini geçersiz kılmak gerekir;
 *  gen sayaçları bunu zaten sağlar (inkBumpLayerGen). */
function inkCompositeInvalidate(ownerId) {
  if (ownerId) inkCompositeRuntime.groups.delete(ownerId);
}

/* =========================================================
   kırpma / alfa kilidi yardımcı API (panel + köprü kullanır)
   ========================================================= */

/** Bir katmanı kırpılabilir yapar: üstünde bir clip üyesi veya base olabildiği
 *  yalnızca altında başka katmanlar varken etkilidir. */
function inkCanToggleClip(layerId) {
  const layer = typeof inkLayerById === 'function' ? inkLayerById(layerId) : null;
  if (!layer || layer.kind !== 'attached') return false;
  // FAZ 1 (gruplar): klasör üyesi zaten grup alfasına bağlıdır — ikinci kırpma yok.
  if (layer.parentId) return false;
  const ownerId = layer.ownerId;
  const stack = inkLayersForOwner(ownerId);
  return stack.indexOf(layer) > 0;
}

/** FAZ 1 (piksel-gerçek merge-down): kaynak katmanın rasterını alt
 *  katmanın rasterının ÜZERİNE render kurallarıyla (kaynak opaklığı +
 *  kaynak blend) birleştirir ve dataURL döndürür. Alt katmanın kendi
 *  blend/opaklığı ekran düzeyinde kalır (çifte uygulama yok).
 *  Kırpma semantiği korunur: kaynak bir klip üyesiyse YALNIZCA zincir
 *  tabanı alt katmanın kendisiyken kabul edilir ve atop ile basılır.
 *  @returns {{src, w, h}|null} pişen görüntü ya da ret.
 */
function inkCompositeMergeDownPixels(source, below) {
  if (!source || source.kind !== 'attached' ||
      !below || below.kind !== 'attached') return null;
  const runtime = (typeof inkRuntime !== 'undefined' && inkRuntime) ? inkRuntime : null;
  if (!runtime) return null;
  const belowCanvas = runtime.itemCanvases.get(below.id);
  const sourceCanvas = runtime.itemCanvases.get(source.id);
  if (!belowCanvas || !belowCanvas.width || !belowCanvas.height) return null;

  // Kırpma zinciri denetimi: kaynak kendi zincirinin tabanıysa
    // (üzerine kırpılan üyeleri varsa) birleştirme reddedilir.
  let sourceOp = 'source-over';
  if (typeof inkAttachedDisplayPlan === 'function') {
    const plan = inkAttachedDisplayPlan(source.ownerId);
    const ownChain = plan.find(e => e.base && e.base.id === source.id &&
      e.clips && e.clips.length);
    if (ownChain) return null;
    const asClip = plan.find(e => e.base && e.base.id !== source.id &&
      e.clips && e.clips.some(l => l.id === source.id));
    if (asClip) {
      // Kaynak klip: zincir tabanı alt katman olmalı (atop doğru olur).
      if (asClip.base.id !== below.id) return null;
      sourceOp = 'source-atop';
    }
  }

  const out = document.createElement('canvas');
  out.width = belowCanvas.width;
  out.height = belowCanvas.height;
  const ctx = out.getContext('2d', { colorSpace: 'srgb' });
  if (!ctx) return null;
  ctx.drawImage(belowCanvas, 0, 0);
  if (sourceCanvas && source.visible !== false && source.opacity > 0.001) {
    ctx.save();
    if (sourceOp === 'source-atop') ctx.globalCompositeOperation = sourceOp;
    else if (source.blend && source.blend !== 'normal') {
      ctx.globalCompositeOperation = source.blend;
    }
    ctx.globalAlpha = Math.min(1, Math.max(0, source.opacity));
    ctx.drawImage(sourceCanvas, 0, 0, out.width, out.height);
    ctx.restore();
  }
  return {
    src: out.toDataURL('image/png'),
    w: out.width, h: out.height,
    canvas: out, // bake önbelleğine senkron koyulmak için (baked'a yazılmaz)
  };
}

/* Alt taraftaki export yardımı: bir görselin plan girişlerini sırayla
   basar (screen ile aynı raster/kural). */function inkCompositePaintPlanToContext(ctx, ownerId, override,
  drawFn) {
  const plan = inkAttachedDisplayPlan(ownerId);
  for (const entry of plan) {
    if (!inkPlanEntryVisible(entry)) continue;
    const raster = inkCompositeEntryCanvas(entry, override);
    if (!raster || !raster.width || !raster.height) continue;
    drawFn(ctx, entry, raster);
  }
}

/** Bir görselin birleşik düzlem içeren katmanları var mı?
 *  (kırpma zinciri veya klasör üyeliği) Panel köprüsü ve render kapısı kullanır. */
function inkCompositeHasClips(ownerId) {
  const layers = typeof inkOwnerStackLayers === 'function'
    ? inkOwnerStackLayers(ownerId)
    : (typeof inkLayersForOwner === 'function' && ownerId
      ? inkLayersForOwner(ownerId) : []);
  return layers.some(l => l.clip || l.parentId || l.kind === 'group');
}

/* TailRef app · ink stabilizer · One-Euro Filter (FAZ 2)
   --------------------------------------------------------------------
   docs/ARCH-RESCUE-PLAN.md FAZ 2 çekirdeği. Bu modül DOM'suz ve saf
   matemattır: hem tarayıcı zincirinde hem de Node tabanlı birim
   testlerde (scripts/ink-stabilizer-test.js) aynı haliyle çalışır.

   One-Euro Filter (Casiez vd., CHI 2012): düşük hızda titremeyi
   bastıran, yüksek hızda gecikmeyi neredeyse sıfıra düşüren adaptif
   low-pass. Klasik EMA'nın aksine "yavaşken yumuşak, hızlıken
   keskin" davranır — tablet titremesi ile çizim gecikmesinin
   sanayide kabul görmüş çözümüdür.

       α(dt, f_c) = 1 / (1 + τ/f_c) tan τ = 1 / (2π·f_c)
       dx'        = lowpass(dx, α(dt, f_d))       türev hattı
       f_c        = f_min + β·|dx'|               hız-adaptif kesim
       x'         = lowpass(x, α(dt, f_c))        konum hattı
   ========================================================= */
'use strict';

/* Fiziksel girdi ölçeği: girdi çerçeveleri CSS pikselidir; 96 dpi
   referanslı OS ölçeğinde 1 CSS px = 25.4/96 mm. Hız artık cihaz-DPR
   pencere-büyüklük tanımsız kalır (FAZ2-2). */
/* var: Node tabanlı birim testte vm sandbox'ına sızmaları için
   (tarayıcıda klasik script üst-level const'tan farkı yoktur). */
var INK_MM_PER_CSS_PX = 25.4 / 96;

function inkEuroAlpha(dtSec, cutoffHz) {
  const tau = 1 / (2 * Math.PI * Math.max(0.001, cutoffHz));
  return 1 / (1 + tau / Math.max(dtSec, 0.001));
}

/** Yumuşatma seviyesi (smoothing 0..0.95) → One-Euro parametreleri.
 *  smoothing=0 → kapalı (null), üstel eğriyle 16 → tam 0.5 Hz iner. */
function inkStabilizerCutoffs(amount) {
  const s = clamp(Number.isFinite(amount) ? amount : 0, 0, 0.95);
  if (s <= 0.001) return null;
  return {
    // min cutoff: küçük = daha yumuşak (0'da 16 Hz, 0.95'te 0.5 Hz).
    minCutoff: 16 * Math.pow(0.5 / 16, s / 0.95),
    // beta: hız arttıkça kesim frekansını yükselten katsayı.
    beta: 0.007 + 0.028 * s,
  };
}

/** Vuruş başına stabilizatör durumu: üç bağımsız kanal (x, y, basınç)
 *  + birleşik zaman. */
function inkStabilizerBegin() {
  return {
    t: 0,
    x: null, xD: null,
    y: null, yD: null,
    p: null, pD: null,
  };
}

function inkEuroStep(stab, x, y, pressure, tMs, cutoffs) {
  if (!Number.isFinite(tMs)) tMs = 0;
  const dtSec = stab.t ? Math.max(0.001, (tMs - stab.t) / 1000) : 0.0167;

  /* — x kanalı —
     Türev hattı ilk gerçek hamlede filtresiz alır (One-Euro makalesinin
     başlatma deseni): hız hemen kesim frekansına destek olur, hızlı
     vuruşta gecikme ilk örnekten itibaren düşük kalır. */
  const hadX = stab.x !== null;
  const dxRaw = hadX ? (x - stab.x) / dtSec : 0;
  const aD = inkEuroAlpha(dtSec, 1.0);
  stab.xD = !hadX ? null
    : (stab.xD === null ? dxRaw : dxRaw * aD + stab.xD * (1 - aD));
  const cutX = cutoffs.minCutoff + cutoffs.beta * Math.abs(stab.xD);
  const aX = inkEuroAlpha(dtSec, cutX);
  /* İlk örnek: filtresiz al (gecikme 0), sonrakiler low-pass. */
  stab.x = stab.x === null ? x : stab.x + (x - stab.x) * aX;

  /* — y kanalı — */
  const hadY = stab.y !== null;
  const dyRaw = hadY ? (y - stab.y) / dtSec : 0;
  stab.yD = !hadY ? null
    : (stab.yD === null ? dyRaw : dyRaw * aD + stab.yD * (1 - aD));
  const cutY = cutoffs.minCutoff + cutoffs.beta * Math.abs(stab.yD);
  const aY = inkEuroAlpha(dtSec, cutY);
  stab.y = stab.y === null ? y : stab.y + (y - stab.y) * aY;

  /* — basınç kanalı — konumdan bağımsız, daha yumuşak kesim */
  const hadP = stab.p !== null;
  const prRaw = hadP ? (pressure - stab.p) / dtSec : 0;
  stab.pD = !hadP ? null
    : (stab.pD === null ? prRaw : prRaw * aD + stab.pD * (1 - aD));
  const cutP = Math.max(1.2, cutoffs.minCutoff);
  const aP = inkEuroAlpha(dtSec, cutP);
  stab.p = stab.p === null ? pressure : stab.p + (pressure - stab.p) * aP;

  stab.t = Number.isFinite(tMs) ? tMs : stab.t;
  return { x: stab.x, y: stab.y, p: stab.p };
}

/** Vuruş girdisini yumuşat. amount ≤ 0 → ham değerler (yapı değişmez). */
function inkStabilizerApply(stab, x, y, pressure, tMs, amount) {
  const cutoffs = amount <= 0.001 ? null : inkStabilizerCutoffs(amount);
  if (!stab || !cutoffs) return { x, y, p: pressure, raw: true };
  const out = inkEuroStep(stab, x, y, pressure, tMs, cutoffs);
  return { x: out.x, y: out.y, p: out.p, raw: false };
}

/* =========================================================
   fare için hız → basınç simülasyonu (FAZ2-4)
   ========================================================= */

/** Fare (basınç bildirmeyen cihaz) için: yavaş ele güçlü basınç,
 *  hızlı ele ince çizgi. speed 0..1 (inkSpeedInfluence). */
function inkSimulatedPressure(speed) {
  return clamp(1 - 0.7 * speed, 0.3, 1);
}

/* =========================================================
   uzun vuruşun nokta sınırı: başı yutmadan seyrelt (FAZ2-5)
   ========================================================= */

/**
 * `points.length >= cap` durumunda baş noktayı asla atmayıp içeri
 * seyreltir (FAZ2-5). Seyreltilmiş noktalar hâlâ aynı parçaların
 * arasından geçtiği için polilinea geometrisi görsel olarak korunur;
 * oynatma ve raster yeniden çizimi aynı tek listeden okur → tutarlı.
 * İlk nokta + son 2 nokta (canlı damga penceresi) asla silinmez.
 * Değişiklik yoksa null döner.
 * @returns {Array|null}
 */
function inkDecimateStrokePoints(points, cap) {
  if (!points || points.length < cap) return null;
  const src = points;
  const kept = [src[0]];
  for (let i = 2; i < src.length - 3; i += 2) kept.push(src[i]);
  // Son 2 nokta canlı damga penceresidir (prev2/prev): atlanmaz.
  kept.push(src[src.length - 2]);
  kept.push(src[src.length - 1]);
  // En az 2 nokta kalır.
  return kept.length >= 2 ? kept : null;
}

/* TailRef app · ink color · linear-light + OKLab (FAZ 3)
   --------------------------------------------------------------------
   docs/ARCH-RESCUE-PLAN.md FAZ 3 çekirdeği. Bu modül DOM'suz saf
   matemattır: tarayıcı zinciri ve Node tabanlı birim testler
   (scripts/ink-color-test.js) aynı haliyle çalışır.

   FAZ 3'e kadar tüm karışım gamma-kodlu 8-bit sRGB üzerindeydi —
   "muddy" karışımlar üretir (gamma ortalaması, ortalamadan koyu çıkar).
   Bu modül tek transfer çiftini ve Ottosson OKLab'ı (CSS Color 4
   matrisleri) sağlar; karışım noktaları sırayla buraya taşınır:

       gamma 8-bit  --inkSrgbToLin-->  linear 0..1   (ışık/doz uzayı)
       linear 0..1  --inkLinToSrgb-->  gamma 8-bit   (kaydetme uzayı)
       linear       --inkLinearToOkLab-->  OKLab     (algı uzayı)
       OKLab        --inkOkLabToLinear-->  linear
       OKLab        <-> OKLCH (l: 0..1, c: 0..~0.33, h: derece)

   Ottosson'ın "±0.015625 (1/64)" bordör notu: LMS küp kök sınır
   durumlarıdır; Math.cbrt'ün sign-koruyan davranışı + 8-bit yuvarlama
   bunu sağlar. Lineer değerlere yapay "sıfır bölgesi" UYGULANMAZ —
   gölgedeki koyu geçerli değerler (lin 0.003 gibi) yutulup
   siyahlaşmasın.

   ⚠︎ Performans kuralı: piksel döngüleri (smudge/dab) Math.pow yerine
   LUT kullanır (inkLinLut / inkLinToSrgbLut) — FAZ 3-1 notu.
   ========================================================= */
'use strict';

/* -----------------------------------------------------------
   Transfer çifti (FAZ 3-1: tek kaynak, başka yerde pow yok)
   ----------------------------------------------------------- */

/** Gamma 8-bit (0..255) → lineer (0..1).
 *  Formül: c/255 → c <= 0.04045 ? c/12.92 : ((c+0.055)/1.055)^2.4 */
function inkSrgbToLin(c255) {
  const c = c255 / 255;
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

/** Lineer (0..1) → gamma 8-bit (0..255, yuvarlanmış, sıkıştırılmış). */
function inkLinToSrgb(lin) {
  const c = inkGamutClamp01(lin);
  const g = c <= 0.0031308
    ? c * 12.92
    : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;
  return Math.round(g * 255);
}

/* Gamut sıkıştırma: gerçek sınır değerler (negatif/NaN → 0, taşma → 1).
   Yapay merkez-sıfır bölgesi YOKTUR — koyu lineer değerler geçerlidir. */
function inkGamutClamp01(v) {
  if (!(v > 0)) return 0;   /* NaN dahil → 0 */
  if (v >= 1) return 1;
  return v;
}

/* Piksel döngüsü LUT'ları: ilk kullanımda kurulur (FAZ 3-1).
   inkLinLut()[i]        : gamma i (0..255)   → lineer
   inkLinToSrgbLut()[j]  : lineer j/1023 → gamma 8-bit (yakın 8-bit) */
var inkLinTable = null;
var inkGamutTable = null;

function inkLinLut() {
  if (!inkLinTable) {
    inkLinTable = new Float64Array(256);
    for (let i = 0; i < 256; i++) inkLinTable[i] = inkSrgbToLin(i);
  }
  return inkLinTable;
}

function inkLinToSrgbLut() {
  if (!inkGamutTable) {
    /* 65536 adım: karanlık toe'da (12.92 bölümü) lin-grid adımı
       ~3.2 γ-birim kapsamaz — 1024 adım orada ±2 γ hatası üretirdi. */
    const N = 65536;
    inkGamutTable = new Uint8Array(N + 1);
    for (let j = 0; j <= N; j++) inkGamutTable[j] = inkLinToSrgb(j / N);
  }
  return inkGamutTable;
}

/** Piksel döngüsü hız yolu: gamma 8-bit → lineer. Tamsayı girdi
 *  LUT değerinin birebir kendisi; kesirli girdi (smudge pickup
 *  ortalaması) bitişik iki LUT girişi arasında doğrusal ara. */
function inkLinData(c255) {
  const t = inkLinLut();
  const x = c255 >= 255 ? 255 : c255 <= 0 ? 0 : c255;
  const i0 = Math.floor(x), f = x - i0;
  if (!f) return t[i0];
  const i1 = Math.min(255, i0 + 1);
  return t[i0] + (t[i1] - t[i0]) * f;
}

/** Piksel döngüsü hız yolu: lineer → gamma 8-bit (yakın indeks). */
function inkGamutData(lin) {
  const t = inkLinToSrgbLut();
  const j = Math.round(inkGamutClamp01(lin) * 65535);
  return t[j > 65535 ? 65535 : j < 0 ? 0 : j];
}

/* -----------------------------------------------------------
   hex yardımcıları (hatalı girdi affedici — projenin genel tutumu
   eski inkColorToHsl davranışına eştilerdi, FAZ 3'te konvansiyon
   korunarak OKLab hattına taşındı)
   ----------------------------------------------------------- */

/** '#rrggbb' → lineer {r,g,b} (0..1). Hatalı girdi → beyaz. */
function inkHexToLinear(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
  if (!m) return { r: 1, g: 1, b: 1 };
  const n = parseInt(m[1], 16);
  return {
    r: inkLinLut()[(n >> 16) & 255],
    g: inkLinLut()[(n >> 8) & 255],
    b: inkLinLut()[n & 255],
  };
}

/** lineer {r,g,b} → '#rrggbb' (8-bit, sıkıştırılmış). */
function inkLinearToHex(c) {
  const to = v => {
    const j = Math.round(inkGamutClamp01(v) * 65535);
    return inkLinToSrgbLut()[j > 65535 ? 65535 : j < 0 ? 0 : j]
      .toString(16).padStart(2, '0');
  };
  return '#' + to(c.r) + to(c.g) + to(c.b);
}

/* -----------------------------------------------------------
   Ottosson OKLab (CSS Color 4 matrisleri, linear 0..1 ↔ Lab)
   ----------------------------------------------------------- */

/** Doğrusal sRGB (0..1) → OKLab {L,a,b}. */
function inkLinearToOkLab(r, g, b) {
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
  const l_ = Math.cbrt(l);
  const m_ = Math.cbrt(m);
  const s_ = Math.cbrt(s);
  return {
    L: 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
    a: 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
    b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
  };
}

/** OKLab {L,a,b} → doğrusal sRGB {r,g,b} (gamut dışı borderline'lar
 *  inkGamutClamp01'e dahil değil; hex'e girişte sıkışır). */
function inkOkLabToLinear(L, a, b) {
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.2914855480 * b;
  const l = l_ * l_ * l_;
  const m = m_ * m_ * m_;
  const s = s_ * s_ * s_;
  return {
    r: +4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    g: -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    b: -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
  };
}

function inkHexToOkLab(hex) {
  const c = inkHexToLinear(hex);
  return inkLinearToOkLab(c.r, c.g, c.b);
}

function inkOkLabToHex(L, a, b) {
  return inkLinearToHex(inkOkLabToLinear(L, a, b));
}

/* -----------------------------------------------------------
   OKLCH (l: 0..1, c: 0..~0.33, h: 0..360 derece, NaN=akromatik)
   ----------------------------------------------------------- */

function inkOkLabToOkLch(L, a, b) {
  const c = Math.hypot(a, b);
  let h = Math.atan2(b, a) * 180 / Math.PI;
  if (!(h >= 0)) h += 360;              /* -0°-ları 360'a sar */
  if (h >= 360) h -= 360;
  return { l: L, c, h };
}

function inkOkLchToOkLab(l, c, h) {
  const rad = h * Math.PI / 180;
  return { L: l, a: Math.cos(rad) * c, b: Math.sin(rad) * c };
}

function inkHexToOkLch(hex) {
  const lab = inkHexToOkLab(hex);
  return inkOkLabToOkLch(lab.L, lab.a, lab.b);
}

function inkOkLchToHex(l, c, h) {
  const lab = inkOkLchToOkLab(l, c, h);
  return inkOkLabToHex(lab.L, lab.a, lab.b);
}

/** OKLab → sRGB baytları {r,g,b} (piksel döngüsü için; hex string'siz). */
function inkOkLabToBytes(L, a, b) {
  const lin = inkOkLabToLinear(L, a, b);
  return {
    r: inkGamutData(lin.r),
    g: inkGamutData(lin.g),
    b: inkGamutData(lin.b),
  };
}

/** sRGB baytları → OKLab + OKLCH (piksel döngüsü için; hex string'siz,
 *  paletleyicinin L/a/b toplaması ve L/C/H eşikleri tek çağrıda). */
function inkRgbBytesToOkLch(r, g, b) {
  const lab = inkLinearToOkLab(inkLinData(r), inkLinData(g), inkLinData(b));
  const lch = inkOkLabToOkLch(lab.L, lab.a, lab.b);
  return { L: lab.L, a: lab.a, b: lab.b, l: lch.l, c: lch.c, h: lch.h };
}

/** source-over tek piksel (FAZ 3-2 dab/smudge döngüsü için saf birim):
 *  hedef gamma 8-bit + düz alfa; kaynak lineer + düz alfa; amount =
 *  dab mask payı (0..1). Karışım LINEER uzayda yapılır (muddy yok).
 *  Çıktı: gamma 8-bit (0..255). bgByte tam sayı olmalı (piksel verisi). */
function inkDabOverChannel(bgByte, bgA, srcLin, srcA, amount) {
  const keep = bgA * (1 - amount);
  const add = srcA * amount;
  const outA = keep + add;
  if (!(outA > 0)) return 0;
  const out = (inkLinData(bgByte) * keep + srcLin * add) / outA;
  return inkGamutData(out);
}

/** OKLCH → sRGB baytları {r,g,b} (piksel döngüsü için; hex string'siz). */
function inkOkLchToBytes(l, c, h) {
  const lab = inkOkLchToOkLab(
    inkGamutClamp01(l),
    Math.min(0.35, Math.max(0, c)),
    h);
  const lin = inkOkLabToLinear(lab.L, lab.a, lab.b);
  return {
    r: inkGamutData(lin.r),
    g: inkGamutData(lin.g),
    b: inkGamutData(lin.b),
  };
}

function inkOkLchToHex(l, c, h) {
  const b = inkOkLchToBytes(l, c, h);
  return '#' + [b.r, b.g, b.b].map(n => n.toString(16).padStart(2, '0')).join('');
}

/* -----------------------------------------------------------
   çark (FAZ 3-3): dış halka renk kimliği eski HSV saf ton tanımıyla
   aynı kalır (görsel devamlılık); iç üçgen köşeleri OKLCH karışımıdır:
     A beyaz {l:1, c:0} · B siyah {l:0, c:0} · C saf ton {l,c,h}
   Piksel rengi = barycentric ağırlıkların OKLCH-L düzleminde doğrusal
   karışımı (eski gamma düz karışım muddy üçgen üretiyordu).
   ----------------------------------------------------------- */

/** Saf ton renk (halkayla aynı tanım: HSV s=1, v=1) → baytlar. */
function inkHsvSectorRgb(hue) {
  const h = ((hue % 360) + 360) % 360;
  const x = 1 - Math.abs(((h / 60) % 2) - 1);
  let r = 0, g = 0, b = 0;
  if (h < 60)       { r = 1; g = x; }
  else if (h < 120) { r = x; g = 1; }
  else if (h < 180) { g = 1; b = x; }
  else if (h < 240) { g = x; b = 1; }
  else if (h < 300) { r = x; b = 1; }
  else              { r = 1; b = x; }
  return {
    r: Math.round(r * 255),
    g: Math.round(g * 255),
    b: Math.round(b * 255),
  };
}

/* Saf ton köşe önbelleği: derece başına bir giriş (≤360 kayıt). */
var inkWheelCorners = new Map();

function inkWheelPureCorner(hue) {
  const h = Number.isFinite(hue) ? ((hue % 360) + 360) % 360 : 0;
  const k = Math.round(h) % 360;
  let corner = inkWheelCorners.get(k);
  if (!corner) {
    const rgb = inkHsvSectorRgb(k);
    const hex = inkRgbToHexBytes(rgb);
    const lch = inkHexToOkLch(hex);
    corner = {
      /* h = ÇARK açısı (köşe seçici); okH = köşenin gerçek OKLCH hue'su
         (kırmızı ≈ 29.2° — üçgen boyunca chroma ekseni o yöne iner). */
      h: k,
      rgb,
      hex,
      l: lch.l,
      c: lch.c,
      okH: lch.h,
    };
    inkWheelCorners.set(k, corner);
  }
  return corner;
}

/* FAZ 6 A10: Ottosson gamut yardımcıları (public domain, kaynak
   docs/reference/ok-color-conversion.js — MIT). Üçgen köşesi halka
   kimliği için klasik HSV saf tonunda KALIR (referans çizim uygulamalarının
   tanıdıklığı); cusp, üçgen-içi doğruluğun denetim pusulasıdır. a_ ve b_ normalize
   (a_²+b_²=1) hue yönü; dönüş [L_cusp, C_cusp]. */
function inkWheelMaxSaturation(a_, b_) {
  let k0, k1, k2, k3, k4, wl, wm, ws;
  if (-1.88170328 * a_ - 0.80936493 * b_ > 1) {
    /* kırmızı kanalı */
    k0 = +1.19086277; k1 = +1.76576728; k2 = +0.59662641; k3 = +0.75515197; k4 = +0.56771245;
    wl = +4.0767416621; wm = -3.3077115913; ws = +0.2309699292;
  } else if (1.81444104 * a_ - 1.19445276 * b_ > 1) {
    /* yeşil kanalı */
    k0 = +0.73956515; k1 = -0.45954404; k2 = +0.08285427; k3 = +0.12541070; k4 = +0.14503204;
    wl = -1.2684380046; wm = +2.6097574011; ws = -0.3413193965;
  } else {
    /* mavi kanalı */
    k0 = +1.35733652; k1 = -0.00915799; k2 = -1.15130210; k3 = -0.50559606; k4 = +0.00692167;
    wl = -0.0041960863; wm = -0.7034186147; ws = +1.7076147010;
  }
  /* polinom yaklaşık + bir adım Halley düzeltmesi */
  let S = k0 + k1 * a_ + k2 * b_ + k3 * a_ * a_ + k4 * a_ * b_;
  const k_l = +0.3963377774 * a_ + 0.2158037573 * b_;
  const k_m = -0.1055613458 * a_ - 0.0638541728 * b_;
  const k_s = -0.0894841775 * a_ - 1.2914855480 * b_;
  {
    const l_ = 1 + S * k_l, m_ = 1 + S * k_m, s_ = 1 + S * k_s;
    const l = l_ * l_ * l_, m = m_ * m_ * m_, s = s_ * s_ * s_;
    const l_dS = 3 * k_l * l_ * l_, m_dS = 3 * k_m * m_ * m_, s_dS = 3 * k_s * s_ * s_;
    const l2 = 6 * k_l * k_l * l_, m2 = 6 * k_m * k_m * m_, s2 = 6 * k_s * k_s * s_;
    const f = wl * l + wm * m + ws * s;
    const f1 = wl * l_dS + wm * m_dS + ws * s_dS;
    const f2 = wl * l2 + wm * m2 + ws * s2;
    S = S - f * f1 / (f1 * f1 - 0.5 * f * f2);
  }
  return S;
}

function inkWheelCusp(a_, b_) {
  const S_cusp = inkWheelMaxSaturation(a_, b_);
  const rgb = inkOkLabToLinear(1, S_cusp * a_, S_cusp * b_);
  const L_cusp = Math.cbrt(1 / Math.max(Math.max(rgb.r, rgb.g), rgb.b));
  return [L_cusp, L_cusp * S_cusp];
}

/* Çark açısı ↔ OKLCH hue eşlemesi (tersi): saf tonun OKLCH hue'su çark
   açısına göre monoton artar (kırmızı 29° → sarı ~110° → yeşil ~143° →
   mavi ~264° → macenta ~328°).
   FAZ 6 A10: biseksiyon KALDIRILDI. Köşe ızgarası düz basamaklıdır
   (sarıda 1.6° sıçrama): biseksiyon hedefe kilitlenemezken hücre
   sınırında sabitlenir (57.4999 / 56.5000), hex kuantalama gürültüsü
   sınırı iteler ve state ±1° "hue yürür" (60.5 → 61.5 → ...) —
   arkadaşın panel-dışı gösterge kaymasını üreten katman. Argmin:
   h daima chroma eksenini çizecek köşenin BİREBİR derecesidir;
   state→hex→state sabit noktada, yürüyüş imkansızdır. */
function inkWheelHueFromOkHue(target) {
  const t = Number.isFinite(target) ? ((target % 360) + 360) % 360 : 0;
  let best = 0, bestD = Infinity;
  for (let k = 0; k < 360; k++) {
    const d = Math.abs(((inkWheelPureCorner(k).okH - t) % 360 + 540) % 360 - 180);
    if (d < bestD) { bestD = d; best = k; }
  }
  return best;
}

function inkRgbToHexBytes(b) {
  return '#' + [b.r, b.g, b.b].map(n =>
    (n & 255).toString(16).padStart(2, '0')).join('');
}

/** FAZ 6 A10: OKLCH noktası lineer sRGB tam kübünde mı (klampsız)?
 *  inkGamutData kanal-klampı hücrette hue'yi bozar (koyu mavi → mor
 *  kayması); bu nedenle çark yolunda eşleşmelerşı önce burada yakalarız.
 *  Tolerans ±0.002 (≈ 1 γ-LSB): JİLET-KADAR örneklerde (8-bit yuvarlama
 *  duvarına değen kanallar) ±1e-6 yanıt sallar ve state→hex zinciri
 *  geçişler arasında_hop yapar; 8-bit aralığında karar her bayta
 *  aynıdır (fark ≤ 1 LSB). */
function inkWheelOkLchInGamut(l, c, h) {
  const lab = inkOkLchToOkLab(
    inkGamutClamp01(l), Math.max(0, Number.isFinite(c) ? c : 0), h);
  const lin = inkOkLabToLinear(lab.L, lab.a, lab.b);
  const TOL = 0.002;
  return lin.r > -TOL && lin.r < 1 + TOL &&
    lin.g > -TOL && lin.g < 1 + TOL &&
    lin.b > -TOL && lin.b < 1 + TOL;
}

/* Çark durumu (h, s, v) ↔ hex. Geometri eşlemesi eskiyle birebir:
     a (beyaz payı) = v − s · b (siyah payı) = 1 − v · c (saf ton payı) = s
   Renk karışımı OKLab düzleminde (a/b) düz: chroma ekseni köşenin
   GERÇEK OKLCH hue'suna (okH) doğru iner — çark açısı h yalnız
   köşe seçimini belirler. */
function inkWheelStateToHex(h, s, v) {
  const corner = inkWheelPureCorner(h);
  const sc = Math.min(1, Math.max(0, Number(s) || 0));
  const vc = Math.min(1, Math.max(0, Number(v) || 0));
  /* Eşitlik payı: K–P kenarında v == s matematiksel olarak denk ama
     kayan noktada ±1 ULP sapan örnekler eski v<s yolu yanlışacağında
     dal değiştirebilir (hue 20° kayması). Pay bant içinde üçgen içidir. */
  if (vc + 1e-9 >= sc) {
    const wa = Math.min(1, Math.max(0, vc - sc));
    const wb = Math.min(1, Math.max(0, 1 - vc));
    const wc = Math.min(1, Math.max(0, 1 - wa - wb));
    const sum = wa + wb + wc || 1;
    const na = wa / sum, nc = wc / sum;
    let C = nc * corner.c;
    const L = na + nc * corner.l;
    const H = corner.okH;
    /* FAZ 6 A10: gamut garantisı. K–P ışını koyu doygun mavi/magenta
       yönlerinde sRGB'den taşar; kanal-klampı hue'yi bozardı (arkadaşın
       "renk yanlış" bulgusunun kökü — 20° mor kayması). Ottosson
       gamut-clipping ilkesi: hue ve L KORUNUR, chroma in-gamut
       tavane düşürülür (ikili arama; girişi gamutta olan noktalar
       buna girmez). */
    if (C > 1e-9 && !inkWheelOkLchInGamut(L, C, H)) {
      let lo = 0, hi = C;
      for (let i = 0; i < 22; i++) {
        const mid = (lo + hi) / 2;
        if (inkWheelOkLchInGamut(L, mid, H)) lo = mid; else hi = mid;
      }
      C = lo;
    }
    return inkOkLchToHex(L, C, H);
  }
  /* v < s: üçgenin dışında (yalnız hex girişinden gelir). Eski
     davranış aynen korunur: HSV sektör matematiği (kanal = ch0·s·v
     + v(1−s)) — state→hex kendi kendine tutarlı kalır. */
  const rgb = inkHsvSectorRgb(corner.h);
  return '#' +
    [rgb.r, rgb.g, rgb.b].map(raw => {
      const c0 = raw / 255;
      return Math.round((c0 * sc * vc + vc * (1 - sc)) * 255)
        .toString(16).padStart(2, '0');
    }).join('');
}

/* FAZ 6 A10: hex → çark durumu. Eskiden üçgen dışı (v<s, s>1) bölge
   üretilebiliyordu — tutamaç üçgen dışına çıkıyor ve gösterilen renk
   seçilenle tutarsızlaşıyordu (arkadaşın iki bulgusu). Yol: OKLCH
   (l,c) düzleminde en yakın üçgen kenarına 2-D projeksiyon — OKLCH-L
   korunur, hue korunur, yalnız chroma kırpılır:
     (1) s = lch.c/cPure → [0,1]      (P ötesi doygunluk kırpılır)
     (2) l − s·lPure < 0 → K–P kenarı: s = l/lPure  (L korunur)
     (3) v > 1 → W–P kenarı: s = (1−l)/(1−lPure), v = 1
   Sonuç: tutamaç üçgen İÇİNDE garantili; gösterilen renk = seçilen renk. */
function inkHexToWheelState(hex) {
  const lch = inkHexToOkLch(hex);
  const h = inkWheelHueFromOkHue(lch.h);
  const corner = inkWheelPureCorner(h);
  let s = corner.c > 1e-9 ? lch.c / corner.c : 0;
  if (s > 1) s = 1;                              /* (1) P ötesi */
  if (lch.l < s * corner.l) s = corner.l > 1e-9  /* (2) K–P kenarı */
    ? Math.min(1, Math.max(0, lch.l / corner.l)) : 0;
  let v = lch.l + s * (1 - corner.l);       /* v = wa + wc (bary toplamı 1) */
  if (v > 1) {                                   /* (3) W–P kenarı */
    v = 1;
    s = corner.l < 1 - 1e-9
      ? Math.min(1, Math.max(0, (1 - lch.l) / (1 - corner.l))) : 0;
  }
  return {
    h,
    s: Math.min(1, Math.max(0, s)),
    v: Math.min(1, Math.max(0, v)),
  };
}

/** FAZ 6 A10: çark durumunu üçgen içinde stabil tutar (defansif son
 *  savunma): s ∈ [0,1], v ∈ [s,1]. 31-ink-ui.js'te durum bilgisini
 *  yazan üç noktaya bağlanır; sürükleme zaten bary clamp ile tutar. */
function inkWheelClampStateStable(st) {
  const s = Math.min(1, Math.max(0, Number(st && st.s) || 0));
  const v0 = Math.min(1, Math.max(0, Number(st && st.v) || 0));
  const hRaw = Number(st && st.h);
  return {
    h: Number.isFinite(hRaw) ? ((hRaw % 360) + 360) % 360 : 0,
    s,
    v: Math.min(1, Math.max(s, v0)),
  };
}

/* -----------------------------------------------------------
   karışım çekirdeği (FAZ 3-2'de beş noktaya bağlanır)
   ----------------------------------------------------------- */

/** Doğrusal-ışık karışımı: doz/ışık ortalaması (muddy'siz).
 *  t=0 → a, t=1 → b. */
function inkMixHexLinear(hexA, hexB, t) {
  const a = inkHexToLinear(hexA);
  const b = inkHexToLinear(hexB);
  const k = Number.isFinite(t) ? Math.min(1, Math.max(0, t)) : 0.5;
  return inkLinearToHex({
    r: a.r + (b.r - a.r) * k,
    g: a.g + (b.g - a.g) * k,
    b: a.b + (b.b - a.b) * k,
  });
}

/** Algısal karışım (OKLab a/b düzleminde düz): renk tekeri/dual-brush
 *  karışımında doğal orta renk üretir. */
function inkMixHexOkLab(hexA, hexB, t) {
  const a = inkHexToOkLab(hexA);
  const b = inkHexToOkLab(hexB);
  const k = Number.isFinite(t) ? Math.min(1, Math.max(0, t)) : 0.5;
  return inkOkLabToHex(a.L + (b.L - a.L) * k,
    a.a + (b.a - a.a) * k, a.b + (b.b - a.b) * k);
}

/** OKLCH kanal karışımı: L ve C doğrusal, hue en kısa yay boyunca
 *  (FAZ 3-2 renk dinamikleri: L-chroma korunarak hue dönüşü).
 *  girdi/çıktı: {l,c,h} (c 0..~0.33, h derece). */
function inkMixOkLch(a, b, t) {
  const k = Number.isFinite(t) ? Math.min(1, Math.max(0, t)) : 0.5;
  /* en kısa yay: farkı [-180, 180) aralığına sar */
  let dh = ((b.h - a.h) % 360 + 540) % 360 - 180;
  if (!Number.isFinite(dh)) dh = 0;
  let h = a.h + dh * k;
  h = (h % 360 + 360) % 360;
  return {
    l: a.l + (b.l - a.l) * k,
    c: a.c + (b.c - a.c) * k,
    h,
  };
}

/* TailRef app · renk seçici pro paneli (57)
   --------------------------------------------------------------------
   31-ink-ui.js'teki üçgen çarkın üstüne sektör standartlarıyla
   (Photoshop / Krita kalıpları) genişletilmiş seçici:

     · Mod seçici menü: Hue Triangle · Hue Square · Color Sliders
       (HSB/RGB) · Color Harmony · Digital Mixing — orta alan dinamik
       değişir; seçim kalıcı.
     · Ön plan / arka plan kareleri (iç içe), ok/X ile takas,
       siyah-beyaza sıfırlama mini ikonu.
     · COLOR HISTORY: kullanılan renkler MRU sırayla 9×2 ızgara.
     · PALETTES: kalıcı palet; + aktif rengi ekler, sağ tık siler.

   RENK DOĞRULUĞU (önceki turun dersi): Kare/Sliders/Harmony modları
   SAF HSV üzerinde çalışır — hex↔hsv dönüşümü bayt-birebirdir
   (inkCpHsvToHex ⇄ inkCpHexToHsv idempotent: gösterilen piksel =
   seçilen hex; hue kayması matematiksel olarak imkânsız). Üçgen modu
   FAZ 3-3 OKLCH yolunu AYNEN korur (denetim: tests/color-wheel-
   audit.js). Karıştırma lineer-ışık karışımı (inkMixHexLinear —
   gamma-düzlem muhallebisi yok).

   Kalıcılık: localStorage 'tailref-color-picker' (try/catch — her
   modülde olduğu gibi bozulursa varsayılana dönüşür).

   Bağlantı noktaları (31-ink-ui.js'ten):
     inkInitUI()  → inkCpInit()
     inkSetColor()→ inkCpOnColorSet(hex, save)
     inkSyncColorWheel(updatePickers) → inkCpSync(hex, updatePickers)
     inkWheelDraw() yalnızca üçgen modundayken koşar (inkCpWheelVisible)
   ========================================================= */
'use strict';

const INK_CP_STORAGE_KEY = 'tailref-color-picker';
const INK_CP_MODES = ['triangle', 'square', 'sliders', 'harmony', 'mixing'];
const INK_CP_HISTORY_MAX = 18;      /* 9 sütun × 2 sıra */
const INK_CP_PALETTE_MAX = 27;      /* 3 sıraya kadar sar */
const INK_CP_PALETTES_MAX = 24;     /* adlı palet sayısı tavanı */
const INK_CP_PAL_NAME_MAX = 32;
const INK_CP_DEFAULT_PALETTE = [
  '#4c8dff', '#ff8a3d', '#b6f04a', '#35c77d', '#2e6bff',
  '#9a55ff', '#ff4d6d', '#f7c948', '#8adfff', '#ff5a5f',
];

const inkCp = {
  ready: false,
  mode: 'triangle',
  harmony: 'complementary',
  sliderSpace: 'hsb',
  bg: '#ffffff',
  fg: '#ff5a5f',
  history: [],
  palettes: [{ name: 'Palette 1', colors: INK_CP_DEFAULT_PALETTE.slice() }],
  activePal: 0,
  /* Kare/Sliders/Harmony modlarının SAF HSV durumu (üçgeninkinden bağımsız). */
  sv: { h: 358, s: 1, v: 1 },
  dragging: '',
  pointerId: null,
  editingSlider: false,
  squareCache: null,
  squareHue: -1,
  squarePx: 0,
  mixSeededPx: 0,
  histTimer: 0,
  saveTimer: 0,
  els: {},
};

/* -----------------------------------------------------------
   durum yükle / kaydet
   ----------------------------------------------------------- */

/** Palet adı temizliği: boşsa "Palet N" üretir (t() varsa çevirili). */
function inkCpPalName(raw, index) {
  const name = String(raw == null ? '' : raw).trim().slice(0, INK_CP_PAL_NAME_MAX);
  if (name) return name;
  const word = typeof t === 'function' ? t('Palette') : 'Palette';
  return word + ' ' + (index + 1);
}

/** Etkin palet: bozuk indeks/boş diziye karşı korumalı tek kapı. */
function inkCpActivePalette() {
  if (!Array.isArray(inkCp.palettes) || !inkCp.palettes.length) {
    inkCp.palettes = [{ name: inkCpPalName('', 0), colors: INK_CP_DEFAULT_PALETTE.slice() }];
    inkCp.activePal = 0;
  }
  if (!Number.isInteger(inkCp.activePal) ||
      inkCp.activePal < 0 || inkCp.activePal >= inkCp.palettes.length) {
    inkCp.activePal = 0;
  }
  return inkCp.palettes[inkCp.activePal];
}

/** Çakışan adları otomatik numaralandır: "Palet 2 (2)" gibi. */
function inkCpUniquePalName(base, skip = -1) {
  const taken = new Set();
  inkCp.palettes.forEach((p, i) => { if (i !== skip) taken.add(p.name.toLowerCase()); });
  if (!taken.has(base.toLowerCase())) return base;
  for (let n = 2; ; n += 1) {
    const candidate = base + ' (' + n + ')';
    if (!taken.has(candidate.toLowerCase())) return candidate;
  }
}

function inkCpLoad() {
  try {
    const raw = localStorage.getItem(INK_CP_STORAGE_KEY);
    if (!raw) return;
    const src = JSON.parse(raw);
    if (!src || typeof src !== 'object') return;
    if (INK_CP_MODES.includes(src.mode)) inkCp.mode = src.mode;
    if (['complementary', 'analogous', 'triadic'].includes(src.harmony)) {
      inkCp.harmony = src.harmony;
    }
    if (src.sliderSpace === 'rgb') inkCp.sliderSpace = 'rgb';
    if (typeof src.bg === 'string' && /^#[0-9a-f]{6}$/i.test(src.bg)) {
      inkCp.bg = src.bg.toLowerCase();
    }
    if (Array.isArray(src.history)) {
      inkCp.history = src.history
        .filter(h => typeof h === 'string' && /^#[0-9a-f]{6}$/i.test(h))
        .map(h => h.toLowerCase())
        .slice(0, INK_CP_HISTORY_MAX);
    }
    if (Array.isArray(src.palettes) && src.palettes.length) {
      /* v2: adlı paletler dizisi. */
      inkCp.palettes = src.palettes.slice(0, INK_CP_PALETTES_MAX).map((p, i) => ({
        name: inkCpPalName(p && typeof p === 'object' ? p.name : '', i),
        colors: ((p && typeof p === 'object' && Array.isArray(p.colors)) ? p.colors : [])
          .filter(h => typeof h === 'string' && /^#[0-9a-f]{6}$/i.test(h))
          .map(h => h.toLowerCase())
          .slice(0, INK_CP_PALETTE_MAX),
      }));
      inkCp.activePal = Number.isInteger(src.activePal) &&
        src.activePal >= 0 && src.activePal < inkCp.palettes.length
        ? src.activePal
        : 0;
    } else if (Array.isArray(src.palette) && src.palette.length) {
      /* v1 → v2 taşıma: eski düz palet, adlı ilk palet olarak devralınır. */
      inkCp.palettes = [{
        name: inkCpPalName('', 0),
        colors: src.palette
          .filter(h => typeof h === 'string' && /^#[0-9a-f]{6}$/i.test(h))
          .map(h => h.toLowerCase())
          .slice(0, INK_CP_PALETTE_MAX),
      }];
      inkCp.activePal = 0;
    }
  } catch { /* bozuk kayıt → varsayılanlar */ }
}

function inkCpSave() {
  if (!inkCp.ready) return;
  clearTimeout(inkCp.saveTimer);
  inkCp.saveTimer = setTimeout(() => {
    try {
      localStorage.setItem(INK_CP_STORAGE_KEY, JSON.stringify({
        v: 2,
        mode: inkCp.mode,
        harmony: inkCp.harmony,
        sliderSpace: inkCp.sliderSpace,
        bg: inkCp.bg,
        history: inkCp.history,
        palettes: inkCp.palettes.map(p => ({ name: p.name, colors: p.colors })),
        activePal: inkCp.activePal,
        /* v1 uyumluluğu: eski sürüm etkin paleti düz dizi olarak okur. */
        palette: inkCpActivePalette().colors,
      }));
    } catch { /* sessiz: kota/gizlilik kısıtları */ }
  }, 250);
}

/* -----------------------------------------------------------
   saf HSV matematiği (bayt-birebir; kaymasız görünüm)
   ----------------------------------------------------------- */

/** (h, s, v) → '#rrggbb'. inkHsvSectorRgb'nin sektör tanımıyla birebir:
 *  kanal = v · (1 − s · (1 − sektör_kanal)). hex→hsv→hex döngüsü
 *  bu tanımla kendini yeniden üretir (idempotent). */
function inkCpHsvToHex(h, s, v) {
  const sec = inkHsvSectorRgb(Number.isFinite(h) ? h : 0);
  const sc = Math.min(1, Math.max(0, Number(s) || 0));
  const vc = Math.min(1, Math.max(0, Number(v) || 0));
  return '#' + [sec.r, sec.g, sec.b].map(raw => {
    const f = raw / 255;
    return Math.round(255 * vc * (1 - sc * (1 - f)))
      .toString(16).padStart(2, '0');
  }).join('');
}

/** '#rrggbb' → { h: 0..360, s: 0..1, v: 0..1 } (standart RGB→HSV). */
function inkCpHexToHsv(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
  let r = 0, g = 0, b = 0;
  if (m) {
    const n = parseInt(m[1], 16);
    r = (n >> 16) & 255;
    g = (n >> 8) & 255;
    b = n & 255;
  }
  const R = r / 255, G = g / 255, B = b / 255;
  const max = Math.max(R, G, B);
  const min = Math.min(R, G, B);
  const d = max - min;
  const v = max;
  const s = max > 0 ? d / max : 0;
  let h = 0;
  if (d > 0) {
    if (max === R) h = 60 * (((G - B) / d) % 6);
    else if (max === G) h = 60 * ((B - R) / d + 2);
    else h = 60 * ((R - G) / d + 4);
  }
  if (h < 0) h += 360;
  return { h, s, v };
}

function inkCpClampHsv(st) {
  const h = Number.isFinite(st && st.h) ? ((st.h % 360) + 360) % 360 : 0;
  const s = Math.min(1, Math.max(0, Number(st && st.s) || 0));
  const v = Math.min(1, Math.max(0, Number(st && st.v) || 0));
  return { h, s, v };
}

/** hex → SAF HSV durumu. Akramatik renklerde (s≈0 veya v≈0) ton
 *  tanımsızdır: mevcut ton KORUNUR — kullanıcı siyah/beyaz/griye
 *  inince halka tutamacı sıçramaz (sektör standardı davranış;
 *  hex idempotence bozulmaz: hex yalnız s,v'ye bağlı). */
function inkCpDeriveSv(hex) {
  const hsv = inkCpHexToHsv(hex);
  const achromatic = hsv.s <= 1e-6 || hsv.v <= 1e-6;
  return {
    h: achromatic ? inkCp.sv.h : hsv.h,
    s: hsv.s,
    v: hsv.v,
  };
}

function inkCpHexBytes(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
  const n = m ? parseInt(m[1], 16) : 0;
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/* -----------------------------------------------------------
   kurulum
   ----------------------------------------------------------- */

function inkCpInit() {
  if (inkCp.ready) return;
  const ids = {
    panel: 'inkColorWheel',
    wheelCanvas: 'inkWheelCanvas',
    squareCanvas: 'inkCpSquareCanvas',
    harmonyCanvas: 'inkCpHarmonyCanvas',
    mixCanvas: 'inkCpMixCanvas',
    sliders: 'inkCpSliders',
    spaceSeg: 'inkCpSpaceSeg',
    harmonyRow: 'inkCpHarmonyRow',
    harmonySeg: 'inkCpHarmonySeg',
    harmonySwatches: 'inkCpHarmonySwatches',
    mixTools: 'inkCpMixTools',
    mixSeed: 'inkCpMixSeed',
    fg: 'inkCpFg',
    bg: 'inkCpBg',
    swap: 'inkCpSwap',
    def: 'inkCpDefault',
    modeBtn: 'inkCpModeBtn',
    modeMenu: 'inkCpModeMenu',
    eyedrop: 'inkCpEyedrop',
    history: 'inkCpHistory',
    palette: 'inkCpPalette',
    paletteAdd: 'inkCpPaletteAdd',
    palSelect: 'inkCpPalSelect',
    palRenameInput: 'inkCpPalRenameInputEl',
    palNew: 'inkCpPalNew',
    palRename: 'inkCpPalRename',
    palDelete: 'inkCpPalDelete',
  };
  const els = inkCp.els;
  for (const [key, id] of Object.entries(ids)) {
    els[key] = document.getElementById(id);
  }
  if (!els.panel) return;

  inkCpLoad();
  inkCpBindHead();
  inkCpBindSquare();
  inkCpBindSliders();
  inkCpBindHarmony();
  inkCpBindMixing();
  inkCpBindCollections();

  inkCp.ready = true;
  inkCpSetMode(inkCp.mode, false);
  inkCpSyncSegs();
  inkCpSyncSquares();
  inkCpRenderHistory();
  inkCpRenderPalette();
  inkCpRenderPalBar();
  inkCpSyncSliders(inkState().color || inkCp.fg);
}

/** Segment (radiogroup) butonlarını yüklü duruma göre işaretle. */
function inkCpSyncSegs() {
  const els = inkCp.els;
  const segs = [
    { seg: els.spaceSeg, attr: 'data-space', val: inkCp.sliderSpace },
    { seg: els.harmonySeg, attr: 'data-harmony', val: inkCp.harmony },
  ];
  for (const { seg, attr, val } of segs) {
    if (!seg) continue;
    for (const btn of seg.querySelectorAll('button[' + attr + ']')) {
      const on = btn.getAttribute(attr) === val;
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
    }
  }
}

/** Üst şerit: ön plan/arka plan kareleri, takas, sıfırlama, mod menüsü. */
function inkCpBindHead() {
  const els = inkCp.els;
  const swap = () => inkCpSwapColors();
  if (els.swap) els.swap.addEventListener('click', swap);
  if (els.bg) els.bg.addEventListener('click', swap);
  if (els.def) {
    els.def.addEventListener('click', () => {
      inkCp.bg = '#ffffff';
      if (typeof inkSetColor === 'function') inkSetColor('#000000', true);
      inkCpSyncSquares();
      inkCpSave();
    });
  }

  const btn = els.modeBtn;
  const menu = els.modeMenu;
  if (!btn || !menu) return;
  btn.addEventListener('click', event => {
    event.stopPropagation();
    const open = !menu.hidden;
    menu.hidden = open;
    btn.setAttribute('aria-expanded', open ? 'false' : 'true');
  });
  menu.addEventListener('click', event => {
    const item = event.target instanceof Element
      ? event.target.closest('button[data-mode]') : null;
    if (!item) return;
    event.stopPropagation();
    inkCpSetMode(item.dataset.mode);
  });
  /* Menü dışına tıklama ve Escape ile kapanış (çarkın kendi dış-tık
     kapanışıyla aynı kalıp: capture + closest). */
  document.addEventListener('pointerdown', event => {
    if (menu.hidden) return;
    const t = event.target instanceof Element ? event.target : null;
    if (t && (t.closest('#inkCpModeMenu') || t.closest('#inkCpModeBtn'))) return;
    menu.hidden = true;
    btn.setAttribute('aria-expanded', 'false');
  }, true);
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || menu.hidden) return;
    menu.hidden = true;
    btn.setAttribute('aria-expanded', 'false');
  });
}

/* -----------------------------------------------------------
   kare modu (halka + SV karesi — saf HSV)
   ----------------------------------------------------------- */

function inkCpSquareGeom() {
  const c = inkCp.els.squareCanvas;
  if (!c) return null;
  const css = Math.max(72, c.clientWidth || 228);
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const px = Math.max(1, Math.round(css * dpr));
  if (c.width !== px || c.height !== px) {
    c.width = px;
    c.height = px;
    inkCp.squareCache = null;
  }
  const outer = css / 2 - 4;
  const inner = outer * 0.775;
  const half = inner * 0.72;   /* kare köşegeni iç çemberin içinde kalır */
  return {
    css, dpr, px, cx: css / 2, cy: css / 2, outer, inner, half,
    left: css / 2 - half, top: css / 2 - half, side: half * 2,
  };
}

function inkCpSquareHit(x, y, g) {
  const d = Math.hypot(x - g.cx, y - g.cy);
  if (d >= g.inner - 4 && d <= g.outer + 4) return 'ring';
  if (x >= g.left - 2 && x <= g.left + g.side + 2 &&
      y >= g.top - 2 && y <= g.top + g.side + 2) return 'sv';
  return '';
}

function inkCpSquarePoint(event, g) {
  const r = inkCp.els.squareCanvas.getBoundingClientRect();
  return {
    x: (event.clientX - r.left) * (g.css / Math.max(1, r.width)),
    y: (event.clientY - r.top) * (g.css / Math.max(1, r.height)),
  };
}

/** SV karesi: ton değişince yeniden üretilir. Piksel rengi SAF HSV —
 *  kare üzerindeki her piksel birebir inkCpHsvToHex(h,s,v) değeridir. */
function inkCpSquareFill(g, hue) {
  if (inkCp.squareCache && inkCp.squareHue === hue && inkCp.squarePx === g.px) {
    return inkCp.squareCache;
  }
  const cv = document.createElement('canvas');
  cv.width = cv.height = g.px;
  const c = cv.getContext('2d', { colorSpace: 'srgb' });
  const img = c.createImageData(g.px, g.px);
  const data = img.data;
  const sec = inkHsvSectorRgb(hue);
  const fr = sec.r / 255, fg = sec.g / 255, fb = sec.b / 255;
  for (let py = 0; py < g.px; py++) {
    const y = (py + 0.5) / g.dpr;
    for (let pxi = 0; pxi < g.px; pxi++) {
      const x = (pxi + 0.5) / g.dpr;
      if (x < g.left || x > g.left + g.side ||
          y < g.top || y > g.top + g.side) continue;
      const s = (x - g.left) / g.side;
      const v = 1 - (y - g.top) / g.side;
      const i = (py * g.px + pxi) * 4;
      data[i] = Math.round(255 * v * (1 - s * (1 - fr)));
      data[i + 1] = Math.round(255 * v * (1 - s * (1 - fg)));
      data[i + 2] = Math.round(255 * v * (1 - s * (1 - fb)));
      data[i + 3] = 255;
    }
  }
  c.putImageData(img, 0, 0);
  inkCp.squareCache = cv;
  inkCp.squareHue = hue;
  inkCp.squarePx = g.px;
  return cv;
}

function inkCpSquareDraw() {
  const c = inkCp.els.squareCanvas;
  const g = inkCpSquareGeom();
  if (!c || !g) return;
  const ctx = c.getContext('2d');
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, g.px, g.px);
  ctx.drawImage(inkWheelRing(g), 0, 0);
  ctx.drawImage(inkCpSquareFill(g, inkCp.sv.h), 0, 0);

  /* kare kenar çizgisi */
  ctx.setTransform(g.dpr, 0, 0, g.dpr, 0, 0);
  ctx.beginPath();
  ctx.rect(g.left + 0.5, g.top + 0.5, g.side - 1, g.side - 1);
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(0,0,0,.4)';
  ctx.stroke();

  const a = inkCp.sv.h * Math.PI / 180;
  const hr = (g.outer + g.inner) / 2;
  inkWheelHandle(
    ctx,
    (g.cx + Math.cos(a) * hr) * g.dpr,
    (g.cy + Math.sin(a) * hr) * g.dpr,
    8 * g.dpr,
    inkWheelPureCorner(inkCp.sv.h).hex);
  inkWheelHandle(
    ctx,
    (g.left + inkCp.sv.s * g.side) * g.dpr,
    (g.top + (1 - inkCp.sv.v) * g.side) * g.dpr,
    7.5 * g.dpr,
    inkCpHsvToHex(inkCp.sv.h, inkCp.sv.s, inkCp.sv.v));
}

function inkCpSquareApply(event, mode) {
  const g = inkCpSquareGeom();
  if (!g) return;
  const p = inkCpSquarePoint(event, g);
  if (mode === 'ring') {
    const ang = Math.atan2(p.y - g.cy, p.x - g.cx);
    inkCp.sv.h = ((ang * 180 / Math.PI) + 360) % 360;
  } else if (mode === 'sv') {
    inkCp.sv.s = Math.min(1, Math.max(0, (p.x - g.left) / g.side));
    inkCp.sv.v = Math.min(1, Math.max(0, 1 - (p.y - g.top) / g.side));
  } else {
    return;
  }
  if (typeof inkSetColor === 'function') {
    inkSetColor(inkCpHsvToHex(inkCp.sv.h, inkCp.sv.s, inkCp.sv.v), false);
  }
}

function inkCpBindSquare() {
  const canvas = inkCp.els.squareCanvas;
  if (!canvas) return;
  canvas.addEventListener('pointerdown', event => {
    if (event.button !== 0) return;
    const g = inkCpSquareGeom();
    if (!g) return;
    const p = inkCpSquarePoint(event, g);
    const mode = inkCpSquareHit(p.x, p.y, g);
    if (!mode) return;
    event.preventDefault();
    event.stopPropagation();
    inkCp.dragging = mode;
    inkCp.pointerId = event.pointerId;
    try { canvas.setPointerCapture(event.pointerId); } catch { /* sessiz */ }
    inkCpSquareApply(event, mode);
  });
  canvas.addEventListener('pointermove', event => {
    if (!inkCp.dragging) return;
    if (inkCp.pointerId !== null && event.pointerId !== inkCp.pointerId) return;
    if (event.buttons !== undefined && (event.buttons & 1) === 0) return;
    event.preventDefault();
    inkCpSquareApply(event, inkCp.dragging);
  });
  const end = event => {
    if (!inkCp.dragging) return;
    inkCp.dragging = '';
    inkCp.pointerId = null;
    try { canvas.releasePointerCapture(event.pointerId); } catch { /* sessiz */ }
    if (typeof scheduleSave === 'function') scheduleSave();
  };
  canvas.addEventListener('pointerup', end);
  canvas.addEventListener('pointercancel', end);
}

/* -----------------------------------------------------------
   kaydırıcı modu (HSB / RGB — canlı gradyan raylar)
   ----------------------------------------------------------- */

function inkCpSliderRows() {
  const els = inkCp.els;
  const rows = { hsb: [], rgb: [], map: {} };
  if (!els.sliders) return rows;
  for (const row of els.sliders.querySelectorAll('.inkCpSliderRow')) {
    const ch = row.dataset.ch;
    const inputs = row.querySelectorAll('input');
    const item = { row, range: inputs[0], num: inputs[1] };
    if (['h', 's', 'b'].includes(ch)) { rows.hsb.push(item); rows.map[ch] = item; }
    else { rows.rgb.push(item); rows.map[ch] = item; }
  }
  return rows;
}

function inkCpHueRampCss() {
  const stops = [];
  for (let i = 0; i <= 6; i++) stops.push(inkCpHsvToHex(i * 60, 1, 1));
  return 'linear-gradient(to right,' + stops.join(',') + ')';
}

function inkCpSyncSliders(hex) {
  const els = inkCp.els;
  if (!els.sliders || !inkCp.ready) return;
  const { map } = inkCpSliderRows();
  if (!map.h) return;
  const hsv = inkCpHexToHsv(hex);
  const [r, g, b] = inkCpHexBytes(hex);
  const active = document.activeElement;

  const put = (item, value) => {
    if (!item) return;
    const v = String(value);
    if (item.range && active !== item.range) item.range.value = v;
    if (item.num && active !== item.num) item.num.value = v;
  };
  put(map.h, Math.round(hsv.h));
  put(map.s, Math.round(hsv.s * 100));
  put(map.b, Math.round(hsv.v * 100));
  put(map.r, r);
  put(map.g, g);
  put(map.bl, b);

  /* gradyan raylar (HSB eksenleri mevcut renge göre canlı) */
  const paint = (item, css) => {
    if (item && item.range) item.range.style.background = css;
  };
  paint(map.h, inkCpHueRampCss());
  paint(map.s, 'linear-gradient(to right,' +
    inkCpHsvToHex(hsv.h, 0, hsv.v) + ',' + inkCpHsvToHex(hsv.h, 1, hsv.v) + ')');
  paint(map.b, 'linear-gradient(to right,' +
    inkCpHsvToHex(hsv.h, hsv.s, 0) + ',' + inkCpHsvToHex(hsv.h, hsv.s, 1) + ')');
  paint(map.r, 'linear-gradient(to right,rgb(0,' + g + ',' + b + '),rgb(255,' + g + ',' + b + '))');
  paint(map.g, 'linear-gradient(to right,rgb(' + r + ',0,' + b + '),rgb(' + r + ',255,' + b + '))');
  paint(map.bl, 'linear-gradient(to right,rgb(' + r + ',' + g + ',0),rgb(' + r + ',' + g + ',255))');

  /* boşluk seçimi görünürlüğü (kullanıcı değiştirmişse koru) */
  const showHsb = inkCp.sliderSpace === 'hsb';
  for (const item of rowsList(map, 'hsb')) item.row.hidden = !showHsb;
  for (const item of rowsList(map, 'rgb')) item.row.hidden = showHsb;
}

function rowsList(map, space) {
  return space === 'hsb'
    ? ['h', 's', 'b'].map(ch => map[ch]).filter(Boolean)
    : ['r', 'g', 'bl'].map(ch => map[ch]).filter(Boolean);
}

function inkCpSliderCommit(item, save, src) {
  if (!item || !item.range) return;
  const max = Number(item.range.max) || 100;
  /* Kaynağı oku: olayı atan input (range sürüklemesi ya da num'a yazım).
     Num'a yazılan taşan girdi de kelepçelenir. Boş metin (number input
     geçersiz yazımda '' verir) NaN sayılır → son geçerli değere dönüş. */
  const rawText = src ? String(src.value).trim() : String(item.range.value);
  const raw = rawText === '' ? NaN : Number(rawText);
  if (!isFinite(raw)) {
    /* Boş/geçersiz yazım: canlı yazımda kurcalama; commit'te (Enter/
       blur) son geçerli değere — range'in tuttuğuna — sessizce dön. */
    if (save && item.num) item.num.value = String(item.range.value);
    return;
  }
  const value = Math.round(Math.min(max, Math.max(0, raw)));
  /* Gösterimi normalize et: range her zaman kelepçeli değeri taşır;
     num yalnızca canlı yazım (src=num, save=false) dışında eşitlenir —
     böylece "9999" kutuda takılı kalmaz, yazım da bozulmaz. */
  item.range.value = String(value);
  if (item.num && !(src === item.num && !save)) item.num.value = String(value);
  const { map } = inkCpSliderRows();
  let hex = '';
  if (inkCp.sliderSpace === 'hsb') {
    const h = Number(map.h.range.value) || 0;
    const s = Number(map.s.range.value) || 0;
    const b = Number(map.b.range.value) || 0;
    hex = inkCpHsvToHex(
      item === map.h ? value : h,
      item === map.s ? value / 100 : s / 100,
      item === map.b ? value / 100 : b / 100);
  } else {
    const parts = {
      r: Number(map.r.range.value) || 0,
      g: Number(map.g.range.value) || 0,
      bl: Number(map.bl.range.value) || 0,
    };
    const ch = { h: '', s: '', b: '', r: 'r', g: 'g', bl: 'bl' }[item.row.dataset.ch];
    if (ch) parts[ch] = value;
    hex = '#' + [parts.r, parts.g, parts.bl]
      .map(v => Math.round(Math.min(255, Math.max(0, v)))
        .toString(16).padStart(2, '0')).join('');
  }
  if (typeof inkSetColor === 'function') inkSetColor(hex, save);
}

function inkCpBindSliders() {
  const els = inkCp.els;
  if (!els.sliders) return;
  const { map } = inkCpSliderRows();
  for (const item of Object.values(map)) {
    if (!item || !item.range) continue;
    const pair = [item.range, item.num].filter(Boolean);
    for (const input of pair) {
      input.addEventListener('input', () => inkCpSliderCommit(item, false, input));
      input.addEventListener('change', () => inkCpSliderCommit(item, true, input));
    }
  }
  if (!els.spaceSeg) return;
  els.spaceSeg.addEventListener('click', event => {
    const btn = event.target instanceof Element
      ? event.target.closest('button[data-space]') : null;
    if (!btn) return;
    inkCp.sliderSpace = btn.dataset.space === 'rgb' ? 'rgb' : 'hsb';
    for (const seg of els.spaceSeg.querySelectorAll('button[data-space]')) {
      const on = seg.dataset.space === inkCp.sliderSpace;
      seg.classList.toggle('active', on);
      seg.setAttribute('aria-checked', on ? 'true' : 'false');
    }
    inkCpSyncSliders(inkState().color || inkCp.fg);
    inkCpSave();
  });
}

/* -----------------------------------------------------------
   harmony modu (tamamlayıcı / benzer / üçlü)
   ----------------------------------------------------------- */

function inkCpHarmonyAngles() {
  const h = inkCp.sv.h;
  if (inkCp.harmony === 'complementary') return [h, h + 180];
  if (inkCp.harmony === 'analogous') return [h - 30, h, h + 30];
  return [h, h + 120, h + 240];   /* triadic */
}

function inkCpHarmonyGeom() {
  const c = inkCp.els.harmonyCanvas;
  if (!c) return null;
  const css = Math.max(72, c.clientWidth || 228);
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const px = Math.max(1, Math.round(css * dpr));
  if (c.width !== px || c.height !== px) {
    c.width = px;
    c.height = px;
  }
  const outer = css / 2 - 4;
  const inner = outer * 0.775;
  return { css, dpr, px, cx: css / 2, cy: css / 2, outer, inner };
}

function inkCpHarmonyDraw() {
  const c = inkCp.els.harmonyCanvas;
  const g = inkCpHarmonyGeom();
  if (!c || !g) return;
  const ctx = c.getContext('2d');
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, g.px, g.px);
  ctx.drawImage(inkWheelRing(g), 0, 0);

  /* merkez: aktif renk diski (ton halkasında bağlam) */
  ctx.setTransform(g.dpr, 0, 0, g.dpr, 0, 0);
  ctx.beginPath();
  ctx.arc(g.cx, g.cy, g.inner * 0.5, 0, Math.PI * 2);
  ctx.fillStyle = inkState().color || inkCp.fg;
  ctx.fill();
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = 'rgba(255,255,255,.35)';
  ctx.stroke();

  const hr = (g.outer + g.inner) / 2;
  for (const angle of inkCpHarmonyAngles()) {
    const a = angle * Math.PI / 180;
    inkWheelHandle(
      ctx,
      (g.cx + Math.cos(a) * hr) * g.dpr,
      (g.cy + Math.sin(a) * hr) * g.dpr,
      7 * g.dpr,
      inkCpHsvToHex(angle, inkCp.sv.s, inkCp.sv.v));
  }
}

function inkCpRenderHarmonySwatches() {
  const wrap = inkCp.els.harmonySwatches;
  if (!wrap) return;
  wrap.replaceChildren();
  const angles = inkCpHarmonyAngles();
  const baseHex = inkState().color || inkCp.fg;
  for (let i = 0; i < angles.length; i++) {
    const hex = i === 0 ? baseHex
      : inkCpHsvToHex(angles[i], inkCp.sv.s, inkCp.sv.v);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'inkCpSwatch' + (i === 0 ? ' active' : '');
    btn.style.background = hex;
    btn.title = hex.toUpperCase() +
      (i === 0 ? ' · ' + (typeof t === 'function' ? t('Current color') : 'Current color') : '');
    btn.setAttribute('aria-label', btn.title);
    btn.addEventListener('click', () => {
      if (typeof inkSetColor === 'function') inkSetColor(hex, true);
    });
    wrap.append(btn);
  }
}

function inkCpBindHarmony() {
  const seg = inkCp.els.harmonySeg;
  if (!seg) return;
  seg.addEventListener('click', event => {
    const btn = event.target instanceof Element
      ? event.target.closest('button[data-harmony]') : null;
    if (!btn) return;
    inkCp.harmony = btn.dataset.harmony;
    for (const item of seg.querySelectorAll('button[data-harmony]')) {
      const on = item.dataset.harmony === inkCp.harmony;
      item.classList.toggle('active', on);
      item.setAttribute('aria-checked', on ? 'true' : 'false');
    }
    if (isPanelVisible(inkCp.els.panel) && inkCp.mode === 'harmony') {
      inkCpHarmonyDraw();
      inkCpRenderHarmonySwatches();
    }
    inkCpSave();
  });
}

/* -----------------------------------------------------------
   dijital karıştırma (palet bıçağı gibi harmanlama)
   ----------------------------------------------------------- */

function inkCpMixCtx() {
  const c = inkCp.els.mixCanvas;
  if (!c) return null;
  const cssW = Math.max(120, c.clientWidth || 228);
  const cssH = Math.max(64, c.clientHeight || 128);
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const pxW = Math.round(cssW * dpr);
  const pxH = Math.round(cssH * dpr);
  if (c.width !== pxW || c.height !== pxH) {
    c.width = pxW;
    c.height = pxH;
    inkCp.mixSeededPx = 0;
  }
  return { c, ctx: c.getContext('2d'), cssW, cssH, dpr, pxW, pxH };
}

/** Paleti geçmiş/palet renkleriyle tohumla (yumuşak diskler). */
function inkCpMixSeed() {
  const m = inkCpMixCtx();
  if (!m) return;
  const { ctx, pxW, pxH, dpr } = m;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = '#26282e';
  ctx.fillRect(0, 0, pxW, pxH);

  const src = [...inkCpActivePalette().colors, ...inkCp.history]
    .filter((hex, i, arr) => arr.indexOf(hex) === i)
    .slice(0, 10);
  if (!src.length) src.push('#ff5a5f', '#4c8dff', '#35c77d', '#f7c948');
  const cols = Math.min(5, Math.max(2, Math.ceil(src.length / 2)));
  const rows = Math.ceil(src.length / cols);
  const r = Math.min(pxW / (cols * 2.1), pxH / (rows * 1.6));
  for (let i = 0; i < src.length; i++) {
    const cx = ((i % cols) + 0.5) / cols * pxW;
    const cy = (Math.floor(i / cols) + 0.5) / rows * pxH;
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    g.addColorStop(0, src[i]);
    g.addColorStop(0.62, src[i]);
    g.addColorStop(1, src[i] + '00');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  }
  inkCp.mixSeededPx = pxW;
}

/** Noktaya harman darnası: tuvalden örneklenen renk ile aktif renk
 *  lineer-ışık uzayında karışır (muddy yok), yumuşak alpha ile basılır. */
function inkCpMixDab(m, cssX, cssY, radiusCss) {
  const { ctx, dpr, pxW, pxH } = m;
  const dx = Math.round(cssX * dpr);
  const dy = Math.round(cssY * dpr);
  let sampled = null;
  try {
    const d = ctx.getImageData(
      Math.min(pxW - 1, Math.max(0, dx)),
      Math.min(pxH - 1, Math.max(0, dy)), 1, 1).data;
    if (d[3] > 8) {
      sampled = '#' + [d[0], d[1], d[2]]
        .map(v => v.toString(16).padStart(2, '0')).join('');
    }
  } catch { /* tuval kirli değil; örnekleme sorununda yalın darnа */ }
  const active = inkState().color || inkCp.fg;
  const color = sampled && typeof inkMixHexLinear === 'function'
    ? inkMixHexLinear(sampled, active, 0.55)
    : active;
  const b = inkCpHexBytes(color);
  const rgba = a => 'rgba(' + b[0] + ',' + b[1] + ',' + b[2] + ',' + a + ')';
  const r = radiusCss * dpr;
  const g = ctx.createRadialGradient(dx, dy, 0, dx, dy, r);
  g.addColorStop(0, rgba(0.85));
  g.addColorStop(0.65, rgba(0.4));
  g.addColorStop(1, rgba(0));
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(dx, dy, r, 0, Math.PI * 2);
  ctx.fill();
}

function inkCpMixPoint(event) {
  const m = inkCpMixCtx();
  if (!m) return null;
  const rect = m.c.getBoundingClientRect();
  return {
    x: (event.clientX - rect.left) * (m.cssW / Math.max(1, rect.width)),
    y: (event.clientY - rect.top) * (m.cssH / Math.max(1, rect.height)),
  };
}

function inkCpMixSample(event) {
  const m = inkCpMixCtx();
  const p = inkCpMixPoint(event);
  if (!m || !p) return;
  const { ctx, dpr, pxW, pxH } = m;
  try {
    const d = ctx.getImageData(
      Math.min(pxW - 1, Math.max(0, Math.round(p.x * dpr))),
      Math.min(pxH - 1, Math.max(0, Math.round(p.y * dpr))), 1, 1).data;
    if (d[3] <= 8) return;
    const hex = '#' + [d[0], d[1], d[2]]
      .map(v => v.toString(16).padStart(2, '0')).join('');
    if (typeof inkSetColor === 'function') inkSetColor(hex, true);
  } catch { /* sessiz */ }
}

function inkCpBindMixing() {
  const canvas = inkCp.els.mixCanvas;
  if (!canvas) return;
  let painting = false;
  let last = null;

  const strokeTo = (p) => {
    const m = inkCpMixCtx();
    if (!m || !p) return;
    if (last) {
      /* hızlı harekette kopukluk olmasın: segment boyunca darnala */
      const dist = Math.hypot(p.x - last.x, p.y - last.y);
      const steps = Math.max(1, Math.ceil(dist / 4));
      for (let i = 1; i <= steps; i++) {
        inkCpMixDab(m,
          last.x + (p.x - last.x) * i / steps,
          last.y + (p.y - last.y) * i / steps, 11);
      }
    } else {
      inkCpMixDab(m, p.x, p.y, 11);
    }
    last = p;
  };

  canvas.addEventListener('pointerdown', event => {
    const m = inkCpMixCtx();
    if (!m) return;
    if (event.altKey || event.button === 2) {
      event.preventDefault();
      inkCpMixSample(event);
      return;
    }
    if (event.button !== 0) return;
    event.preventDefault();
    painting = true;
    last = null;
    inkCp.pointerId = event.pointerId;
    try { canvas.setPointerCapture(event.pointerId); } catch { /* sessiz */ }
    if (!inkCp.mixSeededPx) inkCpMixSeed();
    strokeTo(inkCpMixPoint(event));
  });
  canvas.addEventListener('pointermove', event => {
    if (!painting) return;
    if (inkCp.pointerId !== null && event.pointerId !== inkCp.pointerId) return;
    event.preventDefault();
    strokeTo(inkCpMixPoint(event));
  });
  const end = event => {
    if (!painting) return;
    painting = false;
    last = null;
    inkCp.pointerId = null;
    try { canvas.releasePointerCapture(event.pointerId); } catch { /* sessiz */ }
  };
  canvas.addEventListener('pointerup', end);
  canvas.addEventListener('pointercancel', end);
  canvas.addEventListener('contextmenu', event => {
    event.preventDefault();
    inkCpMixSample(event);
  });
  if (inkCp.els.mixSeed) {
    inkCp.els.mixSeed.addEventListener('click', () => inkCpMixSeed());
  }
}

/* -----------------------------------------------------------
   ön plan / arka plan + geçmiş + palet
   ----------------------------------------------------------- */

function inkCpSyncSquares() {
  const els = inkCp.els;
  const fg = inkState().color || inkCp.fg;
  inkCp.fg = fg;
  if (els.fg) {
    els.fg.style.background = fg;
    els.fg.classList.toggle('active', true);
  }
  if (els.bg) els.bg.style.background = inkCp.bg;
}

/** X / ok ikonu: iki rengi takas eder. Aktif renk eskiden arka plan olur. */
function inkCpSwapColors(save = true) {
  const fg = inkState().color || inkCp.fg;
  const bg = inkCp.bg;
  inkCp.bg = fg;
  if (typeof inkSetColor === 'function') inkSetColor(bg, save);
  else inkState().color = bg;
  inkCpSyncSquares();
  inkCpSave();
}

/** Kancа (31-ink-ui.js inkSetColor): her renk değişiminde kareleri
 *  günceller; committed (save=true) veya durağanlaşmış (debounce)
 *  değişimleri geçmişe yazar. */
function inkCpOnColorSet(hex, save) {
  inkCp.fg = hex;
  inkCpSyncSquares();
  if (!inkCp.ready) return;
  if (save) {
    clearTimeout(inkCp.histTimer);
    inkCpRecordHistory(hex);
    return;
  }
  clearTimeout(inkCp.histTimer);
  inkCp.histTimer = setTimeout(() => inkCpRecordHistory(hex), 700);
}

function inkCpRecordHistory(hex) {
  if (!inkCp.ready) return;
  if (!/^#[0-9a-f]{6}$/i.test(String(hex || ''))) return;
  hex = hex.toLowerCase();
  if (inkCp.history[0] === hex) return;
  inkCp.history = [hex, ...inkCp.history.filter(h => h !== hex)]
    .slice(0, INK_CP_HISTORY_MAX);
  inkCpRenderHistory();
  inkCpSave();
}

function inkCpRenderHistory() {
  const wrap = inkCp.els.history;
  if (!wrap) return;
  wrap.replaceChildren();
  if (!inkCp.history.length) {
    const hint = document.createElement('span');
    hint.className = 'inkCpEmpty';
    hint.setAttribute('data-l10n', 'Colors you pick will appear here');
    hint.textContent = 'Colors you pick will appear here';
    wrap.append(hint);
    return;
  }
  for (const hex of inkCp.history) {
    wrap.append(inkCpSwatchButton(hex));
  }
}

function inkCpRenderPalette() {
  const wrap = inkCp.els.palette;
  if (!wrap) return;
  wrap.replaceChildren();
  const pal = inkCpActivePalette();
  if (!pal.colors.length) {
    /* Yeni/boş palet: ipucu göster. */
    const hint = document.createElement('div');
    hint.className = 'inkCpEmpty';
    hint.textContent = typeof t === 'function'
      ? t('Click + to add the current color')
      : 'Click + to add the current color';
    wrap.append(hint);
    return;
  }
  for (const hex of pal.colors) {
    const btn = inkCpSwatchButton(hex);
    btn.addEventListener('contextmenu', event => {
      event.preventDefault();
      pal.colors = pal.colors.filter(h => h !== hex);
      inkCpRenderPalette();
      inkCpSave();
    });
    wrap.append(btn);
  }
}

/** Palet seçici çubuğunu (ad listesi + sil düğmesi durumu) tazele. */
function inkCpRenderPalBar() {
  const sel = inkCp.els.palSelect;
  if (!sel) return;
  inkCpActivePalette(); /* indeksi normalize et */
  sel.replaceChildren();
  inkCp.palettes.forEach((p, i) => {
    const opt = document.createElement('option');
    opt.value = String(i);
    opt.textContent = p.name || inkCpPalName('', i);
    sel.append(opt);
  });
  sel.value = String(inkCp.activePal);
  const del = inkCp.els.palDelete;
  if (del) del.disabled = inkCp.palettes.length <= 1;
}

function inkCpSwatchButton(hex) {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'inkCpSwatch';
  btn.style.background = hex;
  btn.title = hex.toUpperCase() + ' · ' +
    (typeof t === 'function' ? t('Click to use') : 'Click to use');
  btn.setAttribute('aria-label', btn.title);
  btn.addEventListener('click', () => {
    if (typeof inkSetColor === 'function') inkSetColor(hex, true);
  });
  return btn;
}

function inkCpBindCollections() {
  const add = inkCp.els.paletteAdd;
  if (add) {
    add.addEventListener('click', () => {
      const hex = (inkState().color || inkCp.fg).toLowerCase();
      const pal = inkCpActivePalette();
      if (pal.colors.includes(hex)) {
        /* zaten varsa başa taşı (MRU) */
        pal.colors = [hex, ...pal.colors.filter(h => h !== hex)];
      } else {
        pal.colors = [hex, ...pal.colors].slice(0, INK_CP_PALETTE_MAX);
      }
      inkCpRenderPalette();
      inkCpSave();
    });
  }

  /* --- adlı paletler: seç / yeni / yeniden adlandır / sil --- */
  const sel = inkCp.els.palSelect;
  if (sel) {
    sel.addEventListener('change', () => {
      const idx = parseInt(sel.value, 10);
      if (Number.isInteger(idx) && idx >= 0 && idx < inkCp.palettes.length) {
        inkCp.activePal = idx;
        inkCpRenderPalette();
        inkCpSave();
      }
    });
  }

  const create = inkCp.els.palNew;
  if (create) {
    create.addEventListener('click', () => {
      if (inkCp.palettes.length >= INK_CP_PALETTES_MAX) return;
      const base = inkCpPalName('', inkCp.palettes.length);
      const name = inkCpUniquePalName(base);
      inkCp.palettes.push({ name, colors: [] });
      inkCp.activePal = inkCp.palettes.length - 1;
      inkCpRenderPalBar();
      inkCpRenderPalette();
      inkCpSave();
    });
  }

  const renameBtn = inkCp.els.palRename;
  if (renameBtn) renameBtn.addEventListener('click', inkCpPalRenameStart);

  const del = inkCp.els.palDelete;
  if (del) {
    del.addEventListener('click', () => {
      if (inkCp.palettes.length <= 1) return;
      inkCp.palettes.splice(inkCp.activePal, 1);
      inkCp.activePal = Math.min(inkCp.activePal, inkCp.palettes.length - 1);
      inkCpRenderPalBar();
      inkCpRenderPalette();
      inkCpSave();
    });
  }
  const drop = inkCp.els.eyedrop;
  if (drop) {
    drop.addEventListener('click', () => {
      if (typeof inkSetTool === 'function') inkSetTool('eyedropper');
    });
  }
}

/** Etkin paleti satır içi giriyle yeniden adlandır (Enter/blur onay, Esc vazgeç). */
function inkCpPalRenameStart() {
  const sel = inkCp.els.palSelect;
  const input = inkCp.els.palRenameInput;
  const pal = inkCpActivePalette();
  if (!sel || !input || sel.hidden) return;
  let done = false;
  const keys = new AbortController();
  const finish = commit => {
    if (done) return;
    done = true;
    keys.abort(); /* dinleyici sızıntısını kes */
    const next = commit
      ? String(input.value || '').trim().slice(0, INK_CP_PAL_NAME_MAX)
      : '';
    if (next && next !== pal.name) {
      pal.name = inkCpUniquePalName(next, inkCp.activePal);
      inkCpSave();
    }
    sel.hidden = false;
    input.hidden = true;
    inkCpRenderPalBar();
  };
  input.value = pal.name;
  input.addEventListener('keydown', e => {
    e.stopPropagation();
    if (e.key === 'Enter') {
      e.preventDefault();
      finish(true);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      finish(false);
    }
  }, { signal: keys.signal });
  input.addEventListener('blur', () => finish(true), { once: true });
  sel.hidden = true;
  input.hidden = false;
  input.focus();
  input.select();
}

/* -----------------------------------------------------------
   mod seçimi + senkron kancası
   ----------------------------------------------------------- */

function inkCpSetMode(mode, save = true) {
  if (!INK_CP_MODES.includes(mode)) mode = 'triangle';
  inkCp.mode = mode;
  const els = inkCp.els;
  if (!els.panel) return;

  const show = (el, on) => { if (el) el.hidden = !on; };
  show(els.wheelCanvas, mode === 'triangle');
  show(els.squareCanvas, mode === 'square');
  show(els.harmonyCanvas, mode === 'harmony');
  show(els.mixCanvas, mode === 'mixing');
  show(els.sliders, mode === 'sliders');
  show(els.harmonyRow, mode === 'harmony');
  show(els.mixTools, mode === 'mixing');

  if (els.modeMenu) {
    for (const item of els.modeMenu.querySelectorAll('button[data-mode]')) {
      const on = item.dataset.mode === mode;
      item.setAttribute('aria-checked', on ? 'true' : 'false');
    }
    els.modeMenu.hidden = true;
  }
  if (els.modeBtn) els.modeBtn.setAttribute('aria-expanded', 'false');

  if (mode === 'square' || mode === 'harmony') {
    /* SAF HSV durumunu geçerli renkten türet (bayt-birebir döngü) */
    inkCp.sv = inkCpDeriveSv(inkState().color || inkCp.fg);
  }
  if (save) inkCpSave();
  inkCpSync(inkState().color || inkCp.fg, true);
}

/** Kancа (31-ink-ui.js inkSyncColorWheel): panel görünürken aktif modun
 *  görünümünü günceller. updatePickers=true → dış senkron (renk dışarıdan
 *  değişti); sürükleme sırasında durum zaten yereldir (yeniden türetme
 *  bayt kuantalamasına geriden gelmesin diye korunur). */
function inkCpSync(hex, updatePickers) {
  if (!inkCp.ready) return;
  const els = inkCp.els;
  hex = typeof inkWheelHex === 'function'
    ? inkWheelHex(hex) : (hex || inkCp.fg);
  inkCp.fg = hex;
  inkCpSyncSquares();
  if (!els.panel || !isPanelVisible(els.panel)) return;

  if (inkCp.mode === 'square') {
    if (updatePickers && !inkCp.dragging) {
      inkCp.sv = inkCpDeriveSv(hex);
    }
    inkCpSquareDraw();
  } else if (inkCp.mode === 'sliders') {
    if (!inkCp.editingSlider) inkCpSyncSliders(hex);
  } else if (inkCp.mode === 'harmony') {
    if (updatePickers && !inkCp.dragging) {
      inkCp.sv = inkCpDeriveSv(hex);
    }
    inkCpHarmonyDraw();
    inkCpRenderHarmonySwatches();
  } else if (inkCp.mode === 'mixing') {
    const m = inkCpMixCtx();
    if (m && !inkCp.mixSeededPx) inkCpMixSeed();
  }
}

/* Pencere boyutu değişince önbellekleri düşür (31'deki resize dinleyicisi
   üçgen için aynısını yapar; buradaki modlar kendi önbelleğini tutar). */
window.addEventListener('resize', () => {
  if (!inkCp.ready) return;
  inkCp.squareCache = null;
  inkCp.squareHue = -1;
  inkCp.squarePx = 0;
  if (isPanelVisible(inkCp.els.panel) &&
      (inkCp.mode === 'square' || inkCp.mode === 'harmony')) {
    inkCpSync(inkState().color || inkCp.fg, true);
  }
});

/** Kancа (31-ink-ui.js inkWheelDraw): üçgen tuvalinin çizimi yalnızca
 *  üçgen modunda anlamlı — diğer modlarda gizli tuvale boşa piksel
 *  dökülmesini (halka drag gecikmesi) önler. Satır-içi kart da artık
 *  mod değiştirebildiği için kural tüm bağlamlarda aynıdır. */
function inkCpWheelVisible() {
  if (!inkCp.ready) return true;
  return inkCp.mode === 'triangle';
}

/* TailRef app · ink tile canon · FAZ 4 — Kas (plan madde 1)
   ------------------------------------------------------------------
   Kanon: 256×256 px karolar; ekran/yalın depo RGBA8'de kalır (tuval /
   tile canvas), RAM aynası **premultplied lineer Float32** uzamdadır.
   Tüm tüketiciler (tile-diff undo, smudge advected field, editor
   dirty-tile önizleme) bu aynadan okur; tuvale geri yazma tek kapıda.

   LRU: dokunulan tile sona taşınır; kapasite aşımında en eskisi
   (temiz/iç sıra) düşer. Kanon bir *aynadır* — display tuvaline çöp
   yazmaz; `flush` yalnızca çağıran ona hedef gösterirse yazar.

   Saf mantıktır: IO iki kapıyla gelir (readVolume / writeImageData),
   böylece tarayıcı olmadan da (node) altın örneklerle test edilir.
   ========================================================= */
'use strict';

var INK_CANON_TILE = 256;                 // px kenar (plan: 256×256)
var INK_CANON_PIXELS = INK_CANON_TILE * INK_CANON_TILE;
var INK_CANON_DEFAULT_MAX_TILES = 64;     // ≈64 MB lin ayna üst sınırı

var inkCanon = {
  tiles: new Map(),       // key -> { layerId, tx, ty, lin, stamp }
  maxTiles: INK_CANON_DEFAULT_MAX_TILES,
  stats: { mirrors: 0, flushes: 0, evictions: 0, hits: 0, misses: 0, diffs: 0 },
};

/* =========================================================
   lineer uzay çifti (56-ink-color ile birebir aynı inkâr yok:
   kanon modülü kendi minimal çiftini taşır — worker'da da kullanılır)
   ========================================================= */
function inkCanonSRGBToLin01(c) {
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}
function inkCanonLin01ToSRGB(c) {
  if (c <= 0) return 0;
  if (c >= 1) return 1;
  return c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;
}

/** RGBA8 bytes (0..255, premul DEĞİL) → premul lineer Float32 karoya. */
function inkCanonPatchToLin(patch /* Uint8ClampedArray RGBA */) {
  const n = patch.length >> 2;
  const lin = new Float32Array(n * 4);
  for (let i = 0; i < n; i++) {
    const j = i * 4;
    const a = patch[j + 3] / 255;
    lin[j] = inkCanonSRGBToLin01(patch[j] / 255) * a;
    lin[j + 1] = inkCanonSRGBToLin01(patch[j + 1] / 255) * a;
    lin[j + 2] = inkCanonSRGBToLin01(patch[j + 2] / 255) * a;
    lin[j + 3] = a;
  }
  return lin;
}

/** Premul lineer karoya → RGBA8 bytes (0..255, premul değil). */
function inkCanonLinToPatch(lin) {
  const n = lin.length >> 2;
  const out = new Uint8ClampedArray(n * 4);
  for (let i = 0; i < n; i++) {
    const j = i * 4;
    const a = lin[j + 3];
    if (a <= 0) { out[j + 3] = 0; continue; }
    out[j] = Math.round(inkCanonLin01ToSRGB(lin[j] / a) * 255);
    out[j + 1] = Math.round(inkCanonLin01ToSRGB(lin[j + 1] / a) * 255);
    out[j + 2] = Math.round(inkCanonLin01ToSRGB(lin[j + 2] / a) * 255);
    out[j + 3] = Math.round(a * 255);
  }
  return out;
}

/* =========================================================
   karo anahtar / kaplama listesi
   ========================================================= */
function inkCanonTileKey(layerId, tx, ty) {
  return layerId + ':' + tx + ',' + ty;
}

/** Dikdörtgenin (px) kapladığı karolar; kenar taşmaları tam karo okunur. */
function inkCanonTilesForRect(rect) {
  if (!rect || !(rect.w > 0) || !(rect.h > 0)) return [];
  const tx0 = Math.floor(rect.x / INK_CANON_TILE);
  const ty0 = Math.floor(rect.y / INK_CANON_TILE);
  const tx1 = Math.floor((rect.x + rect.w - 1) / INK_CANON_TILE);
  const ty1 = Math.floor((rect.y + rect.h - 1) / INK_CANON_TILE);
  const out = [];
  for (let ty = ty0; ty <= ty1; ty++) {
    for (let tx = tx0; tx <= tx1; tx++) out.push({ tx, ty });
  }
  return out;
}

/* =========================================================
   LRU havuz
   ========================================================= */
function inkCanonTouch(key) {
  // Map ekleme sırası = L least-recent: dokunulan yeniden takılır.
  const t = inkCanon.tiles.get(key);
  if (!t) return t;
  inkCanon.tiles.delete(key);
  inkCanon.tiles.set(key, t);
  return t;
}

function inkCanonEvictOne() {
  const first = inkCanon.tiles.keys().next();
  if (first.done) return false;
  inkCanon.tiles.delete(first.value);
  inkCanon.stats.evictions++;
  return true;
}

function inkCanonEnsureCapacityOrEvict(reserve = 0) {
  while (inkCanon.tiles.size + reserve >= inkCanon.maxTiles) {
    if (!inkCanonEvictOne()) break;
  }
}

function inkCanonSetTile(layerId, tx, ty, lin) {
  const key = inkCanonTileKey(layerId, tx, ty);
  const had = inkCanon.tiles.has(key);
  inkCanonEnsureCapacityOrEvict();
  // had ise sadece değeri yenile (sıra bozulmaz); yeniyse en sona ekle.
  inkCanon.tiles.set(key, { layerId, tx, ty, lin, stamp: 0 });
  if (!had) inkCanon.stats.misses++;
  else inkCanon.stats.hits++;
  return inkCanon.tiles.get(key);
}

/* =========================================================
   aynala / karşılaştır / akıt
   ========================================================= */

/** `readVolume(x, y, w, h) -> Uint8ClampedArray` ile karoları aynala. */
function inkCanonMirrorTiles(layerId, tiles, readVolume, out = null) {
  const mirrored = out || [];
  for (const t of tiles) {
    const x = t.tx * INK_CANON_TILE, y = t.ty * INK_CANON_TILE;
    const vol = readVolume(x, y, INK_CANON_TILE, INK_CANON_TILE);
    if (!vol) continue;
    const lin = inkCanonPatchToLin(vol);
    inkCanonSetTile(layerId, t.tx, t.ty, lin);
    inkCanonTouch(inkCanonTileKey(layerId, t.tx, t.ty));
    mirrored.push({ tx: t.tx, ty: t.ty, lin });
  }
  return mirrored;
}

/** Kannona dışarıdan (undo 'before' kuyruğu gibi) ikinci bir harita
 *  ağırlığı olmadan aynı istemci için ayrı madde gerekmez: diff, aynadaki
 *  lin ile YENİyeninin karşılaştırmasıdır.
 *  `readVolume` aynısı; dönüş: değişen tile listesi
 *  [{tx,ty, beforeLin, afterLin}], commit=true iken ayna yeniye taşınır. */
function inkCanonDiffTiles(layerId, tiles, readVolume, opts = {}) {
  const commit = opts.commit !== false;
  const tol = Number.isFinite(opts.tolerance) ? opts.tolerance : 1 / 255;
  const changed = [];
  for (const t of tiles) {
    const key = inkCanonTileKey(layerId, t.tx, t.ty);
    const cur = inkCanon.tiles.get(key);
    if (!cur) continue; // aynalanmamış karoda diff yapılmaz (mirror önce)
    const x = t.tx * INK_CANON_TILE, y = t.ty * INK_CANON_TILE;
    const vol = readVolume(x, y, INK_CANON_TILE, INK_CANON_TILE);
    if (!vol) continue;
    const after = inkCanonPatchToLin(vol);
    const before = cur.lin;
    let diff = false;
    const n = after.length;
    for (let i = 0; i < n; i++) {
      if (Math.abs(after[i] - before[i]) > tol) { diff = true; break; }
    }
    inkCanon.stats.diffs++;
    if (diff) {
    changed.push({ tx: t.tx, ty: t.ty, beforeLin: before, afterLin: after });
      if (commit) {
      // Ayna yeniye taşınır (before aynanın kendisidir; korunur).
      cur.lin = after;
      cur.stamp++;
      inkCanonTouch(key);
      }
    }
  }
  return changed;
}

/** Aynadaki karoları sRGB'ye çevirip `writeImageData(x, y, patch, w, h)` ile
 *  yazar — undo restore / editor dirty-tile birleştirici kullanır. */
function inkCanonFlushTiles(layerId, tiles, writeImageData) {
  for (const t of tiles) {
    const key = inkCanonTileKey(layerId, t.tx, t.ty);
    const cur = inkCanon.tiles.get(key);
    if (!cur) continue;
    const patch = inkCanonLinToPatch(cur.lin);
    writeImageData(
      t.tx * INK_CANON_TILE, t.ty * INK_CANON_TILE,
      patch, INK_CANON_TILE, INK_CANON_TILE
    );
    inkCanon.stats.flushes++;
    inkCanonTouch(key);
  }
}

/* =========================================================
   bölge katmanı — tek okuma karolara dilimlenir
   (undo capture'ı tuvale TEK getImageData yapıp bize region uzatır;
   kilitleme ve dizilim burada çözülür)
   ========================================================= */

/** Dikdörtgeni karo sınırlarına kırpılmış dilimlere ayırır. */
function inkCanonRegionSlices(rect) {
  if (!rect || !(rect.w > 0) || !(rect.h > 0)) return [];
  const out = [];
  for (const t of inkCanonTilesForRect(rect)) {
    const x0 = t.tx * INK_CANON_TILE, y0 = t.ty * INK_CANON_TILE;
    const x = Math.max(rect.x, x0);
    const y = Math.max(rect.y, y0);
    const w = Math.min(rect.x + rect.w, x0 + INK_CANON_TILE) - x;
    const h = Math.min(rect.y + rect.h, y0 + INK_CANON_TILE) - y;
    if (w > 0 && h > 0) out.push({ tx: t.tx, ty: t.ty, x, y, w, h });
  }
  return out;
}

/** region içinden (offsetli) piksel dilimini lineere çevirir. */
function inkCanonRegionSliceToLin(region, slice) {
  const data = region && region.data;
  if (!data) return null;
  const lin = new Float32Array(slice.w * slice.h * 4);
  for (let row = 0; row < slice.h; row++) {
    const sy = slice.y - (region.modelY || 0) + row;
    for (let col = 0; col < slice.w; col++) {
      const sx = slice.x - (region.modelX || 0) + col;
      const o = (sy * region.width + sx) * 4;
      const d = (row * slice.w + col) * 4;
      lin[d] = data[o];
      lin[d + 1] = data[o + 1];
      lin[d + 2] = data[o + 2];
      lin[d + 3] = data[o + 3];
    }
  }
  return inkCanonPatchToLin(lin);
}

function inkCanonSliceIntoLin(lin /* tile lin */, sliceLin, slice) {
  const lx = slice.x - slice.tx * INK_CANON_TILE;
  const ly = slice.y - slice.ty * INK_CANON_TILE;
  for (let row = 0; row < slice.h; row++) {
    for (let col = 0; col < slice.w; col++) {
      const d = (row * slice.w + col) * 4;
      const j = ((ly + row) * INK_CANON_TILE + lx + col) * 4;
      lin[j] = sliceLin[d];
      lin[j + 1] = sliceLin[d + 1];
      lin[j + 2] = sliceLin[d + 2];
      lin[j + 3] = sliceLin[d + 3];
    }
  }
}

/** `region` (tek ImageData benzeri {width,height,data}; data bölge köşesinden
 *  başlar — mutlak koordinat için region.modelX/modelY verilebilir) karoları
 *  aynaya yazar. Karonun aynası yoksa ÖNCE tam karo okunur (`readVolume`) —
 *  bölge dışı içerik yanlış sıfırlanmaz. Döner: dilim listesi. */
function inkCanonPatchFromRegion(layerId, rect, region, readVolume) {
  const slices = inkCanonRegionSlices(rect);
  if (!slices.length) return slices;
  for (const slice of slices) {
    const key = inkCanonTileKey(layerId, slice.tx, slice.ty);
    /* DÜZELTME (profiler bulgusu): soğuk karoyu TAM 256×256 okuyarak
       aynalamak her vuruşta 10-20 getImageData üretiyordu (LRU=64;
       2560 basamaklı tuvalde bant değişince trash). Ayna yalnız zaten
       sıcak karolara güncellenir; soğuk karoda undo kaydı yalnız bölge
       dilimlerinden kurulur. Ayna tüketen yollar (diff/flush) karosuz
       durumda fail-soft davranır. */
    const tile = inkCanon.tiles.get(key);
    if (!tile) continue;
    const sliceLin = inkCanonRegionSliceToLin(region, slice);
    inkCanonSliceIntoLin(tile.lin, sliceLin, slice);
    tile.stamp++;
    inkCanonTouch(key);
  }
  return slices;
}

/** Aynı bölge aynadaki (öncesi) değerle karşılaştırılır; dönüş: değişen
 *  dilim listesi [{tx,ty,x,y,w,h}] (post-paint diff). commit iken ayna
 *  yalnız slice alanında yeniye taşınır. */
function inkCanonDiffFromRegion(layerId, rect, region, opts = {}) {
  const commit = opts.commit !== false;
  const tol = Number.isFinite(opts.tolerance) ? opts.tolerance : 1 / 255;
  const changed = [];
  for (const slice of inkCanonRegionSlices(rect)) {
    const key = inkCanonTileKey(layerId, slice.tx, slice.ty);
    const tile = inkCanon.tiles.get(key);
    if (!tile) continue;
    const sliceLin = inkCanonRegionSliceToLin(region, slice);
    if (!sliceLin) continue;
    const lx = slice.x - slice.tx * INK_CANON_TILE;
    const ly = slice.y - slice.ty * INK_CANON_TILE;
    let differs = false;
    for (let row = 0; row < slice.h && !differs; row++) {
      for (let col = 0; col < slice.w; col++) {
        const d = (row * slice.w + col) * 4;
        const j = ((ly + row) * INK_CANON_TILE + lx + col) * 4;
        if (Math.abs(sliceLin[d] - tile.lin[j]) > tol ||
            Math.abs(sliceLin[d + 1] - tile.lin[j + 1]) > tol ||
            Math.abs(sliceLin[d + 2] - tile.lin[j + 2]) > tol ||
            Math.abs(sliceLin[d + 3] - tile.lin[j + 3]) > tol) {
          differs = true;
          break;
        }
      }
    }
    inkCanon.stats.diffs++;
    if (!differs) continue;
    changed.push({ tx: slice.tx, ty: slice.ty, x: slice.x, y: slice.y, w: slice.w, h: slice.h });
    if (commit) {
      inkCanonSliceIntoLin(tile.lin, sliceLin, slice);
      tile.stamp++;
      inkCanonTouch(key);
    }
  }
  return changed;
}

/* =========================================================
   ömür
   ========================================================= */
function inkCanonInvalidate(layerId) {
  if (!layerId) { inkCanonClear(); return; }
  const prefix = layerId + ':';
  for (const key of Array.from(inkCanon.tiles.keys())) {
    if (key.startsWith(prefix)) inkCanon.tiles.delete(key);
  }
}

function inkCanonClear() {
  inkCanon.tiles.clear();
  inkCanon.stats = { mirrors: 0, flushes: 0, evictions: 0, hits: 0, misses: 0, diffs: 0 };
}

function inkCanonStats() {
  return {
    tiles: inkCanon.tiles.size,
    maxTiles: inkCanon.maxTiles,
    mb: +(inkCanon.tiles.size * INK_CANON_PIXELS * 4 * 4 / (1024 * 1024)).toFixed(2),
    evictions: inkCanon.stats.evictions,
    mirrors: inkCanon.stats.mirrors,
    flushes: inkCanon.stats.flushes,
    diffs: inkCanon.stats.diffs,
  };
}

